#!/usr/bin/env node

// Load environment variables from .env file
require('dotenv').config({ path: require('path').join(__dirname, '.env') });
require('dotenv').config({ path: require('path').join(process.env.HOME, '.blueprint', '.env') });

/**
 * BluePrint CLI - AI-Powered Construction Takeoff System
 * 
 * Integrates multiple vision models for comprehensive document analysis:
 * - Kimi K2.5 Vision: Construction drawings (floor plans, details, sections)
 * - Llama Nemotron Nano VL: Specs, schedules, bid docs, tables
 * - NV-CLIP: Semantic search across all project documents
 * 
 * Architecture: 8 Trade Expert Agents + Hybrid Methodology
 */

const { Command } = require('commander');
const chalk = require('chalk');
const ora = require('ora');
const path = require('path');
const fs = require('fs');

// Commands
const projectCmd = require('./commands/project');
const ingestCmd = require('./commands/ingest');
const takeoffCmd = require('./commands/takeoff');
const queryCmd = require('./commands/query');
const expertCmd = require('./commands/expert');
const searchCmd = require('./commands/search');
const visionCmd = require('./commands/vision');

const VERSION = '1.0.0';
const CONFIG_PATH = path.join(process.env.HOME, '.blueprint', 'config.json');

const program = new Command();

program
  .name('blueprint')
  .description(chalk.cyan('🏗️  BluePrint CLI - AI-Powered Construction Takeoff System'))
  .version(VERSION);

// ═══════════════════════════════════════════════════════════════════
// PROJECT MANAGEMENT
// ═══════════════════════════════════════════════════════════════════

program
  .command('init <name>')
  .description('Initialize a new project')
  .option('-t, --type <type>', 'Project type (bid|estimate|audit)', 'bid')
  .option('-d, --dir <path>', 'Project directory')
  .action(projectCmd.init);

program
  .command('list')
  .alias('ls')
  .description('List all projects')
  .option('-a, --all', 'Include archived projects')
  .action(projectCmd.list);

program
  .command('open <name>')
  .description('Open/set active project')
  .action(projectCmd.open);

program
  .command('status')
  .description('Show current project status')
  .option('-v, --verbose', 'Detailed status')
  .action(projectCmd.status);

// ═══════════════════════════════════════════════════════════════════
// DOCUMENT INGESTION
// ═══════════════════════════════════════════════════════════════════

program
  .command('ingest <path>')
  .description('Ingest documents into project')
  .option('-t, --type <type>', 'Document type (drawings|specs|bid|schedule|all)', 'all')
  .option('--ocr', 'Force OCR processing')
  .option('--vision', 'Use vision models for drawing analysis')
  .action(ingestCmd.ingest);

program
  .command('extract')
  .description('Extract structured data from ingested documents')
  .option('-t, --type <type>', 'Extraction type (rooms|equipment|quantities|all)', 'all')
  .option('-e, --expert <trade>', 'Run specific expert extraction')
  .action(ingestCmd.extract);

// ═══════════════════════════════════════════════════════════════════
// VISION ANALYSIS (NVIDIA NIM Models)
// ═══════════════════════════════════════════════════════════════════

program
  .command('vision <action>')
  .description('Vision model operations (analyze|batch|compare)')
  .option('-m, --model <model>', 'Vision model (kimi|nemotron|auto)', 'auto')
  .option('-i, --input <path>', 'Input image or PDF')
  .option('-p, --prompt <text>', 'Analysis prompt')
  .option('-o, --output <path>', 'Output file')
  .action(visionCmd.run);

// ═══════════════════════════════════════════════════════════════════
// TAKEOFF OPERATIONS
// ═══════════════════════════════════════════════════════════════════

program
  .command('takeoff')
  .description('Run takeoff analysis')
  .option('-m, --method <method>', 'Methodology (hybrid|alpha|beta)', 'hybrid')
  .option('-e, --experts <list>', 'Specific experts to run (comma-separated)')
  .option('-i, --items <range>', 'Bid item range (e.g., "1-50" or "8,12,45")')
  .option('--dry-run', 'Preview without executing')
  .option('--parallel', 'Run experts in parallel')
  .action(takeoffCmd.run);

program
  .command('validate')
  .description('Validate takeoff results')
  .option('--strict', 'Strict validation mode')
  .option('--fix', 'Attempt to fix discrepancies')
  .action(takeoffCmd.validate);

program
  .command('export <format>')
  .description('Export takeoff results (excel|csv|json|pdf)')
  .option('-o, --output <path>', 'Output file path')
  .option('--template <name>', 'Export template')
  .action(takeoffCmd.export);

// ═══════════════════════════════════════════════════════════════════
// EXPERT AGENTS
// ═══════════════════════════════════════════════════════════════════

program
  .command('expert <action>')
  .description('Expert agent operations (list|run|status|memory)')
  .option('-t, --trade <trade>', 'Specific trade expert')
  .option('-q, --query <text>', 'Query for expert')
  .option('--context <items>', 'Bid items for context')
  .action(expertCmd.run);

// ═══════════════════════════════════════════════════════════════════
// SEMANTIC SEARCH (NV-CLIP)
// ═══════════════════════════════════════════════════════════════════

program
  .command('search <query>')
  .description('Semantic search across project documents')
  .option('-t, --type <type>', 'Search scope (drawings|specs|all)', 'all')
  .option('-n, --limit <n>', 'Max results', '10')
  .option('--visual', 'Include visual similarity search')
  .action(searchCmd.run);

// ═══════════════════════════════════════════════════════════════════
// QUERY & Q&A
// ═══════════════════════════════════════════════════════════════════

program
  .command('ask <question>')
  .description('Ask a question about the project')
  .option('-e, --expert <trade>', 'Route to specific expert')
  .option('--cite', 'Include citations')
  .action(queryCmd.ask);

program
  .command('rfi')
  .description('Generate RFI list from analysis')
  .option('-p, --priority <level>', 'Min priority (critical|high|medium|low)', 'medium')
  .option('--export <path>', 'Export RFI list')
  .action(queryCmd.rfi);

// ═══════════════════════════════════════════════════════════════════
// CONFIGURATION
// ═══════════════════════════════════════════════════════════════════

program
  .command('config <action>')
  .description('Configuration (show|set|api-keys)')
  .option('-k, --key <key>', 'Config key')
  .option('-v, --value <value>', 'Config value')
  .action(async (action, options) => {
    const config = require('./lib/config');

    switch (action) {
      case 'show':
        const cfg = await config.load();
        console.log(chalk.cyan('\n📋 BluePrint Configuration:\n'));
        console.log(JSON.stringify(cfg, null, 2));
        break;

      case 'set':
        if (!options.key || !options.value) {
          console.error(chalk.red('❌ --key and --value required'));
          process.exit(1);
        }
        await config.set(options.key, options.value);
        console.log(chalk.green(`✓ Set ${options.key}`));
        break;

      case 'api-keys':
        console.log(chalk.cyan('\n🔑 API Key Status:\n'));
        const status = await config.checkApiKeys();
        for (const [name, ok] of Object.entries(status)) {
          console.log(`  ${ok ? '✓' : '✗'} ${name}: ${ok ? chalk.green('configured') : chalk.red('missing')}`);
        }
        break;

      default:
        console.error(chalk.red(`Unknown action: ${action}`));
    }
  });

// ═══════════════════════════════════════════════════════════════════
// BANNER & HELP
// ═══════════════════════════════════════════════════════════════════

program.addHelpText('beforeAll', `
${chalk.cyan('╔═══════════════════════════════════════════════════════════════╗')}
${chalk.cyan('║')}  ${chalk.bold.white('🏗️  BluePrint')} ${chalk.gray('- AI-Powered Construction Takeoff')}           ${chalk.cyan('║')}
${chalk.cyan('║')}  ${chalk.gray('Version ' + VERSION + ' | Hybrid Methodology | 8 Expert Agents')}   ${chalk.cyan('║')}
${chalk.cyan('╚═══════════════════════════════════════════════════════════════╝')}
`);

program.addHelpText('afterAll', `
${chalk.gray('Vision Models:')}
  ${chalk.yellow('kimi')}      Kimi K2.5 - Construction drawings analysis
  ${chalk.yellow('nemotron')}  Llama Nemotron Nano VL - Document/table extraction
  ${chalk.yellow('nvclip')}    NV-CLIP - Semantic visual search

${chalk.gray('Expert Agents:')}
  mechanical, electrical, plumbing, fire-protection,
  architectural, structural, civil, general-conditions

${chalk.gray('Examples:')}
  ${chalk.green('$')} blueprint init "HHC Brooklyn Dental" --type bid
  ${chalk.green('$')} blueprint ingest ./drawings --type drawings --vision
  ${chalk.green('$')} blueprint takeoff --method hybrid --parallel
  ${chalk.green('$')} blueprint ask "What fire rating is required for Room 501?"
  ${chalk.green('$')} blueprint search "standpipe locations" --visual
`);

// Parse and run
program.parse(process.argv);

// Show help if no command
if (!process.argv.slice(2).length) {
  program.outputHelp();
}

/**
 * BluePrint Vision Models Integration
 * 
 * Multi-provider vision support with automatic fallback:
 * 1. NVIDIA NIM (Kimi K2.5, Nemotron, NV-CLIP)
 * 2. Anthropic Claude (claude-3-opus, claude-3-sonnet)
 * 3. OpenAI GPT-4V
 * 
 * Fallback order: nvidia → anthropic → openai
 */

const fs = require('fs').promises;
const path = require('path');
const config = require('../lib/config');

// ═══════════════════════════════════════════════════════════════════
// MODEL DEFINITIONS
// ═══════════════════════════════════════════════════════════════════

const PROVIDERS = {
  nvidia: {
    name: 'NVIDIA NIM',
    baseUrl: 'https://integrate.api.nvidia.com/v1',
    envKey: 'NVIDIA_API_KEY'
  },
  anthropic: {
    name: 'Anthropic',
    baseUrl: 'https://api.anthropic.com/v1',
    envKey: 'ANTHROPIC_API_KEY'
  },
  openai: {
    name: 'OpenAI',
    baseUrl: 'https://api.openai.com/v1',
    envKey: 'OPENAI_API_KEY'
  }
};

const MODELS = {
  // NVIDIA NIM Models
  kimi: {
    provider: 'nvidia',
    name: 'Kimi K2.5 Vision',
    model: 'moonshotai/kimi-k2.5',
    maxTokens: 8192,
    bestFor: ['drawings', 'floor-plans', 'details', 'sections', 'diagrams'],
    description: 'Best for interpreting construction drawings - reads dimensions, symbols, equipment placement'
  },
  nemotron: {
    provider: 'nvidia',
    name: 'Llama Nemotron Nano VL',
    model: 'nvidia/llama-nemotron-nano-vl-8b-v1',
    maxTokens: 4096,
    bestFor: ['specs', 'schedules', 'tables', 'forms', 'text-heavy'],
    description: '#1 on OCRBench - best for specifications, schedules, bid forms, tables'
  },
  nvclip: {
    provider: 'nvidia',
    name: 'NV-CLIP',
    model: 'nvidia/nvclip',
    type: 'embedding',
    dimensions: 1024,
    bestFor: ['search', 'similarity', 'embeddings'],
    description: 'Multimodal embeddings for semantic search across documents and drawings'
  },

  // Anthropic Claude Models (Fallback)
  claude: {
    provider: 'anthropic',
    name: 'Claude Sonnet 4',
    model: 'claude-sonnet-4-20250514',
    maxTokens: 4096,
    bestFor: ['drawings', 'specs', 'general'],
    description: 'Excellent vision + reasoning, good fallback for all document types'
  },
  'claude-opus': {
    provider: 'anthropic',
    name: 'Claude Opus 4',
    model: 'claude-opus-4-20250514',
    maxTokens: 4096,
    bestFor: ['complex', 'detailed-analysis'],
    description: 'Most capable Claude model for complex document analysis'
  },

  // OpenAI Models (Fallback)
  'gpt4v': {
    provider: 'openai',
    name: 'GPT-4 Vision',
    model: 'gpt-4o',
    maxTokens: 4096,
    bestFor: ['drawings', 'specs', 'general'],
    description: 'Strong vision capabilities, good general fallback'
  },
  'gpt4o-mini': {
    provider: 'openai',
    name: 'GPT-4o Mini',
    model: 'gpt-4o-mini',
    maxTokens: 4096,
    bestFor: ['quick', 'cost-effective'],
    description: 'Faster and cheaper, good for batch processing'
  }
};

// Fallback chains by use case
// Claude is reliable fallback when NVIDIA is slow/unavailable
const FALLBACK_CHAINS = {
  drawings: ['kimi', 'claude', 'gpt4v'],
  specs: ['nemotron', 'claude', 'gpt4v'],
  tables: ['nemotron', 'gpt4v', 'claude'],
  search: ['nvclip', 'claude', 'gpt4v'],
  general: ['claude', 'kimi', 'gpt4v']
};

// API request timeout (NVIDIA can be slow)
const API_TIMEOUT_MS = 60000;

// ═══════════════════════════════════════════════════════════════════
// PROVIDER API CALLS
// ═══════════════════════════════════════════════════════════════════

async function callNvidia(model, imageBase64, mimeType, prompt, options = {}) {
  const apiKey = await config.getApiKey('nvidia');
  if (!apiKey) throw new Error('NVIDIA API key not configured');

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), options.timeout || API_TIMEOUT_MS);

  try {
    const response = await fetch(`${PROVIDERS.nvidia.baseUrl}/chat/completions`, {
      signal: controller.signal,
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${apiKey}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      model: model.model,
      messages: [{
        role: 'user',
        content: [
          { type: 'image_url', image_url: { url: `data:${mimeType};base64,${imageBase64}` } },
          { type: 'text', text: prompt }
        ]
      }],
      max_tokens: options.maxTokens || model.maxTokens,
      temperature: options.temperature || 0.1
    })
  });

  if (!response.ok) {
    const error = await response.text();
    throw new Error(`NVIDIA API error: ${response.status} - ${error}`);
  }

    const result = await response.json();
    return {
      content: result.choices[0]?.message?.content || '',
      usage: result.usage
    };
  } finally {
    clearTimeout(timeout);
  }
}

async function callAnthropic(model, imageBase64, mimeType, prompt, options = {}) {
  const apiKey = await config.getApiKey('anthropic');
  if (!apiKey) throw new Error('Anthropic API key not configured');

  // Map mime type to Anthropic's expected format
  const mediaType = mimeType === 'image/jpg' ? 'image/jpeg' : mimeType;

  const response = await fetch(`${PROVIDERS.anthropic.baseUrl}/messages`, {
    method: 'POST',
    headers: {
      'x-api-key': apiKey,
      'Content-Type': 'application/json',
      'anthropic-version': '2023-06-01'
    },
    body: JSON.stringify({
      model: model.model,
      max_tokens: options.maxTokens || model.maxTokens,
      messages: [{
        role: 'user',
        content: [
          {
            type: 'image',
            source: {
              type: 'base64',
              media_type: mediaType,
              data: imageBase64
            }
          },
          { type: 'text', text: prompt }
        ]
      }]
    })
  });

  if (!response.ok) {
    const error = await response.text();
    throw new Error(`Anthropic API error: ${response.status} - ${error}`);
  }

  const result = await response.json();
  return {
    content: result.content[0]?.text || '',
    usage: {
      prompt_tokens: result.usage?.input_tokens,
      completion_tokens: result.usage?.output_tokens,
      total_tokens: (result.usage?.input_tokens || 0) + (result.usage?.output_tokens || 0)
    }
  };
}

async function callOpenAI(model, imageBase64, mimeType, prompt, options = {}) {
  const apiKey = await config.getApiKey('openai');
  if (!apiKey) throw new Error('OpenAI API key not configured');

  const response = await fetch(`${PROVIDERS.openai.baseUrl}/chat/completions`, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${apiKey}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      model: model.model,
      messages: [{
        role: 'user',
        content: [
          { type: 'image_url', image_url: { url: `data:${mimeType};base64,${imageBase64}`, detail: 'high' } },
          { type: 'text', text: prompt }
        ]
      }],
      max_tokens: options.maxTokens || model.maxTokens,
      temperature: options.temperature || 0.1
    })
  });

  if (!response.ok) {
    const error = await response.text();
    throw new Error(`OpenAI API error: ${response.status} - ${error}`);
  }

  const result = await response.json();
  return {
    content: result.choices[0]?.message?.content || '',
    usage: result.usage
  };
}

// ═══════════════════════════════════════════════════════════════════
// MAIN API
// ═══════════════════════════════════════════════════════════════════

/**
 * Auto-select best model based on document type
 */
function selectModel(docType, forceModel = null) {
  if (forceModel && MODELS[forceModel]) {
    return forceModel;
  }

  const typeMap = {
    'drawing': 'kimi',
    'floor-plan': 'kimi',
    'detail': 'kimi',
    'section': 'kimi',
    'elevation': 'kimi',
    'diagram': 'kimi',
    'spec': 'nemotron',
    'specification': 'nemotron',
    'schedule': 'nemotron',
    'table': 'nemotron',
    'form': 'nemotron',
    'bid': 'nemotron',
    'search': 'nvclip',
    'embed': 'nvclip'
  };

  return typeMap[docType?.toLowerCase()] || 'claude'; // Default to Claude
}

/**
 * Check which providers have valid API keys
 */
async function getAvailableProviders() {
  const available = {};

  for (const [id, provider] of Object.entries(PROVIDERS)) {
    const key = await config.getApiKey(id);
    available[id] = !!key;
  }

  return available;
}

/**
 * Analyze an image with automatic fallback
 */
async function analyze(imagePath, prompt, options = {}) {
  // Read and encode image
  const imageData = await fs.readFile(imagePath);
  const base64Image = imageData.toString('base64');
  const ext = path.extname(imagePath).toLowerCase();
  const mimeType = {
    '.png': 'image/png',
    '.jpg': 'image/jpeg',
    '.jpeg': 'image/jpeg',
    '.webp': 'image/webp',
    '.gif': 'image/gif'
  }[ext] || 'image/png';

  // Determine fallback chain
  const docType = options.docType || 'general';
  const chain = options.model 
    ? [options.model] 
    : (FALLBACK_CHAINS[docType] || FALLBACK_CHAINS.general);

  const errors = [];

  // Try each model in chain
  for (const modelId of chain) {
    const model = MODELS[modelId];
    if (!model) continue;

    try {
      // Check if provider key exists
      const apiKey = await config.getApiKey(model.provider);
      if (!apiKey) {
        errors.push({ model: modelId, error: `${model.provider} API key not configured` });
        continue;
      }

      // Call appropriate provider
      let result;
      switch (model.provider) {
        case 'nvidia':
          result = await callNvidia(model, base64Image, mimeType, prompt, options);
          break;
        case 'anthropic':
          result = await callAnthropic(model, base64Image, mimeType, prompt, options);
          break;
        case 'openai':
          result = await callOpenAI(model, base64Image, mimeType, prompt, options);
          break;
        default:
          throw new Error(`Unknown provider: ${model.provider}`);
      }

      // Success!
      return {
        model: modelId,
        modelName: model.name,
        provider: model.provider,
        content: result.content,
        usage: result.usage,
        imagePath,
        timestamp: new Date().toISOString(),
        fallbacksAttempted: errors.length
      };

    } catch (err) {
      errors.push({ model: modelId, error: err.message });
      // Continue to next fallback
    }
  }

  // All failed
  throw new Error(`All vision models failed:\n${errors.map(e => `  - ${e.model}: ${e.error}`).join('\n')}`);
}

/**
 * Generate embeddings (NV-CLIP with text fallback)
 */
async function embed(input, options = {}) {
  const apiKey = await config.getApiKey('nvidia');

  if (apiKey) {
    // Try NV-CLIP
    try {
      const model = MODELS.nvclip;
      let payload;

      if (options.type === 'image') {
        const imageData = await fs.readFile(input);
        const base64Image = imageData.toString('base64');
        payload = {
          model: model.model,
          input: [{ type: 'image_url', image_url: { url: `data:image/png;base64,${base64Image}` } }],
          encoding_format: 'float'
        };
      } else {
        payload = {
          model: model.model,
          input: [input],
          input_type: 'query',
          encoding_format: 'float'
        };
      }

      const response = await fetch(`${PROVIDERS.nvidia.baseUrl}/embeddings`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${apiKey}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(payload)
      });

      if (response.ok) {
        const result = await response.json();
        return {
          embedding: result.data[0]?.embedding || [],
          model: 'nvclip',
          provider: 'nvidia',
          dimensions: model.dimensions,
          input: typeof input === 'string' ? input : path.basename(input)
        };
      }
    } catch (err) {
      // Fall through to OpenAI
    }
  }

  // Fallback: OpenAI embeddings (text only)
  const openaiKey = await config.getApiKey('openai');
  if (openaiKey && options.type !== 'image') {
    const response = await fetch(`${PROVIDERS.openai.baseUrl}/embeddings`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${openaiKey}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        model: 'text-embedding-3-small',
        input: input
      })
    });

    if (response.ok) {
      const result = await response.json();
      return {
        embedding: result.data[0]?.embedding || [],
        model: 'text-embedding-3-small',
        provider: 'openai',
        dimensions: 1536,
        input: typeof input === 'string' ? input : path.basename(input)
      };
    }
  }

  throw new Error('No embedding provider available');
}

/**
 * Batch analyze multiple images with fallback
 */
async function batchAnalyze(images, prompt, options = {}) {
  const results = [];
  const concurrency = options.concurrency || 3;

  for (let i = 0; i < images.length; i += concurrency) {
    const batch = images.slice(i, i + concurrency);
    const batchResults = await Promise.all(
      batch.map(img => analyze(img, prompt, options).catch(err => ({
        error: err.message,
        imagePath: img
      })))
    );
    results.push(...batchResults);
  }

  return results;
}

// ═══════════════════════════════════════════════════════════════════
// CONSTRUCTION-SPECIFIC PROMPTS
// ═══════════════════════════════════════════════════════════════════

const PROMPTS = {
  floorPlan: `Analyze this construction floor plan drawing. Extract:
1. Room numbers and names
2. Dimensions (length x width)
3. Door and window locations
4. Wall types (if indicated)
5. Any MEP equipment shown
6. Notes and annotations
Format as structured JSON.`,

  detail: `Analyze this construction detail drawing. Extract:
1. Detail number/reference
2. Scale
3. Materials specified
4. Dimensions
5. Assembly sequence
6. Notes and specifications
Format as structured JSON.`,

  mechanicalPlan: `Analyze this mechanical plan drawing. Extract:
1. Equipment schedule (units, sizes, capacities)
2. Ductwork routing and sizes
3. Diffuser/grille locations
4. Control zones
5. Notes and specifications
Format as structured JSON.`,

  firePlan: `Analyze this fire protection plan drawing. Extract:
1. Standpipe locations and sizes
2. Sprinkler head locations and types
3. Fire pump specifications
4. Hose connections
5. Fire department connections (FDC)
6. Pipe routing and sizes
Format as structured JSON.`,

  schedule: `Extract all data from this schedule/table. Preserve:
1. Column headers
