/**
 * Takeoff Commands
 * 
 * Core takeoff operations using the Hybrid methodology:
 * - Alpha: Bid-structure-first (top-down)
 * - Beta: Document-first (bottom-up) 
 * - Hybrid: Cross-validate both approaches (production methodology)
 */

const fs = require('fs').promises;
const path = require('path');
const chalk = require('chalk');
const ora = require('ora');
const config = require('../lib/config');

const EXPERTS = [
  'mechanical',
  'electrical',
  'plumbing',
  'fire-protection',
  'architectural',
  'structural',
  'civil',
  'general-conditions'
];

async function run(options) {
  const cfg = await config.load();

  if (!cfg.activeProject) {
    console.log(chalk.red('❌ No active project.'));
    process.exit(1);
  }

  const method = options.method || cfg.takeoff?.defaultMethod || 'hybrid';
  const spinner = ora(`Running ${method.toUpperCase()} takeoff...`).start();

  try {
    const projectPath = cfg.activeProject.path;
    const projectFile = path.join(projectPath, 'project.json');
    const project = JSON.parse(await fs.readFile(projectFile, 'utf8'));

    if (options.dryRun) {
      spinner.info('Dry run - no changes will be made');
    }

    // Determine which experts to run
    let expertsToRun = EXPERTS;
    if (options.experts) {
      expertsToRun = options.experts.split(',').map(e => e.trim());
    }

    // Parse item range if specified
    let itemFilter = null;
    if (options.items) {
      itemFilter = parseItemRange(options.items);
    }

    // Initialize results
    const results = {
      method,
      started: new Date().toISOString(),
      experts: {},
      items: {},
      rfis: [],
      discrepancies: [],
      confidence: 0
    };

    // Run based on methodology
    switch (method) {
      case 'alpha':
        await runAlpha(project, results, expertsToRun, itemFilter, spinner, options);
        break;
      case 'beta':
        await runBeta(project, results, expertsToRun, itemFilter, spinner, options);
        break;
      case 'hybrid':
      default:
        await runHybrid(project, results, expertsToRun, itemFilter, spinner, options);
        break;
    }

    results.completed = new Date().toISOString();
    results.duration = new Date(results.completed) - new Date(results.started);

    // Save results
    if (!options.dryRun) {
      project.takeoff = {
        ...project.takeoff,
        method,
        status: 'completed',
        lastRun: results.completed,
        results,
        rfis: results.rfis,
        discrepancies: results.discrepancies
      };

      await fs.writeFile(projectFile, JSON.stringify(project, null, 2));

      // Save detailed results
      const resultsPath = path.join(projectPath, 'takeoff', `takeoff-${Date.now()}.json`);
      await fs.writeFile(resultsPath, JSON.stringify(results, null, 2));
    }

    spinner.succeed(chalk.green(`Takeoff complete (${method.toUpperCase()})`));

    // Summary
    console.log('');
    console.log(chalk.bold('📊 Results:'));
    console.log(`  Method: ${method.toUpperCase()}`);
    console.log(`  Confidence: ${(results.confidence * 100).toFixed(1)}%`);
    console.log(`  Duration: ${(results.duration / 1000).toFixed(1)}s`);
    console.log(`  Experts: ${Object.keys(results.experts).length}`);
    console.log(`  Items: ${Object.keys(results.items).length}`);

    if (results.rfis.length > 0) {
      console.log('');
      console.log(chalk.yellow(`⚠ ${results.rfis.length} RFIs generated`));
    }

    if (results.discrepancies.length > 0) {
      console.log(chalk.yellow(`⚠ ${results.discrepancies.length} discrepancies found`));
    }

    console.log('');
    console.log(chalk.gray('Next: blueprint validate --strict'));
    console.log(chalk.gray('      blueprint export excel -o takeoff.xlsx'));

  } catch (err) {
    spinner.fail(chalk.red(`Takeoff failed: ${err.message}`));
    process.exit(1);
  }
}

// ═══════════════════════════════════════════════════════════════════
// METHODOLOGY IMPLEMENTATIONS
// ═══════════════════════════════════════════════════════════════════

async function runAlpha(project, results, experts, itemFilter, spinner, options) {
  // Alpha: Start with bid structure, validate against documents
  spinner.text = 'ALPHA: Bid-structure-first analysis...';

  // Load bid items
  const bidItems = project.extraction.bidItems || [];

  for (const expert of experts) {
    spinner.text = `ALPHA: Running ${expert} expert...`;

    results.experts[expert] = {
      status: 'completed',
      items: [],
      findings: [],
      confidence: 0.75 // Alpha baseline
    };

    // Filter items for this expert
    const expertItems = bidItems.filter(item => 
      item.expert === expert || !item.expert
    );

    for (const item of expertItems) {
      if (itemFilter && !itemFilter.includes(item.number)) continue;

      results.items[item.number] = {
        description: item.description,
        expert,
        quantity: item.quantity || 'TBD',
        unit: item.unit || 'LS',
        confidence: 0.75,
        method: 'alpha'
      };
    }
  }

  results.confidence = 0.75;
}

async function runBeta(project, results, experts, itemFilter, spinner, options) {
  // Beta: Start with documents, map to bid items
  spinner.text = 'BETA: Document-first analysis...';

  for (const expert of experts) {
    spinner.text = `BETA: Running ${expert} expert...`;

    results.experts[expert] = {
      status: 'completed',
      items: [],
      findings: [],
      confidence: 0.78 // Beta baseline
    };
  }

  results.confidence = 0.78;
}

async function runHybrid(project, results, experts, itemFilter, spinner, options) {
  // Hybrid: Run both, cross-validate, resolve discrepancies
  spinner.text = 'HYBRID: Running dual-pass analysis...';

  // Pass 1: Alpha (bid-first)
  const alphaResults = { experts: {}, items: {}, confidence: 0 };
  await runAlpha(project, alphaResults, experts, itemFilter, 
    { text: (t) => spinner.text = `HYBRID Pass 1: ${t}` }, options);

  // Pass 2: Beta (doc-first)
  const betaResults = { experts: {}, items: {}, confidence: 0 };
  await runBeta(project, betaResults, experts, itemFilter,
    { text: (t) => spinner.text = `HYBRID Pass 2: ${t}` }, options);

  // Pass 3: Cross-validation
  spinner.text = 'HYBRID Pass 3: Cross-validation...';

  const allItems = new Set([
    ...Object.keys(alphaResults.items),
    ...Object.keys(betaResults.items)
  ]);

  for (const itemId of allItems) {
    const alpha = alphaResults.items[itemId];
    const beta = betaResults.items[itemId];

    if (alpha && beta) {
      // Both found - compare and reconcile
      if (alpha.quantity !== beta.quantity) {
        results.discrepancies.push({
          item: itemId,
          type: 'quantity_mismatch',
          alpha: alpha.quantity,
          beta: beta.quantity,
          resolution: 'pending'
        });
      }

      // Hybrid result with boosted confidence
      results.items[itemId] = {
        ...alpha,
        ...beta,
        alphaQuantity: alpha.quantity,
        betaQuantity: beta.quantity,
        quantity: alpha.quantity, // Could implement smart resolution
        confidence: Math.min((alpha.confidence + beta.confidence) / 2 + 0.1, 0.99),
        method: 'hybrid',
        validated: true
      };
    } else if (alpha) {
      // Only alpha found - flag for review
      results.items[itemId] = {
        ...alpha,
        confidence: alpha.confidence * 0.9, // Slight penalty
        method: 'hybrid',
        validated: false,
        note: 'Not found in document-first pass'
      };

      results.rfis.push({
        item: itemId,
        priority: 'medium',
        question: `Verify quantity for ${alpha.description} - not found in document extraction`
      });
    } else if (beta) {
      // Only beta found - flag as potentially missing from bid
      results.items[itemId] = {
        ...beta,
        confidence: beta.confidence * 0.9,
        method: 'hybrid',
        validated: false,
        note: 'Found in documents but not in bid structure'
      };

      results.rfis.push({
        item: itemId,
        priority: 'high',
        question: `Item found in documents but missing from bid breakdown: ${beta.description}`
      });
    }
  }

  // Merge expert results
  for (const expert of experts) {
    results.experts[expert] = {
      alpha: alphaResults.experts[expert],
      beta: betaResults.experts[expert],
      status: 'completed',
      confidence: 0.92 // Hybrid confidence boost
    };
  }

  // Calculate overall confidence
  const itemConfidences = Object.values(results.items).map(i => i.confidence);
  results.confidence = itemConfidences.length > 0
    ? itemConfidences.reduce((a, b) => a + b) / itemConfidences.length
    : 0.92;
}

