// VALIDATION & EXPORT
// ═══════════════════════════════════════════════════════════════════

async function validate(options) {
  const cfg = await config.load();

  if (!cfg.activeProject) {
    console.log(chalk.red('❌ No active project.'));
    process.exit(1);
  }

  const spinner = ora('Validating takeoff...').start();

  try {
    const projectPath = cfg.activeProject.path;
    const projectFile = path.join(projectPath, 'project.json');
    const project = JSON.parse(await fs.readFile(projectFile, 'utf8'));

    if (!project.takeoff?.results) {
      spinner.fail('No takeoff results to validate. Run: blueprint takeoff');
      return;
    }

    const issues = [];
    const results = project.takeoff.results;

    // Check confidence thresholds
    const threshold = options.strict ? 0.85 : 0.70;

    for (const [itemId, item] of Object.entries(results.items)) {
      if (item.confidence < threshold) {
        issues.push({
          type: 'low_confidence',
          item: itemId,
          confidence: item.confidence,
          threshold
        });
      }

      if (!item.validated) {
        issues.push({
          type: 'not_validated',
          item: itemId,
          note: item.note
        });
      }
    }

    // Check for unresolved discrepancies
    for (const disc of results.discrepancies) {
      if (disc.resolution === 'pending') {
        issues.push({
          type: 'unresolved_discrepancy',
          item: disc.item,
          details: disc
        });
      }
    }

    spinner.succeed('Validation complete');

    if (issues.length === 0) {
      console.log(chalk.green('\n✓ All validations passed'));
    } else {
      console.log(chalk.yellow(`\n⚠ ${issues.length} issues found:`));

      for (const issue of issues.slice(0, 10)) {
        console.log(chalk.gray(`  - [${issue.type}] Item ${issue.item}`));
      }

      if (issues.length > 10) {
        console.log(chalk.gray(`  ... and ${issues.length - 10} more`));
      }
    }

  } catch (err) {
    spinner.fail(chalk.red(`Validation failed: ${err.message}`));
  }
}

async function exportResults(format, options) {
  const cfg = await config.load();

  if (!cfg.activeProject) {
    console.log(chalk.red('❌ No active project.'));
    process.exit(1);
  }

  const spinner = ora(`Exporting to ${format}...`).start();

  try {
    const projectPath = cfg.activeProject.path;
    const projectFile = path.join(projectPath, 'project.json');
    const project = JSON.parse(await fs.readFile(projectFile, 'utf8'));

    if (!project.takeoff?.results) {
      spinner.fail('No takeoff results to export. Run: blueprint takeoff');
      return;
    }

    const outputPath = options.output || path.join(
      projectPath, 'exports', 
      `takeoff-${Date.now()}.${format}`
    );

    switch (format) {
      case 'json':
        await fs.writeFile(outputPath, JSON.stringify(project.takeoff.results, null, 2));
        break;

      case 'csv':
        const csv = resultsToCSV(project.takeoff.results);
        await fs.writeFile(outputPath, csv);
        break;

      case 'excel':
        // Would use exceljs or similar
        spinner.info('Excel export requires exceljs package');
        const csvFallback = resultsToCSV(project.takeoff.results);
        const csvPath = outputPath.replace('.xlsx', '.csv');
        await fs.writeFile(csvPath, csvFallback);
        spinner.succeed(`Exported to CSV: ${csvPath}`);
        return;

      case 'pdf':
        spinner.info('PDF export coming soon');
        return;

      default:
        spinner.fail(`Unknown format: ${format}`);
        return;
    }

    spinner.succeed(`Exported to: ${outputPath}`);

  } catch (err) {
    spinner.fail(chalk.red(`Export failed: ${err.message}`));
  }
}

function resultsToCSV(results) {
  const headers = ['Item', 'Description', 'Quantity', 'Unit', 'Expert', 'Confidence', 'Validated', 'Method'];
  const rows = [headers.join(',')];

  for (const [itemId, item] of Object.entries(results.items)) {
    rows.push([
      itemId,
      `"${(item.description || '').replace(/"/g, '""')}"`,
      item.quantity,
      item.unit,
      item.expert,
      item.confidence?.toFixed(2),
      item.validated ? 'Yes' : 'No',
      item.method
    ].join(','));
  }

  return rows.join('\n');
}

function parseItemRange(rangeStr) {
  const items = [];

  for (const part of rangeStr.split(',')) {
    if (part.includes('-')) {
      const [start, end] = part.split('-').map(Number);
      for (let i = start; i <= end; i++) {
        items.push(i.toString());
      }
    } else {
      items.push(part.trim());
    }
  }

  return items;
}

module.exports = {
  run,
  validate,
  export: exportResults
};

