function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

async function runDemo() {
  if (demoRunning) return;
  demoRunning = true;

  const sowEl = document.getElementById('demo-sow');
  const cursorEl = document.getElementById('demo-cursor');
  const resultsEl = document.getElementById('demo-results');

  // Reset
  sowEl.textContent = '';
  cursorEl.style.display = 'inline';
  resultsEl.innerHTML = `
    <div class="demo-placeholder">
      <div class="demo-spinner"></div>
      <span>Waiting for scope input...</span>
    </div>`;

  // Type SOW text
  for (let i = 0; i < SOW_TEXT.length; i++) {
    sowEl.textContent += SOW_TEXT[i];
    await sleep(18);
  }

  cursorEl.style.display = 'none';
  await sleep(400);

  // Show processing
  resultsEl.innerHTML = `
    <div class="demo-placeholder">
      <div class="demo-spinner"></div>
      <span>Planner analyzing scope...</span>
    </div>`;
  await sleep(800);

  resultsEl.innerHTML = `
    <div class="demo-placeholder">
      <div class="demo-spinner"></div>
      <span>Executor mapping to UPB...</span>
    </div>`;
  await sleep(800);

  resultsEl.innerHTML = `
    <div class="demo-placeholder">
      <div class="demo-spinner"></div>
      <span>Critic reviewing mappings...</span>
    </div>`;
  await sleep(600);

  // Build results
  resultsEl.innerHTML = '';
  for (let i = 0; i < LINE_ITEMS.length; i++) {
    const item = LINE_ITEMS[i];
    const el = document.createElement('div');
    el.className = 'demo-line-item';
    el.innerHTML = `
      <div class="demo-line-code">${item.code}</div>
      <div class="demo-line-desc">${item.desc} — ${item.qty}</div>
      <div class="demo-line-meta">
        <span class="demo-line-confidence">✓ ${item.confidence}% confidence</span>
        <span class="demo-line-source">${item.source}</span>
      </div>`;
    resultsEl.appendChild(el);
    await sleep(100);
    el.classList.add('visible');
    await sleep(500);
  }

  demoRunning = false;
}

document.getElementById('demo-run').addEventListener('click', runDemo);
document.getElementById('demo-reset').addEventListener('click', resetDemo);

// Auto-run demo when scrolled into view
const demoSection = document.getElementById('demo');
let demoAutoRan = false;
const demoObserver = new IntersectionObserver((entries) => {
  if (entries[0].isIntersecting && !demoAutoRan && !demoRunning) {
    demoAutoRan = true;
    setTimeout(runDemo, 500);
  }
}, { threshold: 0.3 });
demoObserver.observe(demoSection);

*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --bg: #0a0a0b;
  --bg2: #111113;
  --surface: #18181b;
  --border: #27272a;
  --text: #fafafa;
  --text2: #a1a1aa;
  --accent: #6366f1;
  --accent2: #8b5cf6;
  --green: #22c55e;
  --amber: #f59e0b;
  --radius: 12px;
}

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

.container { max-width: 1100px; margin: 0 auto; padding: 0 24px; }

/* Fade-in on scroll */
.fade-in {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity .6s ease, transform .6s ease;
}
.fade-in.visible {
  opacity: 1;
  transform: translateY(0);
}

/* Nav */
.nav {
  position: fixed; top: 0; left: 0; right: 0; z-index: 100;
