.logo { display: flex; align-items: center; gap: 10px; font-weight: 700; font-size: 1.1rem; }

/* Buttons */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  padding: 10px 20px; border-radius: 8px; font-weight: 600; font-size: .9rem;
  text-decoration: none; border: none; cursor: pointer;
  background: var(--accent); color: #fff;
  transition: all .2s;
}
.btn:hover { background: var(--accent2); transform: translateY(-1px); }
.btn-sm { padding: 8px 16px; font-size: .85rem; }
.btn-lg { padding: 14px 28px; font-size: 1rem; }
.btn-full { width: 100%; }
.btn-ghost { background: transparent; border: 1px solid var(--border); color: var(--text2); }
.btn-ghost:hover { background: var(--surface); color: var(--text); }

/* Hero */
.hero {
  position: relative; padding: 160px 0 100px; text-align: center;
  overflow: hidden;
}
.hero-glow {
  position: absolute; top: -200px; left: 50%; transform: translateX(-50%);
  width: 800px; height: 600px;
  background: radial-gradient(ellipse, rgba(99,102,241,.15) 0%, transparent 70%);
  pointer-events: none;
}
.badge {
  display: inline-block; padding: 6px 16px; border-radius: 20px;
  background: rgba(99,102,241,.1); border: 1px solid rgba(99,102,241,.3);
  color: var(--accent); font-size: .85rem; font-weight: 500; margin-bottom: 24px;
}
.hero h1 { font-size: clamp(2.2rem, 5vw, 3.5rem); font-weight: 800; line-height: 1.15; letter-spacing: -.03em; margin-bottom: 20px; }
.hero-sub { font-size: 1.15rem; color: var(--text2); max-width: 600px; margin: 0 auto 32px; }
.hero-cta { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; margin-bottom: 24px; }
.hero-note { font-size: .85rem; color: var(--text2); }

/* Sections */
.section { padding: 100px 0; }
.section-dark { background: var(--bg2); }
.section-label {
  font-size: .8rem; font-weight: 600; text-transform: uppercase; letter-spacing: .1em;
  color: var(--accent); margin-bottom: 12px;
}
.section h2 { font-size: clamp(1.8rem, 3.5vw, 2.5rem); font-weight: 800; letter-spacing: -.02em; margin-bottom: 16px; }
.section-sub { font-size: 1.05rem; color: var(--text2); max-width: 600px; margin-bottom: 48px; }

/* Pain Grid */
.pain-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 20px; }
.pain-card {
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
  padding: 28px;

