.pain-icon { font-size: 1.5rem; margin-bottom: 12px; }
.pain-card h3 { font-size: 1.05rem; font-weight: 700; margin-bottom: 8px; }
.pain-card p { font-size: .9rem; color: var(--text2); }

/* Solution Grid */
.solution-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 20px; }
.solution-card {
  background: rgba(99,102,241,.05); border: 1px solid rgba(99,102,241,.15); border-radius: var(--radius);
  padding: 32px;
}
.solution-card h3 { font-size: 1.1rem; font-weight: 700; margin-bottom: 8px; }
.solution-card p { font-size: .9rem; color: var(--text2); }

/* Interactive Demo */
.demo-container {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  gap: 0;
  align-items: stretch;
  margin-bottom: 24px;
}
.demo-panel {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
}
.demo-panel-header {
  display: flex; align-items: center; gap: 6px;
  padding: 10px 16px;
  background: rgba(255,255,255,.03);
  border-bottom: 1px solid var(--border);
}
.demo-dot { width: 10px; height: 10px; border-radius: 50%; }
.demo-dot.red { background: #ef4444; }
.demo-dot.yellow { background: #f59e0b; }
.demo-dot.green { background: #22c55e; }
.demo-panel-title { margin-left: 8px; font-size: .75rem; color: var(--text2); font-weight: 500; text-transform: uppercase; letter-spacing: .05em; }
.demo-panel-body { padding: 20px; min-height: 220px; font-family: 'JetBrains Mono', monospace; font-size: .85rem; line-height: 1.7; color: var(--text2); }
.demo-sow { display: inline; }
.demo-cursor { display: inline; color: var(--accent); animation: blink 1s step-end infinite; }
@keyframes blink { 50% { opacity: 0; } }

.demo-arrow {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  padding: 0 20px; gap: 8px;
}
.demo-arrow-line { width: 2px; height: 40px; background: var(--border); }
.demo-arrow-label { font-size: .7rem; color: var(--accent); font-weight: 600; text-transform: uppercase; letter-spacing: .05em; writing-mode: vertical-rl; text-orientation: mixed; }

.demo-placeholder { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 12px; height: 100%; min-height: 180px; color: var(--text2); font-family: 'Inter', sans-serif; font-size: .85rem; }
.demo-spinner { width: 24px; height: 24px; border: 2px solid var(--border); border-top-color: var(--accent); border-radius: 50%; animation: spin 1s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }

.demo-line-item {
  opacity: 0; transform: translateX(-12px);
  transition: opacity .4s ease, transform .4s ease;
  padding: 12px 0;
  border-bottom: 1px solid var(--border);
  font-family: 'Inter', sans-serif;
}
.demo-line-item.visible { opacity: 1; transform: translateX(0); }
.demo-line-item:last-child { border-bottom: none; }
.demo-line-code { font-family: 'JetBrains Mono', monospace; font-size: .8rem; color: var(--accent); font-weight: 500; }
.demo-line-desc { font-size: .85rem; color: var(--text); margin: 2px 0; }
.demo-line-meta { display: flex; gap: 16px; font-size: .75rem; color: var(--text2); }
.demo-line-confidence { color: var(--green); font-weight: 600; }
.demo-line-source { color: var(--amber); }

.demo-controls { display: flex; gap: 8px; justify-content: center; }

/* Pipeline / Team of Rivals */
.pipeline {
  display: flex; align-items: flex-start; justify-content: center;
  gap: 0; margin-bottom: 48px;
}
.pipeline-stage {
  flex: 1; max-width: 280px; text-align: center; padding: 0 16px;
}
.pipeline-icon {
  width: 64px; height: 64px; border-radius: 16px;
  display: flex; align-items: center; justify-content: center;
  margin: 0 auto 16px;
  position: relative;
}
.pipeline-icon.planner { background: rgba(99,102,241,.15); color: var(--accent); }
.pipeline-icon.executor { background: rgba(139,92,246,.15); color: var(--accent2); }
.pipeline-icon.critic { background: rgba(245,158,11,.15); color: var(--amber); }

.pipeline-icon::after {
  content: '';
  position: absolute;
  inset: -3px;
  border-radius: 18px;
  border: 2px solid transparent;
  animation: pulse-border 2s ease-in-out infinite;
}
.pipeline-icon.planner::after { border-color: rgba(99,102,241,.3); animation-delay: 0s; }
.pipeline-icon.executor::after { border-color: rgba(139,92,246,.3); animation-delay: .6s; }
.pipeline-icon.critic::after { border-color: rgba(245,158,11,.3); animation-delay: 1.2s; }

@keyframes pulse-border {
  0%, 100% { opacity: .3; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.05); }
}

.pipeline-stage h3 { font-size: 1.1rem; font-weight: 700; margin-bottom: 8px; }
.pipeline-stage p { font-size: .88rem; color: var(--text2); }

.pipeline-connector {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  padding-top: 28px; width: 48px; flex-shrink: 0;
}
.pipeline-connector-line { width: 100%; height: 2px; background: linear-gradient(90deg, var(--accent), var(--accent2)); position: relative; }
.pipeline-connector-dot {
  width: 8px; height: 8px; border-radius: 50%; background: var(--accent);
  margin-top: -5px;
  animation: flow-dot 2s ease-in-out infinite;
}
@keyframes flow-dot {
  0% { transform: translateX(-20px); opacity: 0; }
  50% { opacity: 1; }
  100% { transform: translateX(20px); opacity: 0; }
}

.pipeline-stats {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-bottom: 32px;
  text-align: center;
}
.stat-value { font-size: 2rem; font-weight: 800; background: linear-gradient(135deg, var(--accent), var(--accent2)); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }
.stat-label { font-size: .85rem; color: var(--text2); margin-top: 4px; }

.pipeline-note {
  text-align: center; font-size: .85rem; color: var(--text2); max-width: 600px; margin: 0 auto;
  font-style: italic;
}

/* Steps */
.steps { display: flex; align-items: flex-start; gap: 0; flex-wrap: wrap; justify-content: center; }
.step { flex: 1; min-width: 220px; max-width: 300px; text-align: center; padding: 0 20px; }
.step-num {
  width: 48px; height: 48px; border-radius: 50%;
  background: linear-gradient(135deg, var(--accent), var(--accent2));
  display: flex; align-items: center; justify-content: center;
  font-weight: 800; font-size: 1.2rem; margin: 0 auto 16px;
}
.step h3 { font-size: 1.05rem; font-weight: 700; margin-bottom: 8px; }
.step p { font-size: .9rem; color: var(--text2); }

