#!/usr/bin/env node
/**
 * JOC Translator Financial Calculator
 * Run: node calculator.js
 */

const readline = require('readline');
const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

// Default assumptions
let assumptions = {
  pricePerMonth: 300,
  customersMonth1: 3,
  growthRate: 0.15, // 15% monthly growth
  churnRate: 0.05, // 5% monthly churn
  infraCost: 320,
  costPerCustomer: 20,
  targetMRR: 15000
};

function formatMoney(amount) {
  return '$' + Math.round(amount).toLocaleString();
}

function calculateProjection(months = 12) {
  let customers = assumptions.customersMonth1;
  let mrr = customers * assumptions.pricePerMonth;
  let results = [];

  for (let m = 1; m <= months; m++) {
    // Apply churn
    customers = customers * (1 - assumptions.churnRate);

    // Apply growth (new customers)
    let newCustomers = customers * assumptions.growthRate;
    customers += newCustomers;

    mrr = customers * assumptions.pricePerMonth;
    let costs = assumptions.infraCost + (customers * assumptions.costPerCustomer);
    let profit = mrr - costs;

    results.push({
      month: m,
      customers: Math.round(customers),
      mrr: mrr,
      costs: costs,
      profit: profit
    });
  }

  return results;
}

function printDashboard() {
  console.log('\n' + '='.repeat(60));
  console.log('💰 JOC TRANSLATOR FINANCIAL CALCULATOR');
  console.log('='.repeat(60));

  console.log('\n📊 CURRENT ASSUMPTIONS:');
  console.log(`  Price per customer: ${formatMoney(assumptions.pricePerMonth)}/mo`);
  console.log(`  Starting customers: ${assumptions.customersMonth1}`);
  console.log(`  Monthly growth rate: ${(assumptions.growthRate * 100).toFixed(0)}%`);
  console.log(`  Monthly churn rate: ${(assumptions.churnRate * 100).toFixed(0)}%`);
  console.log(`  Infrastructure cost: ${formatMoney(assumptions.infraCost)}/mo`);
  console.log(`  Cost per customer: ${formatMoney(assumptions.costPerCustomer)}/mo`);
  console.log(`  🎯 Target MRR: ${formatMoney(assumptions.targetMRR)}/mo`);

  const projection = calculateProjection(24);

  console.log('\n📈 12-MONTH PROJECTION:');
  console.log('-'.repeat(60));
  console.log('Month | Customers | MRR      | Costs    | Profit   ');
  console.log('-'.repeat(60));

  let totalRevenue = 0;
  let totalProfit = 0;
  let targetMonth = null;

  for (let i = 0; i < 12; i++) {
    const p = projection[i];
    totalRevenue += p.mrr;
    totalProfit += p.profit;

    if (!targetMonth && p.mrr >= assumptions.targetMRR) {
      targetMonth = p.month;
    }

    if (i % 3 === 0 || i === 11) {
      console.log(
        `  ${p.month.toString().padStart(2)}   | ` +
        `${p.customers.toString().padStart(9)} | ` +
        `${formatMoney(p.mrr).padStart(8)} | ` +
        `${formatMoney(p.costs).padStart(8)} | ` +
        `${formatMoney(p.profit).padStart(8)}`
      );
    }
  }

  console.log('-'.repeat(60));
  console.log(`Year 1 Total Revenue: ${formatMoney(totalRevenue)}`);
  console.log(`Year 1 Total Profit:  ${formatMoney(totalProfit)}`);

  if (targetMonth) {
    console.log(`\n🎯 Target MRR (${formatMoney(assumptions.targetMRR)}) reached in Month ${targetMonth}!`);
  } else {
    const lastMRR = projection[projection.length - 1].mrr;
    console.log(`\n⚠️  Target MRR not reached in 12 months. Ending MRR: ${formatMoney(lastMRR)}`);
  }

  // Break-even analysis
  const breakEvenCustomers = assumptions.infraCost / (assumptions.pricePerMonth - assumptions.costPerCustomer);
  console.log(`\n💡 Break-even: ${Math.ceil(breakEvenCustomers)} paying customers`);

  // LTV calculation
  const avgLifetime = 1 / assumptions.churnRate;
  const ltv = assumptions.pricePerMonth * avgLifetime * 0.9; // 90% gross margin
  console.log(`💎 Customer LTV: ${formatMoney(ltv)} (avg lifetime: ${avgLifetime.toFixed(1)} months)`);
}

function askQuestion(question) {
  return new Promise(resolve => {
    rl.question(question, answer => resolve(answer));
  });
}

async function interactiveMode() {
  printDashboard();

  while (true) {
    console.log('\n' + '='.repeat(60));
    console.log('OPTIONS:');
    console.log('  1. Change price per customer');
    console.log('  2. Change starting customers');
    console.log('  3. Change growth rate');
    console.log('  4. Change churn rate');
    console.log('  5. Change target MRR');
    console.log('  6. View 24-month projection');
    console.log('  7. Run sensitivity analysis');
    console.log('  8. Exit');
    console.log('='.repeat(60));

    const choice = await askQuestion('\nSelect option (1-8): ');

    switch(choice.trim()) {
      case '1':
        const price = await askQuestion('New price per customer ($): ');
        assumptions.pricePerMonth = parseFloat(price) || 300;
        break;
      case '2':
        const start = await askQuestion('Starting customers: ');
        assumptions.customersMonth1 = parseInt(start) || 3;
        break;
      case '3':
        const growth = await askQuestion('Monthly growth rate (%): ');
        assumptions.growthRate = (parseFloat(growth) || 15) / 100;
        break;
      case '4':
        const churn = await askQuestion('Monthly churn rate (%): ');
        assumptions.churnRate = (parseFloat(churn) || 5) / 100;
        break;
      case '5':
        const target = await askQuestion('Target MRR ($): ');
        assumptions.targetMRR = parseFloat(target) || 15000;
        break;
      case '6':
        console.log('\n📈 24-MONTH PROJECTION:');
        console.log('-'.repeat(70));
        console.log('Month | Customers | MRR       | Costs     | Profit    ');
        console.log('-'.repeat(70));
        const longProj = calculateProjection(24);
        longProj.forEach((p, i) => {
          if (i % 2 === 0 || i === 23) {
            console.log(
              `  ${p.month.toString().padStart(2)}   | ` +
              `${p.customers.toString().padStart(9)} | ` +
              `${formatMoney(p.mrr).padStart(9)} | ` +
              `${formatMoney(p.costs).padStart(9)} | ` +
              `${formatMoney(p.profit).padStart(9)}`
            );
          }
        });
        console.log('-'.repeat(70));
        break;
      case '7':
        console.log('\n🧪 SENSITIVITY ANALYSIS:');
        console.log('Testing impact of growth rate on Month 12 MRR...');
        console.log('-'.repeat(50));
        const originalGrowth = assumptions.growthRate;
        [0.05, 0.10, 0.15, 0.20, 0.25].forEach(g => {
          assumptions.growthRate = g;
          const proj = calculateProjection(12);
          const m12 = proj[11];
          console.log(`  Growth ${(g*100).toString().padStart(2)}%: ` +
            `${m12.customers.toString().padStart(3)} customers, ` +
            `${formatMoney(m12.mrr).padStart(8)} MRR`);
        });
        assumptions.growthRate = originalGrowth;
        break;
      case '8':
        console.log('\n👋 Happy calculating!');
        rl.close();
        return;
      default:
        console.log('Invalid option');
    }

    printDashboard();
  }
}

// Run if called directly
if (require.main === module) {
  interactiveMode();
}

module.exports = { calculateProjection, assumptions };

