import { useState } from 'react';
import { api } from '../lib/api';
import { useApi } from '../hooks/useApi';
import Card from '../components/Card';
import MarkdownViewer from '../components/MarkdownViewer';
import { FolderOpen, Clock, FileText, ExternalLink, ChevronDown, ChevronUp, Zap } from 'lucide-react';

const statusConfig: Record<string, { color: string; dot: string; label: string }> = {
  active: { color: 'bg-green-500/20 text-green-400', dot: 'bg-green-500', label: 'Active' },
  beta: { color: 'bg-yellow-500/20 text-yellow-400', dot: 'bg-yellow-500', label: 'Beta' },
  'landing-page': { color: 'bg-blue-500/20 text-blue-400', dot: 'bg-blue-500', label: 'Landing Page' },
  planned: { color: 'bg-dark-500/20 text-dark-400', dot: 'bg-dark-500', label: 'Planned' },
};

function ProjectCard({ project, onViewDoc }: { project: any; onViewDoc: (label: string, path: string) => void }) {
  const [expanded, setExpanded] = useState(false);
  const s = statusConfig[project.status] || statusConfig.active;
  const hasDetails = project.highlights?.length || project.links?.length || Object.keys(project.stats || {}).length;

  return (
    <Card
      className="hover:border-gold-700/50 transition-all duration-200 cursor-pointer"
      onClick={() => hasDetails && setExpanded(!expanded)}
    >
      <div className="flex items-start justify-between mb-2">
        <div className="flex items-center gap-2">
          <FolderOpen size={18} className="text-gold-500" />
          <h3 className="text-lg font-semibold text-white">{project.name}</h3>
        </div>
        <div className="flex items-center gap-2">
          <span className={`inline-flex items-center gap-1.5 text-xs px-2 py-0.5 rounded-full ${s.color}`}>
            <span className={`w-1.5 h-1.5 rounded-full ${s.dot}`} />
            {s.label}
          </span>
          {hasDetails && (
            expanded ? <ChevronUp size={16} className="text-dark-500" /> : <ChevronDown size={16} className="text-dark-500" />
          )}
        </div>
      </div>

      <p className="text-sm text-dark-400 mb-3">
        {expanded ? project.description : (project.description?.slice(0, 120) + (project.description?.length > 120 ? '...' : ''))}
      </p>

      {/* Tech tags */}
      {project.tech?.length > 0 && (
        <div className="flex flex-wrap gap-1.5 mb-3">
          {project.tech.map((t: string) => (
            <span key={t} className="text-xs px-2 py-0.5 rounded bg-dark-700 text-dark-300">
              {t}
            </span>
          ))}
        </div>
      )}

      {/* Basic info row */}
      <div className="flex items-center gap-4 text-xs text-dark-500">
        {project.lastActivity && (
          <span className="flex items-center gap-1">
            <Clock size={12} />
            {project.lastActivity}
          </span>
        )}
        {project.fileCount > 0 && (
          <span className="flex items-center gap-1">
            <FileText size={12} />
            {project.fileCount} files
          </span>
        )}
      </div>

      {/* Expanded details */}
      {expanded && (
        <div className="mt-4 pt-4 border-t border-dark-700 space-y-3 animate-in fade-in">
          {/* Stats */}
          {Object.keys(project.stats || {}).length > 0 && (
            <div className="flex flex-wrap gap-3">
              {Object.entries(project.stats).map(([key, val]) => (
                <div key={key} className="bg-dark-700/50 rounded px-3 py-1.5">
                  <div className="text-lg font-bold text-gold-400">{String(val)}</div>
                  <div className="text-xs text-dark-500">{key.replace(/_/g, ' ')}</div>
                </div>
              ))}
            </div>
          )}

          {/* Highlights */}
          {project.highlights?.length > 0 && (
            <div>
              <ul className="space-y-1">
                {project.highlights.map((h: string, i: number) => (
                  <li key={i} className="flex items-start gap-2 text-sm text-dark-300">
                    <Zap size={12} className="text-gold-500 mt-1 shrink-0" />
                    {h}
                  </li>
                ))}
              </ul>
            </div>
          )}

          {/* Links */}
          {project.links?.length > 0 && (
            <div className="flex flex-wrap gap-2">
              {project.links.map((l: any, i: number) => (
                l.url ? (
                  <a
                    key={i}
                    href={l.url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex items-center gap-1 text-xs px-2.5 py-1 rounded bg-gold-500/10 text-gold-400 hover:bg-gold-500/20 transition-colors"
                    onClick={(e) => e.stopPropagation()}
                  >
                    <ExternalLink size={11} />
                    {l.label}
                  </a>
                ) : l.path ? (
                  <button
                    key={i}
                    className="inline-flex items-center gap-1 text-xs px-2.5 py-1 rounded bg-dark-700 text-dark-300 hover:bg-dark-600 transition-colors"
                    onClick={(e) => { e.stopPropagation(); onViewDoc(l.label, l.path); }}
                  >
                    <FileText size={11} />
                    {l.label}
                  </button>
                ) : (
                  <span key={i} className="inline-flex items-center gap-1 text-xs px-2.5 py-1 rounded bg-dark-700 text-dark-400">
                    <FileText size={11} />
                    {l.label}
                  </span>
                )
              ))}
            </div>
          )}
        </div>
      )}
    </Card>
  );
}

export default function Projects() {
  const { data, loading } = useApi(api.projects);
  const [viewingDoc, setViewingDoc] = useState<{ name: string; content: string } | null>(null);

  const openDoc = async (label: string, path: string) => {
    try {
      const res = await fetch(`/api/documents/custom?path=${encodeURIComponent(path)}`);
      const data = await res.json();
      setViewingDoc({ name: label, content: data.content });
    } catch {
      setViewingDoc({ name: label, content: '# Error\n\nFailed to load document.' });
    }
  };

  return (
    <div className="space-y-6">
      <h1 className="text-2xl font-bold text-white">Projects</h1>
      {loading ? (
        <p className="text-dark-500">Loading...</p>
      ) : (
        <div className="grid md:grid-cols-2 gap-4">
          {data?.map((p: any) => (
            <ProjectCard key={p.dirName || p.name} project={p} onViewDoc={openDoc} />
