import express from 'express';
import cors from 'cors';
import { readdir, readFile, stat } from 'fs/promises';
import { join, resolve } from 'path';
import { execSync } from 'child_process';
import { existsSync } from 'fs';

const app = express();
app.use(cors());
app.use(express.json());

const CLAWD = resolve('/home/ec2-user/clawd');
const SESSIONS = resolve('/home/ec2-user/.clawdbot/agents/main/sessions');
const REPORTS = join(CLAWD, 'projects/sasha-job-search/reports');
const MEMORY = join(CLAWD, 'memory');
const SKILLS = join(CLAWD, 'skills');
const PROJECTS = join(CLAWD, 'projects');

// --- Status ---
app.get('/api/status', async (req, res) => {
  try {
    let uptime = 'unknown';
    try { uptime = execSync('uptime -p', { encoding: 'utf8' }).trim(); } catch {}

    const models = ['claude-opus-4-5', 'claude-sonnet-4', 'gpt-4o'];

    let skillsCount = 0;
    try {
      const skills = await readdir(SKILLS);
      skillsCount = skills.filter(s => !s.startsWith('.')).length;
    } catch {}

    let memoryFilesCount = 0;
    try {
      const mfiles = await readdir(MEMORY);
      memoryFilesCount = mfiles.filter(f => f.endsWith('.md')).length;
    } catch {}

    // Dynamic projects list
    let projects = [];
    try {
      const entries = await readdir(PROJECTS, { withFileTypes: true });
      projects = entries.filter(e => e.isDirectory() && !e.name.startsWith('.')).map(e => e.name);
    } catch {}

    res.json({ uptime, models, skillsCount, memoryFilesCount, projects });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// --- Projects (dynamic + meta) ---
app.get('/api/projects', async (req, res) => {
  try {
    // Load meta config
    let meta = {};
    try {
      meta = JSON.parse(await readFile(join(PROJECTS, 'projects-meta.json'), 'utf8'));
    } catch {}

    const hidden = meta._hidden || [];
    const entries = await readdir(PROJECTS, { withFileTypes: true });
    const dirs = entries.filter(e => e.isDirectory() && !e.name.startsWith('.') && !hidden.includes(e.name));

    const projects = await Promise.all(dirs.map(async (d) => {
      const dirPath = join(PROJECTS, d.name);
      const s = await stat(dirPath);

      let fileCount = 0;
      try {
        const files = await readdir(dirPath);
        fileCount = files.filter(f => !f.startsWith('.') && f !== 'node_modules').length;
      } catch {}

      const m = meta[d.name];

      if (m) {
        // Resolve dynamic links
        const resolvedLinks = (m.links || []).map(link => {
          // Resolve tunnel URLs dynamically
          if (link.url && link.url.startsWith('/api/links/tunnel/')) {
            const tunnelName = link.url.split('/').pop();
            try {
              const logPath = `/home/ec2-user/.pm2/logs/${tunnelName}-error.log`;
              const log = require('fs').readFileSync(logPath, 'utf8');
              const matches = log.match(/https:\/\/[^\s]*trycloudflare\.com/g);
              if (matches) link = { ...link, url: matches[matches.length - 1] };
            } catch {}
          }
          // Resolve "latest" report paths
          if (link.path && link.path.endsWith('/latest')) {
            const dir = link.path.replace('/latest', '');
            try {
              const files = require('fs').readdirSync(dir).filter(f => f.endsWith('.md')).sort();
              if (files.length) link = { ...link, path: join(dir, files[files.length - 1]) };
            } catch {}
          }
          return link;
        });
        return {
          dirName: d.name,
          name: m.name || d.name,
          description: m.description || '',
          status: m.status || 'active',
          tech: m.tech || [],
          links: resolvedLinks,
          stats: m.stats || {},
          highlights: m.highlights || [],
          lastActivity: s.mtime.toISOString().slice(0, 10),
          fileCount,
        };
      }

      const prettyName = d.name.replace(/-/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
      let description = '';
      for (const readmeFile of ['README.md', 'project-brief.md']) {
        try {
          const content = await readFile(join(dirPath, readmeFile), 'utf8');
          const lines = content.split('\n').filter(l => l.trim() && !l.startsWith('#'));
          description = lines[0]?.trim().slice(0, 120) || '';
          if (description) break;
        } catch {}
      }

      return {
        dirName: d.name,
        name: prettyName,
        description: description || `Project: ${d.name}`,
        status: 'active',
        tech: [],
        links: [],
        stats: {},
        highlights: [],
        lastActivity: s.mtime.toISOString().slice(0, 10),
        fileCount,
      };
    }));

    res.json(projects);
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// --- Investments ---
app.get('/api/investments', async (req, res) => {
  const symbols = [
    { symbol: 'SI=F', name: 'Silver Futures', currency: 'USD' },
    { symbol: 'SILJ', name: 'SILJ ETF (Junior Silver Miners)', currency: 'USD' },
    { symbol: 'GSVRF', name: 'Guanajuato Silver', currency: 'USD' },
  ];

  try {
    const results = await Promise.all(symbols.map(async (s) => {
      try {
        const url = `https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(s.symbol)}?range=1mo&interval=1d`;
        const resp = await fetch(url, { headers: { 'User-Agent': 'Mozilla/5.0' } });
        const data = await resp.json();
        const result = data.chart?.result?.[0];
        if (!result) throw new Error('No data');
        const meta = result.meta;
        const closes = result.indicators?.quote?.[0]?.close?.filter(Boolean) || [];
        const price = meta.regularMarketPrice || closes[closes.length - 1] || 0;
        const prevClose = meta.chartPreviousClose || closes[closes.length - 2] || price;
        const change = price - prevClose;
        const changePercent = prevClose ? (change / prevClose) * 100 : 0;
        return { ...s, price, change, changePercent, history: closes.slice(-20) };
      } catch {
        return { ...s, price: 0, change: 0, changePercent: 0, history: [] };
      }
    }));
    res.json(results);
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// --- Cost Tracker (fixed to parse nested usage.cost.total) ---
app.get('/api/costs', async (req, res) => {
  try {
    const dailyMap = {};
    const modelMap = {};
    let cumulative = 0;

    let sessionFiles = [];
    try {
      const entries = await readdir(SESSIONS);
      sessionFiles = entries.filter(f => f.endsWith('.jsonl')).sort();
    } catch {}

    for (const file of sessionFiles.slice(-50)) {
      try {
        const content = await readFile(join(SESSIONS, file), 'utf8');
        for (const line of content.split('\n')) {
          if (!line.trim()) continue;
          try {
            const entry = JSON.parse(line);

            // Cost can be in multiple places:
            // 1. entry.message.usage.cost.total (clawdbot format)
            // 2. entry.costUsd / entry.cost_usd (legacy)
            // 3. entry.usage.cost (flat)
            let cost = 0;
            let model = 'unknown';
            let timestamp = entry.timestamp || '';

            const msg = entry.message;
            if (msg && msg.usage && msg.usage.cost && typeof msg.usage.cost === 'object') {
              cost = msg.usage.cost.total || 0;
              model = msg.model || msg.provider || 'unknown';
              timestamp = msg.timestamp ? new Date(msg.timestamp).toISOString() : timestamp;
            } else if (entry.costUsd || entry.cost_usd) {
              cost = entry.costUsd || entry.cost_usd || 0;
              model = entry.model || 'unknown';
            } else if (entry.usage && typeof entry.usage.cost === 'number') {
              cost = entry.usage.cost;
              model = entry.model || 'unknown';
            }

            if (cost <= 0) continue;

            const date = (timestamp || '').slice(0, 10) || 'unknown';

            dailyMap[date] = (dailyMap[date] || 0) + cost;
            if (!modelMap[model]) modelMap[model] = { cost: 0, calls: 0 };
            modelMap[model].cost += cost;
            modelMap[model].calls += 1;
            cumulative += cost;
          } catch {}
        }
      } catch {}
    }

    const daily = Object.entries(dailyMap).sort().map(([date, cost]) => ({ date, cost }));
    const byModel = Object.entries(modelMap).map(([model, v]) => ({ model, ...v })).sort((a, b) => b.cost - a.cost);

    res.json({ daily, cumulative, byModel });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// --- Job Reports ---
app.get('/api/jobs', async (req, res) => {
  try {
    let files = [];
    try {
      const entries = await readdir(REPORTS);
      files = entries.filter(f => f.endsWith('.md') || f.endsWith('.txt') || f.endsWith('.json')).sort().reverse();
    } catch {}

    if (files.length === 0) {
      return res.json({ empty: true, message: 'No reports yet — job scan runs daily at 6AM ET' });
    }

    const reports = [];
    for (const f of files.slice(0, 20)) {
      try {
        const content = await readFile(join(REPORTS, f), 'utf8');
        const listingsMatch = content.match(/(\d+)\s*(?:listings?|jobs?|positions?|postings?)/i);
        const verifiedMatch = content.match(/(\d+)\s*verified/i) || content.match(/✅\s*Verified[^:]*:\s*(\d+)/i);
        const dateMatch = f.match(/(\d{4}-\d{2}-\d{2})/);
        reports.push({
          filename: f,
          date: dateMatch ? dateMatch[1] : 'unknown',
          listings: listingsMatch ? parseInt(listingsMatch[1]) : 0,
          verified: verifiedMatch ? parseInt(verifiedMatch[1]) : 0,
        });
      } catch {}
    }
    res.json(reports);
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.get('/api/jobs/:filename', async (req, res) => {
  try {
    const safe = req.params.filename.replace(/[^a-zA-Z0-9._-]/g, '');
    const content = await readFile(join(REPORTS, safe), 'utf8');
    res.json({ filename: safe, content });
  } catch (e) {
    res.status(404).json({ error: 'Report not found' });
  }
});

// --- Memory ---
app.get('/api/memory', async (req, res) => {
  try {
    const files = [];

    try {
      const content = await readFile(join(CLAWD, 'MEMORY.md'), 'utf8');
      files.push({ name: 'MEMORY.md', path: 'MEMORY.md', content });
