    let filePath = req.query.path;
    if (!filePath || !filePath.startsWith('/home/ec2-user/clawd/')) {
      return res.status(403).json({ error: 'Access denied' });
    }
    // Resolve "/latest" — find newest file in parent directory
    if (filePath.endsWith('/latest')) {
      const dir = filePath.replace('/latest', '');
      try {
        const files = (await readdir(dir)).filter(f => f.endsWith('.md') || f.endsWith('.txt')).sort();
        if (files.length) filePath = join(dir, files[files.length - 1]);
        else return res.status(404).json({ error: 'No files in directory' });
      } catch { return res.status(404).json({ error: 'Directory not found' }); }
    }
    const content = await readFile(filePath, 'utf8');
    if (req.query.raw === '1') {
      res.setHeader('Content-Type', 'text/markdown; charset=utf-8');
      return res.send(content);
    }
    res.json({ path: filePath, content });
  } catch (e) {
    res.status(404).json({ error: 'Document not found' });
  }
});

app.get('/api/documents/:id', async (req, res) => {
  try {
    const configPath = join(resolve('/home/ec2-user/clawd/dashboard/api'), 'links-config.json');
    const config = JSON.parse(await readFile(configPath, 'utf8'));
    const doc = config.documents.find(d => d.id === req.params.id);
    if (!doc) return res.status(404).json({ error: 'Document not found' });
    const content = await readFile(doc.filePath, 'utf8');
    if (req.query.raw === '1') {
      res.setHeader('Content-Type', 'text/markdown');
      res.setHeader('Content-Disposition', `attachment; filename="${doc.id}.md"`);
      return res.send(content);
    }
    res.json({ id: doc.id, name: doc.name, description: doc.description, content });
  } catch (e) {
    res.status(404).json({ error: 'Document not found or unreadable' });
  }
});

