import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import tailwindcss from '@tailwindcss/vite'

// https://vite.dev/config/
export default defineConfig({
  plugins: [react(), tailwindcss()],
  server: {
    port: 3400,
    host: true
  }
})

@import "tailwindcss";

:root {
  --pilar-navy: #1a365d;
  --pilar-ocean: #2c5282;
  --pilar-foam: #bee3f8;
  --pilar-wood: #8b6914;
  --pilar-brass: #d4a853;
}

body {
  margin: 0;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: #0f172a;
  color: #e2e8f0;
}

/* Scrollbar styling */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: #1e293b;
}

::-webkit-scrollbar-thumb {
  background: #475569;
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: #64748b;
}

export type MeasurementType = 'linear' | 'area' | 'count';

export interface Point {
  x: number;
  y: number;
}

export interface Measurement {
  id: string;
  type: MeasurementType;
  name: string;
  points: Point[];          // For linear: 2 points, for area: polygon points
  value: number;            // Calculated value (LF, SF, or count)
  unit: 'LF' | 'SF' | 'EA';
  color: string;
  pageNumber: number;
  jocLineItem?: JOCLineItem;
  createdAt: Date;
}

export interface JOCLineItem {
  code: string;             // e.g., "09 91 23.13 1000"
  description: string;      // e.g., "PAINTING - INTERIOR - WALLS"
  unit: 'LF' | 'SF' | 'EA' | 'LS';
  unitPrice: number;
  multipliers?: Multiplier[];
}

export interface Multiplier {
  name: string;             // e.g., "Occupied Facility"
  factor: number;           // e.g., 1.15
}

export interface MeasurementGroup {
  id: string;
  name: string;
  color: string;
  measurementIds: string[];
  collapsed: boolean;
}

export interface Project {
  id: string;
  name: string;
  pdfFile?: File;
  pdfUrl?: string;
  scale: number | null;     // pixels per foot (null = not calibrated)
  scaleUnit: 'ft' | 'in' | 'm';
  currentPage: number;
  totalPages: number;
  measurements: Measurement[];
  groups: MeasurementGroup[];
  createdAt: Date;
  updatedAt: Date;
}

export type Tool = 'select' | 'pan' | 'calibrate' | 'linear' | 'area' | 'count';

import { create } from 'zustand';
import type { Project, Measurement, MeasurementGroup, Tool, Point } from '../types';

interface ProjectState {
  // Current project
  project: Project | null;

  // UI State
  activeTool: Tool;
  zoom: number;
  panOffset: Point;
  selectedMeasurementId: string | null;

  // Calibration state
  isCalibrating: boolean;
  calibrationPoints: Point[];

  // Drawing state
  isDrawing: boolean;
  currentPoints: Point[];

  // Actions
  setProject: (project: Project) => void;
  setActiveTool: (tool: Tool) => void;
  setZoom: (zoom: number) => void;
  setPanOffset: (offset: Point) => void;
  setCurrentPage: (page: number) => void;

  // Calibration
  startCalibration: () => void;
  addCalibrationPoint: (point: Point) => void;
  completeCalibration: (knownDistance: number, unit: 'ft' | 'in' | 'm') => void;
  cancelCalibration: () => void;

  // Measurements
  addMeasurement: (measurement: Omit<Measurement, 'id' | 'createdAt'>) => void;
  updateMeasurement: (id: string, updates: Partial<Measurement>) => void;
  deleteMeasurement: (id: string) => void;
  selectMeasurement: (id: string | null) => void;

  // Drawing
  startDrawing: () => void;
  addPoint: (point: Point) => void;
  finishDrawing: () => Point[];
  cancelDrawing: () => void;

  // Groups
  addGroup: (name: string) => void;
  deleteGroup: (id: string) => void;
  addToGroup: (measurementId: string, groupId: string) => void;
}

const generateId = () => Math.random().toString(36).substring(2, 15);

const COLORS = [
  '#ef4444', '#f97316', '#eab308', '#22c55e', '#14b8a6',
  '#3b82f6', '#8b5cf6', '#ec4899', '#06b6d4', '#84cc16'
];

export const useProjectStore = create<ProjectState>((set, get) => ({
  project: null,
  activeTool: 'pan',
  zoom: 1,
  panOffset: { x: 0, y: 0 },
  selectedMeasurementId: null,
  isCalibrating: false,
  calibrationPoints: [],
  isDrawing: false,
  currentPoints: [],

  setProject: (project) => set({ project }),

  setActiveTool: (tool) => {
    const state = get();
    // Cancel any in-progress drawing when switching tools
    if (state.isDrawing) {
      set({ isDrawing: false, currentPoints: [] });
    }
    if (state.isCalibrating && tool !== 'calibrate') {
      set({ isCalibrating: false, calibrationPoints: [] });
    }
    set({ activeTool: tool });
  },

  setZoom: (zoom) => set({ zoom: Math.max(0.1, Math.min(5, zoom)) }),

  setPanOffset: (offset) => set({ panOffset: offset }),

  setCurrentPage: (page) => {
    const { project } = get();
    if (project && page >= 1 && page <= project.totalPages) {
      set({ project: { ...project, currentPage: page } });
    }
  },

  // Calibration
  startCalibration: () => set({ 
    isCalibrating: true, 
    calibrationPoints: [],
    activeTool: 'calibrate'
  }),

  addCalibrationPoint: (point) => {
    const { calibrationPoints } = get();
    if (calibrationPoints.length < 2) {
      set({ calibrationPoints: [...calibrationPoints, point] });
    }
  },

  completeCalibration: (knownDistance, unit) => {
    const { project, calibrationPoints } = get();
    if (!project || calibrationPoints.length !== 2) return;

    const [p1, p2] = calibrationPoints;
    const pixelDistance = Math.sqrt(
      Math.pow(p2.x - p1.x, 2) + Math.pow(p2.y - p1.y, 2)
    );

    // Convert to feet
    let distanceInFeet = knownDistance;
    if (unit === 'in') distanceInFeet = knownDistance / 12;
    if (unit === 'm') distanceInFeet = knownDistance * 3.28084;

    const scale = pixelDistance / distanceInFeet;

    set({
      project: { ...project, scale, scaleUnit: unit },
      isCalibrating: false,
      calibrationPoints: [],
      activeTool: 'select'
    });
  },

  cancelCalibration: () => set({
    isCalibrating: false,
    calibrationPoints: [],
    activeTool: 'select'
  }),

  // Measurements
  addMeasurement: (measurement) => {
    const { project } = get();
    if (!project) return;

    const newMeasurement: Measurement = {
      ...measurement,
      id: generateId(),
      createdAt: new Date()
    };

    set({
      project: {
        ...project,
        measurements: [...project.measurements, newMeasurement],
        updatedAt: new Date()
      }
    });
  },

  updateMeasurement: (id, updates) => {
    const { project } = get();
    if (!project) return;

    set({
      project: {
        ...project,
        measurements: project.measurements.map(m =>
          m.id === id ? { ...m, ...updates } : m
        ),
        updatedAt: new Date()
      }
    });
  },

  deleteMeasurement: (id) => {
    const { project, selectedMeasurementId } = get();
    if (!project) return;

    set({
      project: {
        ...project,
        measurements: project.measurements.filter(m => m.id !== id),
        groups: project.groups.map(g => ({
          ...g,
          measurementIds: g.measurementIds.filter(mId => mId !== id)
        })),
        updatedAt: new Date()
      },
      selectedMeasurementId: selectedMeasurementId === id ? null : selectedMeasurementId
    });
  },

  selectMeasurement: (id) => set({ selectedMeasurementId: id }),

  // Drawing
  startDrawing: () => set({ isDrawing: true, currentPoints: [] }),

  addPoint: (point) => {
    const { currentPoints } = get();
    set({ currentPoints: [...currentPoints, point] });
  },

  finishDrawing: () => {
    const { currentPoints } = get();
    set({ isDrawing: false, currentPoints: [] });
    return currentPoints;
  },

  cancelDrawing: () => set({ isDrawing: false, currentPoints: [] }),

  // Groups
  addGroup: (name) => {
    const { project } = get();
    if (!project) return;

    const colorIndex = project.groups.length % COLORS.length;
    const newGroup: MeasurementGroup = {
      id: generateId(),
      name,
      color: COLORS[colorIndex],
      measurementIds: [],
      collapsed: false
    };

    set({
      project: {
        ...project,
        groups: [...project.groups, newGroup],
        updatedAt: new Date()
      }
    });
  },

  deleteGroup: (id) => {
    const { project } = get();
    if (!project) return;

    set({
      project: {
        ...project,
        groups: project.groups.filter(g => g.id !== id),
        updatedAt: new Date()
      }
    });
  },

  addToGroup: (measurementId, groupId) => {
    const { project } = get();
    if (!project) return;

    set({
      project: {
        ...project,
        groups: project.groups.map(g => {
          if (g.id === groupId) {
            return {
              ...g,
              measurementIds: [...new Set([...g.measurementIds, measurementId])]
            };
          }
          // Remove from other groups
          return {
            ...g,
            measurementIds: g.measurementIds.filter(id => id !== measurementId)
          };
        }),
        updatedAt: new Date()
      }
    });
  }
}));

import type { Point } from '../types';

/**
 * Calculate distance between two points in pixels
 */
export function pixelDistance(p1: Point, p2: Point): number {
  return Math.sqrt(Math.pow(p2.x - p1.x, 2) + Math.pow(p2.y - p1.y, 2));
}

/**
 * Calculate real-world distance given scale (pixels per foot)
 */
export function realDistance(p1: Point, p2: Point, scale: number): number {
  return pixelDistance(p1, p2) / scale;
}

/**
 * Calculate polygon area in square pixels using Shoelace formula
 */
export function polygonAreaPixels(points: Point[]): number {
  if (points.length < 3) return 0;

  let area = 0;
  const n = points.length;

  for (let i = 0; i < n; i++) {
    const j = (i + 1) % n;
    area += points[i].x * points[j].y;
    area -= points[j].x * points[i].y;
  }

  return Math.abs(area) / 2;
}

/**
 * Calculate polygon area in square feet
 */
export function polygonAreaFeet(points: Point[], scale: number): number {
  const pixelArea = polygonAreaPixels(points);
  return pixelArea / (scale * scale);
}

/**
 * Calculate polygon perimeter in pixels
 */
export function polygonPerimeterPixels(points: Point[]): number {
  if (points.length < 2) return 0;

  let perimeter = 0;
  for (let i = 0; i < points.length; i++) {
    const j = (i + 1) % points.length;
    perimeter += pixelDistance(points[i], points[j]);
  }

  return perimeter;
}

/**
 * Calculate polygon perimeter in feet
 */
export function polygonPerimeterFeet(points: Point[], scale: number): number {
  return polygonPerimeterPixels(points) / scale;
}

/**
 * Get centroid of a polygon
 */
export function polygonCentroid(points: Point[]): Point {
  if (points.length === 0) return { x: 0, y: 0 };

  const sum = points.reduce(
    (acc, p) => ({ x: acc.x + p.x, y: acc.y + p.y }),
    { x: 0, y: 0 }
  );

  return {
    x: sum.x / points.length,
    y: sum.y / points.length
  };
}

/**
 * Format a measurement value for display
 */
export function formatMeasurement(value: number, unit: string): string {
  if (unit === 'EA') {
    return `${Math.round(value)} EA`;
  }

  // For LF and SF, show appropriate precision
  if (value >= 100) {
    return `${Math.round(value).toLocaleString()} ${unit}`;
  } else if (value >= 10) {
    return `${value.toFixed(1)} ${unit}`;
  } else {
    return `${value.toFixed(2)} ${unit}`;
  }
}

/**
 * Convert between units
 */
export function convertToFeet(value: number, fromUnit: 'ft' | 'in' | 'm'): number {
  switch (fromUnit) {
    case 'ft': return value;
    case 'in': return value / 12;
    case 'm': return value * 3.28084;
  }
}

/**
 * Check if a point is inside a polygon
 */
export function pointInPolygon(point: Point, polygon: Point[]): boolean {
  let inside = false;
  const n = polygon.length;

  for (let i = 0, j = n - 1; i < n; j = i++) {
    const xi = polygon[i].x, yi = polygon[i].y;
    const xj = polygon[j].x, yj = polygon[j].y;

    if (((yi > point.y) !== (yj > point.y)) &&
        (point.x < (xj - xi) * (point.y - yi) / (yj - yi) + xi)) {
      inside = !inside;
    }
  }

  return inside;
}

