import { useCallback, useState } from 'react';

interface DropZoneProps {
  onFileLoad: (file: File) => void;
}

export function DropZone({ onFileLoad }: DropZoneProps) {
  const [isDragging, setIsDragging] = useState(false);

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);

    const file = e.dataTransfer.files[0];
    if (file && file.type === 'application/pdf') {
      onFileLoad(file);
    }
  }, [onFileLoad]);

  const handleFileSelect = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && file.type === 'application/pdf') {
      onFileLoad(file);
    }
  }, [onFileLoad]);

  return (
    <div
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      className={`
        w-full max-w-2xl aspect-video rounded-2xl border-2 border-dashed
        flex flex-col items-center justify-center gap-6 p-12
        transition-all duration-200 cursor-pointer
        ${isDragging 
          ? 'border-blue-400 bg-blue-400/10' 
          : 'border-slate-600 hover:border-slate-500 hover:bg-slate-800/50'
        }
      `}
      onClick={() => document.getElementById('file-input')?.click()}
    >
      <div className="text-6xl">🚤</div>
      <div className="text-center">
        <h2 className="text-2xl font-bold text-white mb-2">Pilar Studio</h2>
        <p className="text-slate-400 mb-4">
          Drop a PDF drawing to start your takeoff
        </p>
        <p className="text-sm text-slate-500">
          or click to browse
        </p>
      </div>
      <input
        id="file-input"
        type="file"
        accept=".pdf"
        className="hidden"
        onChange={handleFileSelect}
      />
    </div>
  );
}

import { useProjectStore } from '../stores/projectStore';
import type { Tool } from '../types';

interface ToolButtonProps {
  tool: Tool;
  icon: string;
  label: string;
  shortcut?: string;
  disabled?: boolean;
}

function ToolButton({ tool, icon, label, shortcut, disabled }: ToolButtonProps) {
  const { activeTool, setActiveTool, startCalibration } = useProjectStore();
  const isActive = activeTool === tool;

  const handleClick = () => {
    if (disabled) return;
    if (tool === 'calibrate') {
      startCalibration();
    } else {
      setActiveTool(tool);
    }
  };

  return (
    <button
      onClick={handleClick}
      disabled={disabled}
      title={`${label}${shortcut ? ` (${shortcut})` : ''}`}
      className={`
        flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium
        transition-all duration-150
        ${isActive 
          ? 'bg-blue-600 text-white' 
          : disabled
            ? 'text-slate-500 cursor-not-allowed'
            : 'text-slate-300 hover:bg-slate-700 hover:text-white'
        }
      `}
    >
      <span className="text-lg">{icon}</span>
      <span className="hidden sm:inline">{label}</span>
    </button>
  );
}

export function Toolbar() {
  const { project, zoom, setZoom, setCurrentPage } = useProjectStore();

  if (!project) return null;

  return (
    <div className="bg-slate-800 border-b border-slate-700 px-4 py-2 flex items-center justify-between">
      {/* Left: Tools */}
      <div className="flex items-center gap-1">
        <ToolButton tool="select" icon="↖" label="Select" shortcut="V" />
        <ToolButton tool="pan" icon="✋" label="Pan" shortcut="H" />

        <div className="w-px h-6 bg-slate-600 mx-2" />

        <ToolButton 
          tool="calibrate" 
          icon="📏" 
          label="Calibrate" 
          shortcut="C"
        />

        <div className="w-px h-6 bg-slate-600 mx-2" />

        <ToolButton 
          tool="linear" 
          icon="📐" 
          label="Linear" 
          shortcut="L"
          disabled={!project.scale}
        />
        <ToolButton 
          tool="area" 
          icon="⬛" 
          label="Area" 
          shortcut="A"
          disabled={!project.scale}
        />
        <ToolButton 
          tool="count" 
          icon="🔢" 
          label="Count" 
          shortcut="N"
          disabled={!project.scale}
        />
      </div>

      {/* Center: Page Navigation */}
      <div className="flex items-center gap-2">
        <button
          onClick={() => setCurrentPage(project.currentPage - 1)}
          disabled={project.currentPage <= 1}
          className="p-1 rounded hover:bg-slate-700 disabled:opacity-30"
        >
          ◀
        </button>
        <span className="text-sm text-slate-300 min-w-20 text-center">
          Page {project.currentPage} / {project.totalPages}
        </span>
        <button
          onClick={() => setCurrentPage(project.currentPage + 1)}
          disabled={project.currentPage >= project.totalPages}
          className="p-1 rounded hover:bg-slate-700 disabled:opacity-30"
        >
          ▶
        </button>
      </div>

      {/* Right: Zoom */}
      <div className="flex items-center gap-2">
        <button
          onClick={() => setZoom(zoom - 0.25)}
          className="p-1 px-2 rounded hover:bg-slate-700 text-slate-300"
        >
          −
        </button>
        <span className="text-sm text-slate-300 min-w-16 text-center">
          {Math.round(zoom * 100)}%
        </span>
        <button
          onClick={() => setZoom(zoom + 0.25)}
          className="p-1 px-2 rounded hover:bg-slate-700 text-slate-300"
        >
          +
        </button>
        <button
          onClick={() => setZoom(1)}
          className="p-1 px-3 rounded hover:bg-slate-700 text-slate-300 text-sm"
        >
          Fit
        </button>
      </div>
    </div>
  );
}

import { useEffect, useRef, useState, useCallback } from 'react';
import * as pdfjsLib from 'pdfjs-dist';
import { useProjectStore } from '../stores/projectStore';
import { MeasurementCanvas } from './MeasurementCanvas';

// Set up worker
pdfjsLib.GlobalWorkerOptions.workerSrc = `https://cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.js`;

export function PDFViewer() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [pdfDoc, setPdfDoc] = useState<pdfjsLib.PDFDocumentProxy | null>(null);
  const [pageSize, setPageSize] = useState({ width: 0, height: 0 });
  const [isLoading, setIsLoading] = useState(false);

  const { 
    project, 
    zoom, 
    panOffset, 
    setPanOffset,
    activeTool,
    setProject
  } = useProjectStore();

  // Load PDF
  useEffect(() => {
    if (!project?.pdfUrl) return;

    setIsLoading(true);
    pdfjsLib.getDocument(project.pdfUrl).promise
      .then((doc) => {
        setPdfDoc(doc);
        if (project.totalPages !== doc.numPages) {
          setProject({ ...project, totalPages: doc.numPages });
        }
        setIsLoading(false);
      })
      .catch((err) => {
        console.error('Error loading PDF:', err);
        setIsLoading(false);
      });
  }, [project?.pdfUrl]);

  // Render current page
  useEffect(() => {
    if (!pdfDoc || !canvasRef.current || !project) return;

    const renderPage = async () => {
      const page = await pdfDoc.getPage(project.currentPage);
      const viewport = page.getViewport({ scale: zoom * 2 }); // 2x for retina

      const canvas = canvasRef.current!;
      const context = canvas.getContext('2d')!;

      canvas.width = viewport.width;
      canvas.height = viewport.height;
      canvas.style.width = `${viewport.width / 2}px`;
      canvas.style.height = `${viewport.height / 2}px`;

      setPageSize({ 
        width: viewport.width / 2, 
        height: viewport.height / 2 
      });

      await page.render({
        canvasContext: context,
        viewport
      }).promise;
    };

    renderPage();
  }, [pdfDoc, project?.currentPage, zoom]);

  // Pan handling
  const [isPanning, setIsPanning] = useState(false);
  const [panStart, setPanStart] = useState({ x: 0, y: 0 });

  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    if (activeTool === 'pan' || e.button === 1) { // Middle click also pans
      setIsPanning(true);
      setPanStart({ x: e.clientX - panOffset.x, y: e.clientY - panOffset.y });
    }
  }, [activeTool, panOffset]);

  const handleMouseMove = useCallback((e: React.MouseEvent) => {
    if (isPanning) {
      setPanOffset({
        x: e.clientX - panStart.x,
        y: e.clientY - panStart.y
      });
    }
  }, [isPanning, panStart, setPanOffset]);

  const handleMouseUp = useCallback(() => {
    setIsPanning(false);
  }, []);

  // Zoom with scroll wheel
  const { setZoom } = useProjectStore();
  const handleWheel = useCallback((e: React.WheelEvent) => {
    if (e.ctrlKey || e.metaKey) {
      e.preventDefault();
      const delta = e.deltaY > 0 ? -0.1 : 0.1;
      setZoom(zoom + delta);
    }
  }, [zoom, setZoom]);

  if (isLoading) {
    return (
      <div className="absolute inset-0 flex items-center justify-center">
        <div className="text-slate-400">Loading PDF...</div>
      </div>
    );
  }

  return (
    <div 
      ref={containerRef}
      className="absolute inset-0 overflow-hidden"
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
      onWheel={handleWheel}
      style={{ cursor: activeTool === 'pan' ? 'grab' : 'crosshair' }}
    >
      <div 
        className="absolute"
        style={{
          transform: `translate(${panOffset.x}px, ${panOffset.y}px)`,
          left: '50%',
          top: '50%',
          marginLeft: -pageSize.width / 2,
          marginTop: -pageSize.height / 2
        }}
      >
        {/* PDF Canvas */}
        <canvas 
          ref={canvasRef} 
          className="shadow-2xl"
        />

        {/* Measurement Overlay */}
        {pageSize.width > 0 && (
          <MeasurementCanvas 
            width={pageSize.width} 
            height={pageSize.height}
            panOffset={panOffset}
          />
        )}
      </div>
    </div>
  );
}

import { useRef, useEffect, useCallback, useState } from 'react';
import { useProjectStore } from '../stores/projectStore';
import { realDistance, polygonAreaFeet, formatMeasurement } from '../utils/geometry';
import type { Point, Measurement } from '../types';
import toast from 'react-hot-toast';

interface MeasurementCanvasProps {
  width: number;
  height: number;
  panOffset: Point;
}

const COLORS = [
  '#ef4444', '#f97316', '#eab308', '#22c55e', '#14b8a6',
  '#3b82f6', '#8b5cf6', '#ec4899'
];

export function MeasurementCanvas({ width, height }: MeasurementCanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [colorIndex, setColorIndex] = useState(0);

  const {
    project,
    activeTool,
    zoom,
    isCalibrating,
    calibrationPoints,
    addCalibrationPoint,
    isDrawing,
    currentPoints,
    startDrawing,
    addPoint,
    finishDrawing,
    addMeasurement,
    selectedMeasurementId
  } = useProjectStore();

  // Get canvas-relative coordinates
  const getCanvasPoint = useCallback((e: React.MouseEvent): Point => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };

    const rect = canvas.getBoundingClientRect();
    return {
      x: (e.clientX - rect.left) / zoom,
      y: (e.clientY - rect.top) / zoom
    };
  }, [zoom]);

  // Handle clicks
  const handleClick = useCallback((e: React.MouseEvent) => {
    if (!project) return;

    const point = getCanvasPoint(e);

    // Calibration mode
    if (isCalibrating) {
      addCalibrationPoint(point);
      return;
    }

    // Measurement modes
    if (activeTool === 'linear') {
      if (!isDrawing) {
        startDrawing();
        addPoint(point);
      } else if (currentPoints.length === 1) {
        addPoint(point);
        const points = [...currentPoints, point];
        const distance = realDistance(points[0], points[1], project.scale!);

        const measurement: Omit<Measurement, 'id' | 'createdAt'> = {
          type: 'linear',
          name: `Line ${project.measurements.length + 1}`,
          points,
          value: distance,
          unit: 'LF',
          color: COLORS[colorIndex % COLORS.length],
          pageNumber: project.currentPage
        };

        addMeasurement(measurement);
        finishDrawing();
        setColorIndex(c => c + 1);
        toast.success(`${formatMeasurement(distance, 'LF')} added`);
      }
    }

    if (activeTool === 'area') {
      if (!isDrawing) {
        startDrawing();
      }
      addPoint(point);
    }

    if (activeTool === 'count') {
      const measurement: Omit<Measurement, 'id' | 'createdAt'> = {
        type: 'count',
        name: `Count ${project.measurements.length + 1}`,
        points: [point],
        value: 1,
        unit: 'EA',
        color: COLORS[colorIndex % COLORS.length],
        pageNumber: project.currentPage
      };

      addMeasurement(measurement);
      setColorIndex(c => c + 1);
      toast.success('Count added');
    }
  }, [
    project, activeTool, isCalibrating, isDrawing, currentPoints, zoom,
    getCanvasPoint, addCalibrationPoint, startDrawing, addPoint, 
    finishDrawing, addMeasurement, colorIndex
  ]);

  // Handle double-click to finish polygon
  const handleDoubleClick = useCallback(() => {
    if (activeTool === 'area' && isDrawing && currentPoints.length >= 3) {
      const area = polygonAreaFeet(currentPoints, project!.scale!);

      const measurement: Omit<Measurement, 'id' | 'createdAt'> = {
        type: 'area',
        name: `Area ${project!.measurements.length + 1}`,
        points: currentPoints,
        value: area,
        unit: 'SF',
        color: COLORS[colorIndex % COLORS.length],
        pageNumber: project!.currentPage
      };

      addMeasurement(measurement);
      finishDrawing();
      setColorIndex(c => c + 1);
      toast.success(`${formatMeasurement(area, 'SF')} added`);
    }
  }, [activeTool, isDrawing, currentPoints, project, colorIndex, addMeasurement, finishDrawing]);

  // Handle escape to cancel
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        finishDrawing();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [finishDrawing]);

  // Draw everything
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d')!;
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Scale for zoom
    ctx.save();
    ctx.scale(zoom, zoom);

    // Draw existing measurements
    project?.measurements
      .filter(m => m.pageNumber === project.currentPage)
      .forEach(m => {
        const isSelected = m.id === selectedMeasurementId;
        ctx.strokeStyle = m.color;
        ctx.fillStyle = m.color + '40';
        ctx.lineWidth = isSelected ? 3 : 2;

        if (m.type === 'linear' && m.points.length === 2) {
          ctx.beginPath();
          ctx.moveTo(m.points[0].x, m.points[0].y);
          ctx.lineTo(m.points[1].x, m.points[1].y);
          ctx.stroke();

          // Draw endpoints
          m.points.forEach(p => {
            ctx.beginPath();
            ctx.arc(p.x, p.y, 5, 0, Math.PI * 2);
            ctx.fill();
          });

          // Draw label
          const midX = (m.points[0].x + m.points[1].x) / 2;
          const midY = (m.points[0].y + m.points[1].y) / 2;
          drawLabel(ctx, formatMeasurement(m.value, m.unit), midX, midY, m.color);
        }

        if (m.type === 'area' && m.points.length >= 3) {
          ctx.beginPath();
          ctx.moveTo(m.points[0].x, m.points[0].y);
          m.points.slice(1).forEach(p => ctx.lineTo(p.x, p.y));
          ctx.closePath();
          ctx.fill();
          ctx.stroke();

          // Draw label at centroid
          const cx = m.points.reduce((sum, p) => sum + p.x, 0) / m.points.length;
          const cy = m.points.reduce((sum, p) => sum + p.y, 0) / m.points.length;
          drawLabel(ctx, formatMeasurement(m.value, m.unit), cx, cy, m.color);
        }

        if (m.type === 'count') {
          const p = m.points[0];
          ctx.beginPath();
          ctx.arc(p.x, p.y, 12, 0, Math.PI * 2);
          ctx.fill();
          ctx.stroke();

          ctx.fillStyle = '#fff';
          ctx.font = 'bold 12px sans-serif';
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';
          ctx.fillText(m.value.toString(), p.x, p.y);
        }
      });

    // Draw calibration points
    if (isCalibrating && calibrationPoints.length > 0) {
      ctx.strokeStyle = '#fbbf24';
      ctx.fillStyle = '#fbbf24';
      ctx.lineWidth = 2;
      ctx.setLineDash([5, 5]);

      calibrationPoints.forEach((p, i) => {
        ctx.beginPath();
        ctx.arc(p.x, p.y, 8, 0, Math.PI * 2);
        ctx.fill();

        if (i === 0 && calibrationPoints.length === 2) {
          ctx.beginPath();
          ctx.moveTo(calibrationPoints[0].x, calibrationPoints[0].y);
          ctx.lineTo(calibrationPoints[1].x, calibrationPoints[1].y);
          ctx.stroke();
        }
      });

      ctx.setLineDash([]);
    }

    // Draw current drawing in progress
    if (isDrawing && currentPoints.length > 0) {
      const color = COLORS[colorIndex % COLORS.length];
      ctx.strokeStyle = color;
      ctx.fillStyle = color + '40';
      ctx.lineWidth = 2;
      ctx.setLineDash([5, 5]);

      if (activeTool === 'linear') {
        ctx.beginPath();
        ctx.arc(currentPoints[0].x, currentPoints[0].y, 5, 0, Math.PI * 2);
        ctx.fill();
      }

      if (activeTool === 'area' && currentPoints.length > 1) {
        ctx.beginPath();
        ctx.moveTo(currentPoints[0].x, currentPoints[0].y);
        currentPoints.slice(1).forEach(p => ctx.lineTo(p.x, p.y));
        ctx.stroke();

        currentPoints.forEach(p => {
          ctx.beginPath();
          ctx.arc(p.x, p.y, 4, 0, Math.PI * 2);
          ctx.fill();
        });
      }

      ctx.setLineDash([]);
    }

    ctx.restore();
  }, [
    project, zoom, isCalibrating, calibrationPoints, 
    isDrawing, currentPoints, activeTool, colorIndex, selectedMeasurementId
  ]);

  return (
    <canvas
      ref={canvasRef}
      width={width * zoom}
      height={height * zoom}
      className="absolute top-0 left-0 pointer-events-auto"
      style={{ width, height }}
      onClick={handleClick}
      onDoubleClick={handleDoubleClick}
    />
  );
}

function drawLabel(ctx: CanvasRenderingContext2D, text: string, x: number, y: number, color: string) {
  ctx.font = 'bold 12px sans-serif';
  const metrics = ctx.measureText(text);
  const padding = 4;
  const width = metrics.width + padding * 2;
  const height = 18;

  ctx.fillStyle = color;
  ctx.fillRect(x - width / 2, y - height / 2, width, height);

  ctx.fillStyle = '#fff';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, x, y);
}

import { useState } from 'react';
import { useProjectStore } from '../stores/projectStore';
import toast from 'react-hot-toast';

interface CalibrationDialogProps {
  onClose: () => void;
}

export function CalibrationDialog({ onClose }: CalibrationDialogProps) {
  const [distance, setDistance] = useState('');
  const [unit, setUnit] = useState<'ft' | 'in' | 'm'>('ft');

  const { completeCalibration, cancelCalibration } = useProjectStore();

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const value = parseFloat(distance);
    if (isNaN(value) || value <= 0) {
      toast.error('Please enter a valid distance');
      return;
    }

    completeCalibration(value, unit);
    toast.success('Scale calibrated!');
    onClose();
  };

  const handleCancel = () => {
    cancelCalibration();
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50">
      <div className="bg-slate-800 rounded-xl shadow-2xl p-6 w-full max-w-md">
        <h2 className="text-xl font-bold text-white mb-4">📏 Calibrate Scale</h2>
        <p className="text-slate-400 mb-6">
          Enter the known distance between the two points you selected.
        </p>

        <form onSubmit={handleSubmit}>
          <div className="flex gap-2 mb-6">
            <input
              type="number"
              step="any"
              value={distance}
              onChange={(e) => setDistance(e.target.value)}
              placeholder="Distance"
              className="flex-1 bg-slate-700 border border-slate-600 rounded-lg px-4 py-2 text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
              autoFocus
            />
            <select
              value={unit}
              onChange={(e) => setUnit(e.target.value as 'ft' | 'in' | 'm')}
              className="bg-slate-700 border border-slate-600 rounded-lg px-4 py-2 text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              <option value="ft">Feet</option>
              <option value="in">Inches</option>
              <option value="m">Meters</option>
            </select>
          </div>

          <div className="flex gap-3">
            <button
              type="button"
              onClick={handleCancel}
              className="flex-1 px-4 py-2 rounded-lg border border-slate-600 text-slate-300 hover:bg-slate-700"
            >
              Cancel
            </button>
            <button
              type="submit"
              className="flex-1 px-4 py-2 rounded-lg bg-blue-600 text-white hover:bg-blue-500"
            >
              Set Scale
            </button>
          </div>
        </form>

        <div className="mt-6 p-4 bg-slate-700/50 rounded-lg text-sm text-slate-400">
          <strong className="text-slate-300">Tip:</strong> For best accuracy, use a known dimension 
          like a door width (typically 3'-0") or a room dimension shown on the drawing.
        </div>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { useProjectStore } from '../stores/projectStore';
import { formatMeasurement } from '../utils/geometry';
import type { Measurement } from '../types';

export function MeasurementPanel() {
  const { 
    project, 
    selectedMeasurementId, 
    selectMeasurement,
    updateMeasurement,
    deleteMeasurement 
  } = useProjectStore();

  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');

  if (!project) return null;

  const measurements = project.measurements;

  // Group by type
  const linear = measurements.filter(m => m.type === 'linear');
  const areas = measurements.filter(m => m.type === 'area');
  const counts = measurements.filter(m => m.type === 'count');

  // Totals
  const totalLF = linear.reduce((sum, m) => sum + m.value, 0);
  const totalSF = areas.reduce((sum, m) => sum + m.value, 0);
  const totalCount = counts.reduce((sum, m) => sum + m.value, 0);

  const handleEdit = (m: Measurement) => {
    setEditingId(m.id);
    setEditName(m.name);
  };

  const handleSaveEdit = (id: string) => {
    updateMeasurement(id, { name: editName });
    setEditingId(null);
  };

  const handleDelete = (id: string) => {
    if (confirm('Delete this measurement?')) {
      deleteMeasurement(id);
    }
  };

  return (
    <div className="w-80 bg-slate-800 border-l border-slate-700 flex flex-col">
      {/* Header */}
      <div className="p-4 border-b border-slate-700">
        <h2 className="text-lg font-semibold text-white">Measurements</h2>
        <p className="text-sm text-slate-400">{measurements.length} items</p>
      </div>

      {/* Totals */}
      <div className="p-4 bg-slate-700/50 border-b border-slate-700">
        <div className="grid grid-cols-3 gap-2 text-center">
          <div>
            <div className="text-lg font-bold text-blue-400">{formatMeasurement(totalLF, 'LF')}</div>
            <div className="text-xs text-slate-400">Linear</div>
          </div>
          <div>
            <div className="text-lg font-bold text-green-400">{formatMeasurement(totalSF, 'SF')}</div>
            <div className="text-xs text-slate-400">Area</div>
          </div>
          <div>
            <div className="text-lg font-bold text-purple-400">{totalCount} EA</div>
            <div className="text-xs text-slate-400">Count</div>
          </div>
        </div>
      </div>

      {/* Measurement List */}
      <div className="flex-1 overflow-y-auto">
        {measurements.length === 0 ? (
          <div className="p-8 text-center text-slate-500">
            <div className="text-4xl mb-2">📐</div>
            <p>No measurements yet</p>
            <p className="text-sm mt-2">
              Calibrate scale first, then use the measurement tools
            </p>
          </div>
        ) : (
          <div className="p-2">
            {measurements.map(m => (
              <div
                key={m.id}
                onClick={() => selectMeasurement(m.id)}
                className={`
                  p-3 rounded-lg mb-2 cursor-pointer transition-all
                  ${selectedMeasurementId === m.id 
                    ? 'bg-slate-600 ring-2 ring-blue-500' 
                    : 'bg-slate-700/50 hover:bg-slate-700'
                  }
                `}
              >
                <div className="flex items-center gap-2">
                  {/* Color indicator */}
                  <div 
                    className="w-3 h-3 rounded-full"
                    style={{ backgroundColor: m.color }}
                  />

                  {/* Name */}
                  {editingId === m.id ? (
                    <input
                      type="text"
                      value={editName}
                      onChange={(e) => setEditName(e.target.value)}
                      onBlur={() => handleSaveEdit(m.id)}
                      onKeyDown={(e) => e.key === 'Enter' && handleSaveEdit(m.id)}
                      className="flex-1 bg-slate-600 px-2 py-1 rounded text-white text-sm"
                      autoFocus
                      onClick={(e) => e.stopPropagation()}
                    />
                  ) : (
                    <span 
                      className="flex-1 text-white text-sm truncate"
                      onDoubleClick={(e) => {
                        e.stopPropagation();
                        handleEdit(m);
                      }}
                    >
                      {m.name}
                    </span>
                  )}

                  {/* Value */}
                  <span className="text-sm font-mono text-slate-300">
                    {formatMeasurement(m.value, m.unit)}
                  </span>
                </div>

                {/* Actions (visible when selected) */}
                {selectedMeasurementId === m.id && (
                  <div className="flex gap-2 mt-2 pt-2 border-t border-slate-600">
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        handleEdit(m);
                      }}
                      className="text-xs text-slate-400 hover:text-white"
                    >
                      ✏️ Rename
                    </button>
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        handleDelete(m.id);
                      }}
                      className="text-xs text-red-400 hover:text-red-300"
                    >
                      🗑️ Delete
                    </button>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Export Button */}
      {measurements.length > 0 && (
        <div className="p-4 border-t border-slate-700">
          <button
            onClick={() => exportToCSV(measurements)}
            className="w-full py-2 px-4 bg-green-600 hover:bg-green-500 text-white rounded-lg font-medium"
          >
            📥 Export to CSV
          </button>
        </div>
      )}
    </div>
  );
}

function exportToCSV(measurements: Measurement[]) {
  const headers = ['Name', 'Type', 'Value', 'Unit', 'Page'];
  const rows = measurements.map(m => [
    m.name,
    m.type,
    m.value.toFixed(2),
    m.unit,
    m.pageNumber
  ]);

  const csv = [
    headers.join(','),
    ...rows.map(r => r.join(','))
  ].join('\n');

  const blob = new Blob([csv], { type: 'text/csv' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'takeoff.csv';
  a.click();
  URL.revokeObjectURL(url);
}

