export default App;

import { useProjectStore } from '../stores/projectStore';
import type { Tool } from '../types';

interface ToolButtonProps {
  tool: Tool;
  icon: string;
  label: string;
  shortcut?: string;
  disabled?: boolean;
}

function ToolButton({ tool, icon, label, shortcut, disabled }: ToolButtonProps) {
  const { activeTool, setActiveTool, startCalibration } = useProjectStore();
  const isActive = activeTool === tool;

  const handleClick = () => {
    if (disabled) return;
    if (tool === 'calibrate') {
      startCalibration();
    } else {
      setActiveTool(tool);
    }
  };

  return (
    <button
      onClick={handleClick}
      disabled={disabled}
      title={`${label}${shortcut ? ` (${shortcut})` : ''}`}
      className="flex items-center gap-2 px-4 py-2 rounded text-sm font-medium transition-all duration-150"
      style={{
        background: isActive ? '#c9a227' : 'transparent',
        color: isActive ? '#1a2f3d' : disabled ? '#4a6a7a' : '#e8f1f5',
        cursor: disabled ? 'not-allowed' : 'pointer',
        opacity: disabled ? 0.5 : 1,
        border: isActive ? 'none' : '1px solid transparent',
      }}
      onMouseEnter={(e) => {
        if (!disabled && !isActive) {
          e.currentTarget.style.background = '#2d4a5e';
          e.currentTarget.style.borderColor = '#4a6a7a';
        }
      }}
      onMouseLeave={(e) => {
        if (!isActive) {
          e.currentTarget.style.background = 'transparent';
          e.currentTarget.style.borderColor = 'transparent';
        }
      }}
    >
      <span className="text-lg">{icon}</span>
      <span className="hidden sm:inline">{label}</span>
    </button>
  );
}

function Divider() {
  return <div className="w-px h-6 mx-2" style={{ background: '#2d4a5e' }} />;
}

export function Toolbar() {
  const { project, zoom, setZoom, setCurrentPage } = useProjectStore();

  if (!project) return null;

  return (
    <div className="px-4 py-2 flex items-center justify-between"
         style={{ 
           background: '#152a36',
           borderBottom: '1px solid #2d4a5e'
         }}>
      {/* Left: Tools */}
      <div className="flex items-center">
        <ToolButton tool="select" icon="↖" label="Select" shortcut="V" />
        <ToolButton tool="pan" icon="✋" label="Pan" shortcut="H" />

        <Divider />

        <ToolButton 
          tool="calibrate" 
          icon="⚓" 
          label="Calibrate" 
          shortcut="C"
        />

        <Divider />

        <ToolButton 
          tool="linear" 
          icon="📏" 
          label="Linear" 
          shortcut="L"
          disabled={!project.scale}
        />
        <ToolButton 
          tool="area" 
          icon="⬛" 
          label="Area" 
          shortcut="A"
          disabled={!project.scale}
        />
        <ToolButton 
          tool="count" 
          icon="🎣" 
          label="Count" 
          shortcut="N"
          disabled={!project.scale}
        />
      </div>

      {/* Center: Page Navigation */}
      <div className="flex items-center gap-3 px-4 py-1 rounded"
           style={{ background: '#1a2f3d', border: '1px solid #2d4a5e' }}>
        <button
          onClick={() => setCurrentPage(project.currentPage - 1)}
          disabled={project.currentPage <= 1}
          className="px-2 py-1 rounded transition-colors"
          style={{ 
            color: project.currentPage <= 1 ? '#4a6a7a' : '#e8f1f5',
            cursor: project.currentPage <= 1 ? 'not-allowed' : 'pointer'
          }}
        >
          ◀
        </button>
        <span className="text-sm min-w-24 text-center" style={{ color: '#8b7355' }}>
          Chart {project.currentPage} of {project.totalPages}
        </span>
        <button
          onClick={() => setCurrentPage(project.currentPage + 1)}
          disabled={project.currentPage >= project.totalPages}
          className="px-2 py-1 rounded transition-colors"
          style={{ 
            color: project.currentPage >= project.totalPages ? '#4a6a7a' : '#e8f1f5',
            cursor: project.currentPage >= project.totalPages ? 'not-allowed' : 'pointer'
          }}
        >
          ▶
        </button>
      </div>

      {/* Right: Zoom */}
      <div className="flex items-center gap-2">
        <button
          onClick={() => setZoom(zoom - 0.25)}
          className="px-3 py-1 rounded transition-colors"
          style={{ color: '#e8f1f5' }}
          onMouseEnter={(e) => e.currentTarget.style.background = '#2d4a5e'}
          onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
        >
          −
        </button>
        <span className="text-sm min-w-16 text-center" style={{ color: '#8b7355' }}>
          {Math.round(zoom * 100)}%
        </span>
        <button
          onClick={() => setZoom(zoom + 0.25)}
          className="px-3 py-1 rounded transition-colors"
          style={{ color: '#e8f1f5' }}
          onMouseEnter={(e) => e.currentTarget.style.background = '#2d4a5e'}
          onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
        >
          +
        </button>
        <button
          onClick={() => setZoom(1)}
          className="px-3 py-1 rounded text-sm transition-colors"
          style={{ color: '#c9a227', border: '1px solid #5a4020' }}
          onMouseEnter={(e) => e.currentTarget.style.background = '#2d4a5e'}
          onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
        >
          Fit
        </button>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { useProjectStore } from '../stores/projectStore';
import { formatMeasurement } from '../utils/geometry';
import type { Measurement } from '../types';

export function MeasurementPanel() {
  const { 
    project, 
    selectedMeasurementId, 
    selectMeasurement,
    updateMeasurement,
    deleteMeasurement 
  } = useProjectStore();

  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');

  if (!project) return null;

  const measurements = project.measurements;

  // Group by type
  const linear = measurements.filter(m => m.type === 'linear');
  const areas = measurements.filter(m => m.type === 'area');
  const counts = measurements.filter(m => m.type === 'count');

  // Totals
  const totalLF = linear.reduce((sum, m) => sum + m.value, 0);
  const totalSF = areas.reduce((sum, m) => sum + m.value, 0);
  const totalCount = counts.reduce((sum, m) => sum + m.value, 0);

  const handleEdit = (m: Measurement) => {
    setEditingId(m.id);
    setEditName(m.name);
  };

  const handleSaveEdit = (id: string) => {
    updateMeasurement(id, { name: editName });
    setEditingId(null);
  };

  const handleDelete = (id: string) => {
    if (confirm('Throw this one back?')) {
      deleteMeasurement(id);
    }
  };

  return (
    <div className="w-80 flex flex-col"
         style={{ 
           background: 'linear-gradient(180deg, #1a2f3d 0%, #152a36 100%)',
           borderLeft: '1px solid #2d4a5e'
         }}>
      {/* Header */}
      <div className="p-4" style={{ borderBottom: '1px solid #2d4a5e' }}>
        <h2 className="text-lg font-semibold" 
            style={{ fontFamily: 'Playfair Display, serif', color: '#c9a227' }}>
          Ship's Log
        </h2>
        <p className="text-sm" style={{ color: '#8b7355' }}>
          {measurements.length} {measurements.length === 1 ? 'catch' : 'catches'}
        </p>
      </div>

      {/* Totals */}
      <div className="p-4" style={{ background: '#0f1c24', borderBottom: '1px solid #2d4a5e' }}>
        <div className="grid grid-cols-3 gap-2 text-center">
          <div>
            <div className="text-lg font-bold" style={{ color: '#5fa8d3' }}>
              {formatMeasurement(totalLF, 'LF')}
            </div>
            <div className="text-xs" style={{ color: '#4a6a7a' }}>Linear</div>
          </div>
          <div>
            <div className="text-lg font-bold" style={{ color: '#7cb798' }}>
              {formatMeasurement(totalSF, 'SF')}
            </div>
            <div className="text-xs" style={{ color: '#4a6a7a' }}>Area</div>
          </div>
          <div>
            <div className="text-lg font-bold" style={{ color: '#c9a227' }}>
              {totalCount} EA
            </div>
            <div className="text-xs" style={{ color: '#4a6a7a' }}>Count</div>
          </div>
        </div>
      </div>

      {/* Measurement List */}
      <div className="flex-1 overflow-y-auto">
        {measurements.length === 0 ? (
          <div className="p-8 text-center" style={{ color: '#4a6a7a' }}>
            <div className="text-4xl mb-4 opacity-50">🎣</div>
            <p style={{ fontFamily: 'Playfair Display, serif', fontStyle: 'italic' }}>
              "The water was dark and the light made prisms in it."
            </p>
            <p className="text-sm mt-4">
              Calibrate, then cast your lines
            </p>
          </div>
        ) : (
          <div className="p-2">
            {measurements.map(m => (
              <div
                key={m.id}
                onClick={() => selectMeasurement(m.id)}
                className="p-3 rounded mb-2 cursor-pointer transition-all duration-150"
                style={{
                  background: selectedMeasurementId === m.id ? '#2d4a5e' : '#1e3a4c',
                  border: selectedMeasurementId === m.id 
                    ? '1px solid #c9a227' 
                    : '1px solid transparent'
                }}
                onMouseEnter={(e) => {
                  if (selectedMeasurementId !== m.id) {
                    e.currentTarget.style.background = '#243d4d';
                  }
                }}
                onMouseLeave={(e) => {
                  if (selectedMeasurementId !== m.id) {
                    e.currentTarget.style.background = '#1e3a4c';
                  }
                }}
              >
                <div className="flex items-center gap-2">
                  {/* Color indicator */}
                  <div 
                    className="w-3 h-3 rounded-full"
                    style={{ backgroundColor: m.color }}
                  />

                  {/* Name */}
                  {editingId === m.id ? (
                    <input
                      type="text"
                      value={editName}
                      onChange={(e) => setEditName(e.target.value)}
                      onBlur={() => handleSaveEdit(m.id)}
                      onKeyDown={(e) => e.key === 'Enter' && handleSaveEdit(m.id)}
                      className="flex-1 px-2 py-1 rounded text-sm"
                      style={{ 
                        background: '#1a2f3d', 
                        color: '#e8f1f5',
                        border: '1px solid #4a6a7a'
                      }}
                      autoFocus
                      onClick={(e) => e.stopPropagation()}
                    />
                  ) : (
                    <span 
                      className="flex-1 text-sm truncate"
                      style={{ color: '#e8f1f5' }}
                      onDoubleClick={(e) => {
                        e.stopPropagation();
                        handleEdit(m);
                      }}
                    >
                      {m.name}
                    </span>
                  )}

                  {/* Value */}
                  <span className="text-sm font-mono" style={{ color: '#8b7355' }}>
                    {formatMeasurement(m.value, m.unit)}
                  </span>
                </div>

                {/* Actions (visible when selected) */}
                {selectedMeasurementId === m.id && (
                  <div className="flex gap-3 mt-2 pt-2" 
                       style={{ borderTop: '1px solid #3d5a6e' }}>
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        handleEdit(m);
                      }}
                      className="text-xs transition-colors"
                      style={{ color: '#8b7355' }}
                      onMouseEnter={(e) => e.currentTarget.style.color = '#c9a227'}
                      onMouseLeave={(e) => e.currentTarget.style.color = '#8b7355'}
                    >
                      ✏️ Rename
                    </button>
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        handleDelete(m.id);
                      }}
                      className="text-xs transition-colors"
                      style={{ color: '#a65d37' }}
                      onMouseEnter={(e) => e.currentTarget.style.color = '#d47a4a'}
                      onMouseLeave={(e) => e.currentTarget.style.color = '#a65d37'}
                    >
                      🗑️ Throw back
                    </button>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Export Button */}
      {measurements.length > 0 && (
        <div className="p-4" style={{ borderTop: '1px solid #2d4a5e' }}>
          <button
            onClick={() => exportToCSV(measurements, project.name)}
            className="w-full py-3 px-4 rounded font-medium transition-all duration-150"
            style={{ 
              background: 'linear-gradient(135deg, #c9a227 0%, #a68520 100%)',
              color: '#1a2f3d',
              fontFamily: 'Playfair Display, serif'
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.transform = 'translateY(-1px)';
              e.currentTarget.style.boxShadow = '0 4px 12px rgba(201, 162, 39, 0.3)';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.transform = 'translateY(0)';
              e.currentTarget.style.boxShadow = 'none';
            }}
          >
            📜 Export Ship's Log
          </button>
        </div>
      )}
    </div>
  );
}

function exportToCSV(measurements: Measurement[], projectName: string) {
  const headers = ['Name', 'Type', 'Value', 'Unit', 'Page'];
  const rows = measurements.map(m => [
    m.name,
    m.type,
    m.value.toFixed(2),
    m.unit,
    m.pageNumber
  ]);

  const csv = [
    headers.join(','),
    ...rows.map(r => r.join(','))
  ].join('\n');

  const blob = new Blob([csv], { type: 'text/csv' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `${projectName}-takeoff.csv`;
  a.click();
  URL.revokeObjectURL(url);
}

import { useState } from 'react';
import { useProjectStore } from '../stores/projectStore';
import toast from 'react-hot-toast';

interface CalibrationDialogProps {
  onClose: () => void;
}

export function CalibrationDialog({ onClose }: CalibrationDialogProps) {
  const [distance, setDistance] = useState('');
  const [unit, setUnit] = useState<'ft' | 'in' | 'm'>('ft');

  const { completeCalibration, cancelCalibration } = useProjectStore();

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const value = parseFloat(distance);
    if (isNaN(value) || value <= 0) {
      toast.error('Enter a true heading, Captain');
      return;
    }

    completeCalibration(value, unit);
    toast.success('Charts calibrated — ready to navigate');
    onClose();
  };

  const handleCancel = () => {
    cancelCalibration();
    onClose();
  };

  return (
    <div className="fixed inset-0 flex items-center justify-center z-50"
         style={{ background: 'rgba(15, 28, 36, 0.9)' }}>
      <div className="rounded-lg shadow-2xl p-6 w-full max-w-md"
           style={{ 
             background: 'linear-gradient(135deg, #1a2f3d 0%, #152a36 100%)',
             border: '1px solid #2d4a5e'
           }}>
        <h2 className="text-xl font-bold mb-2" 
            style={{ fontFamily: 'Playfair Display, serif', color: '#c9a227' }}>
          ⚓ Set Your Scale
        </h2>
        <p className="mb-6" style={{ color: '#8b7355' }}>
          What's the true distance between those two points?
        </p>

        <form onSubmit={handleSubmit}>
          <div className="flex gap-2 mb-6">
            <input
              type="number"
              step="any"
              value={distance}
              onChange={(e) => setDistance(e.target.value)}
              placeholder="Distance"
              className="flex-1 rounded-lg px-4 py-3 focus:outline-none"
              style={{
                background: '#0f1c24',
                border: '1px solid #2d4a5e',
                color: '#e8f1f5'
              }}
              autoFocus
            />
            <select
              value={unit}
              onChange={(e) => setUnit(e.target.value as 'ft' | 'in' | 'm')}
              className="rounded-lg px-4 py-3 focus:outline-none cursor-pointer"
              style={{
                background: '#0f1c24',
                border: '1px solid #2d4a5e',
                color: '#e8f1f5'
              }}
            >
              <option value="ft">Feet</option>
              <option value="in">Inches</option>
              <option value="m">Meters</option>
            </select>
          </div>

          <div className="flex gap-3">
            <button
              type="button"
              onClick={handleCancel}
              className="flex-1 px-4 py-3 rounded-lg transition-colors"
              style={{ 
                border: '1px solid #4a6a7a',
                color: '#8b7355'
              }}
              onMouseEnter={(e) => e.currentTarget.style.background = '#2d4a5e'}
              onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
            >
              Belay That
            </button>
            <button
              type="submit"
              className="flex-1 px-4 py-3 rounded-lg font-medium transition-all"
              style={{ 
                background: 'linear-gradient(135deg, #c9a227 0%, #a68520 100%)',
                color: '#1a2f3d'
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.transform = 'translateY(-1px)';
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.transform = 'translateY(0)';
              }}
            >
              Set Course
            </button>
          </div>
        </form>

        <div className="mt-6 p-4 rounded-lg text-sm"
             style={{ background: '#0f1c24', color: '#8b7355' }}>
          <strong style={{ color: '#c9a227' }}>Navigator's Tip:</strong> Use a known dimension 
          like a door width (typically 3'-0") or a room dimension marked on the drawing.
        </div>
      </div>
    </div>
  );
}

import { useCallback, useState } from 'react';

interface DropZoneProps {
  onFileLoad: (file: File) => void;
}

export function DropZone({ onFileLoad }: DropZoneProps) {
  const [isDragging, setIsDragging] = useState(false);

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);

    const file = e.dataTransfer.files[0];
    if (file && file.type === 'application/pdf') {
      onFileLoad(file);
    }
  }, [onFileLoad]);

  const handleFileSelect = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && file.type === 'application/pdf') {
      onFileLoad(file);
    }
  }, [onFileLoad]);

  return (
    <div className="min-h-screen w-full flex flex-col items-center justify-center p-8"
         style={{ background: 'linear-gradient(180deg, #1a2f3d 0%, #0f1c24 100%)' }}>

      {/* Header */}
      <div className="text-center mb-12">
        <div className="text-6xl mb-4">🚤</div>
        <h1 className="text-5xl font-bold mb-2" 
            style={{ fontFamily: 'Playfair Display, serif', color: '#c9a227' }}>
          Pilar Studio
        </h1>
        <p className="text-lg opacity-70" style={{ color: '#e8f1f5' }}>
          Construction Takeoff Tool
        </p>
      </div>

      {/* Drop Zone */}
      <div
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        onClick={() => document.getElementById('file-input')?.click()}
        className={`
          w-full max-w-2xl aspect-[16/10] rounded-lg
          flex flex-col items-center justify-center gap-6 p-12
          transition-all duration-300 cursor-pointer
          ${isDragging 
            ? 'scale-102 shadow-2xl' 
            : 'hover:scale-101'
          }
        `}
        style={{
          background: isDragging 
            ? 'linear-gradient(135deg, #2d4a5e 0%, #1e3a4c 100%)'
            : 'linear-gradient(135deg, #1e3a4c 0%, #152a36 100%)',
          border: `2px dashed ${isDragging ? '#c9a227' : '#4a6a7a'}`,
          boxShadow: isDragging 
            ? '0 20px 60px rgba(0,0,0,0.4), inset 0 0 60px rgba(201, 162, 39, 0.1)'
            : '0 10px 40px rgba(0,0,0,0.3)'
        }}
      >
        <div className="text-5xl opacity-80">📋</div>
        <div className="text-center">
          <p className="text-xl mb-2" style={{ color: '#e8f1f5' }}>
            Drop your drawings here
          </p>
          <p className="text-sm opacity-60">
            PDF files • Click or drag
          </p>
        </div>
      </div>

      {/* Footer */}
      <div className="mt-12 text-center opacity-40">
        <p className="text-xs" style={{ color: '#8b7355' }}>
          Named after Hemingway's 38-foot Wheeler • Built for precision
        </p>
      </div>

      <input
        id="file-input"
        type="file"
        accept=".pdf"
        className="hidden"
        onChange={handleFileSelect}
      />
    </div>
  );
}

import { useProjectStore } from '../stores/projectStore';
import type { Tool } from '../types';

interface ToolButtonProps {
  tool: Tool;
  icon: string;
  label: string;
  shortcut?: string;
  disabled?: boolean;
}

function ToolButton({ tool, icon, label, shortcut, disabled }: ToolButtonProps) {
  const { activeTool, setActiveTool, startCalibration } = useProjectStore();
  const isActive = activeTool === tool;

  const handleClick = () => {
    if (disabled) return;
    if (tool === 'calibrate') {
      startCalibration();
    } else {
      setActiveTool(tool);
    }
  };

  return (
    <button
      onClick={handleClick}
      disabled={disabled}
      title={`${label}${shortcut ? ` (${shortcut})` : ''}`}
      className="flex items-center gap-2 px-4 py-2 rounded text-sm font-medium transition-all duration-150"
      style={{
        background: isActive ? '#c9a227' : 'transparent',
        color: isActive ? '#1a2f3d' : disabled ? '#4a6a7a' : '#e8f1f5',
        cursor: disabled ? 'not-allowed' : 'pointer',
        opacity: disabled ? 0.5 : 1,
        border: isActive ? 'none' : '1px solid transparent',
      }}
      onMouseEnter={(e) => {
        if (!disabled && !isActive) {
          e.currentTarget.style.background = '#2d4a5e';
          e.currentTarget.style.borderColor = '#4a6a7a';
        }
      }}
      onMouseLeave={(e) => {
        if (!isActive) {
          e.currentTarget.style.background = 'transparent';
          e.currentTarget.style.borderColor = 'transparent';
        }
      }}
    >
      <span className="text-lg">{icon}</span>
      <span className="hidden sm:inline">{label}</span>
    </button>
  );
}

