import type { Point } from '../types';

export interface SnapPoint {
  x: number;
  y: number;
  type: 'corner' | 'endpoint' | 'edge';
}

export interface SnapResult {
  snapped: boolean;
  point: Point;
  snapPoint?: SnapPoint;
  distance: number;
}

/**
 * Snap engine - detects corners and edges from rendered PDF canvas
 */
export class SnapEngine {
  private snapPoints: SnapPoint[] = [];
  private snapTolerance: number = 12;
  private spatialIndex: Map<string, SnapPoint[]> = new Map();

  constructor(tolerance: number = 12) {
    this.snapTolerance = tolerance;
  }

  setTolerance(pixels: number) {
    this.snapTolerance = pixels;
  }

  clear() {
    this.snapPoints = [];
    this.spatialIndex.clear();
  }

  /**
   * Detect corners from rendered canvas using simple edge detection
   */
  detectFromCanvas(canvas: HTMLCanvasElement) {
    this.clear();

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = canvas.width;
    const height = canvas.height;
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;

    // Convert to grayscale and find edges
    const gray = new Uint8Array(width * height);
    for (let i = 0; i < width * height; i++) {
      const r = data[i * 4];
      const g = data[i * 4 + 1];
      const b = data[i * 4 + 2];
      gray[i] = Math.round(0.299 * r + 0.587 * g + 0.114 * b);
    }

    // Simple corner detection: look for dark pixels with specific neighbor patterns
    const step = 3; // Check every 3rd pixel for performance
    const threshold = 200; // Pixels darker than this are "lines"

    for (let y = step; y < height - step; y += step) {
      for (let x = step; x < width - step; x += step) {
        const idx = y * width + x;

        // Skip if this pixel is light (background)
        if (gray[idx] > threshold) continue;

        // Count dark neighbors in 8 directions
        const neighbors = [
          gray[idx - width - 1], gray[idx - width], gray[idx - width + 1],
          gray[idx - 1],                            gray[idx + 1],
          gray[idx + width - 1], gray[idx + width], gray[idx + width + 1]
        ];

        const darkCount = neighbors.filter(n => n < threshold).length;

        // Corners have 2-3 dark neighbors (end of lines or intersections)
        // Line midpoints have 2 opposite dark neighbors
        if (darkCount >= 1 && darkCount <= 3) {
          this.addSnapPoint(x, y, 'corner');
        }
      }
    }

    // Also sample along detected dark regions for edge snapping
    for (let y = 10; y < height - 10; y += 20) {
      for (let x = 10; x < width - 10; x += 20) {
        const idx = y * width + x;
        if (gray[idx] < threshold) {
          this.addSnapPoint(x, y, 'edge');
        }
      }
    }

    this.buildSpatialIndex();
    console.log(`SnapEngine: Detected ${this.snapPoints.length} snap points`);
  }

  /**
   * Add a snap point
   */
  addSnapPoint(x: number, y: number, type: SnapPoint['type']) {
    // Avoid duplicates within 5px
    const dominated = this.snapPoints.some(p => 
      Math.abs(p.x - x) < 5 && Math.abs(p.y - y) < 5
    );
    if (!dominated) {
      this.snapPoints.push({ x, y, type });
    }
  }

  /**
   * Build spatial index for fast lookups
   */
  private buildSpatialIndex() {
    this.spatialIndex.clear();
    const cellSize = this.snapTolerance * 3;

    for (const point of this.snapPoints) {
      const cellX = Math.floor(point.x / cellSize);
      const cellY = Math.floor(point.y / cellSize);
      const key = `${cellX},${cellY}`;

      if (!this.spatialIndex.has(key)) {
        this.spatialIndex.set(key, []);
      }
      this.spatialIndex.get(key)!.push(point);
    }
  }

  /**
   * Find nearest snap point
   */
  findNearest(x: number, y: number): SnapResult {
    const cellSize = this.snapTolerance * 3;
    const cellX = Math.floor(x / cellSize);
    const cellY = Math.floor(y / cellSize);

    let nearest: SnapPoint | null = null;
    let minDist = Infinity;

    // Check 3x3 neighborhood
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        const key = `${cellX + dx},${cellY + dy}`;
        const points = this.spatialIndex.get(key);
        if (!points) continue;

        for (const point of points) {
          const dist = Math.sqrt(Math.pow(point.x - x, 2) + Math.pow(point.y - y, 2));
          if (dist < minDist) {
            minDist = dist;
            nearest = point;
          }
        }
      }
    }

    if (nearest && minDist <= this.snapTolerance) {
      return {
        snapped: true,
        point: { x: nearest.x, y: nearest.y },
        snapPoint: nearest,
        distance: minDist
      };
    }

    return {
      snapped: false,
      point: { x, y },
      distance: minDist
    };
  }

  getAllPoints(): SnapPoint[] {
    return [...this.snapPoints];
  }

  get count(): number {
    return this.snapPoints.length;
  }
}

export const snapEngine = new SnapEngine();

