import type { Point } from '../types';

export interface SnapPoint {
  x: number;
  y: number;
  type: 'corner' | 'endpoint' | 'intersection';
}

export interface SnapResult {
  snapped: boolean;
  point: Point;
  snapPoint?: SnapPoint;
  distance: number;
}

/**
 * Snap engine - detects corners and line intersections from rendered PDF
 */
export class SnapEngine {
  private snapPoints: SnapPoint[] = [];
  private snapTolerance: number = 15;
  private spatialIndex: Map<string, SnapPoint[]> = new Map();

  constructor(tolerance: number = 15) {
    this.snapTolerance = tolerance;
  }

  setTolerance(pixels: number) {
    this.snapTolerance = pixels;
  }

  clear() {
    this.snapPoints = [];
    this.spatialIndex.clear();
  }

  /**
   * Detect corners using Harris-like corner detection
   */
  detectFromCanvas(canvas: HTMLCanvasElement, scaleFactor: number = 1) {
    this.clear();

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = canvas.width;
    const height = canvas.height;
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;

    // Convert to grayscale
    const gray = new Float32Array(width * height);
    for (let i = 0; i < width * height; i++) {
      const r = data[i * 4];
      const g = data[i * 4 + 1];
      const b = data[i * 4 + 2];
      gray[i] = 0.299 * r + 0.587 * g + 0.114 * b;
    }

    // Compute gradients using Sobel
    const gx = new Float32Array(width * height);
    const gy = new Float32Array(width * height);

    for (let y = 1; y < height - 1; y++) {
      for (let x = 1; x < width - 1; x++) {
        const idx = y * width + x;

        // Sobel X
        gx[idx] = (
          -gray[idx - width - 1] + gray[idx - width + 1] +
          -2 * gray[idx - 1] + 2 * gray[idx + 1] +
          -gray[idx + width - 1] + gray[idx + width + 1]
        );

        // Sobel Y
        gy[idx] = (
          -gray[idx - width - 1] - 2 * gray[idx - width] - gray[idx - width + 1] +
          gray[idx + width - 1] + 2 * gray[idx + width] + gray[idx + width + 1]
        );
      }
    }

    // Harris corner detection
    const windowSize = 3;
    const k = 0.04;
    const threshold = 50000; // Corner response threshold
    const step = Math.max(2, Math.floor(4 * scaleFactor));

    const corners: { x: number; y: number; response: number }[] = [];

    for (let y = windowSize; y < height - windowSize; y += step) {
      for (let x = windowSize; x < width - windowSize; x += step) {
        let sumIx2 = 0, sumIy2 = 0, sumIxIy = 0;

        // Sum over window
        for (let wy = -windowSize; wy <= windowSize; wy++) {
          for (let wx = -windowSize; wx <= windowSize; wx++) {
            const idx = (y + wy) * width + (x + wx);
            const ix = gx[idx];
            const iy = gy[idx];
            sumIx2 += ix * ix;
            sumIy2 += iy * iy;
            sumIxIy += ix * iy;
          }
        }

        // Harris response
        const det = sumIx2 * sumIy2 - sumIxIy * sumIxIy;
        const trace = sumIx2 + sumIy2;
        const response = det - k * trace * trace;

        if (response > threshold) {
          corners.push({ x, y, response });
        }
      }
    }

    // Non-maximum suppression - keep only local maxima
    const suppressRadius = 10 * scaleFactor;
    const filtered: typeof corners = [];

    // Sort by response (strongest first)
    corners.sort((a, b) => b.response - a.response);

    for (const corner of corners) {
      // Check if this corner is suppressed by a stronger one
      const dominated = filtered.some(f => 
        Math.abs(f.x - corner.x) < suppressRadius && 
        Math.abs(f.y - corner.y) < suppressRadius
      );

      if (!dominated) {
        filtered.push(corner);
      }

      // Limit total corners for performance
      if (filtered.length > 500) break;
    }

    // Add as snap points (scale to display coordinates)
    for (const corner of filtered) {
      this.snapPoints.push({
        x: corner.x / scaleFactor,
        y: corner.y / scaleFactor,
        type: 'corner'
      });
    }

    this.buildSpatialIndex();
    console.log(`SnapEngine: Detected ${this.snapPoints.length} corners`);
  }

  /**
   * Add a snap point manually
   */
  addSnapPoint(x: number, y: number, type: SnapPoint['type']) {
    this.snapPoints.push({ x, y, type });
  }

  private buildSpatialIndex() {
    this.spatialIndex.clear();
    const cellSize = this.snapTolerance * 3;

    for (const point of this.snapPoints) {
      const cellX = Math.floor(point.x / cellSize);
      const cellY = Math.floor(point.y / cellSize);
      const key = `${cellX},${cellY}`;

      if (!this.spatialIndex.has(key)) {
        this.spatialIndex.set(key, []);
      }
      this.spatialIndex.get(key)!.push(point);
    }
  }

  findNearest(x: number, y: number): SnapResult {
    const cellSize = this.snapTolerance * 3;
    const cellX = Math.floor(x / cellSize);
    const cellY = Math.floor(y / cellSize);

    let nearest: SnapPoint | null = null;
    let minDist = Infinity;

    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        const key = `${cellX + dx},${cellY + dy}`;
        const points = this.spatialIndex.get(key);
        if (!points) continue;

        for (const point of points) {
          const dist = Math.sqrt(Math.pow(point.x - x, 2) + Math.pow(point.y - y, 2));
          if (dist < minDist) {
            minDist = dist;
            nearest = point;
          }
        }
      }
    }

    if (nearest && minDist <= this.snapTolerance) {
      return {
        snapped: true,
        point: { x: nearest.x, y: nearest.y },
        snapPoint: nearest,
        distance: minDist
      };
    }

    return {
      snapped: false,
      point: { x, y },
      distance: minDist
    };
  }

  getAllPoints(): SnapPoint[] {
    return [...this.snapPoints];
  }

  get count(): number {
    return this.snapPoints.length;
  }
}

export const snapEngine = new SnapEngine();

import type { Point } from '../types';

export interface SnapPoint {
  x: number;
  y: number;
  type: 'corner' | 'endpoint' | 'intersection';
  strength: number;
}

export interface SnapResult {
  snapped: boolean;
  point: Point;
  snapPoint?: SnapPoint;
  distance: number;
}

/**
 * Snap engine optimized for construction drawings
 * Focuses on line endpoints and intersections, filters out text
 */
export class SnapEngine {
  private snapPoints: SnapPoint[] = [];
  private snapTolerance: number = 15;
  private spatialIndex: Map<string, SnapPoint[]> = new Map();

  constructor(tolerance: number = 15) {
    this.snapTolerance = tolerance;
  }

  setTolerance(pixels: number) {
    this.snapTolerance = pixels;
  }

  clear() {
    this.snapPoints = [];
    this.spatialIndex.clear();
  }

  /**
   * Detect corners optimized for construction drawings
   * Uses multiple strategies and combines results
   */
  detectFromCanvas(canvas: HTMLCanvasElement, scaleFactor: number = 1) {
    this.clear();

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = canvas.width;
    const height = canvas.height;
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;

    // Convert to binary (line/not line)
    const threshold = 200;
    const binary = new Uint8Array(width * height);
    for (let i = 0; i < width * height; i++) {
      const r = data[i * 4];
      const g = data[i * 4 + 1];
      const b = data[i * 4 + 2];
      const gray = 0.299 * r + 0.587 * g + 0.114 * b;
      binary[i] = gray < threshold ? 1 : 0;
    }

    // Find line endpoints and intersections using connectivity analysis
    const step = Math.max(1, Math.floor(2 * scaleFactor));
    const candidates: { x: number; y: number; type: SnapPoint['type']; strength: number }[] = [];

    for (let y = 3; y < height - 3; y += step) {
      for (let x = 3; x < width - 3; x += step) {
        const idx = y * width + x;

        // Skip if not on a line
        if (binary[idx] === 0) continue;

        // Count neighbors in 8 directions and check connectivity pattern
        const n = this.getNeighborPattern(binary, width, x, y);

        // Endpoint: only 1 connected direction (line ends here)
        if (n.connected === 1) {
          candidates.push({ x, y, type: 'endpoint', strength: 100 });
        }
        // Corner: 2 connected directions that are adjacent (L-shape)
        else if (n.connected === 2 && n.isCorner) {
          candidates.push({ x, y, type: 'corner', strength: 80 });
        }
        // T-intersection or cross: 3-4 connected directions
        else if (n.connected >= 3) {
          candidates.push({ x, y, type: 'intersection', strength: 90 });
        }
      }
    }

    // Filter: prefer points that are on thicker lines (walls, not text)
    const filtered = candidates.filter(c => {
      // Check if this point is part of a thick line (multiple parallel dark pixels)
      const thickness = this.measureLineThickness(binary, width, height, c.x, c.y);
      return thickness >= 2; // At least 2 pixels thick
    });

    // Non-maximum suppression
    const suppressRadius = 8 * scaleFactor;
    const final: typeof candidates = [];

    // Sort by strength
    filtered.sort((a, b) => b.strength - a.strength);

    for (const point of filtered) {
      const dominated = final.some(f => 
        Math.abs(f.x - point.x) < suppressRadius && 
        Math.abs(f.y - point.y) < suppressRadius
      );

      if (!dominated) {
        final.push(point);
      }

      if (final.length > 300) break;
    }

    // Add as snap points
    for (const p of final) {
      this.snapPoints.push({
        x: p.x / scaleFactor,
        y: p.y / scaleFactor,
        type: p.type,
        strength: p.strength
      });
    }

    this.buildSpatialIndex();
    console.log(`SnapEngine: Detected ${this.snapPoints.length} snap points (endpoints: ${final.filter(f => f.type === 'endpoint').length}, corners: ${final.filter(f => f.type === 'corner').length}, intersections: ${final.filter(f => f.type === 'intersection').length})`);
  }

  private getNeighborPattern(binary: Uint8Array, width: number, x: number, y: number) {
    // Check 8 directions
    const dirs = [
      { dx: 0, dy: -1, name: 'N' },   // 0
      { dx: 1, dy: -1, name: 'NE' },  // 1
      { dx: 1, dy: 0, name: 'E' },    // 2
      { dx: 1, dy: 1, name: 'SE' },   // 3
      { dx: 0, dy: 1, name: 'S' },    // 4
      { dx: -1, dy: 1, name: 'SW' },  // 5
      { dx: -1, dy: 0, name: 'W' },   // 6
      { dx: -1, dy: -1, name: 'NW' }, // 7
    ];

    const connected: number[] = [];
    for (let i = 0; i < 8; i++) {
      const d = dirs[i];
      const idx = (y + d.dy) * width + (x + d.dx);
      if (binary[idx] === 1) {
        connected.push(i);
      }
    }

    // Check if it's a corner (two adjacent directions)
    let isCorner = false;
    if (connected.length === 2) {
      const diff = Math.abs(connected[0] - connected[1]);
      // Adjacent directions differ by 1, 2, 6, or 7
      isCorner = (diff === 1 || diff === 2 || diff === 6 || diff === 7);
    }

    return { connected: connected.length, isCorner, directions: connected };
  }

  private measureLineThickness(binary: Uint8Array, width: number, height: number, x: number, y: number): number {
    // Measure thickness by counting dark pixels in a small cross pattern
    let thickness = 1;

    // Horizontal thickness
    let hCount = 1;
    for (let dx = 1; dx <= 5; dx++) {
      if (x + dx < width && binary[y * width + x + dx] === 1) hCount++;
      else break;
    }
    for (let dx = 1; dx <= 5; dx++) {
      if (x - dx >= 0 && binary[y * width + x - dx] === 1) hCount++;
      else break;
    }

    // Vertical thickness
    let vCount = 1;
    for (let dy = 1; dy <= 5; dy++) {
      if (y + dy < height && binary[(y + dy) * width + x] === 1) vCount++;
      else break;
    }
    for (let dy = 1; dy <= 5; dy++) {
      if (y - dy >= 0 && binary[(y - dy) * width + x] === 1) vCount++;
      else break;
    }

    // Take the minimum (perpendicular to the line)
    thickness = Math.min(hCount, vCount);
    return thickness;
  }

  addSnapPoint(x: number, y: number, type: SnapPoint['type']) {
    this.snapPoints.push({ x, y, type, strength: 50 });
  }

  private buildSpatialIndex() {
    this.spatialIndex.clear();
    const cellSize = this.snapTolerance * 3;

    for (const point of this.snapPoints) {
      const cellX = Math.floor(point.x / cellSize);
      const cellY = Math.floor(point.y / cellSize);
      const key = `${cellX},${cellY}`;

      if (!this.spatialIndex.has(key)) {
        this.spatialIndex.set(key, []);
      }
      this.spatialIndex.get(key)!.push(point);
    }
  }

  findNearest(x: number, y: number): SnapResult {
    const cellSize = this.snapTolerance * 3;
    const cellX = Math.floor(x / cellSize);
    const cellY = Math.floor(y / cellSize);

    let nearest: SnapPoint | null = null;
    let minDist = Infinity;

    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        const key = `${cellX + dx},${cellY + dy}`;
        const points = this.spatialIndex.get(key);
        if (!points) continue;

        for (const point of points) {
          const dist = Math.sqrt(Math.pow(point.x - x, 2) + Math.pow(point.y - y, 2));
          if (dist < minDist) {
            minDist = dist;
            nearest = point;
          }
        }
      }
    }

    if (nearest && minDist <= this.snapTolerance) {
      return {
        snapped: true,
        point: { x: nearest.x, y: nearest.y },
        snapPoint: nearest,
        distance: minDist
      };
    }

    return {
      snapped: false,
      point: { x, y },
      distance: minDist
    };
  }

  getAllPoints(): SnapPoint[] {
    return [...this.snapPoints];
  }

  get count(): number {
    return this.snapPoints.length;
  }
}

