import type { Point } from '../types';

export interface SnapPoint {
  x: number;
  y: number;
  type: 'grid' | 'corner';
}

export interface SnapResult {
  snapped: boolean;
  point: Point;
  snapPoint?: SnapPoint;
  distance: number;
}

/**
 * Simple snap engine - samples dark pixels on a grid
 * Not fancy, but reliable for any PDF type
 */
export class SnapEngine {
  private snapPoints: SnapPoint[] = [];
  private snapTolerance: number = 20; // Increased tolerance
  private spatialIndex: Map<string, SnapPoint[]> = new Map();

  constructor(tolerance: number = 20) {
    this.snapTolerance = tolerance;
  }

  setTolerance(pixels: number) {
    this.snapTolerance = pixels;
  }

  clear() {
    this.snapPoints = [];
    this.spatialIndex.clear();
  }

  /**
   * Simple grid sampling - find dark pixels throughout the drawing
   */
  detectFromCanvas(canvas: HTMLCanvasElement, scaleFactor: number = 1) {
    this.clear();

    const ctx = canvas.getContext('2d');
    if (!ctx) {
      console.log('SnapEngine: No canvas context');
      return;
    }

    const width = canvas.width;
    const height = canvas.height;

    console.log(`SnapEngine: Analyzing canvas ${width}x${height}, scale=${scaleFactor}`);

    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;

    // Simple grid sampling
    const gridSpacing = 15 * scaleFactor; // Sample every 15 display pixels
    const threshold = 180; // Pixels darker than this are "drawing"

    let darkCount = 0;
    let totalSampled = 0;

    for (let y = 10; y < height - 10; y += gridSpacing) {
      for (let x = 10; x < width - 10; x += gridSpacing) {
        totalSampled++;
        const idx = (Math.floor(y) * width + Math.floor(x)) * 4;
        const r = data[idx];
        const g = data[idx + 1];
        const b = data[idx + 2];
        const gray = 0.299 * r + 0.587 * g + 0.114 * b;

        if (gray < threshold) {
          darkCount++;
          // Add snap point at display coordinates (not canvas coordinates)
          this.snapPoints.push({
            x: x / scaleFactor,
            y: y / scaleFactor,
            type: 'grid'
          });
        }
      }
    }

    this.buildSpatialIndex();
    console.log(`SnapEngine: Sampled ${totalSampled} points, found ${darkCount} dark pixels, created ${this.snapPoints.length} snap points`);
  }

  private buildSpatialIndex() {
    this.spatialIndex.clear();
    const cellSize = this.snapTolerance * 2;

    for (const point of this.snapPoints) {
      const cellX = Math.floor(point.x / cellSize);
      const cellY = Math.floor(point.y / cellSize);
      const key = `${cellX},${cellY}`;

      if (!this.spatialIndex.has(key)) {
        this.spatialIndex.set(key, []);
      }
      this.spatialIndex.get(key)!.push(point);
    }

    console.log(`SnapEngine: Built spatial index with ${this.spatialIndex.size} cells`);
  }

  findNearest(x: number, y: number): SnapResult {
    if (this.snapPoints.length === 0) {
      return { snapped: false, point: { x, y }, distance: Infinity };
    }

    const cellSize = this.snapTolerance * 2;
    const cellX = Math.floor(x / cellSize);
    const cellY = Math.floor(y / cellSize);

    let nearest: SnapPoint | null = null;
    let minDist = Infinity;

    // Check 3x3 neighborhood
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        const key = `${cellX + dx},${cellY + dy}`;
        const points = this.spatialIndex.get(key);
        if (!points) continue;

        for (const point of points) {
          const dist = Math.sqrt(Math.pow(point.x - x, 2) + Math.pow(point.y - y, 2));
          if (dist < minDist) {
            minDist = dist;
            nearest = point;
          }
        }
      }
    }

    if (nearest && minDist <= this.snapTolerance) {
      return {
        snapped: true,
        point: { x: nearest.x, y: nearest.y },
        snapPoint: nearest,
        distance: minDist
      };
    }

    return {
      snapped: false,
      point: { x, y },
      distance: minDist
    };
  }

  getAllPoints(): SnapPoint[] {
    return [...this.snapPoints];
  }

  get count(): number {
    return this.snapPoints.length;
  }
}

export const snapEngine = new SnapEngine();

