import { useRef, useEffect, useCallback, useState } from 'react';
import { useProjectStore } from '../stores/projectStore';
import { realDistance, polygonAreaFeet, formatMeasurement } from '../utils/geometry';
import { snapEngine, type SnapResult } from '../utils/snapEngine';
import type { Point, Measurement } from '../types';
import toast from 'react-hot-toast';

interface MeasurementCanvasProps {
  width: number;
  height: number;
  panOffset: Point;
}

const COLORS = [
  '#ef4444', '#f97316', '#eab308', '#22c55e', '#14b8a6',
  '#3b82f6', '#8b5cf6', '#ec4899'
];

export function MeasurementCanvas({ width, height }: MeasurementCanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [colorIndex, setColorIndex] = useState(0);
  const [tempPoints, setTempPoints] = useState<Point[]>([]);
  const [mousePos, setMousePos] = useState<Point | null>(null);
  const [snapResult, setSnapResult] = useState<SnapResult | null>(null);
  const [snapEnabled, setSnapEnabled] = useState(true);

  const {
    project,
    activeTool,
    zoom,
    isCalibrating,
    calibrationPoints,
    addCalibrationPoint,
    addMeasurement,
    selectedMeasurementId
  } = useProjectStore();

  // Get canvas-relative coordinates with optional snapping
  const getCanvasPoint = useCallback((e: React.MouseEvent, useSnap: boolean = true): Point => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };

    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    // Try to snap if enabled
    if (useSnap && snapEnabled && snapEngine.count > 0) {
      const result = snapEngine.findNearest(x, y);
      if (result.snapped) {
        return result.point;
      }
    }

    return { x, y };
  }, [snapEnabled]);

  // Track mouse position for rubber-banding and snap preview
  const handleMouseMove = useCallback((e: React.MouseEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    // Check for snap
    if (snapEnabled && snapEngine.count > 0) {
      const result = snapEngine.findNearest(x, y);
      setSnapResult(result);
      setMousePos(result.snapped ? result.point : { x, y });
    } else {
      setSnapResult(null);
      setMousePos({ x, y });
    }
  }, [snapEnabled]);

  const handleMouseLeave = useCallback(() => {
    setMousePos(null);
    setSnapResult(null);
  }, []);

  // Handle clicks
  const handleClick = useCallback((e: React.MouseEvent) => {
    if (!project) return;

    const point = getCanvasPoint(e);
    console.log('Click at:', point, 'Tool:', activeTool, 'Snapped:', snapResult?.snapped);

    // Calibration mode
    if (isCalibrating) {
      addCalibrationPoint(point);
      return;
    }

    // Need scale for measurements
    if (!project.scale) {
      toast.error('Please calibrate scale first');
      return;
    }

    // Linear measurement - 2 clicks
    if (activeTool === 'linear') {
      if (tempPoints.length === 0) {
        setTempPoints([point]);
        toast('Click second point', { icon: '📏' });
      } else {
        const points = [tempPoints[0], point];
        const distance = realDistance(points[0], points[1], project.scale);

        const measurement: Omit<Measurement, 'id' | 'createdAt'> = {
          type: 'linear',
          name: `Line ${project.measurements.length + 1}`,
          points,
          value: distance,
          unit: 'LF',
          color: COLORS[colorIndex % COLORS.length],
          pageNumber: project.currentPage
        };

        addMeasurement(measurement);
        setTempPoints([]);
        setColorIndex(c => c + 1);
        toast.success(`${formatMeasurement(distance, 'LF')}`);
      }
    }

    // Area measurement
    if (activeTool === 'area') {
      setTempPoints(prev => [...prev, point]);
    }

    // Count
    if (activeTool === 'count') {
      const measurement: Omit<Measurement, 'id' | 'createdAt'> = {
        type: 'count',
        name: `Count ${project.measurements.length + 1}`,
        points: [point],
        value: 1,
        unit: 'EA',
        color: COLORS[colorIndex % COLORS.length],
        pageNumber: project.currentPage
      };

      addMeasurement(measurement);
      setColorIndex(c => c + 1);
      toast.success('Count added');
    }
  }, [project, activeTool, isCalibrating, tempPoints, colorIndex, snapResult, getCanvasPoint, addCalibrationPoint, addMeasurement]);

  // Double-click to finish area
  const handleDoubleClick = useCallback(() => {
    if (activeTool === 'area' && tempPoints.length >= 3 && project?.scale) {
      const area = polygonAreaFeet(tempPoints, project.scale);

      const measurement: Omit<Measurement, 'id' | 'createdAt'> = {
        type: 'area',
        name: `Area ${project.measurements.length + 1}`,
        points: tempPoints,
        value: area,
        unit: 'SF',
        color: COLORS[colorIndex % COLORS.length],
        pageNumber: project.currentPage
      };

      addMeasurement(measurement);
      setTempPoints([]);
      setColorIndex(c => c + 1);
      toast.success(`${formatMeasurement(area, 'SF')}`);
    }
  }, [activeTool, tempPoints, project, colorIndex, addMeasurement]);

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setTempPoints([]);
        setMousePos(null);
      }
      if (e.key === 's' || e.key === 'S') {
        setSnapEnabled(prev => {
          toast(prev ? 'Snap OFF' : 'Snap ON', { icon: '🧲' });
          return !prev;
        });
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  // Clear temp points when tool changes
  useEffect(() => {
    setTempPoints([]);
    setMousePos(null);
  }, [activeTool]);

  // Draw everything
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d')!;
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw snap points (subtle, in background)
    if (snapEnabled && snapEngine.count > 0) {
      ctx.fillStyle = 'rgba(59, 130, 246, 0.15)';
      for (const sp of snapEngine.getAllPoints()) {
        ctx.beginPath();
        ctx.arc(sp.x, sp.y, 3, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    // Draw existing measurements
    project?.measurements
      .filter(m => m.pageNumber === project.currentPage)
      .forEach(m => {
        const isSelected = m.id === selectedMeasurementId;
        ctx.strokeStyle = m.color;
        ctx.fillStyle = m.color + '40';
        ctx.lineWidth = isSelected ? 3 : 2;

        if (m.type === 'linear' && m.points.length === 2) {
          ctx.beginPath();
          ctx.moveTo(m.points[0].x, m.points[0].y);
          ctx.lineTo(m.points[1].x, m.points[1].y);
          ctx.stroke();

          m.points.forEach(p => {
            ctx.beginPath();
            ctx.arc(p.x, p.y, 5, 0, Math.PI * 2);
            ctx.fill();
          });

          const midX = (m.points[0].x + m.points[1].x) / 2;
          const midY = (m.points[0].y + m.points[1].y) / 2;
          drawLabel(ctx, formatMeasurement(m.value, m.unit), midX, midY, m.color);
        }

        if (m.type === 'area' && m.points.length >= 3) {
          ctx.beginPath();
          ctx.moveTo(m.points[0].x, m.points[0].y);
          m.points.slice(1).forEach(p => ctx.lineTo(p.x, p.y));
          ctx.closePath();
          ctx.fill();
          ctx.stroke();

          const cx = m.points.reduce((sum, p) => sum + p.x, 0) / m.points.length;
          const cy = m.points.reduce((sum, p) => sum + p.y, 0) / m.points.length;
          drawLabel(ctx, formatMeasurement(m.value, m.unit), cx, cy, m.color);
        }

        if (m.type === 'count') {
          const p = m.points[0];
          ctx.beginPath();
          ctx.arc(p.x, p.y, 12, 0, Math.PI * 2);
          ctx.fill();
          ctx.stroke();

          ctx.fillStyle = '#fff';
          ctx.font = 'bold 12px sans-serif';
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';
          ctx.fillText(m.value.toString(), p.x, p.y);
        }
      });

    // Draw calibration points
    if (isCalibrating && calibrationPoints.length > 0) {
      ctx.strokeStyle = '#fbbf24';
      ctx.fillStyle = '#fbbf24';
      ctx.lineWidth = 2;
      ctx.setLineDash([5, 5]);

      calibrationPoints.forEach((p, i) => {
        ctx.beginPath();
        ctx.arc(p.x, p.y, 8, 0, Math.PI * 2);
        ctx.fill();

        if (i === 0 && calibrationPoints.length === 2) {
          ctx.beginPath();
          ctx.moveTo(calibrationPoints[0].x, calibrationPoints[0].y);
          ctx.lineTo(calibrationPoints[1].x, calibrationPoints[1].y);
          ctx.stroke();
        }
      });
      ctx.setLineDash([]);
    }

    // Draw temp points and rubber-band
    if (tempPoints.length > 0) {
      const color = COLORS[colorIndex % COLORS.length];
      ctx.strokeStyle = color;
      ctx.fillStyle = color;
      ctx.lineWidth = 2;
      ctx.setLineDash([5, 5]);

      tempPoints.forEach(p => {
        ctx.beginPath();
        ctx.arc(p.x, p.y, 5, 0, Math.PI * 2);
        ctx.fill();
      });

      if (mousePos && tempPoints.length > 0) {
        ctx.beginPath();
        ctx.moveTo(tempPoints[tempPoints.length - 1].x, tempPoints[tempPoints.length - 1].y);
        ctx.lineTo(mousePos.x, mousePos.y);
        ctx.stroke();
      }

      if (activeTool === 'area' && tempPoints.length > 1) {
        ctx.beginPath();
        ctx.moveTo(tempPoints[0].x, tempPoints[0].y);
        tempPoints.slice(1).forEach(p => ctx.lineTo(p.x, p.y));
        ctx.stroke();
      }

      ctx.setLineDash([]);
    }

    // Draw snap indicator
    if (snapResult?.snapped && mousePos) {
      ctx.strokeStyle = '#22c55e';
      ctx.fillStyle = '#22c55e';
      ctx.lineWidth = 2;

      // Crosshair
      const sp = snapResult.point;
      ctx.beginPath();
      ctx.moveTo(sp.x - 10, sp.y);
      ctx.lineTo(sp.x + 10, sp.y);
      ctx.moveTo(sp.x, sp.y - 10);
      ctx.lineTo(sp.x, sp.y + 10);
      ctx.stroke();

      // Circle
      ctx.beginPath();
      ctx.arc(sp.x, sp.y, 8, 0, Math.PI * 2);
      ctx.stroke();
    }

  }, [project, isCalibrating, calibrationPoints, tempPoints, mousePos, activeTool, colorIndex, selectedMeasurementId, snapResult, snapEnabled]);

  return (
    <canvas
      ref={canvasRef}
      width={width}
      height={height}
      className="absolute top-0 left-0"
      style={{ 
        width, 
        height, 
        pointerEvents: 'auto',
        cursor: snapResult?.snapped ? 'crosshair' : 'default'
      }}
      onClick={handleClick}
      onDoubleClick={handleDoubleClick}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
    />
  );
}

function drawLabel(ctx: CanvasRenderingContext2D, text: string, x: number, y: number, color: string) {
  ctx.font = 'bold 12px sans-serif';
  const metrics = ctx.measureText(text);
  const padding = 6;
  const w = metrics.width + padding * 2;
  const h = 20;

  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.roundRect(x - w/2, y - h/2, w, h, 4);
  ctx.fill();

  ctx.fillStyle = '#fff';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, x, y);
}

