const handleSubmit = (e: React.FormEvent) => {
  e.preventDefault();

  if (mode === 'manual') {
    const value = parseFloat(distance);
    if (isNaN(value) || value <= 0) {
      toast.error('Please enter a valid distance');
      return;
    }
    completeCalibration(value, unit);
    toast.success('Scale calibrated');
  } else {
    // Scale mode: calculate real distance from architectural scale
    const scale = ARCH_SCALES.find(s => s.label === selectedScale);
    if (!scale) {
      toast.error('Please select a scale');
      return;
    }
    const inches = parseFloat(scaleBarInches);
    if (isNaN(inches) || inches <= 0) {
      toast.error('Please enter valid scale bar length');
      return;
    }
    // Real feet = inches on paper × feet per inch for this scale
    const realFeet = inches * scale.feetPerInch;
    completeCalibration(realFeet, 'ft');
    toast.success(`Scale set: ${scale.label}`);
  }
  onClose();
};

