import { useProjectStore } from '../stores/projectStore';
import type { Tool } from '../types';

interface ToolButtonProps {
  tool: Tool;
  icon: string;
  label: string;
  shortcut?: string;
  disabled?: boolean;
}

function ToolButton({ tool, icon, label, shortcut, disabled }: ToolButtonProps) {
  const { activeTool, setActiveTool, startCalibration } = useProjectStore();
  const isActive = activeTool === tool;

  const handleClick = () => {
    if (disabled) return;
    if (tool === 'calibrate') {
      startCalibration();
    } else {
      setActiveTool(tool);
    }
  };

  return (
    <button
      onClick={handleClick}
      disabled={disabled}
      title={`${label}${shortcut ? ` (${shortcut})` : ''}`}
      className="flex items-center gap-2 px-4 py-2 rounded text-sm font-medium transition-all duration-150"
      style={{
        background: isActive ? '#c9a227' : 'transparent',
        color: isActive ? '#1a2f3d' : disabled ? '#4a6a7a' : '#e8f1f5',
        cursor: disabled ? 'not-allowed' : 'pointer',
        opacity: disabled ? 0.5 : 1,
        border: isActive ? 'none' : '1px solid transparent',
      }}
      onMouseEnter={(e) => {
        if (!disabled && !isActive) {
          e.currentTarget.style.background = '#2d4a5e';
          e.currentTarget.style.borderColor = '#4a6a7a';
        }
      }}
      onMouseLeave={(e) => {
        if (!isActive) {
          e.currentTarget.style.background = 'transparent';
          e.currentTarget.style.borderColor = 'transparent';
        }
      }}
    >
      <span className="text-lg">{icon}</span>
      <span className="hidden sm:inline">{label}</span>
    </button>
  );
}

function Divider() {
  return <div className="w-px h-6 mx-2" style={{ background: '#2d4a5e' }} />;
}

export function Toolbar() {
  const { project, zoom, setZoom, setCurrentPage } = useProjectStore();

  if (!project) return null;

  return (
    <div className="px-4 py-2 flex items-center justify-between"
         style={{ 
           background: '#152a36',
           borderBottom: '1px solid #2d4a5e'
         }}>
      {/* Left: Tools */}
      <div className="flex items-center">
        <ToolButton tool="select" icon="↖" label="Select" shortcut="V" />
        <ToolButton tool="pan" icon="✋" label="Pan" shortcut="H" />

        <Divider />

        <ToolButton 
          tool="calibrate" 
          icon="📏" 
          label="Calibrate" 
          shortcut="C"
        />

        <Divider />

        <ToolButton 
          tool="linear" 
          icon="📐" 
          label="Linear" 
          shortcut="L"
          disabled={!project.scale}
        />
        <ToolButton 
          tool="area" 
          icon="⬛" 
          label="Area" 
          shortcut="A"
          disabled={!project.scale}
        />
        <ToolButton 
          tool="count" 
          icon="🔢" 
          label="Count" 
          shortcut="N"
          disabled={!project.scale}
        />
      </div>

      {/* Center: Page Navigation */}
      <div className="flex items-center gap-3 px-4 py-1 rounded"
           style={{ background: '#1a2f3d', border: '1px solid #2d4a5e' }}>
        <button
          onClick={() => setCurrentPage(project.currentPage - 1)}
          disabled={project.currentPage <= 1}
          className="px-2 py-1 rounded transition-colors"
          style={{ 
            color: project.currentPage <= 1 ? '#4a6a7a' : '#e8f1f5',
            cursor: project.currentPage <= 1 ? 'not-allowed' : 'pointer'
          }}
        >
          ◀
        </button>
        <span className="text-sm min-w-24 text-center" style={{ color: '#8b7355' }}>
          Page {project.currentPage} of {project.totalPages}
        </span>
        <button
          onClick={() => setCurrentPage(project.currentPage + 1)}
          disabled={project.currentPage >= project.totalPages}
          className="px-2 py-1 rounded transition-colors"
          style={{ 
            color: project.currentPage >= project.totalPages ? '#4a6a7a' : '#e8f1f5',
            cursor: project.currentPage >= project.totalPages ? 'not-allowed' : 'pointer'
          }}
        >
          ▶
        </button>
      </div>

      {/* Right: Zoom */}
      <div className="flex items-center gap-2">
        <button
          onClick={() => setZoom(zoom - 0.25)}
          className="px-3 py-1 rounded transition-colors"
          style={{ color: '#e8f1f5' }}
          onMouseEnter={(e) => e.currentTarget.style.background = '#2d4a5e'}
          onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
        >
          −
        </button>
        <span className="text-sm min-w-16 text-center" style={{ color: '#8b7355' }}>
          {Math.round(zoom * 100)}%
        </span>
        <button
          onClick={() => setZoom(zoom + 0.25)}
          className="px-3 py-1 rounded transition-colors"
          style={{ color: '#e8f1f5' }}
          onMouseEnter={(e) => e.currentTarget.style.background = '#2d4a5e'}
          onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
        >
          +
        </button>
        <button
          onClick={() => setZoom(1)}
          className="px-3 py-1 rounded text-sm transition-colors"
          style={{ color: '#c9a227', border: '1px solid #5a4020' }}
          onMouseEnter={(e) => e.currentTarget.style.background = '#2d4a5e'}
          onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
        >
          Fit
        </button>
      </div>
    </div>
  );
}

