// Common dimension presets (in feet)
const QUICK_DIMENSIONS = [
  { label: "3'-0\"", value: 3 },
  { label: "5'-0\"", value: 5 },
  { label: "10'-0\"", value: 10 },
  { label: "15'-0\"", value: 15 },
  { label: "20'-0\"", value: 20 },
  { label: "25'-0\"", value: 25 },
  { label: "50'-0\"", value: 50 },
  { label: "100'-0\"", value: 100 },
] as const;

// Parse architectural notation like 19'-3 1/4" or 19'-3.25" to decimal feet
function parseDimension(input: string): number | null {
  const trimmed = input.trim();

  // Try decimal feet first (e.g., "19.27")
  const decimal = parseFloat(trimmed);
  if (!isNaN(decimal) && !trimmed.includes("'") && !trimmed.includes('"')) {
    return decimal;
  }

  // Try feet-inches format: 19'-3 1/4" or 19'-3" or 19'
  const feetInchesMatch = trimmed.match(/^(\d+)'[-\s]*(?:(\d+)?(?:\s+(\d+)\/(\d+))?"?)?$/);
  if (feetInchesMatch) {
    const feet = parseInt(feetInchesMatch[1]) || 0;
    const inches = parseInt(feetInchesMatch[2]) || 0;
    const fracNum = parseInt(feetInchesMatch[3]) || 0;
    const fracDen = parseInt(feetInchesMatch[4]) || 1;
    return feet + (inches + fracNum / fracDen) / 12;
  }

  // Try just inches: 36" or 36 1/2"
  const inchesMatch = trimmed.match(/^(\d+)(?:\s+(\d+)\/(\d+))?"$/);
  if (inchesMatch) {
    const inches = parseInt(inchesMatch[1]) || 0;
    const fracNum = parseInt(inchesMatch[2]) || 0;
    const fracDen = parseInt(inchesMatch[3]) || 1;
    return (inches + fracNum / fracDen) / 12;
  }

  return null;
}

