            style={{
              background: mode === 'scale' ? '#1e3a4c' : 'transparent',
              border: `1px solid ${mode === 'scale' ? '#3b82f6' : '#2d4a5e'}`,
              color: mode === 'scale' ? '#e8f1f5' : '#8b7355'
            }}
          >
            📐 Preset Scale
          </button>
          <button
            type="button"
            onClick={() => setMode('manual')}
