                  color: '#e8f1f5'
                }}
              >
                <option value="">Select drawing scale...</option>
                <optgroup label="Architectural">
                  {ARCH_SCALES.slice(0, 8).map(s => (
                    <option key={s.label} value={s.label}>{s.label}</option>
                  ))}
                </optgroup>
                <optgroup label="Engineering">
                  {ARCH_SCALES.slice(8).map(s => (
                    <option key={s.label} value={s.label}>{s.label}</option>
