  const isValidScaleBar = selectedScaleObj && !isNaN(scaleBarInchesNum) && scaleBarInchesNum > 0;
  const scaleBarFeet = isValidScaleBar ? scaleBarInchesNum * selectedScaleObj!.feetPerInch : 0;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (mode === 'dimension') {
      if (!isValidDimension) {
        toast.error('Please enter a valid dimension');
        return;
      }
      completeCalibration(parsedValue!, 'ft');
      toast.success('Scale set from dimension');
    } else {
      if (!isValidScaleBar) {
        toast.error('Please select scale and enter scale bar length');
        return;
      }
      completeCalibration(scaleBarFeet, 'ft');
      toast.success(`Scale set: ${selectedScale}`);
    }
    onClose();
  };

  const handleCancel = () => {
    cancelCalibration();
    onClose();
  };

  return (
    <div className="fixed inset-0 flex items-center justify-center z-50"
         style={{ background: 'rgba(15, 28, 36, 0.9)' }}>
      <div className="rounded-lg shadow-2xl p-6 w-full max-w-md"
           style={{ 
             background: 'linear-gradient(135deg, #1a2f3d 0%, #152a36 100%)',
             border: '1px solid #2d4a5e'
           }}>
        <h2 className="text-xl font-bold mb-4" 
            style={{ fontFamily: 'Playfair Display, serif', color: '#c9a227' }}>
          📏 Set Scale
        </h2>

        {/* Mode toggle */}
        <div className="flex gap-2 mb-4">
          <button
            type="button"
            onClick={() => setMode('dimension')}
            className="flex-1 px-3 py-2 rounded-lg text-sm transition-colors"
            style={{
              background: mode === 'dimension' ? '#1e3a4c' : 'transparent',
              border: `1px solid ${mode === 'dimension' ? '#3b82f6' : '#2d4a5e'}`,
              color: mode === 'dimension' ? '#e8f1f5' : '#8b7355'
            }}
          >
            📐 Known Dimension
          </button>
          <button
            type="button"
            onClick={() => setMode('scalebar')}
            className="flex-1 px-3 py-2 rounded-lg text-sm transition-colors"
            style={{
              background: mode === 'scalebar' ? '#1e3a4c' : 'transparent',
              border: `1px solid ${mode === 'scalebar' ? '#3b82f6' : '#2d4a5e'}`,
              color: mode === 'scalebar' ? '#e8f1f5' : '#8b7355'
            }}
          >
            📏 Scale Bar
          </button>
        </div>

        <form onSubmit={handleSubmit}>
          {mode === 'dimension' ? (
            <>
              <p className="text-sm mb-3" style={{ color: '#8b7355' }}>
                Enter the dimension shown on the drawing for the line you clicked.
              </p>

              {/* Quick presets */}
              <div className="flex flex-wrap gap-2 mb-3">
                {QUICK_DIMENSIONS.map((preset) => (
                  <button
                    key={preset.label}
                    type="button"
                    onClick={() => setDistance(preset.value.toString())}
                    className="px-3 py-1.5 text-sm rounded transition-colors"
                    style={{ 
                      background: parsedValue === preset.value ? '#2d5a3d' : '#0f1c24',
                      border: `1px solid ${parsedValue === preset.value ? '#7cb798' : '#2d4a5e'}`,
                      color: parsedValue === preset.value ? '#7cb798' : '#8b7355'
                    }}
                  >
                    {preset.label}
                  </button>
                ))}
              </div>

              <input
                type="text"
                value={distance}
                onChange={(e) => setDistance(e.target.value)}
                placeholder="e.g., 19'-3 1/4&quot; or 19.27"
                className="w-full rounded-lg px-4 py-3 mb-2 focus:outline-none"
                style={{
                  background: '#0f1c24',
                  border: `1px solid ${distance && !isValidDimension ? '#ef4444' : '#2d4a5e'}`,
                  color: '#e8f1f5'
                }}
                autoFocus
              />
              <p className="text-xs mb-4" style={{ color: '#4a6a7a' }}>
                Formats: 19'-3 1/4" • 19'-3" • 19' • 19.27 • 36"
              </p>

              {distance && isValidDimension && (
                <div className="p-3 rounded-lg mb-4 text-sm"
                     style={{ background: '#0f1c24', border: '1px solid #2d5a3d', color: '#7cb798' }}>
                  ✓ {parsedValue!.toFixed(2)} feet
                </div>
              )}
            </>
          ) : (
            <>
              <p className="text-sm mb-3" style={{ color: '#8b7355' }}>
                Select the drawing scale, then enter how many inches the scale bar shows.
              </p>

              {/* Drawing scale dropdown */}
              <select
                value={selectedScale}
                onChange={(e) => setSelectedScale(e.target.value)}
                className="w-full rounded-lg px-4 py-3 mb-3 focus:outline-none cursor-pointer"
                style={{
                  background: '#0f1c24',
                  border: '1px solid #2d4a5e',
                  color: '#e8f1f5'
                }}
              >
                <optgroup label="Architectural">
                  {ARCH_SCALES.slice(0, 7).map(s => (
                    <option key={s.label} value={s.label}>{s.label}</option>
                  ))}
                </optgroup>
                <optgroup label="Engineering">
                  {ARCH_SCALES.slice(7).map(s => (
                    <option key={s.label} value={s.label}>{s.label}</option>
                  ))}
                </optgroup>
              </select>

              {/* Scale bar inches input */}
              <div className="flex gap-2 mb-3">
                <input
                  type="number"
                  step="0.25"
                  min="0.25"
                  value={scaleBarInches}
                  onChange={(e) => setScaleBarInches(e.target.value)}
                  className="flex-1 rounded-lg px-4 py-3 focus:outline-none"
                  style={{
                    background: '#0f1c24',
                    border: '1px solid #2d4a5e',
                    color: '#e8f1f5'
                  }}
                />
                <span className="flex items-center px-4 rounded-lg text-sm"
                      style={{ background: '#0f1c24', border: '1px solid #2d4a5e', color: '#8b7355' }}>
                  inch scale bar
                </span>
              </div>

              {/* Preview */}
              {isValidScaleBar && (
                <div className="p-3 rounded-lg mb-4 text-sm"
                     style={{ background: '#0f1c24', border: '1px solid #2d5a3d', color: '#7cb798' }}>
                  ✓ {scaleBarInches}" scale bar = {scaleBarFeet.toFixed(1)}' real distance
                </div>
              )}

              <div className="p-3 rounded-lg mb-4 text-xs"
                   style={{ background: '#1a2a35', border: '1px solid #2d4a5e', color: '#8b7355' }}>
                <strong>How it works:</strong> At {selectedScale}, every 1" on paper = {selectedScaleObj?.feetPerInch}' real.
                Click on a graphic scale bar showing inch marks.
              </div>
            </>
          )}

          <div className="flex gap-3">
            <button
              type="button"
              onClick={handleCancel}
              className="flex-1 px-4 py-3 rounded-lg transition-colors"
              style={{ 
                border: '1px solid #4a6a7a',
                color: '#8b7355'
              }}
              onMouseEnter={(e) => e.currentTarget.style.background = '#2d4a5e'}
              onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={mode === 'dimension' ? !isValidDimension : !isValidScaleBar}
              className="flex-1 px-4 py-3 rounded-lg font-medium transition-all"
              style={{ 
                background: (mode === 'dimension' ? isValidDimension : isValidScaleBar)
                  ? 'linear-gradient(135deg, #c9a227 0%, #a68520 100%)'
                  : '#2d4a5e',
                color: (mode === 'dimension' ? isValidDimension : isValidScaleBar) ? '#1a2f3d' : '#8b7355',
                cursor: (mode === 'dimension' ? isValidDimension : isValidScaleBar) ? 'pointer' : 'not-allowed'
              }}
            >
              Set Scale
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

