content.text:
import { create } from 'zustand';
import type { Project, Measurement, MeasurementGroup, Tool, Point } from '../types';

interface ProjectState {
  // Current project
  project: Project | null;

  // UI State
  activeTool: Tool;
  zoom: number;
  panOffset: Point;
  selectedMeasurementId: string | null;

  // Calibration state
  isCalibrating: boolean;
  calibrationPoints: Point[];

  // Drawing state
  isDrawing: boolean;
  currentPoints: Point[];

  // Actions
  setProject: (project: Project) => void;
  setActiveTool: (tool: Tool) => void;
  setZoom: (zoom: number) => void;
  setPanOffset: (offset: Point) => void;
  setCurrentPage: (page: number) => void;

  // Calibration
  startCalibration: () => void;
  addCalibrationPoint: (point: Point) => void;
  completeCalibration: (knownDistance: number, unit: 'ft' | 'in' | 'm') => void;
  cancelCalibration: () => void;

  // Measurements
  addMeasurement: (measurement: Omit<Measurement, 'id' | 'createdAt'>) => void;
  updateMeasurement: (id: string, updates: Partial<Measurement>) => void;
  deleteMeasurement: (id: string) => void;
  selectMeasurement: (id: string | null) => void;

  // Drawing
  startDrawing: () => void;
  addPoint: (point: Point) => void;
  finishDrawing: () => Point[];
  cancelDrawing: () => void;

  // Groups
  addGroup: (name: string) => void;
  deleteGroup: (id: string) => void;
  addToGroup: (measurementId: string, groupId: string) => void;
}

const generateId = () => Math.random().toString(36).substring(2, 15);

const COLORS = [
  '#ef4444', '#f97316', '#eab308', '#22c55e', '#14b8a6',
  '#3b82f6', '#8b5cf6', '#ec4899', '#06b6d4', '#84cc16'
];

export const useProjectStore = create<ProjectState>((set, get) => ({
  project: null,
  activeTool: 'pan',
  zoom: 1,
  panOffset: { x: 0, y: 0 },
  selectedMeasurementId: null,
  isCalibrating: false,
  calibrationPoints: [],
  isDrawing: false,
  currentPoints: [],

  setProject: (project) => set({ project }),

  setActiveTool: (tool) => {
    const state = get();
    // Cancel any in-progress drawing when switching tools
    if (state.isDrawing) {
      set({ isDrawing: false, currentPoints: [] });
    }
    if (state.isCalibrating && tool !== 'calibrate') {
      set({ isCalibrating: false, calibrationPoints: [] });
    }
    set({ activeTool: tool });
  },

  setZoom: (zoom) => set({ zoom: Math.max(0.1, Math.min(5, zoom)) }),

  setPanOffset: (offset) => set({ panOffset: offset }),

  setCurrentPage: (page) => {
    const { project } = get();
    if (project && page >= 1 && page <= project.totalPages) {
      set({ project: { ...project, currentPage: page } });
    }
  },

  // Calibration
  startCalibration: () => set({ 
    isCalibrating: true, 
    calibrationPoints: [],
    activeTool: 'calibrate'
  }),

  addCalibrationPoint: (point) => {
    const { calibrationPoints } = get();
    if (calibrationPoints.length < 2) {
      set({ calibrationPoints: [...calibrationPoints, point] });
    }
  },

  completeCalibration: (knownDistance, unit) => {
    const { project, calibrationPoints } = get();
    if (!project || calibrationPoints.length !== 2) return;

    const [p1, p2] = calibrationPoints;
    const pixelDistance = Math.sqrt(
      Math.pow(p2.x - p1.x, 2) + Math.pow(p2.y - p1.y, 2)
    );

    // Convert to feet
    let distanceInFeet = knownDistance;
    if (unit === 'in') distanceInFeet = knownDistance / 12;
    if (unit === 'm') distanceInFeet = knownDistance * 3.28084;

    const scale = pixelDistance / distanceInFeet;

    set({
      project: { ...project, scale, scaleUnit: unit },
      isCalibrating: false,
      calibrationPoints: [],
      activeTool: 'select'
    });
  },

  cancelCalibration: () => set({
    isCalibrating: false,
    calibrationPoints: [],
    activeTool: 'select'
  }),

  // Measurements
  addMeasurement: (measurement) => {
    const { project } = get();
    if (!project) return;

    const newMeasurement: Measurement = {
      ...measurement,
      id: generateId(),
      createdAt: new Date()
    };

    set({
      project: {
        ...project,
        measurements: [...project.measurements, newMeasurement],
        updatedAt: new Date()
      }
    });
  },

  updateMeasurement: (id, updates) => {
    const { project } = get();
    if (!project) return;

    set({
      project: {
        ...project,
        measurements: project.measurements.map(m =>
          m.id === id ? { ...m, ...updates } : m
        ),
        updatedAt: new Date()
      }
    });
  },

  deleteMeasurement: (id) => {
    const { project, selectedMeasurementId } = get();
    if (!project) return;

    set({
      project: {
        ...project,
        measurements: project.measurements.filter(m => m.id !== id),
        groups: project.groups.map(g => ({
          ...g,
          measurementIds: g.measurementIds.filter(mId => mId !== id)
        })),
        updatedAt: new Date()
      },
      selectedMeasurementId: selectedMeasurementId === id ? null : selectedMeasurementId
    });
  },

  selectMeasurement: (id) => set({ selectedMeasurementId: id }),

  // Drawing
  startDrawing: () => set({ isDrawing: true, currentPoints: [] }),

  addPoint: (point) => {
    const { currentPoints } = get();
    set({ currentPoints: [...currentPoints, point] });
  },

  finishDrawing: () => {
    const { currentPoints } = get();
    set({ isDrawing: false, currentPoints: [] });
    return currentPoints;
  },

  cancelDrawing: () => set({ isDrawing: false, currentPoints: [] }),

  // Groups
  addGroup: (name) => {
    const { project } = get();
    if (!project) return;

    const colorIndex = project.groups.length % COLORS.length;
    const newGroup: MeasurementGroup = {
      id: generateId(),
      name,
      color: COLORS[colorIndex],
      measurementIds: [],
      collapsed: false
    };

    set({
      project: {
        ...project,
        groups: [...project.groups, newGroup],
        updatedAt: new Date()
      }
    });
  },

  deleteGroup: (id) => {
    const { project } = get();
    if (!project) return;

    set({
      project: {
        ...project,
        groups: project.groups.filter(g => g.id !== id),
        updatedAt: new Date()
      }
    });
  },

  addToGroup: (measurementId, groupId) => {
    const { project } = get();
    if (!project) return;

    set({
      project: {
        ...project,
        groups: project.groups.map(g => {
          if (g.id === groupId) {
            return {
              ...g,
              measurementIds: [...new Set([...g.measurementIds, measurementId])]
            };
          }
          // Remove from other groups
          return {
            ...g,
            measurementIds: g.measurementIds.filter(id => id !== measurementId)
          };
        }),
        updatedAt: new Date()
      }
    });
  }
}));

