// Set scale directly from architectural scale (assumes standard PDF 72 units/inch)
setScaleFromArchScale: (feetPerInch: number) => {
  const { project, zoom } = get();
  if (!project) return;

  // PDF standard: 72 units per inch
  // Our render: zoom * 2 (retina)
  // At architectural scale X" = 1'-0", feetPerInch = 12/X
  // Paper inches per foot = 1/feetPerInch
  // PDF units per foot = 72 / feetPerInch
  // Pixels per foot = (72 / feetPerInch) * renderScale
  const renderScale = zoom * 2;
  const pixelsPerFoot = (72 / feetPerInch) * renderScale;

  set({
    project: { ...project, scale: pixelsPerFoot, scaleUnit: 'ft' },
    isCalibrating: false,
    calibrationPoints: [],
    activeTool: 'select'
  });
},

