/**
 * Convert decimal feet to feet-inches string (e.g., 8'-3 1/4")
 */
export function decimalFeetToFeetInches(decimalFeet: number): string {
  const feet = Math.floor(decimalFeet);
  const remainingInches = (decimalFeet - feet) * 12;
  const wholeInches = Math.floor(remainingInches);
  const fraction = remainingInches - wholeInches;

  // Convert fraction to nearest 1/16th
  const sixteenths = Math.round(fraction * 16);

  let fractionStr = '';
  if (sixteenths > 0 && sixteenths < 16) {
    // Simplify the fraction
    const gcd = (a: number, b: number): number => b === 0 ? a : gcd(b, a % b);
    const divisor = gcd(sixteenths, 16);
    const num = sixteenths / divisor;
    const den = 16 / divisor;
    fractionStr = ` ${num}/${den}`;
  }

  if (feet === 0) {
    return `${wholeInches}${fractionStr}"`;
  } else if (wholeInches === 0 && sixteenths === 0) {
    return `${feet}'-0"`;
  } else {
    return `${feet}'-${wholeInches}${fractionStr}"`;
  }
}

/**
 * Format a measurement value for display
 */
export function formatMeasurement(value: number, unit: string): string {
  if (unit === 'EA') {
    return `${Math.round(value)} EA`;
  }

  // For linear feet, display in feet-inches format
  if (unit === 'LF') {
    return decimalFeetToFeetInches(value);
  }

  // For SF, show appropriate decimal precision
  if (value >= 100) {
    return `${Math.round(value).toLocaleString()} ${unit}`;
  } else if (value >= 10) {
    return `${value.toFixed(1)} ${unit}`;
  } else {
    return `${value.toFixed(2)} ${unit}`;
  }
}

