import { useState } from 'react';
import { useProjectStore } from '../stores/projectStore';
import { formatMeasurement } from '../utils/geometry';
import type { Measurement } from '../types';

export function MeasurementPanel() {
  const { 
    project, 
    selectedMeasurementId, 
    selectMeasurement,
    updateMeasurement,
    deleteMeasurement 
  } = useProjectStore();

  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');

  if (!project) return null;

  const measurements = project.measurements;

  // Group by type
  const linear = measurements.filter(m => m.type === 'linear');
  const areas = measurements.filter(m => m.type === 'area');
  const counts = measurements.filter(m => m.type === 'count');

  // Totals
  const totalLF = linear.reduce((sum, m) => sum + m.value, 0);
  const totalSF = areas.reduce((sum, m) => sum + m.value, 0);
  const totalCount = counts.reduce((sum, m) => sum + m.value, 0);

  const handleEdit = (m: Measurement) => {
    setEditingId(m.id);
    setEditName(m.name);
  };

  const handleSaveEdit = (id: string) => {
    updateMeasurement(id, { name: editName });
    setEditingId(null);
  };

  const handleDelete = (id: string) => {
    if (confirm('Delete this measurement?')) {
      deleteMeasurement(id);
    }
  };

  return (
    <div className="w-80 flex flex-col"
         style={{ 
           background: 'linear-gradient(180deg, #1a2f3d 0%, #152a36 100%)',
           borderLeft: '1px solid #2d4a5e'
         }}>
      {/* Header */}
      <div className="p-4" style={{ borderBottom: '1px solid #2d4a5e' }}>
        <h2 className="text-lg font-semibold" 
            style={{ fontFamily: 'Playfair Display, serif', color: '#c9a227' }}>
          Measurements
        </h2>
        <p className="text-sm" style={{ color: '#8b7355' }}>
          {measurements.length} {measurements.length === 1 ? 'item' : 'items'}
        </p>
      </div>

      {/* Totals */}
      <div className="p-4" style={{ background: '#0f1c24', borderBottom: '1px solid #2d4a5e' }}>
        <div className="grid grid-cols-3 gap-2 text-center">
          <div>
            <div className="text-lg font-bold" style={{ color: '#5fa8d3' }}>
              {formatMeasurement(totalLF, 'LF')}
            </div>
            <div className="text-xs" style={{ color: '#4a6a7a' }}>Linear</div>
          </div>
          <div>
            <div className="text-lg font-bold" style={{ color: '#7cb798' }}>
              {formatMeasurement(totalSF, 'SF')}
            </div>
            <div className="text-xs" style={{ color: '#4a6a7a' }}>Area</div>
          </div>
          <div>
            <div className="text-lg font-bold" style={{ color: '#c9a227' }}>
              {totalCount} EA
            </div>
            <div className="text-xs" style={{ color: '#4a6a7a' }}>Count</div>
          </div>
        </div>
      </div>

      {/* Measurement List */}
      <div className="flex-1 overflow-y-auto">
        {measurements.length === 0 ? (
          <div className="p-8 text-center" style={{ color: '#4a6a7a' }}>
            <div className="text-4xl mb-4 opacity-50">📐</div>
            <p className="font-medium" style={{ color: '#8b7355' }}>
              No measurements yet
            </p>
            <p className="text-sm mt-2">
              Calibrate scale, then start measuring
            </p>
          </div>
        ) : (
          <div className="p-2">
            {measurements.map(m => (
              <div
                key={m.id}
                onClick={() => selectMeasurement(m.id)}
                className="p-3 rounded mb-2 cursor-pointer transition-all duration-150"
                style={{
                  background: selectedMeasurementId === m.id ? '#2d4a5e' : '#1e3a4c',
                  border: selectedMeasurementId === m.id 
                    ? '1px solid #c9a227' 
                    : '1px solid transparent'
                }}
                onMouseEnter={(e) => {
                  if (selectedMeasurementId !== m.id) {
                    e.currentTarget.style.background = '#243d4d';
                  }
                }}
                onMouseLeave={(e) => {
                  if (selectedMeasurementId !== m.id) {
                    e.currentTarget.style.background = '#1e3a4c';
                  }
                }}
              >
                <div className="flex items-center gap-2">
                  {/* Color indicator */}
                  <div 
                    className="w-3 h-3 rounded-full"
                    style={{ backgroundColor: m.color }}
                  />

                  {/* Name */}
                  {editingId === m.id ? (
                    <input
                      type="text"
                      value={editName}
                      onChange={(e) => setEditName(e.target.value)}
                      onBlur={() => handleSaveEdit(m.id)}
                      onKeyDown={(e) => e.key === 'Enter' && handleSaveEdit(m.id)}
                      className="flex-1 px-2 py-1 rounded text-sm"
                      style={{ 
                        background: '#1a2f3d', 
                        color: '#e8f1f5',
                        border: '1px solid #4a6a7a'
                      }}
                      autoFocus
                      onClick={(e) => e.stopPropagation()}
                    />
                  ) : (
                    <span 
                      className="flex-1 text-sm truncate"
                      style={{ color: '#e8f1f5' }}
                      onDoubleClick={(e) => {
                        e.stopPropagation();
                        handleEdit(m);
                      }}
                    >
                      {m.name}
                    </span>
                  )}

                  {/* Value */}
                  <span className="text-sm font-mono" style={{ color: '#8b7355' }}>
                    {formatMeasurement(m.value, m.unit)}
                  </span>
                </div>

                {/* Actions (visible when selected) */}
                {selectedMeasurementId === m.id && (
                  <div className="flex gap-3 mt-2 pt-2" 
                       style={{ borderTop: '1px solid #3d5a6e' }}>
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        handleEdit(m);
                      }}
                      className="text-xs transition-colors"
                      style={{ color: '#8b7355' }}
                      onMouseEnter={(e) => e.currentTarget.style.color = '#c9a227'}
                      onMouseLeave={(e) => e.currentTarget.style.color = '#8b7355'}
                    >
                      ✏️ Rename
                    </button>
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        handleDelete(m.id);
                      }}
                      className="text-xs transition-colors"
                      style={{ color: '#a65d37' }}
                      onMouseEnter={(e) => e.currentTarget.style.color = '#d47a4a'}
                      onMouseLeave={(e) => e.currentTarget.style.color = '#a65d37'}
                    >
                      🗑️ Delete
                    </button>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Export Button */}
      {measurements.length > 0 && (
        <div className="p-4" style={{ borderTop: '1px solid #2d4a5e' }}>
          <button
            onClick={() => exportToCSV(measurements, project.name)}
            className="w-full py-3 px-4 rounded font-medium transition-all duration-150"
            style={{ 
              background: 'linear-gradient(135deg, #c9a227 0%, #a68520 100%)',
              color: '#1a2f3d',
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.transform = 'translateY(-1px)';
              e.currentTarget.style.boxShadow = '0 4px 12px rgba(201, 162, 39, 0.3)';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.transform = 'translateY(0)';
              e.currentTarget.style.boxShadow = 'none';
            }}
          >
            📥 Export to CSV
          </button>
        </div>
      )}
    </div>
  );
}

function exportToCSV(measurements: Measurement[], projectName: string) {
  const headers = ['Name', 'Type', 'Value', 'Unit', 'Page'];
  const rows = measurements.map(m => [
    m.name,
    m.type,
    m.value.toFixed(2),
    m.unit,
    m.pageNumber
  ]);

  const csv = [
    headers.join(','),
    ...rows.map(r => r.join(','))
  ].join('\n');

  const blob = new Blob([csv], { type: 'text/csv' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `${projectName}-takeoff.csv`;
  a.click();
  URL.revokeObjectURL(url);
}

