import { useRef, useEffect, useCallback, useState } from 'react';
import { useProjectStore } from '../stores/projectStore';
import { realDistance, polygonAreaFeet, formatMeasurement } from '../utils/geometry';
// Snap engine parked for now - needs better corner detection
// import { snapEngine, type SnapResult } from '../utils/snapEngine';
import type { Point, Measurement } from '../types';
import toast from 'react-hot-toast';

interface MeasurementCanvasProps {
  width: number;
  height: number;
  panOffset: Point;
}

const COLORS = [
  '#ef4444', '#f97316', '#eab308', '#22c55e', '#14b8a6',
  '#3b82f6', '#8b5cf6', '#ec4899'
];

export function MeasurementCanvas({ width, height }: MeasurementCanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [colorIndex, setColorIndex] = useState(0);
  const [tempPoints, setTempPoints] = useState<Point[]>([]);
  const [mousePos, setMousePos] = useState<Point | null>(null);
  // Snap feature parked - not reliable enough yet
  // Will re-enable once corner detection is improved

  const {
    project,
    activeTool,
    isCalibrating,
    calibrationPoints,
    addCalibrationPoint,
    addMeasurement,
    selectedMeasurementId
  } = useProjectStore();

  // Get canvas-relative coordinates
  const getCanvasPoint = useCallback((e: React.MouseEvent): Point => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };

    const rect = canvas.getBoundingClientRect();
    return {
      x: e.clientX - rect.left,
      y: e.clientY - rect.top
    };
  }, []);

  // Track mouse position for rubber-banding
  const handleMouseMove = useCallback((e: React.MouseEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    setMousePos({ x, y });
  }, []);

  const handleMouseLeave = useCallback(() => {
    setMousePos(null);
  }, []);

  // Handle clicks
  const handleClick = useCallback((e: React.MouseEvent) => {
    if (!project) return;

    const point = getCanvasPoint(e);
    console.log('Click at:', point, 'Tool:', activeTool);

    // Calibration mode
    if (isCalibrating) {
      addCalibrationPoint(point);
      return;
    }

    // Need scale for measurements
    if (!project.scale) {
      toast.error('Please calibrate scale first');

