    // Need scale for measurements
    if (!project.scale) {
      toast.error('Please calibrate scale first');
      return;
    }

    // Linear measurement - 2 clicks
    if (activeTool === 'linear') {
      if (tempPoints.length === 0) {
        setTempPoints([point]);
        toast('Click second point', { icon: '📏' });
      } else {
        const points = [tempPoints[0], point];
        const distance = realDistance(points[0], points[1], project.scale);

        const measurement: Omit<Measurement, 'id' | 'createdAt'> = {
          type: 'linear',
          name: `Line ${project.measurements.length + 1}`,
          points,
          value: distance,
          unit: 'LF',
          color: COLORS[colorIndex % COLORS.length],
          pageNumber: project.currentPage
        };

        addMeasurement(measurement);
        setTempPoints([]);
        setColorIndex(c => c + 1);
        toast.success(`${formatMeasurement(distance, 'LF')}`);
      }
    }

    // Area measurement
    if (activeTool === 'area') {
      setTempPoints(prev => [...prev, point]);
    }

    // Count
    if (activeTool === 'count') {
      const measurement: Omit<Measurement, 'id' | 'createdAt'> = {
        type: 'count',
        name: `Count ${project.measurements.length + 1}`,
        points: [point],
        value: 1,
        unit: 'EA',
        color: COLORS[colorIndex % COLORS.length],
        pageNumber: project.currentPage
      };

      addMeasurement(measurement);
      setColorIndex(c => c + 1);
      toast.success('Count added');
    }
  }, [project, activeTool, isCalibrating, tempPoints, colorIndex, getCanvasPoint, addCalibrationPoint, addMeasurement]);

  // Double-click to finish area
  const handleDoubleClick = useCallback(() => {
    if (activeTool === 'area' && tempPoints.length >= 3 && project?.scale) {
      const area = polygonAreaFeet(tempPoints, project.scale);

