        points: tempPoints,
        value: area,
        unit: 'SF',
        color: COLORS[colorIndex % COLORS.length],
        pageNumber: project.currentPage
      };

      addMeasurement(measurement);
      setTempPoints([]);
      setColorIndex(c => c + 1);
      toast.success(`${formatMeasurement(area, 'SF')}`);
    }
  }, [activeTool, tempPoints, project, colorIndex, addMeasurement]);


