          }}
        >
          ▶
        </button>
      </div>

      {/* Right: Zoom */}
      <div className="flex items-center gap-2">
        <button
          onClick={() => setZoom(zoom - 0.25)}
          className="px-3 py-1 rounded transition-colors"
          style={{ color: '#e8f1f5' }}
          onMouseEnter={(e) => e.currentTarget.style.background = '#2d4a5e'}
          onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
        >
          −
        </button>
        <span className="text-sm min-w-16 text-center" style={{ color: '#8b7355' }}>
          {Math.round(zoom * 100)}%
        </span>
        <button
          onClick={() => setZoom(zoom + 0.25)}
          className="px-3 py-1 rounded transition-colors"
          style={{ color: '#e8f1f5' }}
          onMouseEnter={(e) => e.currentTarget.style.background = '#2d4a5e'}
          onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
        >
          +
        </button>
        <button
          onClick={() => setZoom(1)}
          className="px-3 py-1 rounded text-sm transition-colors"
          style={{ color: '#c9a227', border: '1px solid #5a4020' }}
          onMouseEnter={(e) => e.currentTarget.style.background = '#2d4a5e'}
          onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
        >
          Fit
        </button>
      </div>
    </div>
  );
}

import type { Point } from '../types';

/**
 * Calculate distance between two points in pixels
 */
export function pixelDistance(p1: Point, p2: Point): number {
  return Math.sqrt(Math.pow(p2.x - p1.x, 2) + Math.pow(p2.y - p1.y, 2));
}

/**
 * Calculate real-world distance given scale (pixels per foot)
 */
export function realDistance(p1: Point, p2: Point, scale: number): number {
  return pixelDistance(p1, p2) / scale;
}

/**
 * Calculate polygon area in square pixels using Shoelace formula
 */
export function polygonAreaPixels(points: Point[]): number {
  if (points.length < 3) return 0;

  let area = 0;
  const n = points.length;

  for (let i = 0; i < n; i++) {
    const j = (i + 1) % n;
    area += points[i].x * points[j].y;
    area -= points[j].x * points[i].y;
  }

  return Math.abs(area) / 2;
}

/**
 * Calculate polygon area in square feet
 */
export function polygonAreaFeet(points: Point[], scale: number): number {
  const pixelArea = polygonAreaPixels(points);
  return pixelArea / (scale * scale);
}

/**
 * Calculate polygon perimeter in pixels
 */
export function polygonPerimeterPixels(points: Point[]): number {
  if (points.length < 2) return 0;

  let perimeter = 0;
  for (let i = 0; i < points.length; i++) {
    const j = (i + 1) % points.length;
    perimeter += pixelDistance(points[i], points[j]);
  }

  return perimeter;
}

/**
 * Calculate polygon perimeter in feet
 */
export function polygonPerimeterFeet(points: Point[], scale: number): number {
  return polygonPerimeterPixels(points) / scale;
}

/**
 * Get centroid of a polygon
 */
export function polygonCentroid(points: Point[]): Point {
  if (points.length === 0) return { x: 0, y: 0 };

  const sum = points.reduce(
    (acc, p) => ({ x: acc.x + p.x, y: acc.y + p.y }),
    { x: 0, y: 0 }
  );

  return {
    x: sum.x / points.length,
    y: sum.y / points.length
  };
}

/**
 * Convert decimal feet to feet-inches string (e.g., 8'-3 1/4")
 */
export function decimalFeetToFeetInches(decimalFeet: number): string {
  const feet = Math.floor(decimalFeet);
  const remainingInches = (decimalFeet - feet) * 12;
  const wholeInches = Math.floor(remainingInches);
  const fraction = remainingInches - wholeInches;

  // Convert fraction to nearest 1/16th
  const sixteenths = Math.round(fraction * 16);

  let fractionStr = '';
  if (sixteenths > 0 && sixteenths < 16) {
    // Simplify the fraction
    const gcd = (a: number, b: number): number => b === 0 ? a : gcd(b, a % b);
    const divisor = gcd(sixteenths, 16);
    const num = sixteenths / divisor;
    const den = 16 / divisor;
    fractionStr = ` ${num}/${den}`;
  }

  if (feet === 0) {
    return `${wholeInches}${fractionStr}"`;
  } else if (wholeInches === 0 && sixteenths === 0) {
    return `${feet}'-0"`;
  } else {
    return `${feet}'-${wholeInches}${fractionStr}"`;
  }
}

/**
 * Format a measurement value for display
 */
export function formatMeasurement(value: number, unit: string): string {
  if (unit === 'EA') {
    return `${Math.round(value)} EA`;
  }

  // For linear feet, display in feet-inches format
  if (unit === 'LF') {
    return decimalFeetToFeetInches(value);
  }

  // For SF, show appropriate decimal precision
  if (value >= 100) {
    return `${Math.round(value).toLocaleString()} ${unit}`;
  } else if (value >= 10) {
    return `${value.toFixed(1)} ${unit}`;
  } else {
    return `${value.toFixed(2)} ${unit}`;
  }
}

/**
 * Convert between units
 */
export function convertToFeet(value: number, fromUnit: 'ft' | 'in' | 'm'): number {
  switch (fromUnit) {
    case 'ft': return value;
    case 'in': return value / 12;
    case 'm': return value * 3.28084;
  }
}

/**
 * Check if a point is inside a polygon
 */
export function pointInPolygon(point: Point, polygon: Point[]): boolean {
  let inside = false;
  const n = polygon.length;

  for (let i = 0, j = n - 1; i < n; j = i++) {
    const xi = polygon[i].x, yi = polygon[i].y;
    const xj = polygon[j].x, yj = polygon[j].y;

    if (((yi > point.y) !== (yj > point.y)) &&
        (point.x < (xj - xi) * (point.y - yi) / (yj - yi) + xi)) {
      inside = !inside;
    }
  }

  return inside;
}

