import { useEffect, useRef, useState, useCallback } from 'react';
import * as pdfjsLib from 'pdfjs-dist';
import { useProjectStore } from '../stores/projectStore';
import { MeasurementCanvas } from './MeasurementCanvas';
import { snapEngine } from '../utils/snapEngine';

// Set up worker once at module level
pdfjsLib.GlobalWorkerOptions.workerSrc = new URL(
  'pdfjs-dist/build/pdf.worker.min.mjs',
  import.meta.url
).toString();

export function PDFViewer() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [pdfDoc, setPdfDoc] = useState<pdfjsLib.PDFDocumentProxy | null>(null);
  const [pageSize, setPageSize] = useState({ width: 0, height: 0 });
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const loadingTaskRef = useRef<pdfjsLib.PDFDocumentLoadingTask | null>(null);

  const { 
    project, 
    zoom, 
    panOffset, 
    setPanOffset,
    activeTool,
    setProject
  } = useProjectStore();

  // Load PDF
  useEffect(() => {
    if (!project?.pdfUrl) return;

    // Cancel any previous loading task
    if (loadingTaskRef.current) {
      loadingTaskRef.current.destroy();
    }

    setIsLoading(true);
    setError(null);
    setPdfDoc(null);

    const loadingTask = pdfjsLib.getDocument({
      url: project.pdfUrl,
      cMapUrl: 'https://unpkg.com/pdfjs-dist@4.4.168/cmaps/',
      cMapPacked: true,
    });

    loadingTaskRef.current = loadingTask;

    loadingTask.promise
      .then((doc) => {
        console.log('PDF loaded successfully, pages:', doc.numPages);
        setPdfDoc(doc);
        if (project.totalPages !== doc.numPages) {
          setProject({ ...project, totalPages: doc.numPages });
        }
        setIsLoading(false);
      })
      .catch((err) => {
        if (err.name === 'PasswordException') {
          setError('This PDF is password protected');
        } else if (err.message?.includes('destroyed')) {
          // Ignore - component unmounted
          console.log('Loading cancelled');
        } else {
          console.error('Error loading PDF:', err);
          setError(err.message || 'Failed to load PDF');
        }
        setIsLoading(false);
      });

    return () => {
      if (loadingTaskRef.current) {
        loadingTaskRef.current.destroy();
        loadingTaskRef.current = null;
      }
    };
  }, [project?.pdfUrl]);

  // Render current page
  useEffect(() => {
    if (!pdfDoc || !canvasRef.current || !project) return;

    let cancelled = false;
    let renderTask: pdfjsLib.RenderTask | null = null;

    const renderPage = async () => {
      try {
        const page = await pdfDoc.getPage(project.currentPage);
        if (cancelled) return;

        const scale = zoom * 2; // 2x for retina
        const viewport = page.getViewport({ scale });

        // Store the PDF coordinate conversion factor for accurate measurements
        // viewport.scale tells us pixels per PDF unit
        // PDF standard: 72 units = 1 inch
        // So: pixelsPerInch = viewport.scale * 72
        const pixelsPerPdfUnit = viewport.scale;
        console.log('PDF render info:', {
          viewportScale: viewport.scale,
          pixelsPerPdfUnit,
          pixelsPerInch: pixelsPerPdfUnit * 72,
          width: viewport.width,
          height: viewport.height
        });

        const canvas = canvasRef.current!;
        const context = canvas.getContext('2d')!;

        canvas.width = viewport.width;
        canvas.height = viewport.height;
        canvas.style.width = `${viewport.width / 2}px`;
        canvas.style.height = `${viewport.height / 2}px`;

        setPageSize({ 
          width: viewport.width / 2, 
          height: viewport.height / 2 
        });

        renderTask = page.render({
          canvasContext: context,
          viewport: viewport
        });

        await renderTask.promise;
        console.log('Page', project.currentPage, 'rendered');

        // Detect snap points from rendered canvas (scale = 2x for retina)
        setTimeout(() => {
          try {
            snapEngine.detectFromCanvas(canvas, 2); // Pass scale factor
            console.log('Snap points detected:', snapEngine.count);
          } catch (err) {
            console.warn('Could not detect snap points:', err);
          }
        }, 100);
      } catch (err: any) {
        if (!cancelled && !err.message?.includes('cancelled')) {
          console.error('Error rendering page:', err);
        }
      }
    };

    renderPage();

    return () => {
      cancelled = true;
      if (renderTask) {
        renderTask.cancel();
      }
    };
  }, [pdfDoc, project?.currentPage, zoom]);

  // Pan handling
  const [isPanning, setIsPanning] = useState(false);
  const [panStart, setPanStart] = useState({ x: 0, y: 0 });

  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    if (activeTool === 'pan' || e.button === 1) {
      setIsPanning(true);
      setPanStart({ x: e.clientX - panOffset.x, y: e.clientY - panOffset.y });
    }
  }, [activeTool, panOffset]);

  const handleMouseMove = useCallback((e: React.MouseEvent) => {
    if (isPanning) {
      setPanOffset({
        x: e.clientX - panStart.x,
        y: e.clientY - panStart.y
      });
    }
  }, [isPanning, panStart, setPanOffset]);

  const handleMouseUp = useCallback(() => {
    setIsPanning(false);
  }, []);

  const { setZoom } = useProjectStore();
  const handleWheel = useCallback((e: React.WheelEvent) => {
    if (e.ctrlKey || e.metaKey) {
      e.preventDefault();
      const delta = e.deltaY > 0 ? -0.1 : 0.1;
      setZoom(zoom + delta);
    }
  }, [zoom, setZoom]);

  if (isLoading) {
    return (
      <div className="absolute inset-0 flex items-center justify-center"
           style={{ background: '#0a141a' }}>
        <div className="text-center">
          <div className="text-4xl mb-4 animate-pulse">📄</div>
          <div style={{ color: '#8b7355' }}>Loading PDF...</div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="absolute inset-0 flex items-center justify-center"
           style={{ background: '#0a141a' }}>
        <div className="text-center p-8 rounded-lg" style={{ background: '#1a2f3d', border: '1px solid #a65d37' }}>
          <div className="text-4xl mb-4">⚠️</div>
          <div style={{ color: '#a65d37' }} className="mb-2">Failed to load PDF</div>
          <div style={{ color: '#8b7355' }} className="text-sm max-w-md">{error}</div>
        </div>
      </div>
    );
  }

  if (!pdfDoc) {
    return (
      <div className="absolute inset-0 flex items-center justify-center"
           style={{ background: '#0a141a' }}>
        <div style={{ color: '#4a6a7a' }}>No document loaded</div>
      </div>
    );
  }

  return (
    <div 
      ref={containerRef}
      className="absolute inset-0 overflow-hidden"
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
      onWheel={handleWheel}
      style={{ 
        cursor: activeTool === 'pan' ? (isPanning ? 'grabbing' : 'grab') : 'crosshair',
        background: '#0a141a'
      }}
    >
      <div 
        className="absolute"
        style={{
          transform: `translate(${panOffset.x}px, ${panOffset.y}px)`,
          left: '50%',
          top: '50%',
          marginLeft: -pageSize.width / 2,
          marginTop: -pageSize.height / 2
        }}
      >
        {/* PDF Canvas */}
        <canvas 
          ref={canvasRef} 
          style={{ 
            boxShadow: '0 10px 40px rgba(0,0,0,0.5)',
            background: 'white'
          }}
        />

        {/* Measurement Overlay */}
        {pageSize.width > 0 && (
          <MeasurementCanvas 
            width={pageSize.width} 
            height={pageSize.height}
            panOffset={panOffset}
          />
        )}
      </div>
    </div>
  );
}

