  addPolygonToArea: (polygonPoints: Point[], area: number) => {
    const { project, activeMeasurementId } = get();
    if (!project || !activeMeasurementId) return;

    const measurement = project.measurements.find(m => m.id === activeMeasurementId);
    if (!measurement || measurement.type !== 'area') return;

    // Use a separator point to mark polygon boundaries
    const separator: Point = { x: -99999, y: -99999 };

    set({
      project: {
        ...project,
        measurements: project.measurements.map(m =>
          m.id === activeMeasurementId
            ? { 
                ...m, 
                value: m.value + area, 
                points: [...m.points, separator, ...polygonPoints] 
              }
            : m
        ),
        updatedAt: new Date()
      }
    });
  },

  addPolylineToPerimeter: (polylinePoints: Point[], length: number) => {
    const { project, activeMeasurementId } = get();
    if (!project || !activeMeasurementId) return;

    const measurement = project.measurements.find(m => m.id === activeMeasurementId);
    if (!measurement || measurement.type !== 'perimeter') return;

    // Use a separator point to mark polyline boundaries
    const separator: Point = { x: -99999, y: -99999 };

    set({
      project: {
        ...project,
        measurements: project.measurements.map(m =>
          m.id === activeMeasurementId
            ? { 
                ...m, 
                value: m.value + length, 
                points: [...m.points, separator, ...polylinePoints] 
              }
            : m
        ),
        updatedAt: new Date()
      }
    });
  },

  stopContinuousMeasurement: () => set({ activeMeasurementId: null }),

  // Drawing
  startDrawing: () => set({ isDrawing: true, currentPoints: [] }),

  addPoint: (point) => {
    const { currentPoints } = get();
    set({ currentPoints: [...currentPoints, point] });
  },

  finishDrawing: () => {
    const { currentPoints } = get();
    set({ isDrawing: false, currentPoints: [] });
    return currentPoints;
  },

  cancelDrawing: () => set({ isDrawing: false, currentPoints: [] }),

  // Groups
  addGroup: (name) => {
    const { project } = get();
    if (!project) return;

    const colorIndex = project.groups.length % COLORS.length;
    const newGroup: MeasurementGroup = {
      id: generateId(),
      name,
      color: COLORS[colorIndex],
      measurementIds: [],
      collapsed: false
    };

    set({
      project: {
        ...project,
        groups: [...project.groups, newGroup],
        updatedAt: new Date()
      }
    });
  },

  deleteGroup: (id) => {
    const { project } = get();
    if (!project) return;

    set({
      project: {
        ...project,
        groups: project.groups.filter(g => g.id !== id),
        updatedAt: new Date()
      }
    });
  },

  addToGroup: (measurementId, groupId) => {
    const { project } = get();
    if (!project) return;

    set({
      project: {
        ...project,
        groups: project.groups.map(g => {
          if (g.id === groupId) {
            return {
              ...g,
              measurementIds: [...new Set([...g.measurementIds, measurementId])]
            };
          }
          // Remove from other groups
          return {
            ...g,
            measurementIds: g.measurementIds.filter(id => id !== measurementId)
          };
        }),
        updatedAt: new Date()
      }
    });
  }
}));

