import { useCallback, useState } from 'react';

interface DropZoneProps {
  onFileLoad: (file: File) => void;
}

export function DropZone({ onFileLoad }: DropZoneProps) {
  const [isDragging, setIsDragging] = useState(false);

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);

    const file = e.dataTransfer.files[0];
    if (file && file.type === 'application/pdf') {
      onFileLoad(file);
    }
  }, [onFileLoad]);

  const handleFileSelect = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && file.type === 'application/pdf') {
      onFileLoad(file);
    }
  }, [onFileLoad]);

  return (
    <div className="min-h-screen w-full flex flex-col items-center justify-center p-8"
         style={{ background: 'linear-gradient(180deg, #1a2f3d 0%, #0f1c24 100%)' }}>

      {/* Header */}
      <div className="text-center mb-12">
        <div className="text-6xl mb-4">🚤</div>
        <h1 className="text-5xl font-bold mb-2" 
            style={{ fontFamily: 'Playfair Display, serif', color: '#c9a227' }}>
          Pilar Studio
        </h1>
        <p className="text-lg opacity-70" style={{ color: '#e8f1f5' }}>
          Construction Takeoff Tool
        </p>
      </div>

      {/* Drop Zone */}
      <div
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        onClick={() => document.getElementById('file-input')?.click()}
        className={`
          w-full max-w-2xl aspect-[16/10] rounded-lg
          flex flex-col items-center justify-center gap-6 p-12
          transition-all duration-300 cursor-pointer
          ${isDragging 
            ? 'scale-102 shadow-2xl' 
            : 'hover:scale-101'
          }
        `}
        style={{
          background: isDragging 
            ? 'linear-gradient(135deg, #2d4a5e 0%, #1e3a4c 100%)'
            : 'linear-gradient(135deg, #1e3a4c 0%, #152a36 100%)',
          border: `2px dashed ${isDragging ? '#c9a227' : '#4a6a7a'}`,
          boxShadow: isDragging 
            ? '0 20px 60px rgba(0,0,0,0.4), inset 0 0 60px rgba(201, 162, 39, 0.1)'
            : '0 10px 40px rgba(0,0,0,0.3)'
        }}
      >
        <div className="text-5xl opacity-80">📋</div>
        <div className="text-center">
          <p className="text-xl mb-2" style={{ color: '#e8f1f5' }}>
            Drop your drawings here
          </p>
          <p className="text-sm opacity-60">
            PDF files • Click or drag
          </p>
        </div>
      </div>

      {/* Footer */}
      <div className="mt-12 text-center opacity-40">
        <p className="text-xs" style={{ color: '#8b7355' }}>
          Named after Hemingway's 38-foot Wheeler • Built for precision
        </p>
      </div>

      <input
        id="file-input"
        type="file"
        accept=".pdf"
        className="hidden"
        onChange={handleFileSelect}
      />
    </div>
  );
}

import { useCallback, useState } from 'react';
import { Toaster } from 'react-hot-toast';
import { useProjectStore } from './stores/projectStore';
import { Toolbar } from './components/Toolbar';
import { PDFViewer } from './components/PDFViewer';
import { MeasurementPanel } from './components/MeasurementPanel';
import { DropZone } from './components/DropZone';
import { CalibrationDialog } from './components/CalibrationDialog';
import type { Project } from './types';

function App() {
  const { project, setProject, isCalibrating, calibrationPoints, cancelCalibration } = useProjectStore();

  const handleFileLoad = useCallback((file: File) => {
    const url = URL.createObjectURL(file);
    const newProject: Project = {
      id: Math.random().toString(36).substring(2, 15),
      name: file.name.replace('.pdf', ''),
      pdfFile: file,
      pdfUrl: url,
      scale: null,
      scaleUnit: 'ft',
      currentPage: 1,
      totalPages: 1,
      measurements: [],
      groups: [],
      createdAt: new Date(),
      updatedAt: new Date()
    };
    setProject(newProject);
  }, [setProject]);

  // Show calibration dialog when both points are set
  // Track if user wants direct mode (no clicking) vs calibrate mode (click points)
  const [useDirectScale, setUseDirectScale] = useState(true);

  // Show dialog immediately for direct mode, or after 2 points for calibrate mode
  const shouldShowCalibrationDialog = isCalibrating && (useDirectScale || calibrationPoints.length === 2);

  if (!project) {
    return (
      <>
        <DropZone onFileLoad={handleFileLoad} />
        <Toaster 
          position="bottom-right"
          toastOptions={{
            style: {
              background: '#2d4a5e',
              color: '#e8f1f5',
              border: '1px solid #4a6a7a',
              fontFamily: 'Source Sans 3, sans-serif'
            }
          }}
        />
      </>
    );
  }

  return (
    <div className="min-h-screen flex flex-col" style={{ background: '#1a2f3d' }}>
      {/* Header */}
      <header className="px-4 py-3 flex items-center justify-between"
              style={{ 
                background: 'linear-gradient(90deg, #0f1c24 0%, #1a2f3d 50%, #0f1c24 100%)',
                borderBottom: '1px solid #2d4a5e'
              }}>
        <div className="flex items-center gap-4">
          <span className="text-3xl">🚤</span>
          <div>
            <h1 className="text-xl font-semibold" 
                style={{ fontFamily: 'Playfair Display, serif', color: '#c9a227' }}>
              Pilar Studio
            </h1>
            <p className="text-xs opacity-60" style={{ color: '#e8f1f5' }}>
              {project.name}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-4">
          {project.scale ? (
            <span className="text-sm px-3 py-1 rounded"
                  style={{ background: '#1e3a4c', color: '#7cb798', border: '1px solid #2d5a3d' }}>
              ✓ Scale: {project.scale.toFixed(1)} px/ft
            </span>
          ) : (
            <span className="text-sm px-3 py-1 rounded"
                  style={{ background: '#3d2a1a', color: '#c9a227', border: '1px solid #5a4020' }}>
              ⚠ Calibrate to begin
            </span>
          )}
        </div>
      </header>

      {/* Toolbar */}
      <Toolbar />

      {/* Main Content */}
      <div className="flex-1 flex overflow-hidden">
        {/* PDF Viewer */}
        <div className="flex-1 relative" style={{ background: '#0a141a' }}>
          <PDFViewer />
        </div>

        {/* Measurements Panel */}
        <MeasurementPanel />
      </div>

      {/* Calibration Dialog */}
      {shouldShowCalibrationDialog && (
        <CalibrationDialog 
          onClose={cancelCalibration} 
          onModeChange={(mode) => setUseDirectScale(mode === 'direct')}
          initialMode={useDirectScale ? 'direct' : 'dimension'}
        />
      )}

      <Toaster 
        position="bottom-right"
        toastOptions={{
          style: {
            background: '#2d4a5e',
            color: '#e8f1f5',
            border: '1px solid #4a6a7a',
            fontFamily: 'Source Sans 3, sans-serif'
          }
        }}
      />
    </div>
  );
}

export default App;

