  const { project, zoom } = get();
  if (!project) return;

  // Base formula: (zoom * 2 * 72) / feetPerInch
  // Apply correction factor to handle non-standard PDF exports
  const renderScale = zoom * 2;
  const basePixelsPerFoot = (renderScale * 72) / feetPerInch;
