{/* Groups - hierarchical with parent/child */}
{(() => {
  // Get top-level groups (no parent)
  const topLevelGroups = groups.filter(g => !g.parentId);

  // Recursive renderer for groups
  const renderGroup = (group: MeasurementGroup, depth: number = 0) => {
    const groupMeasurements = measurements.filter(m => group.measurementIds.includes(m.id));
    const childGroups = groups.filter(g => g.parentId === group.id);
    const totals = getGroupTotal(group);
    const isCollapsed = collapsedGroups.has(group.id);
    const isParent = childGroups.length > 0;

    return (
      <div key={group.id} className="mb-1" style={{ marginLeft: depth * 12 }}>
        {/* Group Header */}
        <div 
          className="flex items-center gap-2 px-2 py-2 rounded cursor-pointer transition-colors"
          style={{ 
            background: isParent ? '#1e3a4c' : '#1a2f3d',
            borderLeft: depth > 0 ? `2px solid ${group.color}40` : 'none'
          }}
          onClick={() => toggleGroup(group.id)}
        >
          <span style={{ color: '#6b7280', fontSize: '10px' }}>
            {isCollapsed ? '▶' : '▼'}
          </span>
          <div 
            className="w-3 h-3 rounded"
            style={{ backgroundColor: group.color }}
          />
          <span 
            className="flex-1 text-sm truncate" 
            style={{ 
              color: '#e8f1f5',
              fontWeight: isParent ? 600 : 400
            }}
          >
            {group.name}
          </span>
          {(childGroups.length > 0 || totals.total > 0) && (
            <span className="text-xs" style={{ color: '#6b7280' }}>
              {childGroups.length > 0 ? `${childGroups.length} sub` : totals.total}
            </span>
          )}
          {totals.lf > 0 && (
            <span className="text-xs font-medium" style={{ color: '#3b82f6' }}>
              {decimalFeetToFeetInches(totals.lf)}
            </span>
          )}
          {/* Add subgroup button */}
          <button
            onClick={(e) => {
              e.stopPropagation();
              const name = prompt('Subgroup name:');
              if (name) addGroup(name, group.id);
            }}
            className="opacity-0 hover:opacity-100 text-xs px-1"
            style={{ color: '#7cb798' }}
            title="Add subgroup"
          >
            +
          </button>
          <button
            onClick={(e) => {
              e.stopPropagation();
              deleteGroup(group.id);
            }}
            className="opacity-0 hover:opacity-100 text-xs px-1"
            style={{ color: '#6b7280' }}
          >
            ✕
          </button>
        </div>

        {/* Group Contents - child groups + measurements */}
        {!isCollapsed && (
          <div className="mt-1">
            {/* Child groups first */}
            {childGroups.map(child => renderGroup(child, depth + 1))}

            {/* Then measurements */}
            {groupMeasurements.length > 0 && (
              <div style={{ marginLeft: 12 }}>
                {groupMeasurements.map(m => (
                  <MeasurementRow key={m.id} m={m} showGroupMenu={false} />
                ))}
              </div>
            )}
          </div>
        )}
      </div>
    );
  };

  return topLevelGroups.map(g => renderGroup(g, 0));
})()}

