import { useState, useEffect } from 'react';
import type { Sheet, SheetType } from '../types';

interface SheetSetupDialogProps {
  totalPages: number;
  detectedNames: string[];  // Auto-detected names from PDF
  onConfirm: (sheets: Sheet[]) => void;
  onCancel: () => void;
}

const SHEET_TYPES: { value: SheetType; label: string }[] = [
  { value: 'floor-plan', label: '📐 Floor Plan' },
  { value: 'elevation', label: '🏢 Elevation' },
  { value: 'section', label: '✂️ Section' },
  { value: 'detail', label: '🔍 Detail' },
  { value: 'schedule', label: '📋 Schedule' },
  { value: 'other', label: '📄 Other' },
];

export function SheetSetupDialog({ 
  totalPages, 
  detectedNames, 
  onConfirm, 
  onCancel 
}: SheetSetupDialogProps) {
  const [sheets, setSheets] = useState<Sheet[]>([]);

  // Initialize sheets from detected names
  useEffect(() => {
    const initialSheets: Sheet[] = [];
    for (let i = 1; i <= totalPages; i++) {
      initialSheets.push({
        pageNumber: i,
        name: detectedNames[i - 1] || `Sheet ${i}`,
        type: 'floor-plan',  // Default assumption
        level: undefined,
      });
    }
    setSheets(initialSheets);
  }, [totalPages, detectedNames]);

  const updateSheet = (pageNum: number, updates: Partial<Sheet>) => {
    setSheets(prev => prev.map(s => 
      s.pageNumber === pageNum ? { ...s, ...updates } : s
    ));
  };

  // Try to auto-detect type from name
  const guessTypeFromName = (name: string): SheetType => {
    const lower = name.toLowerCase();
    if (lower.includes('plan') || lower.includes('floor') || /^a-?\d/.test(lower)) return 'floor-plan';
    if (lower.includes('elev')) return 'elevation';
    if (lower.includes('sect')) return 'section';
    if (lower.includes('detail') || /^d-?\d/.test(lower.toLowerCase())) return 'detail';
    if (lower.includes('sched')) return 'schedule';
    return 'other';
  };

  // Try to auto-detect level from name
  const guessLevelFromName = (name: string): number | undefined => {
    const lower = name.toLowerCase();
    // Look for patterns like "1st floor", "level 2", "floor 3", "L1", "2nd"
    const match = lower.match(/(?:level|floor|l)[\s-]*(\d+)|(\d+)(?:st|nd|rd|th)[\s-]*(?:floor|level)/);
    if (match) {
      return parseInt(match[1] || match[2]);
    }
    // Basement patterns
    if (lower.includes('basement') || lower.includes('cellar')) return -1;
    if (lower.match(/b-?\d/)) return -1;
    return undefined;
  };

  return (
    <div 
      className="fixed inset-0 z-50 flex items-center justify-center p-4"
      style={{ background: 'rgba(0,0,0,0.8)' }}
    >
      <div 
        className="w-full max-w-4xl max-h-[80vh] rounded-xl overflow-hidden flex flex-col"
        style={{ 
          background: 'linear-gradient(180deg, #1a2f3d 0%, #0f1c24 100%)',
          border: '1px solid #2d4a5e'
        }}
      >
        {/* Header */}
        <div className="p-4" style={{ borderBottom: '1px solid #2d4a5e' }}>
          <h2 className="text-xl font-semibold" style={{ color: '#c9a227' }}>
            📋 Sheet Setup
          </h2>
          <p className="text-sm mt-1" style={{ color: '#8b7355' }}>
            Review and name your drawing sheets. This helps organize takeoff by location.
          </p>
        </div>

        {/* Sheet List */}
        <div className="flex-1 overflow-y-auto p-4">
          <table className="w-full">
            <thead>
              <tr style={{ color: '#6b7280' }} className="text-xs uppercase">
                <th className="text-left py-2 px-2">Page</th>
                <th className="text-left py-2 px-2">Sheet Name</th>
                <th className="text-left py-2 px-2">Type</th>
                <th className="text-left py-2 px-2">Level</th>
              </tr>
            </thead>
            <tbody>
              {sheets.map((sheet) => (
                <tr 
                  key={sheet.pageNumber}
                  className="border-t"
                  style={{ borderColor: '#1e3a4c' }}
                >
                  <td className="py-2 px-2">
                    <span 
                      className="inline-flex items-center justify-center w-8 h-8 rounded"
                      style={{ background: '#1e3a4c', color: '#8b7355' }}
                    >
                      {sheet.pageNumber}
                    </span>
                  </td>
                  <td className="py-2 px-2">
                    <input
                      type="text"
                      value={sheet.name}
                      onChange={(e) => {
                        const name = e.target.value;
                        updateSheet(sheet.pageNumber, { 
                          name,
                          type: guessTypeFromName(name),
                          level: guessLevelFromName(name)
                        });
                      }}
                      className="w-full px-3 py-2 rounded text-sm"
                      style={{ 
                        background: '#0f1c24', 
                        color: '#e8f1f5',
                        border: '1px solid #2d4a5e'
                      }}
                      placeholder="e.g., A-101 First Floor Plan"
                    />
                  </td>
                  <td className="py-2 px-2">
                    <select
                      value={sheet.type}
                      onChange={(e) => updateSheet(sheet.pageNumber, { type: e.target.value as SheetType })}
                      className="w-full px-3 py-2 rounded text-sm"
                      style={{ 
                        background: '#0f1c24', 
                        color: '#e8f1f5',
                        border: '1px solid #2d4a5e'
                      }}
                    >
                      {SHEET_TYPES.map(t => (
                        <option key={t.value} value={t.value}>{t.label}</option>
                      ))}
                    </select>
                  </td>
                  <td className="py-2 px-2">
                    <input
                      type="number"
                      value={sheet.level ?? ''}
                      onChange={(e) => updateSheet(sheet.pageNumber, { 
                        level: e.target.value ? parseInt(e.target.value) : undefined 
                      })}
                      className="w-20 px-3 py-2 rounded text-sm text-center"
                      style={{ 
                        background: '#0f1c24', 
                        color: '#e8f1f5',
                        border: '1px solid #2d4a5e'
                      }}
                      placeholder="—"
                    />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Footer */}
        <div 
          className="p-4 flex justify-between items-center"
          style={{ borderTop: '1px solid #2d4a5e' }}
        >
          <span className="text-sm" style={{ color: '#6b7280' }}>
            {totalPages} sheets detected
          </span>
          <div className="flex gap-3">
            <button
              onClick={onCancel}
              className="px-4 py-2 rounded text-sm"
              style={{ 
                background: '#1e3a4c', 
                color: '#8b7355',
                border: '1px solid #2d4a5e'
              }}
            >
              Cancel
            </button>
            <button
              onClick={() => onConfirm(sheets)}
              className="px-6 py-2 rounded text-sm font-medium"
              style={{ 
                background: '#c9a227', 
                color: '#0f1c24'
              }}
            >
              Confirm & Start Takeoff
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

