reorderMeasurement: (measurementId, targetIndex) => {
  const { project } = get();
  if (!project) return;

  const measurements = [...project.measurements];
  const currentIndex = measurements.findIndex(m => m.id === measurementId);
  if (currentIndex === -1 || currentIndex === targetIndex) return;

  const [moved] = measurements.splice(currentIndex, 1);
  measurements.splice(targetIndex, 0, moved);

  set({
    project: {
      ...project,
      measurements,
      updatedAt: new Date()
    }
  });
},

