import { create } from 'zustand';
import type { Project, Measurement, MeasurementGroup, Tool, Point, Space } from '../types';

interface ProjectState {
  // Current project
  project: Project | null;

  // UI State
  activeTool: Tool;
  zoom: number;
  panOffset: Point;
  selectedMeasurementId: string | null;

  // Continuous measurement mode - keeps adding to same measurement
  activeMeasurementId: string | null;

  // Calibration state
  isCalibrating: boolean;
  calibrationPoints: Point[];

  // Drawing state
  isDrawing: boolean;
  currentPoints: Point[];

  // Undo/Redo history
  history: Project[];
  historyIndex: number;

  // Layer visibility
  hiddenLayers: Set<string>;

  // Actions
  setProject: (project: Project) => void;
  setActiveTool: (tool: Tool) => void;
  setZoom: (zoom: number) => void;
  setPanOffset: (offset: Point) => void;
  setCurrentPage: (page: number) => void;

  // Calibration
  startCalibration: () => void;
  addCalibrationPoint: (point: Point) => void;
  completeCalibration: (knownDistance: number, unit: 'ft' | 'in' | 'm') => void;
  cancelCalibration: () => void;
  setScaleFromArchScale: (feetPerInch: number, correctionFactor?: number) => void;

  // Measurements
  addMeasurement: (measurement: Omit<Measurement, 'id' | 'createdAt'>) => void;
  updateMeasurement: (id: string, updates: Partial<Measurement>) => void;
  deleteMeasurement: (id: string) => void;
  selectMeasurement: (id: string | null) => void;
  toggleMeasurementVisibility: (id: string) => void;

  // Continuous measurement mode
  setActiveMeasurement: (id: string | null) => void;
  continueFromMeasurement: (id: string) => void;
  addToActiveMeasurement: (point: Point, value?: number, startPoint?: Point) => void;
  addPolygonToArea: (polygonPoints: Point[], area: number) => void;
  addPolylineToPerimeter: (polylinePoints: Point[], length: number) => void;
  stopContinuousMeasurement: () => void;

  // Drawing
  startDrawing: () => void;
  addPoint: (point: Point) => void;
  finishDrawing: () => Point[];
  cancelDrawing: () => void;

  // Groups
  addGroup: (name: string, parentId?: string | null) => void;
  deleteGroup: (id: string) => void;
  addToGroup: (measurementId: string, groupId: string) => void;
  removeFromGroup: (measurementId: string) => void;
  reorderMeasurement: (measurementId: string, targetIndex: number) => void;
  toggleGroupVisibility: (id: string) => void;

  // Undo/Redo
  undo: () => void;
  redo: () => void;
  pushHistory: () => void;

  // Layer visibility
  toggleLayer: (layer: string) => void;

  // Spaces
  addSpace: (space: Omit<Space, 'id'>) => void;
  updateSpace: (id: string, updates: Partial<Space>) => void;
  deleteSpace: (id: string) => void;
  toggleSpaceVisibility: (id: string) => void;
}

const generateId = () => Math.random().toString(36).substring(2, 15);

const COLORS = [
  '#ef4444', '#f97316', '#eab308', '#22c55e', '#14b8a6',
  '#3b82f6', '#8b5cf6', '#ec4899', '#06b6d4', '#84cc16'
];

const MAX_HISTORY = 50;

export const useProjectStore = create<ProjectState>((set, get) => ({
  project: null,
  activeTool: 'pan',
  zoom: 1,
  panOffset: { x: 0, y: 0 },
  selectedMeasurementId: null,
  activeMeasurementId: null,
  isCalibrating: false,
  calibrationPoints: [],
  history: [],
  historyIndex: -1,
  hiddenLayers: new Set<string>(),
  isDrawing: false,
  currentPoints: [],

  setProject: (project) => set({ project }),

  setActiveTool: (tool) => {
    const state = get();
    // Cancel any in-progress drawing when switching tools
    if (state.isDrawing) {
      set({ isDrawing: false, currentPoints: [] });
    }
    if (state.isCalibrating && tool !== 'calibrate') {
      set({ isCalibrating: false, calibrationPoints: [] });
    }
    set({ activeTool: tool });
  },

  setZoom: (zoom) => set({ zoom: Math.max(0.1, Math.min(5, zoom)) }),

  setPanOffset: (offset) => set({ panOffset: offset }),

  setCurrentPage: (page) => {
    const { project } = get();
    if (project && page >= 1 && page <= project.totalPages) {
      // Load the scale for this page (if it was previously calibrated)
      const pageScale = project.scales?.[page] ?? null;
      set({ 
        project: { 
          ...project, 
          currentPage: page,
          scale: pageScale  // Load per-page scale
        } 
      });
    }
  },

  // Calibration
  startCalibration: () => set({ 
    isCalibrating: true, 
    calibrationPoints: [],
    activeTool: 'calibrate'
  }),

  addCalibrationPoint: (point) => {
    const { calibrationPoints } = get();
    if (calibrationPoints.length < 2) {
      set({ calibrationPoints: [...calibrationPoints, point] });
    }
  },

  completeCalibration: (knownDistance, unit) => {
    const { project, calibrationPoints } = get();
    if (!project || calibrationPoints.length !== 2) return;

    const [p1, p2] = calibrationPoints;
    const pixelDistance = Math.sqrt(
      Math.pow(p2.x - p1.x, 2) + Math.pow(p2.y - p1.y, 2)
    );

    // Convert to feet
    let distanceInFeet = knownDistance;
    if (unit === 'in') distanceInFeet = knownDistance / 12;
    if (unit === 'm') distanceInFeet = knownDistance * 3.28084;

    const scale = pixelDistance / distanceInFeet;

    // Save scale for current page
    const newScales = { ...project.scales, [project.currentPage]: scale };

    set({
      project: { ...project, scale, scales: newScales, scaleUnit: unit },
      isCalibrating: false,
      calibrationPoints: [],
      activeTool: 'select'
    });
  },

  cancelCalibration: () => set({
    isCalibrating: false,
    calibrationPoints: [],
    activeTool: 'select'
  }),

  // Set scale directly from architectural scale
  // correctionFactor: 1.0 = no correction, 0.86 = 14% smaller, 1.14 = 14% larger
  setScaleFromArchScale: (feetPerInch: number, correctionFactor: number = 1.0) => {
    const { project, zoom } = get();
    if (!project) return;

    // Base formula: (zoom * 2 * 72) / feetPerInch
    // Apply correction factor to handle non-standard PDF exports
    const renderScale = zoom * 2;
    const basePixelsPerFoot = (renderScale * 72) / feetPerInch;
    const pixelsPerFoot = basePixelsPerFoot * correctionFactor;

    console.log('Setting arch scale:', { feetPerInch, zoom, correctionFactor, pixelsPerFoot });

    // Save scale for current page
    const newScales = { ...project.scales, [project.currentPage]: pixelsPerFoot };

    set({
      project: { ...project, scale: pixelsPerFoot, scales: newScales, scaleUnit: 'ft' },
      isCalibrating: false,
      calibrationPoints: [],
      activeTool: 'select'
    });
  },

  // Measurements
  addMeasurement: (measurement) => {
    const { project, pushHistory } = get();
    if (!project) return;

    // Push to history before making changes
    pushHistory();

    const newId = generateId();
    const newMeasurement: Measurement = {
      ...measurement,
      id: newId,
      visible: true,  // Visible by default
      createdAt: new Date()
    };

    // For counts, linear, perimeter, and area, automatically set as active for continuous mode
    const supportsContinuous = measurement.type === 'count' || measurement.type === 'linear' || measurement.type === 'area' || measurement.type === 'perimeter';

    set({
      project: {
        ...project,
        measurements: [...project.measurements, newMeasurement],
        updatedAt: new Date()
      },
      activeMeasurementId: supportsContinuous ? newId : null,
      selectedMeasurementId: newId
    });
  },

  updateMeasurement: (id, updates) => {
    const { project } = get();
    if (!project) return;

    set({
      project: {
        ...project,
        measurements: project.measurements.map(m =>
          m.id === id ? { ...m, ...updates } : m
        ),
        updatedAt: new Date()
      }
    });
  },

  deleteMeasurement: (id) => {
    const { project, selectedMeasurementId, pushHistory } = get();
    if (!project) return;

    // Push to history before making changes
    pushHistory();

    set({
      project: {
        ...project,
        measurements: project.measurements.filter(m => m.id !== id),
        groups: project.groups.map(g => ({
          ...g,
          measurementIds: g.measurementIds.filter(mId => mId !== id)
        })),
        updatedAt: new Date()
      },
      selectedMeasurementId: selectedMeasurementId === id ? null : selectedMeasurementId
    });
  },

  selectMeasurement: (id) => set({ selectedMeasurementId: id }),

  toggleMeasurementVisibility: (id) => {
    const { project } = get();
    if (!project) return;

    set({
      project: {
        ...project,
        measurements: project.measurements.map(m =>
          m.id === id ? { ...m, visible: !m.visible } : m
        ),
        updatedAt: new Date()
      }
    });
  },

  // Continuous measurement mode
  setActiveMeasurement: (id) => set({ activeMeasurementId: id, selectedMeasurementId: id }),

  continueFromMeasurement: (id) => {
    const { project } = get();
    if (!project) return;
    const measurement = project.measurements.find(m => m.id === id);
    if (measurement) {
      // Set the appropriate tool based on measurement type
      const toolMap: Record<string, Tool> = { linear: 'linear', area: 'area', count: 'count', perimeter: 'perimeter' };
      set({ 
        activeMeasurementId: id, 
        selectedMeasurementId: id,
        activeTool: toolMap[measurement.type] || 'count'
      });
    }
  },

  addToActiveMeasurement: (point, value = 1, startPoint?: Point) => {
    const { project, activeMeasurementId } = get();
    if (!project || !activeMeasurementId) return;

    const measurement = project.measurements.find(m => m.id === activeMeasurementId);
    if (!measurement) return;

    // For counts, increment the value and add the point
    if (measurement.type === 'count') {
      set({
        project: {
          ...project,
          measurements: project.measurements.map(m =>
            m.id === activeMeasurementId
              ? { ...m, value: m.value + value, points: [...m.points, point] }
              : m
          ),
          updatedAt: new Date()
        }
      });
    }
    // For linear, add both segment points and the length
    else if (measurement.type === 'linear' && startPoint) {
      set({
        project: {
          ...project,
          measurements: project.measurements.map(m =>
            m.id === activeMeasurementId
              ? { ...m, value: m.value + value, points: [...m.points, startPoint, point] }
              : m
          ),
          updatedAt: new Date()
        }
      });
    }
  },

  addPolygonToArea: (polygonPoints: Point[], area: number) => {
    const { project, activeMeasurementId } = get();
    if (!project || !activeMeasurementId) return;

    const measurement = project.measurements.find(m => m.id === activeMeasurementId);
    if (!measurement || measurement.type !== 'area') return;

    // Use a separator point to mark polygon boundaries
    const separator: Point = { x: -99999, y: -99999 };

    set({
      project: {
        ...project,
        measurements: project.measurements.map(m =>
          m.id === activeMeasurementId
            ? { 
                ...m, 
                value: m.value + area, 
                points: [...m.points, separator, ...polygonPoints] 
              }
            : m
        ),
        updatedAt: new Date()
      }
    });
  },

  addPolylineToPerimeter: (polylinePoints: Point[], length: number) => {
    const { project, activeMeasurementId } = get();
    if (!project || !activeMeasurementId) return;

    const measurement = project.measurements.find(m => m.id === activeMeasurementId);
    if (!measurement || measurement.type !== 'perimeter') return;

    // Use a separator point to mark polyline boundaries
    const separator: Point = { x: -99999, y: -99999 };

    set({
      project: {
        ...project,
        measurements: project.measurements.map(m =>
          m.id === activeMeasurementId
            ? { 
                ...m, 
                value: m.value + length, 
                points: [...m.points, separator, ...polylinePoints] 
              }
            : m
        ),
        updatedAt: new Date()
      }
    });
  },

  stopContinuousMeasurement: () => set({ activeMeasurementId: null }),

  // Drawing
  startDrawing: () => set({ isDrawing: true, currentPoints: [] }),

  addPoint: (point) => {
    const { currentPoints } = get();
    set({ currentPoints: [...currentPoints, point] });
  },

  finishDrawing: () => {
    const { currentPoints } = get();
    set({ isDrawing: false, currentPoints: [] });
    return currentPoints;
  },

  cancelDrawing: () => set({ isDrawing: false, currentPoints: [] }),

  // Groups
  addGroup: (name, parentId = null) => {
    const { project } = get();
    if (!project) return;

    // If parent exists, inherit its color with slight variation
    const parentGroup = parentId ? project.groups.find(g => g.id === parentId) : null;
    const colorIndex = project.groups.length % COLORS.length;
    const color = parentGroup ? parentGroup.color : COLORS[colorIndex];

    const newGroup: MeasurementGroup = {
      id: generateId(),
      name,
      color,
      measurementIds: [],
      collapsed: false,
      parentId: parentId ?? null
    };

    set({
      project: {
        ...project,
        groups: [...project.groups, newGroup],
        updatedAt: new Date()
      }
    });
  },

  deleteGroup: (id) => {
    const { project } = get();
    if (!project) return;

    set({
      project: {
        ...project,
        groups: project.groups.filter(g => g.id !== id),
        updatedAt: new Date()
      }
    });
  },

  addToGroup: (measurementId, groupId) => {
    const { project } = get();
    if (!project) return;

    set({
      project: {
        ...project,
        groups: project.groups.map(g => {
          if (g.id === groupId) {
            return {
              ...g,
              measurementIds: [...new Set([...g.measurementIds, measurementId])]
            };
          }
          // Remove from other groups
          return {
            ...g,
            measurementIds: g.measurementIds.filter(id => id !== measurementId)
          };
        }),
        updatedAt: new Date()
      }
    });
  },

  removeFromGroup: (measurementId) => {
    const { project } = get();
    if (!project) return;

    set({
      project: {
        ...project,
        groups: project.groups.map(g => ({
          ...g,
          measurementIds: g.measurementIds.filter(id => id !== measurementId)
        })),
        updatedAt: new Date()
      }
    });
  },

  reorderMeasurement: (measurementId, targetIndex) => {
    const { project } = get();
    if (!project) return;

    const measurements = [...project.measurements];
    const currentIndex = measurements.findIndex(m => m.id === measurementId);
    if (currentIndex === -1 || currentIndex === targetIndex) return;

    const [moved] = measurements.splice(currentIndex, 1);
    measurements.splice(targetIndex, 0, moved);

    set({
      project: {
        ...project,
        measurements,
        updatedAt: new Date()
      }
    });
  },

  toggleGroupVisibility: (id) => {
    const { project } = get();
    if (!project) return;

    set({
      project: {
        ...project,
        groups: project.groups.map(g =>
          g.id === id ? { ...g, visible: g.visible === false ? true : false } : g
        ),
        updatedAt: new Date()
      }
    });
  },

  // Undo/Redo
  pushHistory: () => {
    const { project, history, historyIndex } = get();
    if (!project) return;

    // Clone the project for history
    const snapshot = JSON.parse(JSON.stringify(project));

    // Truncate any future history if we're not at the end
    const newHistory = history.slice(0, historyIndex + 1);
    newHistory.push(snapshot);

    // Limit history size
    if (newHistory.length > MAX_HISTORY) {
      newHistory.shift();
    }

    set({
      history: newHistory,
      historyIndex: newHistory.length - 1
    });
  },

  undo: () => {
    const { history, historyIndex, project } = get();
    if (historyIndex < 0 || !project) return;

    // Save current state if this is the first undo
    if (historyIndex === history.length - 1) {
      const snapshot = JSON.parse(JSON.stringify(project));
      const newHistory = [...history, snapshot];
      set({
        history: newHistory,
        historyIndex: historyIndex,
        project: history[historyIndex]
      });
    } else if (historyIndex > 0) {
      set({
        historyIndex: historyIndex - 1,
        project: history[historyIndex - 1]
      });
    }
  },

  redo: () => {
    const { history, historyIndex } = get();
    if (historyIndex >= history.length - 1) return;

    set({
      historyIndex: historyIndex + 1,
      project: history[historyIndex + 1]
    });
  },

  toggleLayer: (layer: string) => {
    const { hiddenLayers } = get();
    const next = new Set(hiddenLayers);
    if (next.has(layer)) {
      next.delete(layer);
    } else {
      next.add(layer);
    }
    set({ hiddenLayers: next });
  },

  // Spaces
  addSpace: (space) => {
    const { project } = get();
    if (!project) return;

    const newSpace: Space = {
      ...space,
      id: generateId(),
      visible: true
    };

    set({
      project: {
        ...project,
        spaces: [...(project.spaces || []), newSpace],
        updatedAt: new Date()
      }
    });
  },

  updateSpace: (id, updates) => {
    const { project } = get();
    if (!project) return;

    set({
      project: {
        ...project,
        spaces: (project.spaces || []).map(s =>
          s.id === id ? { ...s, ...updates } : s
        ),
        updatedAt: new Date()
      }
    });
  },

  deleteSpace: (id) => {
    const { project } = get();
    if (!project) return;

    set({
      project: {
        ...project,
        spaces: (project.spaces || []).filter(s => s.id !== id),
        updatedAt: new Date()
      }
    });
  },

  toggleSpaceVisibility: (id) => {
    const { project } = get();
    if (!project) return;

    set({
      project: {
        ...project,
        spaces: (project.spaces || []).map(s =>
          s.id === id ? { ...s, visible: s.visible === false ? true : false } : s
        ),
        updatedAt: new Date()
      }
    });
  }
}));

