    }

    // Linear measurement - 2 clicks per segment, continuous mode adds to same measurement
    if (activeTool === 'linear') {
      if (tempPoints.length === 0) {
        setTempPoints([point]);
        toast('Click second point', { icon: '📏' });
      } else {
        const segmentStart = tempPoints[0];
        const segmentEnd = point;
        const segmentDistance = realDistance(segmentStart, segmentEnd, project.scale);

        // If there's an active linear measurement, add this segment to it
        if (activeMeasurementId) {
          const activeMeasurement = project.measurements.find(m => m.id === activeMeasurementId);
          if (activeMeasurement && activeMeasurement.type === 'linear') {
            addToActiveMeasurement(segmentEnd, segmentDistance, segmentStart);
            setTempPoints([]);
            toast.success(`${activeMeasurement.name}: ${formatMeasurement(activeMeasurement.value + segmentDistance, 'LF')}`);
            return;
          }
        }

        // Otherwise create a new linear measurement (auto-becomes active)
        const measurement: Omit<Measurement, 'id' | 'createdAt'> = {
          type: 'linear',
          name: `Line ${project.measurements.length + 1}`,
          points: [segmentStart, segmentEnd],
          value: segmentDistance,
          unit: 'LF',
          color: COLORS[colorIndex % COLORS.length],
          pageNumber: project.currentPage
        };

        addMeasurement(measurement);
        setTempPoints([]);
        setColorIndex(c => c + 1);
        toast(`${formatMeasurement(segmentDistance, 'LF')} - keep measuring to add more`, { icon: '📏' });
      }
    }

    // Area measurement - click to add points, double-click closes polygon
    if (activeTool === 'area') {
      setTempPoints(prev => [...prev, point]);
      if (tempPoints.length === 0) {
        toast('Click points to draw area, double-click to close', { icon: '⬛' });
      }
    }

    // Perimeter measurement - click to add points, double-click to finish (doesn't close)
    if (activeTool === 'perimeter') {
      setTempPoints(prev => [...prev, point]);
      if (tempPoints.length === 0) {
        toast('Click points along perimeter, double-click to finish', { icon: '🔄' });
      }
    }

    // Space - click to add points, double-click closes polygon
    if (activeTool === 'space') {
      setTempPoints(prev => [...prev, point]);
      if (tempPoints.length === 0) {
        toast('Click to define space boundary, double-click to close', { icon: '🏠' });
      }
    }

    // Count - supports continuous mode
    if (activeTool === 'count') {
      // If there's an active count measurement, add to it
      if (activeMeasurementId) {
        const activeMeasurement = project.measurements.find(m => m.id === activeMeasurementId);
        if (activeMeasurement && activeMeasurement.type === 'count') {
          addToActiveMeasurement(point, 1);
          toast.success(`${activeMeasurement.name}: ${activeMeasurement.value + 1} EA`);
          return;
        }
      }

      // Otherwise create a new count and make it active (store auto-sets active)
      const measurement: Omit<Measurement, 'id' | 'createdAt'> = {
        type: 'count',
        name: `Count ${project.measurements.length + 1}`,
        points: [point],
        value: 1,
        unit: 'EA',
        color: COLORS[colorIndex % COLORS.length],
        pageNumber: project.currentPage
      };

      addMeasurement(measurement);
      setColorIndex(c => c + 1);
      toast('Count started - keep clicking to add more', { icon: '🔢' });
    }
  }, [project, activeTool, isCalibrating, tempPoints, colorIndex, activeMeasurementId, getCanvasPoint, addCalibrationPoint, addMeasurement, addToActiveMeasurement]);

  // Double-click to finish area polygon or perimeter polyline
  const handleDoubleClick = useCallback(() => {
    // Area measurement - close polygon
    if (activeTool === 'area' && tempPoints.length >= 3 && project?.scale) {
      const polygonArea = polygonAreaFeet(tempPoints, project.scale);

      // If there's an active area measurement, add this polygon to it
      if (activeMeasurementId) {
        const activeMeasurement = project.measurements.find(m => m.id === activeMeasurementId);
        if (activeMeasurement && activeMeasurement.type === 'area') {
          // Add polygon points with a separator (null marker would be ideal, but we'll use a special encoding)
          // Store polygons as: [...poly1Points, {x:-1,y:-1}, ...poly2Points, ...]
          const separator: Point = { x: -99999, y: -99999 }; // Special separator marker
          addToActiveMeasurement(separator, polygonArea, tempPoints[0]);
          // Actually, let's update the store to handle area polygons properly
          useProjectStore.getState().addPolygonToArea(tempPoints, polygonArea);
          setTempPoints([]);
          toast.success(`${activeMeasurement.name}: ${formatMeasurement(activeMeasurement.value + polygonArea, 'SF')}`);
          return;
        }
      }

      // Create new area measurement
      const measurement: Omit<Measurement, 'id' | 'createdAt'> = {
        type: 'area',
        name: `Area ${project.measurements.length + 1}`,
        points: tempPoints,
        value: polygonArea,
        unit: 'SF',
        color: COLORS[colorIndex % COLORS.length],
        pageNumber: project.currentPage
      };

      addMeasurement(measurement);
      setTempPoints([]);
      setColorIndex(c => c + 1);
      toast(`${formatMeasurement(polygonArea, 'SF')} - draw more polygons to add to total`, { icon: '⬛' });
    }

    // Perimeter measurement - open polyline (doesn't close)
    if (activeTool === 'perimeter' && tempPoints.length >= 2 && project?.scale) {
      const totalLength = polylineLengthFeet(tempPoints, project.scale);

      // If there's an active perimeter measurement, add this polyline to it
      if (activeMeasurementId) {
        const activeMeasurement = project.measurements.find(m => m.id === activeMeasurementId);
        if (activeMeasurement && activeMeasurement.type === 'perimeter') {
          useProjectStore.getState().addPolylineToPerimeter(tempPoints, totalLength);
          setTempPoints([]);
          toast.success(`${activeMeasurement.name}: ${formatMeasurement(activeMeasurement.value + totalLength, 'LF')}`);
          return;
        }
      }

      // Create new perimeter measurement
      const measurement: Omit<Measurement, 'id' | 'createdAt'> = {
        type: 'perimeter',
        name: `Perimeter ${project.measurements.length + 1}`,
        points: tempPoints,
        value: totalLength,
        unit: 'LF',
        color: COLORS[colorIndex % COLORS.length],
        pageNumber: project.currentPage
      };

      addMeasurement(measurement);
      setTempPoints([]);
      setColorIndex(c => c + 1);
      toast(`${formatMeasurement(totalLength, 'LF')} - draw more segments to add to total`, { icon: '🔄' });
    }
  }, [activeTool, tempPoints, project, colorIndex, activeMeasurementId, addMeasurement]);

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Don't capture if typing in an input
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) {
        return;
      }

      // Tool shortcuts (only when not drawing)
      if (tempPoints.length === 0 && !isCalibrating) {
        switch (e.key.toLowerCase()) {
          case 'v': setActiveTool('select'); return;
          case 'h': setActiveTool('pan'); return;
          case 'c': startCalibration(); return;
          case 'l': if (project?.scale) setActiveTool('linear'); return;
          case 'p': if (project?.scale) setActiveTool('perimeter'); return;
          case 'a': if (project?.scale) setActiveTool('area'); return;
          case 'n': if (project?.scale) setActiveTool('count'); return;
          case 's': if (project?.scale) setActiveTool('space'); return;
        }
      }

      // Undo/Redo
      if ((e.ctrlKey || e.metaKey) && e.key === 'z') {
        e.preventDefault();
        if (e.shiftKey) {
          redo();
          toast('Redo', { icon: '↪️' });
        } else {
          undo();
          toast('Undo', { icon: '↩️' });
        }
        return;
      }

      // Backspace - delete last point while drawing
      if (e.key === 'Backspace' && tempPoints.length > 0) {
        e.preventDefault();
        setTempPoints(prev => prev.slice(0, -1));
        toast('Point removed', { icon: '⌫' });
        return;
      }

      // Delete - remove selected measurement
      if ((e.key === 'Delete' || e.key === 'Backspace') && selectedMeasurementId && tempPoints.length === 0) {
        e.preventDefault();
        deleteMeasurement(selectedMeasurementId);
        toast('Deleted', { icon: '🗑️' });
        return;
      }

      // Escape
      if (e.key === 'Escape') {
        setTempPoints([]);
        setMousePos(null);
        // Stop continuous measurement mode
        if (activeMeasurementId) {
          useProjectStore.getState().stopContinuousMeasurement();
          toast('Continuous mode stopped', { icon: '⏹️' });
        }
        return;
      }

      // Enter key finishes current measurement (same as double-click)
      if (e.key === 'Enter' && tempPoints.length >= 2 && project?.scale) {
        if (activeTool === 'area' && tempPoints.length >= 3) {
          // Trigger area completion
          const polygonArea = polygonAreaFeet(tempPoints, project.scale);

          if (activeMeasurementId) {
            const activeMeasurement = project.measurements.find(m => m.id === activeMeasurementId);
            if (activeMeasurement && activeMeasurement.type === 'area') {
              useProjectStore.getState().addPolygonToArea(tempPoints, polygonArea);
              setTempPoints([]);
              toast.success(`${activeMeasurement.name}: ${formatMeasurement(activeMeasurement.value + polygonArea, 'SF')}`);
              return;
            }
          }

          const measurement: Omit<Measurement, 'id' | 'createdAt'> = {
            type: 'area',
            name: `Area ${project.measurements.length + 1}`,
            points: tempPoints,
            value: polygonArea,
            unit: 'SF',
            color: COLORS[colorIndex % COLORS.length],
            pageNumber: project.currentPage
          };
          addMeasurement(measurement);
          setTempPoints([]);
          setColorIndex(c => c + 1);
          toast(`${formatMeasurement(polygonArea, 'SF')} - draw more polygons to add to total`, { icon: '⬛' });
        }

        if (activeTool === 'perimeter' && tempPoints.length >= 2) {
          // Trigger perimeter completion
          const totalLength = polylineLengthFeet(tempPoints, project.scale);

          if (activeMeasurementId) {
            const activeMeasurement = project.measurements.find(m => m.id === activeMeasurementId);
            if (activeMeasurement && activeMeasurement.type === 'perimeter') {
              useProjectStore.getState().addPolylineToPerimeter(tempPoints, totalLength);
              setTempPoints([]);
              toast.success(`${activeMeasurement.name}: ${formatMeasurement(activeMeasurement.value + totalLength, 'LF')}`);
              return;
            }
          }

          const measurement: Omit<Measurement, 'id' | 'createdAt'> = {
            type: 'perimeter',
            name: `Perimeter ${project.measurements.length + 1}`,
            points: tempPoints,
            value: totalLength,
            unit: 'LF',
            color: COLORS[colorIndex % COLORS.length],
            pageNumber: project.currentPage
          };
          addMeasurement(measurement);
          setTempPoints([]);
          setColorIndex(c => c + 1);
          toast(`${formatMeasurement(totalLength, 'LF')} - draw more segments to add to total`, { icon: '🔄' });
        }

        // Space - creates a named space with area + perimeter
        if (activeTool === 'space' && tempPoints.length >= 3) {
          const spaceArea = polygonAreaFeet(tempPoints, project.scale);
          const spacePerimeter = polygonPerimeterFeet(tempPoints, project.scale);

          // Prompt for space name
          const spaceName = prompt('Space name:', `Space ${(project.spaces?.length || 0) + 1}`);
          if (!spaceName) {
            setTempPoints([]);
            return;
          }

          addSpace({
            name: spaceName,
            points: tempPoints,
            area: spaceArea,
            perimeter: spacePerimeter,
            color: COLORS[colorIndex % COLORS.length],
            pageNumber: project.currentPage
          });

          setTempPoints([]);
          setColorIndex(c => c + 1);
          toast.success(`${spaceName}: ${formatMeasurement(spaceArea, 'SF')} / ${formatMeasurement(spacePerimeter, 'LF')} perimeter`, { icon: '🏠' });
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [activeMeasurementId, activeTool, tempPoints, project, colorIndex, selectedMeasurementId, isCalibrating, addMeasurement, setActiveTool, startCalibration, deleteMeasurement, undo, redo]);

  // Clear temp points when tool changes
  useEffect(() => {
    setTempPoints([]);
    setMousePos(null);
  }, [activeTool]);

  // Draw everything
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d')!;
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw spaces first (so measurements render on top)
    project?.spaces
      ?.filter(s => s.pageNumber === project.currentPage)
      .filter(s => s.visible !== false)
      .forEach(s => {
        // Fill with semi-transparent color
        ctx.fillStyle = s.color + '25';  // 15% opacity
        ctx.strokeStyle = s.color;
        ctx.lineWidth = 2;
        ctx.setLineDash([5, 5]);

        ctx.beginPath();
        if (s.points.length > 0) {
          ctx.moveTo(s.points[0].x, s.points[0].y);
          s.points.slice(1).forEach(p => ctx.lineTo(p.x, p.y));
          ctx.closePath();
        }
        ctx.fill();
        ctx.stroke();
        ctx.setLineDash([]);

        // Draw space label at centroid
        const cx = s.points.reduce((sum, p) => sum + p.x, 0) / s.points.length;
        const cy = s.points.reduce((sum, p) => sum + p.y, 0) / s.points.length;

        // Background for label
        ctx.font = 'bold 12px sans-serif';
        const nameMetrics = ctx.measureText(s.name);
        const infoText = `${formatMeasurement(s.area, 'SF')} | ${formatMeasurement(s.perimeter, 'LF')}`;
        ctx.font = '10px sans-serif';
        const infoMetrics = ctx.measureText(infoText);
        const maxWidth = Math.max(nameMetrics.width, infoMetrics.width) + 16;

        ctx.fillStyle = s.color + 'E0';  // 88% opacity
        ctx.beginPath();
        ctx.roundRect(cx - maxWidth/2, cy - 20, maxWidth, 36, 6);
        ctx.fill();

        // Name
        ctx.fillStyle = '#fff';
        ctx.font = 'bold 12px sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(s.name, cx, cy - 6);

        // Area/Perimeter
        ctx.font = '10px sans-serif';
        ctx.fillStyle = 'rgba(255,255,255,0.8)';
        ctx.fillText(infoText, cx, cy + 8);
      });

    // Draw existing measurements (respecting layer + individual + group visibility)
    // Get all measurements that belong to hidden groups
    const measurementsInHiddenGroups = new Set(
      project?.groups
        ?.filter(g => g.visible === false)
        .flatMap(g => g.measurementIds) || []
    );

    project?.measurements
      .filter(m => m.pageNumber === project.currentPage)
      .filter(m => !hiddenLayers.has(m.type))  // Skip hidden layers
      .filter(m => m.visible !== false)  // Skip individually hidden items
      .filter(m => !measurementsInHiddenGroups.has(m.id))  // Skip items in hidden groups
      .forEach(m => {
        const isSelected = m.id === selectedMeasurementId;
        ctx.strokeStyle = m.color;
        ctx.fillStyle = m.color + '40';
        ctx.lineWidth = isSelected ? 3 : 2;

        if (m.type === 'linear' && m.points.length >= 2) {
          // Draw all segments (continuous mode stores multiple segment endpoints)
          // Points are stored as pairs: [start1, end1, start2, end2, ...] or as chain
          for (let i = 0; i < m.points.length - 1; i += 2) {
            const p1 = m.points[i];
            const p2 = m.points[i + 1];
            if (!p2) break;

            ctx.beginPath();
            ctx.moveTo(p1.x, p1.y);
            ctx.lineTo(p2.x, p2.y);
            ctx.stroke();

            // Draw endpoint dots
            [p1, p2].forEach(p => {
              ctx.beginPath();
              ctx.arc(p.x, p.y, 4, 0, Math.PI * 2);
              ctx.fill();
            });
          }

          // Draw total label at the last segment midpoint
          if (m.points.length >= 2) {
            const lastIdx = m.points.length - 1;
            const midX = (m.points[lastIdx - 1].x + m.points[lastIdx].x) / 2;
            const midY = (m.points[lastIdx - 1].y + m.points[lastIdx].y) / 2;
            drawLabel(ctx, formatMeasurement(m.value, m.unit), midX, midY, m.color);
          }
        }

        if (m.type === 'area' && m.points.length >= 3) {
          // Split points into separate polygons using separator marker
          const polygons: Point[][] = [];
          let currentPolygon: Point[] = [];

          m.points.forEach(p => {
            if (p.x === -99999 && p.y === -99999) {
              // Separator found, start new polygon
              if (currentPolygon.length >= 3) {
                polygons.push(currentPolygon);
              }
              currentPolygon = [];
            } else {
              currentPolygon.push(p);
            }
          });
          // Don't forget the last polygon
          if (currentPolygon.length >= 3) {
            polygons.push(currentPolygon);
          }

          // Draw each polygon
          let totalCx = 0, totalCy = 0, totalPoints = 0;
          polygons.forEach((poly, polyIndex) => {
            ctx.fillStyle = m.color + '40';
            ctx.strokeStyle = m.color;
            ctx.lineWidth = isSelected ? 3 : 2;

            ctx.beginPath();
            ctx.moveTo(poly[0].x, poly[0].y);
            poly.slice(1).forEach(p => ctx.lineTo(p.x, p.y));
            ctx.closePath();
            ctx.fill();
            ctx.stroke();

            // Draw polygon number
            const cx = poly.reduce((sum, p) => sum + p.x, 0) / poly.length;
            const cy = poly.reduce((sum, p) => sum + p.y, 0) / poly.length;
            totalCx += cx;
            totalCy += cy;
            totalPoints++;

            if (polygons.length > 1) {
              // Show polygon number for multi-polygon areas
              ctx.fillStyle = m.color;
              ctx.font = 'bold 14px sans-serif';
              ctx.textAlign = 'center';
              ctx.textBaseline = 'middle';
              ctx.fillText((polyIndex + 1).toString(), cx, cy);
            }
          });

          // Draw total label
          if (totalPoints > 0) {
            const labelX = totalCx / totalPoints;
            const labelY = totalCy / totalPoints - 20;
            drawLabel(ctx, formatMeasurement(m.value, m.unit), labelX, labelY, m.color);
          }
        }

        if (m.type === 'count') {
          // Draw numbered marker at each count point
          m.points.forEach((p, index) => {
            const number = index + 1;

            // Draw circle background
            ctx.fillStyle = m.color;
            ctx.strokeStyle = isSelected ? '#fff' : m.color;
            ctx.lineWidth = isSelected ? 2 : 1;
            ctx.beginPath();
            ctx.arc(p.x, p.y, 12, 0, Math.PI * 2);
            ctx.fill();
            ctx.stroke();

            // Draw number
            ctx.fillStyle = '#fff';
            ctx.font = 'bold 11px sans-serif';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText(number.toString(), p.x, p.y);
          });

          // Draw total label near the last point
          if (m.points.length > 0) {
            const lastP = m.points[m.points.length - 1];
            drawLabel(ctx, `${m.value} EA`, lastP.x + 20, lastP.y - 15, m.color);
          }
        }

        if (m.type === 'perimeter' && m.points.length >= 2) {
          // Split points into separate polylines using separator marker
          const polylines: Point[][] = [];
          let currentPolyline: Point[] = [];

          m.points.forEach(p => {
            if (p.x === -99999 && p.y === -99999) {
              // Separator found, start new polyline
              if (currentPolyline.length >= 2) {
                polylines.push(currentPolyline);
              }
              currentPolyline = [];
            } else {
              currentPolyline.push(p);
            }
          });
          // Don't forget the last polyline
          if (currentPolyline.length >= 2) {
            polylines.push(currentPolyline);
          }

          // Draw each polyline (NOT closed)
          polylines.forEach(poly => {
            ctx.strokeStyle = m.color;
            ctx.lineWidth = isSelected ? 3 : 2;

            ctx.beginPath();
            ctx.moveTo(poly[0].x, poly[0].y);
            poly.slice(1).forEach(p => ctx.lineTo(p.x, p.y));
            // NO closePath() - perimeter is open
            ctx.stroke();

            // Draw endpoint dots
            poly.forEach(p => {
              ctx.fillStyle = m.color;
              ctx.beginPath();
              ctx.arc(p.x, p.y, 4, 0, Math.PI * 2);
              ctx.fill();
            });
          });

          // Draw total label at midpoint of last segment
          if (m.points.length >= 2) {
            const lastIdx = m.points.length - 1;
            let lastValid = m.points[lastIdx];
            let secondLast = m.points[lastIdx - 1];
            // Skip separator markers
            if (lastValid.x === -99999) {
              lastValid = m.points[lastIdx - 1];
              secondLast = m.points[lastIdx - 2];
            }
            if (secondLast && lastValid) {
              const midX = (secondLast.x + lastValid.x) / 2;
              const midY = (secondLast.y + lastValid.y) / 2;
              drawLabel(ctx, formatMeasurement(m.value, m.unit), midX, midY - 20, m.color);
            }
          }
        }
      });

    // Draw calibration points
    if (isCalibrating && calibrationPoints.length > 0) {
      ctx.strokeStyle = '#fbbf24';
      ctx.fillStyle = '#fbbf24';
      ctx.lineWidth = 2;
      ctx.setLineDash([5, 5]);

      calibrationPoints.forEach((p, i) => {
        ctx.beginPath();
        ctx.arc(p.x, p.y, 8, 0, Math.PI * 2);
        ctx.fill();

        if (i === 0 && calibrationPoints.length === 2) {
          ctx.beginPath();
          ctx.moveTo(calibrationPoints[0].x, calibrationPoints[0].y);
          ctx.lineTo(calibrationPoints[1].x, calibrationPoints[1].y);
          ctx.stroke();
        }
      });
      ctx.setLineDash([]);
    }

    // Draw temp points and rubber-band
    if (tempPoints.length > 0) {
      const color = COLORS[colorIndex % COLORS.length];
      ctx.strokeStyle = color;
      ctx.fillStyle = color;
      ctx.lineWidth = 2;
      ctx.setLineDash([5, 5]);

      tempPoints.forEach(p => {
        ctx.beginPath();
        ctx.arc(p.x, p.y, 5, 0, Math.PI * 2);
        ctx.fill();
      });

      if (mousePos && tempPoints.length > 0) {
        ctx.beginPath();
        ctx.moveTo(tempPoints[tempPoints.length - 1].x, tempPoints[tempPoints.length - 1].y);
        ctx.lineTo(mousePos.x, mousePos.y);
        ctx.stroke();
      }

      if ((activeTool === 'area' || activeTool === 'perimeter' || activeTool === 'space') && tempPoints.length > 1) {
        ctx.beginPath();
        ctx.moveTo(tempPoints[0].x, tempPoints[0].y);
        tempPoints.slice(1).forEach(p => ctx.lineTo(p.x, p.y));
        ctx.stroke();
      }

      ctx.setLineDash([]);
    }

    // Snap indicator drawing parked for now

  }, [project, isCalibrating, calibrationPoints, tempPoints, mousePos, activeTool, colorIndex, selectedMeasurementId, hiddenLayers]);

  return (
    <canvas
      ref={canvasRef}
      width={width}
      height={height}
      className="absolute top-0 left-0"
      style={{ 
        width, 
        height, 
        pointerEvents: 'auto',
        cursor: activeTool !== 'pan' ? 'crosshair' : 'default'
      }}
      onClick={handleClick}
      onDoubleClick={handleDoubleClick}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
    />
  );
}

function drawLabel(ctx: CanvasRenderingContext2D, text: string, x: number, y: number, color: string) {
  ctx.font = 'bold 12px sans-serif';
  const metrics = ctx.measureText(text);
  const padding = 6;
  const w = metrics.width + padding * 2;
  const h = 20;

  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.roundRect(x - w/2, y - h/2, w, h, 4);
  ctx.fill();

  ctx.fillStyle = '#fff';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, x, y);
}

import { useState } from 'react';
import toast from 'react-hot-toast';
import { useProjectStore } from '../stores/projectStore';
import { formatMeasurement, decimalFeetToFeetInches } from '../utils/geometry';
import type { Measurement, MeasurementGroup, Project } from '../types';

// Color palette for measurements - 15 distinct colors
const COLORS = [
  '#ef4444', // Red
  '#f97316', // Orange
  '#facc15', // Yellow
  '#84cc16', // Lime
  '#22c55e', // Green
  '#14b8a6', // Teal
  '#06b6d4', // Cyan
  '#3b82f6', // Blue
  '#6366f1', // Indigo
  '#8b5cf6', // Violet
  '#a855f7', // Purple
  '#d946ef', // Fuchsia
  '#ec4899', // Pink
  '#f43f5e', // Rose
  '#78716c', // Stone (neutral)
];

export function MeasurementPanel() {
  const { 
    project, 
    selectedMeasurementId, 
    selectMeasurement,
    updateMeasurement,
    deleteMeasurement,
    toggleMeasurementVisibility,
    addGroup,
    deleteGroup,
    addToGroup,
    removeFromGroup,
    toggleGroupVisibility,
    activeMeasurementId,
    continueFromMeasurement,
    stopContinuousMeasurement,
    hiddenLayers,
    toggleLayer,
    deleteSpace,
    toggleSpaceVisibility
  } = useProjectStore();

  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const [showColorPicker, setShowColorPicker] = useState<string | null>(null);
  const [newGroupName, setNewGroupName] = useState('');
  const [showNewGroup, setShowNewGroup] = useState(false);
  const [collapsedGroups, setCollapsedGroups] = useState<Set<string>>(new Set());
  const [draggedItemId, setDraggedItemId] = useState<string | null>(null);
  const [dropTargetGroupId, setDropTargetGroupId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [editingNoteId, setEditingNoteId] = useState<string | null>(null);

  if (!project) return null;

  const allMeasurements = project.measurements;
  const groups = project.groups || [];

  // Filter measurements by search query
  const searchLower = searchQuery.toLowerCase().trim();
  const measurements = searchLower 
    ? allMeasurements.filter(m => 
        m.name.toLowerCase().includes(searchLower) ||
        m.type.toLowerCase().includes(searchLower) ||
        m.notes?.toLowerCase().includes(searchLower) ||
        groups.find(g => g.measurementIds.includes(m.id))?.name.toLowerCase().includes(searchLower)
      )
    : allMeasurements;

  // Get ungrouped measurements (from filtered set)
  const groupedIds = new Set(groups.flatMap(g => g.measurementIds));
  const ungrouped = measurements.filter(m => !groupedIds.has(m.id));

  // Totals (linear + perimeter both go to LF)
  const totalLF = measurements.filter(m => m.type === 'linear' || m.type === 'perimeter').reduce((sum, m) => sum + m.value, 0);
  const totalSF = measurements.filter(m => m.type === 'area').reduce((sum, m) => sum + m.value, 0);
  const totalCount = measurements.filter(m => m.type === 'count').reduce((sum, m) => sum + m.value, 0);

  const handleEdit = (m: Measurement) => {
    setEditingId(m.id);
    setEditName(m.name);
  };

  const handleSaveEdit = (id: string) => {
    updateMeasurement(id, { name: editName });
    setEditingId(null);
  };

  const handleDelete = (id: string) => {
    deleteMeasurement(id);
  };

  const handleColorChange = (id: string, color: string) => {
    updateMeasurement(id, { color });
    setShowColorPicker(null);
  };

  const handleCreateGroup = () => {
    if (newGroupName.trim()) {
      addGroup(newGroupName.trim());
      setNewGroupName('');
      setShowNewGroup(false);
    }
  };

  const toggleGroup = (groupId: string) => {
    const newCollapsed = new Set(collapsedGroups);
    if (newCollapsed.has(groupId)) {
      newCollapsed.delete(groupId);
    } else {
      newCollapsed.add(groupId);
    }
    setCollapsedGroups(newCollapsed);
  };

  const getGroupTotal = (group: MeasurementGroup) => {
    const groupMeasurements = measurements.filter(m => group.measurementIds.includes(m.id));
    const lf = groupMeasurements.filter(m => m.type === 'linear' || m.type === 'perimeter').reduce((sum, m) => sum + m.value, 0);
    const sf = groupMeasurements.filter(m => m.type === 'area').reduce((sum, m) => sum + m.value, 0);
    const count = groupMeasurements.filter(m => m.type === 'count').reduce((sum, m) => sum + m.value, 0);
    return { lf, sf, count, total: groupMeasurements.length };
  };

  const MeasurementRow = ({ m, showGroupMenu = true }: { m: Measurement; showGroupMenu?: boolean }) => {
    const isSelected = selectedMeasurementId === m.id;
    const isActive = activeMeasurementId === m.id;
    const isDragging = draggedItemId === m.id;

    return (
      <div
        key={m.id}
        draggable
        onDragStart={(e) => {
          setDraggedItemId(m.id);
          e.dataTransfer.effectAllowed = 'move';
          e.dataTransfer.setData('text/plain', m.id);
        }}
        onDragEnd={() => {
          setDraggedItemId(null);
          setDropTargetGroupId(null);
        }}
        onClick={() => selectMeasurement(m.id)}
        className="p-2 rounded-lg mb-1 cursor-grab transition-all duration-150"
        style={{
          background: isActive ? 'rgba(34, 197, 94, 0.15)' : isSelected ? 'rgba(201, 162, 39, 0.15)' : '#1a2f3d',
          border: isActive ? '2px solid rgba(34, 197, 94, 0.5)' : isSelected ? '1px solid rgba(201, 162, 39, 0.4)' : '1px solid #1e3a4c',
          opacity: isDragging ? 0.5 : 1,
          cursor: isDragging ? 'grabbing' : 'grab'
        }}
      >
        {/* Active indicator */}
        {isActive && (
          <div className="flex items-center gap-2 mb-2 pb-2" style={{ borderBottom: '1px solid rgba(34, 197, 94, 0.3)' }}>
            <span className="text-xs font-medium" style={{ color: '#22c55e' }}>
              ● {m.type === 'count' ? 'COUNTING' : m.type === 'area' ? 'DRAWING' : 'MEASURING'}
            </span>
            <span className="text-xs" style={{ color: '#6b7280' }}>
              {m.type === 'count' ? 'Click to add' : m.type === 'area' ? 'Draw polygon, dbl-click to close' : 'Click 2 points to add'}
            </span>
            <button
              onClick={(e) => {
                e.stopPropagation();
                stopContinuousMeasurement();
              }}
              className="ml-auto text-xs px-2 py-0.5 rounded"
              style={{ background: '#1e3a4c', color: '#8b7355' }}
            >
              Done
            </button>
          </div>
        )}

        {/* Main row */}
        <div className="flex items-center gap-2">
          {/* Color indicator - clickable */}
          <div className="relative">
            <div 
              className="w-5 h-5 rounded-md cursor-pointer transition-all duration-150"
              style={{ 
                backgroundColor: m.color,
                boxShadow: showColorPicker === m.id ? `0 0 0 2px #0f1c24, 0 0 0 3px ${m.color}` : 'none'
              }}
              onMouseEnter={(e) => {
                if (showColorPicker !== m.id) {
                  e.currentTarget.style.transform = 'scale(1.1)';
                  e.currentTarget.style.boxShadow = '0 2px 8px rgba(0,0,0,0.3)';
                }
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.transform = 'scale(1)';
                if (showColorPicker !== m.id) {
                  e.currentTarget.style.boxShadow = 'none';
                }
              }}
              onClick={(e) => {
                e.stopPropagation();
                setShowColorPicker(showColorPicker === m.id ? null : m.id);
              }}
              title="Click to change color"
            />
            {/* Color picker dropdown - opens to the right */}
            {showColorPicker === m.id && (
              <div 
                className="absolute z-50 p-3 rounded-xl shadow-2xl"
                style={{ 
                  top: '-8px',
                  left: '28px',
                  background: 'linear-gradient(145deg, #152a36 0%, #0f1c24 100%)', 
                  border: '1px solid #3d5a6e',
                  boxShadow: '0 10px 40px rgba(0,0,0,0.5)',
                  minWidth: '200px'
                }}
                onClick={(e) => e.stopPropagation()}
              >
                <div className="text-xs font-medium mb-2" style={{ color: '#6b7280' }}>
                  Select Color
                </div>
                <div style={{ 
                  display: 'grid', 
                  gridTemplateColumns: 'repeat(5, 32px)', 
                  gap: '8px' 
                }}>
                  {COLORS.map(color => (
                    <div
                      key={color}
                      style={{ 
                        width: '32px',
                        height: '32px',
                        borderRadius: '6px',
                        backgroundColor: color,
                        cursor: 'pointer',
                        transition: 'transform 0.15s, box-shadow 0.15s',
                        boxShadow: m.color === color ? `0 0 0 2px #0f1c24, 0 0 0 4px ${color}` : 'none'
                      }}
                      onMouseEnter={(e) => {
                        e.currentTarget.style.transform = 'scale(1.15)';
                        e.currentTarget.style.boxShadow = `0 4px 12px ${color}66`;
                      }}
                      onMouseLeave={(e) => {
                        e.currentTarget.style.transform = 'scale(1)';
                        e.currentTarget.style.boxShadow = m.color === color ? `0 0 0 2px #0f1c24, 0 0 0 4px ${color}` : 'none';
                      }}
                      onClick={() => handleColorChange(m.id, color)}
                    />
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* Eye toggle for individual visibility */}
          <button
            onClick={(e) => {
              e.stopPropagation();
              toggleMeasurementVisibility(m.id);
            }}
            className="p-1 rounded transition-all"
            style={{ 
              color: m.visible !== false ? '#7cb798' : '#4a6a7a',
              opacity: m.visible !== false ? 1 : 0.5
            }}
            title={m.visible !== false ? 'Hide measurement' : 'Show measurement'}
          >
            {m.visible !== false ? '👁' : '👁‍🗨'}
          </button>

          {/* Name */}
          {editingId === m.id ? (
            <input
              type="text"
              value={editName}
              onChange={(e) => setEditName(e.target.value)}
              onBlur={() => handleSaveEdit(m.id)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') handleSaveEdit(m.id);
                if (e.key === 'Escape') setEditingId(null);
              }}
              className="flex-1 px-2 py-1 rounded text-sm"
              style={{ 
                background: '#0f1c24', 
                color: '#e8f1f5',
                border: '1px solid #4a6a7a'
              }}
              autoFocus
              onClick={(e) => e.stopPropagation()}
            />
          ) : (
            <span 
              className="flex-1 text-sm truncate cursor-text"
              style={{ color: '#e8f1f5' }}
              onClick={(e) => {
                e.stopPropagation();
                handleEdit(m);
              }}
              title="Click to rename"
            >
              {m.name}
            </span>
          )}

          {/* Value */}
          <span className="text-sm font-medium tabular-nums" style={{ color: m.color }}>
            {formatMeasurement(m.value, m.unit)}
          </span>

          {/* Notes indicator */}
          <button
            onClick={(e) => {
              e.stopPropagation();
              setEditingNoteId(editingNoteId === m.id ? null : m.id);
            }}
            className="text-xs transition-opacity"
            style={{ 
              color: m.notes ? '#c9a227' : '#4a6a7a',
              opacity: m.notes ? 1 : 0.5
            }}
            title={m.notes || 'Add note'}
          >
            {m.notes ? '📝' : '💬'}
          </button>
        </div>

        {/* Notes editor */}
        {editingNoteId === m.id && (
          <div className="mt-2 pt-2" style={{ borderTop: '1px solid #2d4a5e' }}>
            <textarea
              value={m.notes || ''}
              onChange={(e) => updateMeasurement(m.id, { notes: e.target.value })}
              placeholder="Add notes (conditions, RFIs, etc.)"
              className="w-full px-2 py-1.5 rounded text-sm resize-none"
              style={{ 
                background: '#0f1c24', 
                color: '#e8f1f5',
                border: '1px solid #3d3a20',
                minHeight: '60px'
              }}
              onClick={(e) => e.stopPropagation()}
            />
          </div>
        )}

        {/* Action buttons - always visible when selected */}
        {isSelected && !isActive && (
          <div className="flex items-center gap-2 mt-2 pt-2" style={{ borderTop: '1px solid #2d4a5e' }}>
            {/* Continue button for counts, linear, perimeter, and area */}
            {(m.type === 'count' || m.type === 'linear' || m.type === 'area' || m.type === 'perimeter') && (
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  continueFromMeasurement(m.id);
                }}
                className="text-xs px-2 py-1 rounded transition-colors"
                style={{ background: '#1a3d2a', color: '#22c55e' }}
              >
                ▶ Continue
              </button>
            )}
            {showGroupMenu && groups.length > 0 && (
              <select
                className="text-xs px-2 py-1 rounded cursor-pointer flex-1"
                style={{ background: '#0f1c24', color: '#8b7355', border: '1px solid #2d4a5e' }}
                value=""
                onChange={(e) => {
                  e.stopPropagation();
                  if (e.target.value) addToGroup(m.id, e.target.value);
                }}
                onClick={(e) => e.stopPropagation()}
              >
                <option value="">Move to group...</option>
                {groups.map(g => (
                  <option key={g.id} value={g.id}>{g.name}</option>
                ))}
              </select>
            )}
            <button
              onClick={(e) => {
                e.stopPropagation();
                handleEdit(m);
              }}
              className="text-xs px-2 py-1 rounded transition-colors"
              style={{ background: '#1e3a4c', color: '#8b7355' }}
            >
              ✏️ Rename
            </button>
            <button
              onClick={(e) => {
                e.stopPropagation();
                handleDelete(m.id);
              }}
              className="text-xs px-2 py-1 rounded transition-colors"
              style={{ background: '#3d2020', color: '#ef4444' }}
            >
              🗑️
            </button>
          </div>
        )}

        {/* Deductions section - for area measurements */}
        {isSelected && !isActive && m.type === 'area' && (
            <div className="mt-2 pt-2" style={{ borderTop: '1px solid #2d4a5e' }}>
              <div className="flex items-center justify-between mb-1">
                <span className="text-xs" style={{ color: '#6b7280' }}>Deductions</span>
                <select
                  className="text-xs px-2 py-1 rounded cursor-pointer"
                  style={{ background: '#0f1c24', color: '#8b7355', border: '1px solid #2d4a5e' }}
                  value=""
                  onChange={(e) => {
                    e.stopPropagation();
                    if (e.target.value) {
                      const currentDeductions = m.deductions || [];
                      if (!currentDeductions.includes(e.target.value)) {
                        updateMeasurement(m.id, { deductions: [...currentDeductions, e.target.value] });
                        toast.success('Deduction added', { icon: '➖' });
                      }
                    }
                  }}
                  onClick={(e) => e.stopPropagation()}
                >
                  <option value="">+ Add deduction...</option>
                  {allMeasurements
                    .filter(other => 
                      other.id !== m.id && 
                      other.type === 'area' && 
                      !m.deductions?.includes(other.id)
                    )
                    .map(other => (
                      <option key={other.id} value={other.id}>
                        {other.name} ({formatMeasurement(other.value, other.unit)})
                      </option>
                    ))}
                </select>
              </div>

              {/* Show current deductions */}
              {m.deductions && m.deductions.length > 0 && (
                <div className="space-y-1">
                  {m.deductions.map(deductionId => {
                    const deduction = allMeasurements.find(x => x.id === deductionId);
                    if (!deduction) return null;
                    return (
                      <div 
                        key={deductionId}
                        className="flex items-center justify-between px-2 py-1 rounded text-xs"
                        style={{ background: '#2d2020' }}
                      >
                        <span style={{ color: '#ef4444' }}>
                          − {deduction.name}
                        </span>
                        <span style={{ color: '#ef4444' }}>
                          -{formatMeasurement(deduction.value, deduction.unit)}
                        </span>
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            updateMeasurement(m.id, { 
                              deductions: m.deductions?.filter(id => id !== deductionId) 
                            });
                          }}
                          style={{ color: '#6b7280' }}
                        >
                          ✕
                        </button>
                      </div>
                    );
                  })}

                  {/* Net total */}
                  <div 
                    className="flex items-center justify-between px-2 py-1 rounded text-xs font-medium"
                    style={{ background: '#1a3d2a' }}
                  >
                    <span style={{ color: '#22c55e' }}>Net Total</span>
                    <span style={{ color: '#22c55e' }}>
                      {formatMeasurement(
                        m.value - m.deductions.reduce((sum, id) => {
                          const d = allMeasurements.find(x => x.id === id);
                          return sum + (d?.value || 0);
                        }, 0),
                        m.unit
                      )}
                    </span>
                  </div>
                </div>
              )}
            </div>
          )}
      </div>
    );
  };

  return (
    <div className="w-80 flex flex-col"
         style={{ 
           background: '#0f1c24',
           borderLeft: '1px solid #1e3a4c'
         }}>
      {/* Header */}
      <div className="p-4 flex items-center justify-between" style={{ borderBottom: '1px solid #1e3a4c' }}>
        <h2 className="text-base font-semibold tracking-wide" 
            style={{ color: '#e8f1f5' }}>
          Takeoff
        </h2>
        <button
          onClick={() => {
            // Stop continuous mode so next measurement is a new item
            if (activeMeasurementId) {
              stopContinuousMeasurement();
            }
          }}
          className="px-3 py-1.5 rounded text-sm font-medium transition-all"
          style={{ 
            background: activeMeasurementId ? '#2d5a3d' : '#1e3a4c',
            color: activeMeasurementId ? '#7cb798' : '#6b7280',
            border: '1px solid',
            borderColor: activeMeasurementId ? '#3d7a5d' : '#2d4a5e'
          }}
          title="Start a new measurement (current tool)"
        >
          + New Item
        </button>
      </div>

      {/* Search Bar */}
      <div className="px-3 py-2" style={{ borderBottom: '1px solid #1e3a4c' }}>
        <div className="relative">
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="🔍 Search measurements..."
            className="w-full px-3 py-2 pl-8 rounded text-sm"
            style={{ 
              background: '#0f1c24', 
              color: '#e8f1f5',
              border: '1px solid #2d4a5e'
            }}
          />
          {searchQuery && (
            <button
              onClick={() => setSearchQuery('')}
              className="absolute right-2 top-1/2 -translate-y-1/2 text-xs"
              style={{ color: '#6b7280' }}
            >
              ✕
            </button>
          )}
        </div>
      </div>

      {/* Totals Bar */}
      <div className="flex justify-between px-4 py-3" style={{ background: '#0a141a', borderBottom: '1px solid #1e3a4c' }}>
        <div className="text-center">
          <div className="text-sm font-semibold" style={{ color: '#3b82f6' }}>
            {decimalFeetToFeetInches(totalLF)}
          </div>
          <div className="text-xs" style={{ color: '#4a6a7a' }}>Linear</div>
        </div>
        <div className="text-center">
          <div className="text-sm font-semibold" style={{ color: '#22c55e' }}>
            {totalSF.toFixed(0)} SF
          </div>
          <div className="text-xs" style={{ color: '#4a6a7a' }}>Area</div>
        </div>
        <div className="text-center">
          <div className="text-sm font-semibold" style={{ color: '#eab308' }}>
            {totalCount} EA
          </div>
          <div className="text-xs" style={{ color: '#4a6a7a' }}>Count</div>
        </div>
      </div>

      {/* Layer Visibility */}
      <div className="flex items-center gap-1 px-3 py-2" style={{ background: '#0f1c24', borderBottom: '1px solid #1e3a4c' }}>
        <span className="text-xs mr-2" style={{ color: '#4a6a7a' }}>Layers:</span>
        {[
          { key: 'linear', label: 'Linear', color: '#3b82f6', icon: '📐' },
          { key: 'perimeter', label: 'Perim', color: '#06b6d4', icon: '🔄' },
          { key: 'area', label: 'Area', color: '#22c55e', icon: '⬛' },
          { key: 'count', label: 'Count', color: '#eab308', icon: '🔢' },
        ].map(layer => {
          const isHidden = hiddenLayers.has(layer.key);
          return (
            <button
              key={layer.key}
              onClick={() => toggleLayer(layer.key)}
              className="px-2 py-1 rounded text-xs transition-all"
              style={{
                background: isHidden ? '#1a2f3d' : layer.color + '20',
                color: isHidden ? '#4a6a7a' : layer.color,
                border: `1px solid ${isHidden ? '#2d4a5e' : layer.color + '40'}`,
                opacity: isHidden ? 0.5 : 1,
                textDecoration: isHidden ? 'line-through' : 'none'
              }}
              title={`${isHidden ? 'Show' : 'Hide'} ${layer.label}`}
            >
              {layer.icon}
            </button>
          );
        })}
      </div>

      {/* Spaces Section */}
      {project.spaces && project.spaces.length > 0 && (
        <div className="px-2 py-2" style={{ borderBottom: '1px solid #1e3a4c' }}>
          <div className="flex items-center justify-between mb-2">
            <span className="text-xs font-medium" style={{ color: '#8b7355' }}>
              🏠 Spaces ({project.spaces.filter(s => s.pageNumber === project.currentPage).length})
            </span>
          </div>
          <div className="space-y-1">
            {project.spaces
              .filter(s => s.pageNumber === project.currentPage)
              .map(space => (
                <div
                  key={space.id}
                  className="flex items-center gap-2 px-2 py-1.5 rounded text-sm"
                  style={{ background: '#1a2f3d' }}
                >
                  {/* Color dot */}
                  <div 
                    className="w-3 h-3 rounded"
                    style={{ backgroundColor: space.color }}
                  />

                  {/* Visibility toggle */}
                  <button
                    onClick={() => toggleSpaceVisibility(space.id)}
                    className="transition-all"
                    style={{ 
                      color: space.visible !== false ? '#7cb798' : '#4a6a7a',
                      opacity: space.visible !== false ? 1 : 0.5,
                      fontSize: '11px'
                    }}
                    title={space.visible !== false ? 'Hide space' : 'Show space'}
                  >
                    {space.visible !== false ? '👁' : '👁‍🗨'}
                  </button>

                  {/* Name */}
                  <span 
                    className="flex-1 truncate"
                    style={{ 
                      color: space.visible !== false ? '#e8f1f5' : '#6b7280',
                      textDecoration: space.visible === false ? 'line-through' : 'none'
                    }}
                  >
                    {space.name}
                  </span>

                  {/* Area */}
                  <span className="text-xs tabular-nums" style={{ color: '#22c55e' }}>
                    {formatMeasurement(space.area, 'SF')}
                  </span>

                  {/* Perimeter */}
                  <span className="text-xs tabular-nums" style={{ color: '#3b82f6' }}>
                    {formatMeasurement(space.perimeter, 'LF')}
                  </span>

                  {/* Delete */}
                  <button
                    onClick={() => deleteSpace(space.id)}
                    className="opacity-0 hover:opacity-100 text-xs px-1 transition-opacity"
                    style={{ color: '#6b7280' }}
                    title="Delete space"
                  >
                    ✕
                  </button>
                </div>
              ))}
          </div>
        </div>
      )}

      {/* Measurement List */}
      <div className="flex-1 overflow-y-auto p-2">
        {measurements.length === 0 ? (
          <div className="p-8 text-center" style={{ color: '#4a6a7a' }}>
            <div className="text-3xl mb-3 opacity-50">📐</div>
            <p className="text-sm" style={{ color: '#6b7280' }}>
              No measurements yet
            </p>
          </div>
        ) : (
          <>
            {/* Groups - hierarchical with parent/child */}
            {(() => {
              // Get top-level groups (no parent)
              const topLevelGroups = groups.filter(g => !g.parentId);

              // Recursive renderer for groups
              const renderGroup = (group: MeasurementGroup, depth: number = 0) => {
                const groupMeasurements = measurements.filter(m => group.measurementIds.includes(m.id));
                const childGroups = groups.filter(g => g.parentId === group.id);
                const totals = getGroupTotal(group);
                const isCollapsed = collapsedGroups.has(group.id);
                const isParent = childGroups.length > 0;
                const isDropTarget = dropTargetGroupId === group.id;

                return (
                  <div key={group.id} className="mb-1" style={{ marginLeft: depth * 12 }}>
                    {/* Group Header - drop target for measurements */}
                    <div 
                      className="flex items-center gap-2 px-2 py-2 rounded cursor-pointer transition-colors"
                      style={{ 
                        background: isDropTarget ? 'rgba(34, 197, 94, 0.3)' : isParent ? '#1e3a4c' : '#1a2f3d',
                        borderLeft: depth > 0 ? `2px solid ${group.color}40` : 'none',
                        border: isDropTarget ? '2px dashed #22c55e' : undefined
                      }}
                      onClick={() => toggleGroup(group.id)}
                      onDragOver={(e) => {
                        e.preventDefault();
                        e.dataTransfer.dropEffect = 'move';
                        setDropTargetGroupId(group.id);
                      }}
                      onDragLeave={() => {
                        setDropTargetGroupId(null);
                      }}
                      onDrop={(e) => {
                        e.preventDefault();
                        const measurementId = e.dataTransfer.getData('text/plain');
                        if (measurementId) {
                          addToGroup(measurementId, group.id);
                          toast.success(`Moved to ${group.name}`, { icon: '📁' });
                        }
                        setDropTargetGroupId(null);
                        setDraggedItemId(null);
                      }}
                    >
                      <span style={{ color: '#6b7280', fontSize: '10px' }}>
                        {isCollapsed ? '▶' : '▼'}
                      </span>
                      <div 
                        className="w-3 h-3 rounded"
                        style={{ backgroundColor: group.color }}
                      />
                      <span 
                        className="flex-1 text-sm truncate" 
                        style={{ 
                          color: '#e8f1f5',
                          fontWeight: isParent ? 600 : 400
                        }}
                      >
                        {group.name}
                      </span>
                      {(childGroups.length > 0 || totals.total > 0) && (
                        <span className="text-xs" style={{ color: '#6b7280' }}>
                          {childGroups.length > 0 ? `${childGroups.length} sub` : totals.total}
                        </span>
                      )}
                      {totals.lf > 0 && (
                        <span className="text-xs font-medium" style={{ color: '#3b82f6' }}>
                          {decimalFeetToFeetInches(totals.lf)}
                        </span>
                      )}
                      {/* Group visibility toggle */}
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          toggleGroupVisibility(group.id);
                        }}
                        className="px-1 transition-all"
                        style={{ 
                          color: group.visible !== false ? '#7cb798' : '#4a6a7a',
                          opacity: group.visible !== false ? 1 : 0.5,
                          fontSize: '12px'
                        }}
                        title={group.visible !== false ? 'Hide group' : 'Show group'}
                      >
                        {group.visible !== false ? '👁' : '👁‍🗨'}
                      </button>
                      {/* Add subgroup button */}
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          const name = prompt('Subgroup name:');
                          if (name) addGroup(name, group.id);
                        }}
                        className="opacity-0 hover:opacity-100 text-xs px-1"
                        style={{ color: '#7cb798' }}
                        title="Add subgroup"
                      >
                        +
                      </button>
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          deleteGroup(group.id);
                        }}
                        className="opacity-0 hover:opacity-100 text-xs px-1"
                        style={{ color: '#6b7280' }}
                      >
                        ✕
                      </button>
                    </div>

                    {/* Group Contents - child groups + measurements */}
                    {!isCollapsed && (
                      <div className="mt-1">
                        {/* Child groups first */}
                        {childGroups.map(child => renderGroup(child, depth + 1))}

                        {/* Then measurements */}
                        {groupMeasurements.length > 0 && (
                          <div style={{ marginLeft: 12 }}>
                            {groupMeasurements.map(m => (
                              <MeasurementRow key={m.id} m={m} showGroupMenu={false} />
                            ))}
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                );
              };

              return topLevelGroups.map(g => renderGroup(g, 0));
            })()}

            {/* Ungrouped - drop target to remove from groups */}
            {(ungrouped.length > 0 || groups.length > 0) && (
              <div 
                className="mb-3"
                onDragOver={(e) => {
                  e.preventDefault();
                  e.dataTransfer.dropEffect = 'move';
                }}
                onDrop={(e) => {
                  e.preventDefault();
                  const measurementId = e.dataTransfer.getData('text/plain');
                  if (measurementId) {
                    removeFromGroup(measurementId);
                    toast.success('Moved to Ungrouped', { icon: '📤' });
                  }
                  setDraggedItemId(null);
                }}
              >
                {groups.length > 0 && (
                  <div 
                    className="px-2 py-1 text-xs font-medium rounded transition-colors"
                    style={{ 
                      color: '#6b7280',
                      background: draggedItemId ? 'rgba(107, 114, 128, 0.1)' : 'transparent',
                      border: draggedItemId ? '1px dashed #6b7280' : '1px dashed transparent'
                    }}
                  >
                    {draggedItemId ? '📤 Drop here to ungroup' : 'Ungrouped'}
                  </div>
                )}
                {ungrouped.map(m => (
                  <MeasurementRow key={m.id} m={m} />
                ))}
              </div>
            )}
          </>
        )}
      </div>

      {/* Footer Actions */}
      <div className="p-3" style={{ borderTop: '1px solid #1e3a4c' }}>
        {/* New Group */}
        {showNewGroup ? (
          <div className="flex gap-2 mb-2">
            <input
              type="text"
              value={newGroupName}
              onChange={(e) => setNewGroupName(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') handleCreateGroup();
                if (e.key === 'Escape') setShowNewGroup(false);
              }}
              placeholder="Group name..."
              className="flex-1 px-3 py-2 rounded text-sm"
              style={{ 
                background: '#1a2f3d', 
                color: '#e8f1f5',
                border: '1px solid #2d4a5e'
              }}
              autoFocus
            />
            <button
              onClick={handleCreateGroup}
              className="px-3 py-2 rounded text-sm"
              style={{ background: '#2d5a3d', color: '#7cb798' }}
            >
              Add
            </button>
          </div>
        ) : (
          <button
            onClick={() => setShowNewGroup(true)}
            className="w-full py-2 px-3 rounded text-sm mb-2 transition-colors"
            style={{ 
              border: '1px dashed #2d4a5e', 
              color: '#6b7280',
              background: 'transparent'
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.borderColor = '#4a6a7a';
              e.currentTarget.style.color = '#8b7355';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.borderColor = '#2d4a5e';
              e.currentTarget.style.color = '#6b7280';
            }}
          >
            + New Group
          </button>
        )}

        {/* Save/Load/Export Buttons */}
        <div className="flex gap-2 mb-2">
          <button
            onClick={() => saveProject(project)}
            className="flex-1 py-2 px-3 rounded text-sm transition-colors"
            style={{ 
              background: '#1e3a4c',
              color: '#7cb798',
              border: '1px solid #2d5a3d'
            }}
            title="Save project to file (.pilar)"
          >
            💾 Save
          </button>
          <button
            onClick={() => document.getElementById('load-project-input')?.click()}
            className="flex-1 py-2 px-3 rounded text-sm transition-colors"
            style={{ 
              background: '#1e3a4c',
              color: '#8b7355',
              border: '1px solid #3d3020'
            }}
            title="Load project from file"
          >
            📂 Load
          </button>
          <input
            id="load-project-input"
            type="file"
            accept=".pilar,.json"
            className="hidden"
            onChange={(e) => {
              const file = e.target.files?.[0];
              if (file) loadProject(file);
              e.target.value = '';
            }}
          />
        </div>

        {/* Export CSV */}
        {measurements.length > 0 && (
          <button
            onClick={() => exportToCSV(measurements, groups, project.name)}
            className="w-full py-2 px-3 rounded text-sm font-medium transition-all"
            style={{ 
              background: '#c9a227',
              color: '#0f1c24',
            }}
          >
            Export CSV
          </button>
        )}
      </div>
    </div>
  );
}

function exportToCSV(measurements: Measurement[], groups: MeasurementGroup[], projectName: string) {
  const headers = ['Group', 'Name', 'Type', 'Value', 'Unit', 'Page'];

  const getGroupName = (m: Measurement) => {
    const group = groups.find(g => g.measurementIds.includes(m.id));
    return group?.name || 'Ungrouped';
  };

  const rows = measurements.map(m => [
    getGroupName(m),
    m.name,
    m.type,
    m.value.toFixed(2),
    m.unit,
    m.pageNumber
  ]);

  const csv = [
    headers.join(','),
    ...rows.map(r => r.map(cell => `"${cell}"`).join(','))
  ].join('\n');

  const blob = new Blob([csv], { type: 'text/csv' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `${projectName}-takeoff.csv`;
  a.click();
  URL.revokeObjectURL(url);
}

function saveProject(project: Project) {
  // Create a saveable version (exclude pdfFile blob, keep pdfUrl for reference)
  const saveData = {
    version: '1.0',
    savedAt: new Date().toISOString(),
    project: {
      ...project,
      pdfFile: undefined,  // Don't save the blob
      pdfUrl: undefined,   // Will need to re-load PDF
      pdfName: project.name  // Keep the name to help user find the PDF
    }
  };

  const json = JSON.stringify(saveData, null, 2);
  const blob = new Blob([json], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `${project.name}.pilar`;
  a.click();
  URL.revokeObjectURL(url);

  // Also save to localStorage as backup
  try {
    localStorage.setItem('pilar-autosave', json);
    toast.success(`Saved: ${project.name}.pilar`);
  } catch (e) {
    toast.success(`Saved to file (localStorage full)`);
  }
}

function loadProject(file: File) {
  const reader = new FileReader();
  reader.onload = (e) => {
    try {
      const json = e.target?.result as string;
      const data = JSON.parse(json);

      if (!data.project) {
        toast.error('Invalid project file');
        return;
      }

      // Restore the project (user will need to re-load the PDF)
      const project: Project = {
        ...data.project,
        pdfFile: undefined,
        pdfUrl: undefined,
        createdAt: new Date(data.project.createdAt),
        updatedAt: new Date()
      };

      // Prompt user to load the PDF
      toast((t) => (
        <div>
          <p className="font-medium mb-2">Project loaded: {project.name}</p>
          <p className="text-sm opacity-80 mb-3">
            {project.measurements.length} measurements, {Object.keys(project.scales || {}).length} calibrated pages
          </p>
          <p className="text-xs opacity-60">
            Re-load the PDF to continue editing
          </p>
          <button
            onClick={() => {
              toast.dismiss(t.id);
              document.getElementById('reload-pdf-input')?.click();
            }}
            className="mt-2 px-3 py-1 rounded text-sm"
            style={{ background: '#c9a227', color: '#0f1c24' }}
          >
            Load PDF
          </button>
        </div>
      ), { duration: 10000 });

      // Store the loaded project data temporarily
      (window as any).__pendingProject = project;

    } catch (err) {
      toast.error('Failed to parse project file');
      console.error(err);
    }
  };
  reader.readAsText(file);
}

import { useCallback, useState, useEffect } from 'react';
import { Toaster } from 'react-hot-toast';
import toast from 'react-hot-toast';
import * as pdfjsLib from 'pdfjs-dist';
import { useProjectStore } from './stores/projectStore';
import { Toolbar } from './components/Toolbar';
import { PDFViewer } from './components/PDFViewer';
import { MeasurementPanel } from './components/MeasurementPanel';
import { DropZone } from './components/DropZone';
import { CalibrationDialog } from './components/CalibrationDialog';
import { SheetSetupDialog } from './components/SheetSetupDialog';
import type { Project, Sheet } from './types';

// Set up PDF.js worker
pdfjsLib.GlobalWorkerOptions.workerSrc = new URL(
  'pdfjs-dist/build/pdf.worker.min.mjs',
  import.meta.url
).toString();

function App() {
  const { project, setProject, isCalibrating, calibrationPoints, cancelCalibration } = useProjectStore();

  // Sheet setup state
  const [pendingPdf, setPendingPdf] = useState<{ file: File; url: string } | null>(null);
  const [detectedSheets, setDetectedSheets] = useState<{ totalPages: number; names: string[] }>({ totalPages: 0, names: [] });
  const [showSheetSetup, setShowSheetSetup] = useState(false);

  const handleFileLoad = useCallback(async (file: File) => {
    const url = URL.createObjectURL(file);

    // Check if there's a pending project to merge with (from .pilar load)
    const pendingProject = (window as any).__pendingProject as Project | undefined;

    if (pendingProject) {
      // Merge the loaded project data with the new PDF - skip sheet setup
      const mergedProject: Project = {
        ...pendingProject,
        pdfFile: file,
        pdfUrl: url,
        updatedAt: new Date()
      };
      setProject(mergedProject);
      delete (window as any).__pendingProject;
      toast.success(`Restored ${pendingProject.measurements.length} measurements`);
    } else {
      // New project - detect sheets first
      try {
        const pdf = await pdfjsLib.getDocument(url).promise;
        const totalPages = pdf.numPages;

        // Try to get page labels from PDF
        const pageLabels = await pdf.getPageLabels();
        const names: string[] = [];

        for (let i = 1; i <= totalPages; i++) {
          if (pageLabels && pageLabels[i - 1]) {
            names.push(pageLabels[i - 1]);
          } else {
            names.push(`Sheet ${i}`);
          }
        }

        setPendingPdf({ file, url });
        setDetectedSheets({ totalPages, names });
        setShowSheetSetup(true);
      } catch (err) {
        console.error('Error loading PDF:', err);
        toast.error('Failed to load PDF');
      }
    }
  }, [setProject]);

  const handleSheetSetupConfirm = useCallback((sheets: Sheet[]) => {
    if (!pendingPdf) return;

    const newProject: Project = {
      id: Math.random().toString(36).substring(2, 15),
      name: pendingPdf.file.name.replace('.pdf', ''),
      pdfFile: pendingPdf.file,
      pdfUrl: pendingPdf.url,
      scale: null,
      scales: {},
      scaleUnit: 'ft',
      sheets,
      spaces: [],
      currentPage: 1,
      totalPages: sheets.length,
      measurements: [],
      groups: [],
      createdAt: new Date(),
      updatedAt: new Date()
    };

    setProject(newProject);
    setShowSheetSetup(false);
    setPendingPdf(null);
    toast.success(`${sheets.length} sheets configured`);
  }, [pendingPdf, setProject]);

  const handleSheetSetupCancel = useCallback(() => {
    if (pendingPdf) {
      URL.revokeObjectURL(pendingPdf.url);
    }
    setShowSheetSetup(false);
    setPendingPdf(null);
  }, [pendingPdf]);

  // Auto-save to localStorage every 30 seconds
  useEffect(() => {
    if (!project) return;

    const interval = setInterval(() => {
      try {
        const saveData = {
          version: '1.0',
          savedAt: new Date().toISOString(),
          project: {
            ...project,
            pdfFile: undefined,
            pdfUrl: undefined
          }
        };
        localStorage.setItem('pilar-autosave', JSON.stringify(saveData));
      } catch (e) {
        // localStorage might be full, ignore
      }
    }, 30000);

    return () => clearInterval(interval);
  }, [project]);

  // Show calibration dialog when both points are set
  // Track if user wants direct mode (no clicking) vs calibrate mode (click points)
  const [useDirectScale, setUseDirectScale] = useState(true);

  // Show dialog immediately for direct mode, or after 2 points for calibrate mode
  const shouldShowCalibrationDialog = isCalibrating && (useDirectScale || calibrationPoints.length === 2);

  // Check for autosaved project on mount
  useEffect(() => {
    try {
      const saved = localStorage.getItem('pilar-autosave');
      if (saved) {
        const data = JSON.parse(saved);
        if (data.project?.measurements?.length > 0) {
          toast((t) => (
            <div>
              <p className="font-medium mb-2">Found autosaved project</p>
              <p className="text-sm opacity-80 mb-2">
                {data.project.name}: {data.project.measurements.length} measurements
              </p>
              <div className="flex gap-2">
                <button
                  onClick={() => {
                    (window as any).__pendingProject = {
                      ...data.project,
                      createdAt: new Date(data.project.createdAt),
                      updatedAt: new Date()
                    };
                    toast.dismiss(t.id);
                    toast('Load the PDF to restore your work', { icon: '📂' });
                  }}
                  className="px-3 py-1 rounded text-sm"
                  style={{ background: '#22c55e', color: '#fff' }}
                >
                  Restore
                </button>
                <button
                  onClick={() => {
                    localStorage.removeItem('pilar-autosave');
                    toast.dismiss(t.id);
                  }}
                  className="px-3 py-1 rounded text-sm"
                  style={{ background: '#4a6a7a', color: '#fff' }}
                >
                  Discard
                </button>
              </div>
            </div>
          ), { duration: 15000 });
        }
      }
    } catch (e) {
      // Ignore parse errors
    }
  }, []);

  if (!project) {
    return (
      <>
        <DropZone onFileLoad={handleFileLoad} />

        {/* Sheet Setup Dialog */}
        {showSheetSetup && (
          <SheetSetupDialog
            totalPages={detectedSheets.totalPages}
            detectedNames={detectedSheets.names}
            onConfirm={handleSheetSetupConfirm}
            onCancel={handleSheetSetupCancel}
          />
        )}

        <Toaster 
          position="bottom-right"
          toastOptions={{
            style: {
              background: '#2d4a5e',
              color: '#e8f1f5',
              border: '1px solid #4a6a7a',
              fontFamily: 'Source Sans 3, sans-serif'
            }
          }}
        />
      </>
    );
  }

  // Get current sheet info
  const currentSheet = project.sheets?.find(s => s.pageNumber === project.currentPage);

  return (
    <div className="min-h-screen flex flex-col" style={{ background: '#1a2f3d' }}>
      {/* Header */}
      <header className="px-4 py-3 flex items-center justify-between"
              style={{ 
                background: 'linear-gradient(90deg, #0f1c24 0%, #1a2f3d 50%, #0f1c24 100%)',
                borderBottom: '1px solid #2d4a5e'
              }}>
        <div className="flex items-center gap-4">
          <span className="text-3xl">🚤</span>
          <div>
            <h1 className="text-xl font-semibold" 
                style={{ fontFamily: 'Playfair Display, serif', color: '#c9a227' }}>
              Pilar Studio
            </h1>
            <p className="text-xs opacity-60" style={{ color: '#e8f1f5' }}>
              {project.name}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-4">
          {/* Current sheet info */}
          {currentSheet && (
            <span className="text-sm px-3 py-1 rounded"
                  style={{ background: '#1e3a4c', color: '#e8f1f5', border: '1px solid #2d4a5e' }}>
              📄 {currentSheet.name}
              {currentSheet.level !== undefined && (
                <span style={{ color: '#8b7355' }}> (Level {currentSheet.level})</span>
              )}
            </span>
          )}
          {project.scale ? (
            <span className="text-sm px-3 py-1 rounded"
                  style={{ background: '#1e3a4c', color: '#7cb798', border: '1px solid #2d5a3d' }}>
              ✓ Scale set
            </span>
          ) : (
            <span className="text-sm px-3 py-1 rounded"
                  style={{ background: '#3d2a1a', color: '#c9a227', border: '1px solid #5a4020' }}>
              ⚠ Set scale to begin
            </span>
          )}
        </div>
      </header>

      {/* Toolbar */}
      <Toolbar />

      {/* Main Content */}
      <div className="flex-1 flex overflow-hidden">
        {/* PDF Viewer */}
        <div className="flex-1 relative" style={{ background: '#0a141a' }}>
          <PDFViewer />
        </div>

        {/* Measurements Panel */}
        <MeasurementPanel />
      </div>

      {/* Calibration Dialog */}
      {shouldShowCalibrationDialog && (
        <CalibrationDialog 
          onClose={cancelCalibration} 
          onModeChange={(mode) => setUseDirectScale(mode === 'direct')}
          initialMode={useDirectScale ? 'direct' : 'dimension'}
        />
      )}

      {/* Hidden input for reloading PDFs when restoring projects */}
      <input
        id="reload-pdf-input"
        type="file"
        accept=".pdf"
        className="hidden"
        onChange={(e) => {
          const file = e.target.files?.[0];
          if (file) handleFileLoad(file);
          e.target.value = '';
        }}
      />

      <Toaster 
        position="bottom-right"
        toastOptions={{
          style: {
            background: '#2d4a5e',
            color: '#e8f1f5',
            border: '1px solid #4a6a7a',
            fontFamily: 'Source Sans 3, sans-serif'
          }
        }}
      />
    </div>
  );
}

export default App;

import { useProjectStore } from '../stores/projectStore';
import type { Tool } from '../types';

interface ToolButtonProps {
  tool: Tool;
  icon: string;
  label: string;
  shortcut?: string;
  disabled?: boolean;
}

function ToolButton({ tool, icon, label, shortcut, disabled }: ToolButtonProps) {
  const { activeTool, setActiveTool, startCalibration } = useProjectStore();
  const isActive = activeTool === tool;

  const handleClick = () => {
    if (disabled) return;
    if (tool === 'calibrate') {
      startCalibration();
    } else {
      setActiveTool(tool);
    }
  };

  return (
    <button
      onClick={handleClick}
      disabled={disabled}
      title={`${label}${shortcut ? ` (${shortcut})` : ''}`}
      className="flex items-center gap-2 px-4 py-2 rounded text-sm font-medium transition-all duration-150"
      style={{
        background: isActive ? '#c9a227' : 'transparent',
        color: isActive ? '#1a2f3d' : disabled ? '#4a6a7a' : '#e8f1f5',
        cursor: disabled ? 'not-allowed' : 'pointer',
        opacity: disabled ? 0.5 : 1,
        border: isActive ? 'none' : '1px solid transparent',
      }}
      onMouseEnter={(e) => {
        if (!disabled && !isActive) {
          e.currentTarget.style.background = '#2d4a5e';
          e.currentTarget.style.borderColor = '#4a6a7a';
        }
      }}
      onMouseLeave={(e) => {
        if (!isActive) {
          e.currentTarget.style.background = 'transparent';
          e.currentTarget.style.borderColor = 'transparent';
        }
      }}
    >
      <span className="text-lg">{icon}</span>
      <span className="hidden sm:inline">{label}</span>
    </button>
  );
}

