          label="Area" 
          shortcut="A"
          disabled={!project.scale}
        />
        <ToolButton 
          tool="count" 
          icon="🔢" 
          label="Count" 
          shortcut="N"
          disabled={!project.scale}
        />

        <Divider />

        <ToolButton 
          tool="space" 
          icon="🏠" 
          label="Space" 
          shortcut="S"
          disabled={!project.scale}
        />
      </div>

      {/* Center: Page Navigation */}
      <div className="flex items-center gap-3 px-4 py-1 rounded"
           style={{ background: '#1a2f3d', border: '1px solid #2d4a5e' }}>
        <button
          onClick={() => setCurrentPage(project.currentPage - 1)}
          disabled={project.currentPage <= 1}
          className="px-2 py-1 rounded transition-colors"
          style={{ 
            color: project.currentPage <= 1 ? '#4a6a7a' : '#e8f1f5',
            cursor: project.currentPage <= 1 ? 'not-allowed' : 'pointer'
          }}
        >
          ◀
        </button>
        <span className="text-sm min-w-24 text-center" style={{ color: '#8b7355' }}>
          Page {project.currentPage} of {project.totalPages}
        </span>
        <button
          onClick={() => setCurrentPage(project.currentPage + 1)}
          disabled={project.currentPage >= project.totalPages}
          className="px-2 py-1 rounded transition-colors"
          style={{ 
            color: project.currentPage >= project.totalPages ? '#4a6a7a' : '#e8f1f5',
            cursor: project.currentPage >= project.totalPages ? 'not-allowed' : 'pointer'
          }}
        >
          ▶
        </button>
      </div>

      {/* Right: Zoom */}
      <div className="flex items-center gap-2">
        <button
          onClick={() => setZoom(zoom - 0.25)}
          className="px-3 py-1 rounded transition-colors"
          style={{ color: '#e8f1f5' }}
          onMouseEnter={(e) => e.currentTarget.style.background = '#2d4a5e'}
          onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
        >
          −
        </button>
        <span className="text-sm min-w-16 text-center" style={{ color: '#8b7355' }}>
          {Math.round(zoom * 100)}%
        </span>
        <button
          onClick={() => setZoom(zoom + 0.25)}
          className="px-3 py-1 rounded transition-colors"
          style={{ color: '#e8f1f5' }}
          onMouseEnter={(e) => e.currentTarget.style.background = '#2d4a5e'}
          onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
        >
          +
        </button>
        <button
          onClick={() => setZoom(1)}
          className="px-3 py-1 rounded text-sm transition-colors"
          style={{ color: '#c9a227', border: '1px solid #5a4020' }}
          onMouseEnter={(e) => e.currentTarget.style.background = '#2d4a5e'}
          onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
        >
          Fit
        </button>
      </div>
    </div>
  );
}

import { useEffect, useRef, useState, useCallback } from 'react';
import * as pdfjsLib from 'pdfjs-dist';
import { useProjectStore } from '../stores/projectStore';
import { MeasurementCanvas } from './MeasurementCanvas';
import { snapEngine } from '../utils/snapEngine';

// Set up worker once at module level
pdfjsLib.GlobalWorkerOptions.workerSrc = new URL(
  'pdfjs-dist/build/pdf.worker.min.mjs',
  import.meta.url
).toString();

export function PDFViewer() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [pdfDoc, setPdfDoc] = useState<pdfjsLib.PDFDocumentProxy | null>(null);
  const [pageSize, setPageSize] = useState({ width: 0, height: 0 });
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const loadingTaskRef = useRef<pdfjsLib.PDFDocumentLoadingTask | null>(null);

  const { 
    project, 
    zoom, 
    panOffset, 
    setPanOffset,
    activeTool,
    setProject
  } = useProjectStore();

  // Load PDF
  useEffect(() => {
    if (!project?.pdfUrl) return;

    // Cancel any previous loading task
    if (loadingTaskRef.current) {
      loadingTaskRef.current.destroy();
    }

    setIsLoading(true);
    setError(null);
    setPdfDoc(null);

    const loadingTask = pdfjsLib.getDocument({
      url: project.pdfUrl,
      cMapUrl: 'https://unpkg.com/pdfjs-dist@4.4.168/cmaps/',
      cMapPacked: true,
    });

    loadingTaskRef.current = loadingTask;

    loadingTask.promise
      .then((doc) => {
        console.log('PDF loaded successfully, pages:', doc.numPages);
        setPdfDoc(doc);
        if (project.totalPages !== doc.numPages) {
          setProject({ ...project, totalPages: doc.numPages });
        }
        setIsLoading(false);
      })
      .catch((err) => {
        if (err.name === 'PasswordException') {
          setError('This PDF is password protected');
        } else if (err.message?.includes('destroyed')) {
          // Ignore - component unmounted
          console.log('Loading cancelled');
        } else {
          console.error('Error loading PDF:', err);
          setError(err.message || 'Failed to load PDF');
        }
        setIsLoading(false);
      });

    return () => {
      if (loadingTaskRef.current) {
        loadingTaskRef.current.destroy();
        loadingTaskRef.current = null;
      }
    };
  }, [project?.pdfUrl]);

  // Render current page
  useEffect(() => {
    if (!pdfDoc || !canvasRef.current || !project) return;

    let cancelled = false;
    let renderTask: pdfjsLib.RenderTask | null = null;

    const renderPage = async () => {
      try {
        const page = await pdfDoc.getPage(project.currentPage);
        if (cancelled) return;

        const scale = zoom * 2; // 2x for retina
        const viewport = page.getViewport({ scale });

        // Store the PDF coordinate conversion factor for accurate measurements
        // viewport.scale tells us pixels per PDF unit
        // PDF standard: 72 units = 1 inch
        // So: pixelsPerInch = viewport.scale * 72
        const pixelsPerPdfUnit = viewport.scale;
        console.log('PDF render info:', {
          viewportScale: viewport.scale,
          pixelsPerPdfUnit,
          pixelsPerInch: pixelsPerPdfUnit * 72,
          width: viewport.width,
          height: viewport.height
        });

        const canvas = canvasRef.current!;
        const context = canvas.getContext('2d')!;

        canvas.width = viewport.width;
        canvas.height = viewport.height;
        canvas.style.width = `${viewport.width / 2}px`;
        canvas.style.height = `${viewport.height / 2}px`;

        setPageSize({ 
          width: viewport.width / 2, 
          height: viewport.height / 2 
        });

        renderTask = page.render({
          canvasContext: context,
          viewport: viewport
        });

        await renderTask.promise;
        console.log('Page', project.currentPage, 'rendered');

        // Detect snap points from rendered canvas (scale = 2x for retina)
        setTimeout(() => {
          try {
            snapEngine.detectFromCanvas(canvas, 2); // Pass scale factor
            console.log('Snap points detected:', snapEngine.count);
          } catch (err) {
            console.warn('Could not detect snap points:', err);
          }
        }, 100);
      } catch (err: any) {
        if (!cancelled && !err.message?.includes('cancelled')) {
          console.error('Error rendering page:', err);
        }
      }
    };

    renderPage();

    return () => {
      cancelled = true;
      if (renderTask) {
        renderTask.cancel();
      }
    };
  }, [pdfDoc, project?.currentPage, zoom]);

  // Pan handling
  const [isPanning, setIsPanning] = useState(false);
  const [panStart, setPanStart] = useState({ x: 0, y: 0 });

  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    if (activeTool === 'pan' || e.button === 1) {
      setIsPanning(true);
      setPanStart({ x: e.clientX - panOffset.x, y: e.clientY - panOffset.y });
    }
  }, [activeTool, panOffset]);

  const handleMouseMove = useCallback((e: React.MouseEvent) => {
    if (isPanning) {
      setPanOffset({
        x: e.clientX - panStart.x,
        y: e.clientY - panStart.y
      });
    }
  }, [isPanning, panStart, setPanOffset]);

  const handleMouseUp = useCallback(() => {
    setIsPanning(false);
  }, []);

  const { setZoom } = useProjectStore();
  const handleWheel = useCallback((e: React.WheelEvent) => {
    // Always zoom on scroll wheel (no Ctrl required)
    e.preventDefault();
    const delta = e.deltaY > 0 ? -0.1 : 0.1;
    setZoom(zoom + delta);
  }, [zoom, setZoom]);

  if (isLoading) {
    return (
      <div className="absolute inset-0 flex items-center justify-center"
           style={{ background: '#0a141a' }}>
        <div className="text-center">
          <div className="text-4xl mb-4 animate-pulse">📄</div>
          <div style={{ color: '#8b7355' }}>Loading PDF...</div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="absolute inset-0 flex items-center justify-center"
           style={{ background: '#0a141a' }}>
        <div className="text-center p-8 rounded-lg" style={{ background: '#1a2f3d', border: '1px solid #a65d37' }}>
          <div className="text-4xl mb-4">⚠️</div>
          <div style={{ color: '#a65d37' }} className="mb-2">Failed to load PDF</div>
          <div style={{ color: '#8b7355' }} className="text-sm max-w-md">{error}</div>
        </div>
      </div>
    );
  }

  if (!pdfDoc) {
    return (
      <div className="absolute inset-0 flex items-center justify-center"
           style={{ background: '#0a141a' }}>
        <div style={{ color: '#4a6a7a' }}>No document loaded</div>
      </div>
    );
  }

  return (
    <div 
      ref={containerRef}
      className="absolute inset-0 overflow-hidden"
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
      onWheel={handleWheel}
      style={{ 
        cursor: activeTool === 'pan' ? (isPanning ? 'grabbing' : 'grab') : 'crosshair',
        background: '#0a141a'
      }}
    >
      <div 
        className="absolute"
        style={{
          transform: `translate(${panOffset.x}px, ${panOffset.y}px)`,
          left: '50%',
          top: '50%',
          marginLeft: -pageSize.width / 2,
          marginTop: -pageSize.height / 2
        }}
      >
        {/* PDF Canvas */}
        <canvas 
          ref={canvasRef} 
          style={{ 
            boxShadow: '0 10px 40px rgba(0,0,0,0.5)',
            background: 'white'
          }}
        />

        {/* Measurement Overlay */}
        {pageSize.width > 0 && (
          <MeasurementCanvas 
            width={pageSize.width} 
            height={pageSize.height}
            panOffset={panOffset}
          />
        )}
      </div>
    </div>
  );
}

import type { Point } from '../types';

/**
 * Calculate distance between two points in pixels
 */
export function pixelDistance(p1: Point, p2: Point): number {
  return Math.sqrt(Math.pow(p2.x - p1.x, 2) + Math.pow(p2.y - p1.y, 2));
}

/**
 * Calculate real-world distance given scale (pixels per foot)
 */
export function realDistance(p1: Point, p2: Point, scale: number): number {
  return pixelDistance(p1, p2) / scale;
}

/**
 * Calculate polygon area in square pixels using Shoelace formula
 */
export function polygonAreaPixels(points: Point[]): number {
  if (points.length < 3) return 0;

  let area = 0;
  const n = points.length;

  for (let i = 0; i < n; i++) {
    const j = (i + 1) % n;
    area += points[i].x * points[j].y;
    area -= points[j].x * points[i].y;
  }

  return Math.abs(area) / 2;
}

/**
 * Calculate polygon area in square feet
 */
export function polygonAreaFeet(points: Point[], scale: number): number {
  const pixelArea = polygonAreaPixels(points);
  return pixelArea / (scale * scale);
}

/**
 * Calculate polygon perimeter in pixels (closed loop)
 */
export function polygonPerimeterPixels(points: Point[]): number {
  if (points.length < 2) return 0;

  let perimeter = 0;
  for (let i = 0; i < points.length; i++) {
    const j = (i + 1) % points.length;
    perimeter += pixelDistance(points[i], points[j]);
  }

  return perimeter;
}

/**
 * Calculate polygon perimeter in feet (closed loop)
 */
export function polygonPerimeterFeet(points: Point[], scale: number): number {
  return polygonPerimeterPixels(points) / scale;
}

/**
 * Calculate polyline length in pixels (open, doesn't close)
 */
export function polylineLength(points: Point[]): number {
  if (points.length < 2) return 0;

  let length = 0;
  for (let i = 0; i < points.length - 1; i++) {
    length += pixelDistance(points[i], points[i + 1]);
  }

  return length;
}

/**
 * Calculate polyline length in feet (open, doesn't close)
 */
export function polylineLengthFeet(points: Point[], scale: number): number {
  return polylineLength(points) / scale;
}

/**
 * Get centroid of a polygon
 */
export function polygonCentroid(points: Point[]): Point {
  if (points.length === 0) return { x: 0, y: 0 };

  const sum = points.reduce(
    (acc, p) => ({ x: acc.x + p.x, y: acc.y + p.y }),
    { x: 0, y: 0 }
  );

  return {
    x: sum.x / points.length,
    y: sum.y / points.length
  };
}

/**
 * Convert decimal feet to feet-inches string (e.g., 8'-3 1/4")
 */
export function decimalFeetToFeetInches(decimalFeet: number): string {
  const feet = Math.floor(decimalFeet);
  const remainingInches = (decimalFeet - feet) * 12;
  const wholeInches = Math.floor(remainingInches);
  const fraction = remainingInches - wholeInches;

  // Convert fraction to nearest 1/16th
  const sixteenths = Math.round(fraction * 16);

  let fractionStr = '';
  if (sixteenths > 0 && sixteenths < 16) {
    // Simplify the fraction
    const gcd = (a: number, b: number): number => b === 0 ? a : gcd(b, a % b);
    const divisor = gcd(sixteenths, 16);
    const num = sixteenths / divisor;
    const den = 16 / divisor;
    fractionStr = ` ${num}/${den}`;
  }

  if (feet === 0) {
    return `${wholeInches}${fractionStr}"`;
  } else if (wholeInches === 0 && sixteenths === 0) {
    return `${feet}'-0"`;
  } else {
    return `${feet}'-${wholeInches}${fractionStr}"`;
  }
}

/**
 * Format a measurement value for display
 */
export function formatMeasurement(value: number, unit: string): string {
  if (unit === 'EA') {
    return `${Math.round(value)} EA`;
  }

  // For linear feet, display in feet-inches format
  if (unit === 'LF') {
    return decimalFeetToFeetInches(value);
  }

  // For SF, show appropriate decimal precision
  if (value >= 100) {
    return `${Math.round(value).toLocaleString()} ${unit}`;
  } else if (value >= 10) {
    return `${value.toFixed(1)} ${unit}`;
  } else {
    return `${value.toFixed(2)} ${unit}`;
  }
}

/**
 * Convert between units
 */
export function convertToFeet(value: number, fromUnit: 'ft' | 'in' | 'm'): number {
  switch (fromUnit) {
    case 'ft': return value;
    case 'in': return value / 12;
    case 'm': return value * 3.28084;
  }
}

/**
 * Check if a point is inside a polygon
 */
export function pointInPolygon(point: Point, polygon: Point[]): boolean {
  let inside = false;
  const n = polygon.length;

  for (let i = 0, j = n - 1; i < n; j = i++) {
    const xi = polygon[i].x, yi = polygon[i].y;
    const xj = polygon[j].x, yj = polygon[j].y;

    if (((yi > point.y) !== (yj > point.y)) &&
        (point.x < (xj - xi) * (point.y - yi) / (yj - yi) + xi)) {
      inside = !inside;
    }
  }

  return inside;
}

export type MeasurementType = 'linear' | 'area' | 'count' | 'perimeter';

export interface Point {
  x: number;
  y: number;
}

export interface Measurement {
  id: string;
  type: MeasurementType;
  name: string;
  points: Point[];          // For linear: 2 points, for area: polygon points
  value: number;            // Calculated value (LF, SF, or count)
  unit: 'LF' | 'SF' | 'EA';
  color: string;
  pageNumber: number;
  visible?: boolean;        // Individual visibility toggle (default true)
  notes?: string;           // User notes/comments
  deductions?: string[];    // IDs of measurements to subtract from this one
  jocLineItem?: JOCLineItem;
  createdAt: Date;
}

export interface JOCLineItem {
  code: string;             // e.g., "09 91 23.13 1000"
  description: string;      // e.g., "PAINTING - INTERIOR - WALLS"
  unit: 'LF' | 'SF' | 'EA' | 'LS';
  unitPrice: number;
  multipliers?: Multiplier[];
}

export interface Multiplier {
  name: string;             // e.g., "Occupied Facility"
  factor: number;           // e.g., 1.15
}

export interface MeasurementGroup {
  id: string;
  name: string;
  color: string;
  measurementIds: string[];
  collapsed: boolean;
  visible?: boolean;        // Group visibility toggle (default true)
  parentId: string | null;  // null = top-level, otherwise child of parent group
}

export type SheetType = 'floor-plan' | 'elevation' | 'section' | 'detail' | 'schedule' | 'other';

export interface Space {
  id: string;
  name: string;              // e.g., "Corridor 101", "Office 202"
  points: Point[];           // Polygon defining the space boundary
  area: number;              // Calculated SF
  perimeter: number;         // Calculated LF
  color: string;
  pageNumber: number;
  level?: number;            // Building level (inherited from sheet or manual)
  visible?: boolean;
}

export interface Sheet {
  pageNumber: number;       // PDF page (1-indexed)
  name: string;             // e.g., "A-101" or "1st Floor Plan"
  description?: string;     // e.g., "First Floor - East Wing"
  type: SheetType;
  level?: number;           // Building level/floor (1, 2, 3, B1 for basement = -1)
  scale?: string;           // Drawing scale as shown (e.g., "1/4\" = 1'-0\"")
}

export interface Project {
  id: string;
  name: string;
  pdfFile?: File;
  pdfUrl?: string;
  scale: number | null;     // pixels per foot for current page (null = not calibrated)
  scales: Record<number, number>;  // per-page scales: { pageNum: pixelsPerFoot }
  scaleUnit: 'ft' | 'in' | 'm';
  sheets: Sheet[];          // Sheet metadata for each page
  spaces: Space[];          // Defined spaces/rooms
  currentPage: number;
  totalPages: number;
  measurements: Measurement[];
  groups: MeasurementGroup[];
  createdAt: Date;
  updatedAt: Date;
}

export type Tool = 'select' | 'pan' | 'calibrate' | 'linear' | 'perimeter' | 'area' | 'count' | 'space';

