// Shared constants across the application

// 15 distinct measurement colors
export const MEASUREMENT_COLORS = [
  '#ef4444', // Red
  '#f97316', // Orange
  '#facc15', // Yellow
  '#84cc16', // Lime
  '#22c55e', // Green
  '#14b8a6', // Teal
  '#06b6d4', // Cyan
  '#3b82f6', // Blue
  '#6366f1', // Indigo
  '#8b5cf6', // Violet
  '#a855f7', // Purple
  '#d946ef', // Fuchsia
  '#ec4899', // Pink
  '#f43f5e', // Rose
  '#78716c', // Stone (neutral)
];

// History limit for undo/redo
export const MAX_HISTORY = 50;

// Auto-save interval (ms)
export const AUTOSAVE_INTERVAL = 30000;

// Separator marker for multi-polygon/polyline storage
export const SEPARATOR_POINT = { x: -99999, y: -99999 };

// Project save/load/export utilities
import toast from 'react-hot-toast';
import type { Project, Measurement, MeasurementGroup } from '../types';
import { formatMeasurement } from './geometry';

/**
 * Export measurements to CSV
 */
export function exportToCSV(
  measurements: Measurement[], 
  groups: MeasurementGroup[], 
  projectName: string
): void {
  const headers = ['Group', 'Name', 'Type', 'Value', 'Unit', 'Page'];

  const getGroupName = (m: Measurement) => {
    const group = groups.find(g => g.measurementIds.includes(m.id));
    return group?.name || 'Ungrouped';
  };

  const rows = measurements.map(m => [
    getGroupName(m),
    m.name,
    m.type,
    m.value.toFixed(2),
    m.unit,
    m.pageNumber
  ]);

  const csv = [
    headers.join(','),
    ...rows.map(r => r.map(cell => `"${cell}"`).join(','))
  ].join('\n');

  downloadFile(csv, `${projectName}-takeoff.csv`, 'text/csv');
}

/**
 * Save project to .pilar file
 */
export function saveProject(project: Project): void {
  const saveData = {
    version: '1.0',
    savedAt: new Date().toISOString(),
    project: {
      ...project,
      pdfFile: undefined,
      pdfUrl: undefined,
      pdfName: project.name
    }
  };

  const json = JSON.stringify(saveData, null, 2);
  downloadFile(json, `${project.name}.pilar`, 'application/json');

  // Also save to localStorage as backup
  try {
    localStorage.setItem('pilar-autosave', json);
    toast.success(`Saved: ${project.name}.pilar`);
  } catch {
    toast.success(`Saved to file (localStorage full)`);
  }
}

/**
 * Load project from .pilar file
 * Returns the project data or null if invalid
 */
export function loadProjectFile(
  file: File, 
  onSuccess: (project: Project) => void
): void {
  const reader = new FileReader();

  reader.onload = (e) => {
    try {
      const json = e.target?.result as string;
      const data = JSON.parse(json);

      if (!data.project) {
        toast.error('Invalid project file');
        return;
      }

      const project: Project = {
        ...data.project,
        pdfFile: undefined,
        pdfUrl: undefined,
        createdAt: new Date(data.project.createdAt),
        updatedAt: new Date()
      };

      // Show restore dialog
      toast((t) => (
        <div>
          <p className="font-medium mb-2">Project loaded: {project.name}</p>
          <p className="text-sm opacity-80 mb-3">
            {project.measurements.length} measurements, {Object.keys(project.scales || {}).length} calibrated pages
          </p>
          <p className="text-xs opacity-60">
            Re-load the PDF to continue editing
          </p>
          <button
            onClick={() => {
              toast.dismiss(t.id);
              document.getElementById('reload-pdf-input')?.click();
            }}
            className="mt-2 px-3 py-1 rounded text-sm"
            style={{ background: '#c9a227', color: '#0f1c24' }}
          >
            Load PDF
          </button>
        </div>
      ), { duration: 10000 });

      onSuccess(project);
    } catch (err) {
      toast.error('Failed to parse project file');
      console.error(err);
    }
  };

  reader.readAsText(file);
}

/**
 * Check for autosaved project in localStorage
 */
export function getAutosaveData(): { project: Project; savedAt: string } | null {
  try {
    const saved = localStorage.getItem('pilar-autosave');
    if (!saved) return null;

    const data = JSON.parse(saved);
    if (!data.project?.measurements?.length) return null;

    return {
      project: {
        ...data.project,
        createdAt: new Date(data.project.createdAt),
        updatedAt: new Date()
      },
      savedAt: data.savedAt
    };
  } catch {
    return null;
  }
}

/**
 * Clear autosave data
 */
export function clearAutosave(): void {
  localStorage.removeItem('pilar-autosave');
}

/**
 * Save to autosave slot
 */
export function autosave(project: Project): void {
  try {
    const saveData = {
      version: '1.0',
      savedAt: new Date().toISOString(),
      project: {
        ...project,
        pdfFile: undefined,
        pdfUrl: undefined
      }
    };
    localStorage.setItem('pilar-autosave', JSON.stringify(saveData));
  } catch {
    // localStorage might be full, ignore
  }
}

// Helper
function downloadFile(content: string, filename: string, mimeType: string): void {
  const blob = new Blob([content], { type: mimeType });
  const url = URL.createObjectURL(blob);
