// Project Library - manages saved projects using IndexedDB for larger storage
import type { Project } from '../types';

const DB_NAME = 'pilar-studio';
const DB_VERSION = 1;
const STORE_NAME = 'projects';

export interface ProjectMeta {
  id: string;
  name: string;
  createdAt: Date;
  updatedAt: Date;
  measurementCount: number;
  pageCount: number;
  thumbnail?: string; // Base64 data URL
}

// Initialize IndexedDB
function openDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve(request.result);

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        const store = db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        store.createIndex('updatedAt', 'updatedAt', { unique: false });
        store.createIndex('name', 'name', { unique: false });
      }
    };
  });
}

/**
 * Save a project to the library
 */
export async function saveProjectToLibrary(project: Project, thumbnail?: string): Promise<void> {
  const db = await openDB();

  // Create a storable version (no File/Blob objects)
  const storable = {
    ...project,
    pdfFile: undefined,
    pdfUrl: undefined,
    thumbnail,
    createdAt: project.createdAt.toISOString(),
    updatedAt: new Date().toISOString()
  };

  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    const request = store.put(storable);

    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve();
  });
}

/**
 * Get all projects (metadata only for listing)
 */
export async function listProjects(): Promise<ProjectMeta[]> {
  const db = await openDB();

  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onerror = () => reject(request.error);
    request.onsuccess = () => {
      const projects = request.result.map((p: any) => ({
        id: p.id,
        name: p.name,
        createdAt: new Date(p.createdAt),
        updatedAt: new Date(p.updatedAt),
        measurementCount: p.measurements?.length || 0,
        pageCount: p.totalPages || 0,
        thumbnail: p.thumbnail
      }));

      // Sort by most recently updated
      projects.sort((a, b) => b.updatedAt.getTime() - a.updatedAt.getTime());
      resolve(projects);
    };
  });
}

/**
 * Load a full project by ID
 */
export async function loadProjectFromLibrary(id: string): Promise<Project | null> {
  const db = await openDB();

  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    const request = store.get(id);

    request.onerror = () => reject(request.error);
    request.onsuccess = () => {
      const data = request.result;
      if (!data) {
        resolve(null);
        return;
      }

      // Restore Date objects
      const project: Project = {
        ...data,
        createdAt: new Date(data.createdAt),
        updatedAt: new Date(data.updatedAt),
        pdfFile: undefined,
        pdfUrl: undefined
      };

      resolve(project);
    };
  });
}

/**
 * Delete a project from the library
 */
export async function deleteProjectFromLibrary(id: string): Promise<void> {
  const db = await openDB();

  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    const request = store.delete(id);

    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve();
  });
}

/**
 * Rename a project
 */
export async function renameProject(id: string, newName: string): Promise<void> {
  const project = await loadProjectFromLibrary(id);
  if (!project) throw new Error('Project not found');

  project.name = newName;
  project.updatedAt = new Date();
  await saveProjectToLibrary(project);
}

/**
 * Duplicate a project
 */
export async function duplicateProject(id: string): Promise<string> {
  const project = await loadProjectFromLibrary(id);
  if (!project) throw new Error('Project not found');

  const newId = Math.random().toString(36).substring(2, 15);
  const duplicate: Project = {
    ...project,
    id: newId,
    name: `${project.name} (Copy)`,
    createdAt: new Date(),
    updatedAt: new Date()
  };

  await saveProjectToLibrary(duplicate);
  return newId;
}

/**
 * Search projects by name
 */
export async function searchProjects(query: string): Promise<ProjectMeta[]> {
  const all = await listProjects();
  const q = query.toLowerCase();
  return all.filter(p => p.name.toLowerCase().includes(q));
}

/**
 * Generate a thumbnail from the first page of a PDF
 * Call this after rendering the first page
 */
export function generateThumbnail(canvas: HTMLCanvasElement, maxWidth = 200): string {
  const scale = maxWidth / canvas.width;
  const thumbCanvas = document.createElement('canvas');
  thumbCanvas.width = maxWidth;
  thumbCanvas.height = canvas.height * scale;

  const ctx = thumbCanvas.getContext('2d')!;
  ctx.drawImage(canvas, 0, 0, thumbCanvas.width, thumbCanvas.height);

  return thumbCanvas.toDataURL('image/jpeg', 0.7);
}

import { useState, useEffect } from 'react';
import toast from 'react-hot-toast';
import { 
  listProjects, 
  deleteProjectFromLibrary, 
  renameProject,
  duplicateProject,
  type ProjectMeta 
} from '../utils/projectLibrary';

interface ProjectLibraryProps {
  onNewProject: () => void;
  onOpenProject: (id: string) => void;
}

export function ProjectLibrary({ onNewProject, onOpenProject }: ProjectLibraryProps) {
  const [projects, setProjects] = useState<ProjectMeta[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const [menuOpenId, setMenuOpenId] = useState<string | null>(null);

  // Load projects on mount
  useEffect(() => {
    loadProjects();
  }, []);

  const loadProjects = async () => {
    setLoading(true);
    try {
      const list = await listProjects();
      setProjects(list);
    } catch (err) {
      console.error('Failed to load projects:', err);
      toast.error('Failed to load projects');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string, name: string) => {
    if (!confirm(`Delete "${name}"? This cannot be undone.`)) return;

    try {
      await deleteProjectFromLibrary(id);
      setProjects(prev => prev.filter(p => p.id !== id));
      toast.success('Project deleted');
    } catch (err) {
      toast.error('Failed to delete project');
    }
  };

  const handleRename = async (id: string) => {
    if (!editName.trim()) return;

    try {
      await renameProject(id, editName.trim());
      setProjects(prev => prev.map(p => 
        p.id === id ? { ...p, name: editName.trim() } : p
      ));
      setEditingId(null);
      toast.success('Renamed');
    } catch (err) {
      toast.error('Failed to rename');
    }
  };

  const handleDuplicate = async (id: string) => {
    try {
      const newId = await duplicateProject(id);
      await loadProjects();
      toast.success('Project duplicated');
    } catch (err) {
      toast.error('Failed to duplicate');
    }
  };

  const filteredProjects = searchQuery
    ? projects.filter(p => p.name.toLowerCase().includes(searchQuery.toLowerCase()))
    : projects;

  const formatDate = (date: Date) => {
    const now = new Date();
    const diff = now.getTime() - date.getTime();
    const days = Math.floor(diff / (1000 * 60 * 60 * 24));

    if (days === 0) return 'Today';
    if (days === 1) return 'Yesterday';
    if (days < 7) return `${days} days ago`;
    return date.toLocaleDateString();
  };

  return (
    <div className="min-h-screen flex flex-col" style={{ background: '#0a141a' }}>
      {/* Header */}
      <header className="px-8 py-6" style={{ 
        background: 'linear-gradient(180deg, #152a36 0%, #0a141a 100%)',
        borderBottom: '1px solid #1e3a4c'
      }}>
        <div className="max-w-6xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-4">
            <span className="text-4xl">🚤</span>
            <div>
              <h1 className="text-2xl font-semibold" 
                  style={{ fontFamily: 'Playfair Display, serif', color: '#c9a227' }}>
                Pilar Studio
              </h1>
              <p className="text-sm" style={{ color: '#6b7280' }}>
                Construction Takeoff & JOC Integration
              </p>
            </div>
          </div>

          <button
            onClick={onNewProject}
            className="px-6 py-3 rounded-lg text-base font-medium transition-all"
            style={{ 
              background: 'linear-gradient(135deg, #c9a227 0%, #a88620 100%)',
              color: '#0f1c24',
              boxShadow: '0 4px 12px rgba(201, 162, 39, 0.3)'
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.transform = 'translateY(-2px)';
              e.currentTarget.style.boxShadow = '0 6px 20px rgba(201, 162, 39, 0.4)';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.transform = 'translateY(0)';
              e.currentTarget.style.boxShadow = '0 4px 12px rgba(201, 162, 39, 0.3)';
            }}
          >
            + New Project
          </button>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 px-8 py-8">
        <div className="max-w-6xl mx-auto">
          {/* Search Bar */}
          <div className="mb-8">
            <div className="relative max-w-md">
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search projects..."
                className="w-full px-4 py-3 pl-12 rounded-lg text-base"
                style={{ 
                  background: '#152a36',
                  color: '#e8f1f5',
                  border: '1px solid #2d4a5e'
                }}
              />
              <span className="absolute left-4 top-1/2 -translate-y-1/2 text-lg opacity-50">
                🔍
              </span>
            </div>
          </div>

          {/* Project Grid */}
          {loading ? (
            <div className="flex items-center justify-center py-20">
              <div className="text-center">
                <div className="text-4xl mb-4 animate-pulse">📁</div>
                <p style={{ color: '#6b7280' }}>Loading projects...</p>
              </div>
            </div>
          ) : filteredProjects.length === 0 ? (
            <div className="flex items-center justify-center py-20">
              <div className="text-center">
                <div className="text-6xl mb-6 opacity-30">📐</div>
                <h2 className="text-xl font-medium mb-2" style={{ color: '#e8f1f5' }}>
                  {searchQuery ? 'No projects found' : 'No projects yet'}
                </h2>
                <p className="mb-6" style={{ color: '#6b7280' }}>
                  {searchQuery 
                    ? 'Try a different search term'
                    : 'Create your first project to get started'}
                </p>
                {!searchQuery && (
                  <button
                    onClick={onNewProject}
                    className="px-6 py-3 rounded-lg text-base font-medium"
                    style={{ 
                      background: '#1e3a4c',
                      color: '#c9a227',
                      border: '1px solid #3d5a6e'
                    }}
                  >
                    + New Project
                  </button>
                )}
              </div>
            </div>
          ) : (
            <>
              <div className="mb-4">
                <span className="text-sm" style={{ color: '#6b7280' }}>
                  {filteredProjects.length} project{filteredProjects.length !== 1 ? 's' : ''}
                </span>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {filteredProjects.map(project => (
                  <div
                    key={project.id}
                    className="rounded-xl overflow-hidden transition-all duration-200 cursor-pointer group relative"
                    style={{ 
                      background: '#152a36',
                      border: '1px solid #2d4a5e'
                    }}
                    onMouseEnter={(e) => {
                      e.currentTarget.style.borderColor = '#4a6a7a';
                      e.currentTarget.style.transform = 'translateY(-4px)';
                      e.currentTarget.style.boxShadow = '0 8px 24px rgba(0,0,0,0.3)';
                    }}
                    onMouseLeave={(e) => {
                      e.currentTarget.style.borderColor = '#2d4a5e';
                      e.currentTarget.style.transform = 'translateY(0)';
                      e.currentTarget.style.boxShadow = 'none';
                    }}
                    onClick={() => {
                      if (!editingId && !menuOpenId) {
                        onOpenProject(project.id);
                      }
                    }}
                  >
                    {/* Thumbnail */}
                    <div 
                      className="h-36 flex items-center justify-center"
                      style={{ background: '#0a141a' }}
                    >
                      {project.thumbnail ? (
                        <img 
                          src={project.thumbnail} 
                          alt={project.name}
                          className="w-full h-full object-contain"
                        />
                      ) : (
                        <span className="text-5xl opacity-20">📄</span>
                      )}
                    </div>

                    {/* Info */}
                    <div className="p-4">
                      {editingId === project.id ? (
                        <input
                          type="text"
                          value={editName}
                          onChange={(e) => setEditName(e.target.value)}
                          onBlur={() => handleRename(project.id)}
                          onKeyDown={(e) => {
                            if (e.key === 'Enter') handleRename(project.id);
                            if (e.key === 'Escape') setEditingId(null);
                          }}
                          className="w-full px-2 py-1 rounded text-base font-medium"
                          style={{ 
                            background: '#0a141a',
                            color: '#e8f1f5',
                            border: '1px solid #4a6a7a'
                          }}
                          autoFocus
                          onClick={(e) => e.stopPropagation()}
                        />
                      ) : (
                        <h3 className="text-base font-medium truncate mb-2" 
                            style={{ color: '#e8f1f5' }}>
                          {project.name}
                        </h3>
                      )}

                      <div className="flex items-center gap-4 text-sm" style={{ color: '#6b7280' }}>
                        <span>{project.measurementCount} items</span>
                        <span>•</span>
                        <span>{project.pageCount} pages</span>
                      </div>

                      <div className="flex items-center justify-between mt-3">
                        <span className="text-xs" style={{ color: '#4a6a7a' }}>
                          {formatDate(project.updatedAt)}
                        </span>

                        {/* Action Menu */}
                        <div className="relative">
                          <button
                            onClick={(e) => {
                              e.stopPropagation();
                              setMenuOpenId(menuOpenId === project.id ? null : project.id);
                            }}
                            className="p-2 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity"
                            style={{ background: '#0a141a' }}
                          >
                            <span style={{ color: '#6b7280' }}>⋯</span>
                          </button>

                          {menuOpenId === project.id && (
                            <div 
                              className="absolute right-0 bottom-full mb-2 py-2 rounded-lg shadow-xl z-10 min-w-32"
                              style={{ 
                                background: '#1e3a4c',
                                border: '1px solid #3d5a6e'
                              }}
                              onClick={(e) => e.stopPropagation()}
                            >
                              <button
                                onClick={() => {
                                  setEditingId(project.id);
                                  setEditName(project.name);
                                  setMenuOpenId(null);
                                }}
                                className="w-full px-4 py-2 text-left text-sm hover:bg-black/20"
                                style={{ color: '#e8f1f5' }}
                              >
                                ✏️ Rename
                              </button>
                              <button
                                onClick={() => {
                                  handleDuplicate(project.id);
                                  setMenuOpenId(null);
                                }}
                                className="w-full px-4 py-2 text-left text-sm hover:bg-black/20"
                                style={{ color: '#e8f1f5' }}
                              >
                                📋 Duplicate
                              </button>
                              <button
                                onClick={() => {
                                  handleDelete(project.id, project.name);
                                  setMenuOpenId(null);
                                }}
                                className="w-full px-4 py-2 text-left text-sm hover:bg-black/20"
                                style={{ color: '#ef4444' }}
                              >
                                🗑️ Delete
                              </button>
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </>
          )}
        </div>
      </main>

      {/* Footer */}
      <footer className="px-8 py-4 text-center" style={{ borderTop: '1px solid #1e3a4c' }}>
        <p className="text-sm" style={{ color: '#4a6a7a' }}>
          Pilar Studio • Built for JOC Estimators
        </p>
      </footer>

      {/* Click outside to close menu */}
      {menuOpenId && (
        <div 
          className="fixed inset-0 z-0" 
          onClick={() => setMenuOpenId(null)}
        />
      )}
    </div>
  );
}

