import { useCallback, useState, useEffect, useRef } from 'react';
import { Toaster } from 'react-hot-toast';
import toast from 'react-hot-toast';
import * as pdfjsLib from 'pdfjs-dist';
import { useProjectStore } from './stores/projectStore';
import { Toolbar } from './components/Toolbar';
import { PDFViewer } from './components/PDFViewer';
import { MeasurementPanel } from './components/MeasurementPanel';
import { DropZone } from './components/DropZone';
import { CalibrationDialog } from './components/CalibrationDialog';
import { SheetSetupDialog } from './components/SheetSetupDialog';
import { ProjectLibrary } from './components/ProjectLibrary';
import { autosave } from './utils/project';
import { saveProjectToLibrary, loadProjectFromLibrary, generateThumbnail } from './utils/projectLibrary';
import { AUTOSAVE_INTERVAL } from './constants';
import type { Project, Sheet } from './types';

// Set up PDF.js worker
pdfjsLib.GlobalWorkerOptions.workerSrc = new URL(
  'pdfjs-dist/build/pdf.worker.min.mjs',
  import.meta.url
).toString();

type AppView = 'library' | 'dropzone' | 'editor';

function App() {
  const { project, setProject, isCalibrating, calibrationPoints, cancelCalibration } = useProjectStore();

  // App view state
  const [view, setView] = useState<AppView>('library');
  const [pendingProjectId, setPendingProjectId] = useState<string | null>(null);

  // Sheet setup state
  const [pendingPdf, setPendingPdf] = useState<{ file: File; url: string } | null>(null);
  const [detectedSheets, setDetectedSheets] = useState<{ totalPages: number; names: string[] }>({ totalPages: 0, names: [] });
  const [showSheetSetup, setShowSheetSetup] = useState(false);

  // Thumbnail capture ref
  const thumbnailCaptured = useRef(false);

  // Handle opening a project from the library
  const handleOpenProject = useCallback(async (id: string) => {
    try {
      const loadedProject = await loadProjectFromLibrary(id);
      if (!loadedProject) {
        toast.error('Project not found');
        return;
      }

      // Store the project ID for later saves
      setPendingProjectId(id);

      // Store as pending and prompt for PDF
      (window as any).__pendingProject = loadedProject;
      toast('Load the PDF to continue working', { icon: '📂', duration: 5000 });
      setView('dropzone');
    } catch (err) {
      console.error('Failed to load project:', err);
      toast.error('Failed to load project');
    }
  }, []);

  // Handle creating a new project
  const handleNewProject = useCallback(() => {
    setPendingProjectId(null);
    setView('dropzone');
  }, []);

  // Handle going back to library
  const handleBackToLibrary = useCallback(async () => {
    if (project) {
      // Save current project to library before leaving
      try {
        // Try to capture thumbnail if we haven't yet
        const canvas = document.querySelector('canvas') as HTMLCanvasElement;
        const thumbnail = canvas ? generateThumbnail(canvas) : undefined;

        await saveProjectToLibrary(project, thumbnail);
        toast.success('Project saved');
      } catch (err) {
        console.error('Failed to save:', err);
      }
    }

    // Clear state
    setProject(null as any);
    setPendingProjectId(null);
    thumbnailCaptured.current = false;
    setView('library');
  }, [project, setProject]);

  const handleFileLoad = useCallback(async (file: File) => {
    const url = URL.createObjectURL(file);

    // Check if there's a pending project to merge with
    const pendingProject = (window as any).__pendingProject as Project | undefined;

    if (pendingProject) {
      // Merge the loaded project data with the new PDF
      const mergedProject: Project = {
        ...pendingProject,
        pdfFile: file,
        pdfUrl: url,
        updatedAt: new Date()
      };
      setProject(mergedProject);
      delete (window as any).__pendingProject;
      thumbnailCaptured.current = false;
      setView('editor');
      toast.success(`Restored ${pendingProject.measurements.length} measurements`);
    } else {
      // New project - detect sheets first
      try {
        const pdf = await pdfjsLib.getDocument(url).promise;
        const totalPages = pdf.numPages;

        // Try to get page labels from PDF
        const pageLabels = await pdf.getPageLabels();
        const names: string[] = [];

        for (let i = 1; i <= totalPages; i++) {
          if (pageLabels && pageLabels[i - 1]) {
            names.push(pageLabels[i - 1]);
          } else {
            names.push(`Sheet ${i}`);
          }
        }

        setPendingPdf({ file, url });
        setDetectedSheets({ totalPages, names });
        setShowSheetSetup(true);
      } catch (err) {
        console.error('Error loading PDF:', err);
        toast.error('Failed to load PDF');
      }
    }
  }, [setProject]);

  const handleSheetSetupConfirm = useCallback((sheets: Sheet[]) => {
    if (!pendingPdf) return;

    const newProject: Project = {
      id: pendingProjectId || Math.random().toString(36).substring(2, 15),
      name: pendingPdf.file.name.replace('.pdf', ''),
      pdfFile: pendingPdf.file,
      pdfUrl: pendingPdf.url,
      scale: null,
      scales: {},
      scaleUnit: 'ft',
      sheets,
      spaces: [],
      currentPage: 1,
      totalPages: sheets.length,
      measurements: [],
      groups: [],
      createdAt: new Date(),
      updatedAt: new Date()
    };

    setProject(newProject);
    setShowSheetSetup(false);
    setPendingPdf(null);
    thumbnailCaptured.current = false;
    setView('editor');
    toast.success(`${sheets.length} sheets configured`);
  }, [pendingPdf, pendingProjectId, setProject]);

  const handleSheetSetupCancel = useCallback(() => {
    if (pendingPdf) {
      URL.revokeObjectURL(pendingPdf.url);
    }
    setShowSheetSetup(false);
    setPendingPdf(null);
    setView('library');
  }, [pendingPdf]);

  // Auto-save to library periodically
  useEffect(() => {
    if (!project || view !== 'editor') return;

    const interval = setInterval(async () => {
      try {
        // Capture thumbnail on first save
        let thumbnail: string | undefined;
        if (!thumbnailCaptured.current) {
          const canvas = document.querySelector('canvas') as HTMLCanvasElement;
          if (canvas) {
            thumbnail = generateThumbnail(canvas);
            thumbnailCaptured.current = true;
          }
        }

        await saveProjectToLibrary(project, thumbnail);
        // Also keep localStorage backup
        autosave(project);
      } catch (err) {
        console.error('Auto-save failed:', err);
      }
    }, AUTOSAVE_INTERVAL);

    return () => clearInterval(interval);
  }, [project, view]);

  // Calibration dialog state
  const [useDirectScale, setUseDirectScale] = useState(true);
  const shouldShowCalibrationDialog = isCalibrating && (useDirectScale || calibrationPoints.length === 2);

  // ==================== RENDER ====================

  // Library View
  if (view === 'library') {
    return (
      <>
        <ProjectLibrary 
          onNewProject={handleNewProject}
          onOpenProject={handleOpenProject}
        />
        <Toaster 
          position="bottom-right"
          toastOptions={{
            style: {
              background: '#2d4a5e',
              color: '#e8f1f5',
              border: '1px solid #4a6a7a',
              fontFamily: 'Source Sans 3, sans-serif'
            }
          }}
        />
      </>
    );
  }

  // DropZone View (creating new or loading existing)
  if (view === 'dropzone' || !project) {
    return (
      <>
        <DropZone 
          onFileLoad={handleFileLoad} 
          onBack={() => setView('library')}
          showBackButton={true}
        />

        {/* Sheet Setup Dialog */}
        {showSheetSetup && (
          <SheetSetupDialog
            totalPages={detectedSheets.totalPages}
            detectedNames={detectedSheets.names}
            onConfirm={handleSheetSetupConfirm}
            onCancel={handleSheetSetupCancel}
          />
        )}

        <Toaster 
          position="bottom-right"
          toastOptions={{
            style: {
              background: '#2d4a5e',
              color: '#e8f1f5',
              border: '1px solid #4a6a7a',
              fontFamily: 'Source Sans 3, sans-serif'
            }
          }}
        />
      </>
    );
  }

  // Editor View
  const currentSheet = project.sheets?.find(s => s.pageNumber === project.currentPage);

  return (
    <div className="min-h-screen flex flex-col" style={{ background: '#1a2f3d' }}>
      {/* Header */}
      <header className="px-4 py-3 flex items-center justify-between"
              style={{ 
                background: 'linear-gradient(90deg, #0f1c24 0%, #1a2f3d 50%, #0f1c24 100%)',
                borderBottom: '1px solid #2d4a5e'
              }}>
        <div className="flex items-center gap-4">
          {/* Back to Library Button */}
          <button
            onClick={handleBackToLibrary}
            className="p-2 rounded-lg transition-all"
            style={{ color: '#6b7280' }}
            onMouseEnter={(e) => {
              e.currentTarget.style.background = '#1e3a4c';
              e.currentTarget.style.color = '#e8f1f5';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.background = 'transparent';
              e.currentTarget.style.color = '#6b7280';
            }}
            title="Back to Project Library"
          >
            ← 📁
          </button>

          <span className="text-3xl">🚤</span>
          <div>
            <h1 className="text-xl font-semibold" 
                style={{ fontFamily: 'Playfair Display, serif', color: '#c9a227' }}>
              Pilar Studio
            </h1>
            <p className="text-xs opacity-60" style={{ color: '#e8f1f5' }}>
              {project.name}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-4">
          {/* Current sheet info */}
          {currentSheet && (
            <span className="text-sm px-3 py-1 rounded"
                  style={{ background: '#1e3a4c', color: '#e8f1f5', border: '1px solid #2d4a5e' }}>
              📄 {currentSheet.name}
              {currentSheet.level !== undefined && (
                <span style={{ color: '#8b7355' }}> (Level {currentSheet.level})</span>
              )}
            </span>
          )}
          {project.scale ? (
            <span className="text-sm px-3 py-1 rounded"
                  style={{ background: '#1e3a4c', color: '#7cb798', border: '1px solid #2d5a3d' }}>
              ✓ Scale set
            </span>
          ) : (
            <span className="text-sm px-3 py-1 rounded"
                  style={{ background: '#3d2a1a', color: '#c9a227', border: '1px solid #5a4020' }}>
              ⚠ Set scale to begin
            </span>
          )}
        </div>
      </header>

      {/* Toolbar */}
      <Toolbar />

      {/* Main Content */}
      <div className="flex-1 flex overflow-hidden">
        {/* PDF Viewer */}
        <div className="flex-1 relative" style={{ background: '#0a141a' }}>
          <PDFViewer />
        </div>

        {/* Measurements Panel */}
        <MeasurementPanel />
      </div>

      {/* Calibration Dialog */}
      {shouldShowCalibrationDialog && (
        <CalibrationDialog 
          onClose={cancelCalibration} 
          onModeChange={(mode) => setUseDirectScale(mode === 'direct')}
          initialMode={useDirectScale ? 'direct' : 'dimension'}
        />
      )}

      {/* Hidden input for reloading PDFs when restoring projects */}
      <input
        id="reload-pdf-input"
        type="file"
        accept=".pdf"
        className="hidden"
        onChange={(e) => {
          const file = e.target.files?.[0];
          if (file) handleFileLoad(file);
          e.target.value = '';
        }}
      />

      <Toaster 
        position="bottom-right"
        toastOptions={{
          style: {
            background: '#2d4a5e',
            color: '#e8f1f5',
            border: '1px solid #4a6a7a',
            fontFamily: 'Source Sans 3, sans-serif'
          }
        }}
      />
    </div>
  );
}

export default App;

