import { useState } from 'react';

export interface ProjectMetadata {
  name: string;
  location: string;
  owner: string;
  description?: string;
}

interface NewProjectDialogProps {
  onConfirm: (metadata: ProjectMetadata) => void;
  onCancel: () => void;
}

export function NewProjectDialog({ onConfirm, onCancel }: NewProjectDialogProps) {
  const [name, setName] = useState('');
  const [location, setLocation] = useState('');
  const [owner, setOwner] = useState('');
  const [description, setDescription] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) return;

    onConfirm({
      name: name.trim(),
      location: location.trim(),
      owner: owner.trim(),
      description: description.trim() || undefined
    });
  };

  return (
    <div 
      className="fixed inset-0 z-50 flex items-center justify-center p-4"
      style={{ background: 'rgba(0,0,0,0.7)', backdropFilter: 'blur(4px)' }}
      onClick={onCancel}
    >
      <div 
        className="w-full max-w-lg rounded-xl overflow-hidden shadow-2xl"
        style={{ 
          background: 'linear-gradient(180deg, #1e3a4c 0%, #152a36 100%)',
          border: '1px solid #3d5a6e'
        }}
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="px-6 py-4" style={{ borderBottom: '1px solid #2d4a5e' }}>
          <h2 className="text-xl font-semibold" style={{ color: '#c9a227' }}>
            New Project
          </h2>
          <p className="text-sm mt-1" style={{ color: '#6b7280' }}>
            Enter project details before uploading drawings
          </p>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} className="p-6 space-y-5">
          {/* Project Name */}
          <div>
            <label className="block text-sm font-medium mb-2" style={{ color: '#e8f1f5' }}>
              Project Name <span style={{ color: '#ef4444' }}>*</span>
            </label>
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="e.g., HHC Brooklyn Dental Suite"
              className="w-full px-4 py-3 rounded-lg text-base"
              style={{ 
                background: '#0f1c24',
                color: '#e8f1f5',
                border: '1px solid #2d4a5e'
              }}
              autoFocus
              required
            />
          </div>

          {/* Project Location */}
          <div>
            <label className="block text-sm font-medium mb-2" style={{ color: '#e8f1f5' }}>
              Project Location
            </label>
            <input
              type="text"
              value={location}
              onChange={(e) => setLocation(e.target.value)}
              placeholder="e.g., 451 Clarkson Ave, Brooklyn, NY"
              className="w-full px-4 py-3 rounded-lg text-base"
              style={{ 
                background: '#0f1c24',
                color: '#e8f1f5',
                border: '1px solid #2d4a5e'
              }}
            />
          </div>

          {/* Project Owner */}
          <div>
            <label className="block text-sm font-medium mb-2" style={{ color: '#e8f1f5' }}>
              Project Owner / Client
            </label>
            <input
              type="text"
              value={owner}
              onChange={(e) => setOwner(e.target.value)}
              placeholder="e.g., NYC Health + Hospitals"
              className="w-full px-4 py-3 rounded-lg text-base"
              style={{ 
                background: '#0f1c24',
                color: '#e8f1f5',
                border: '1px solid #2d4a5e'
              }}
            />
          </div>

          {/* Description (optional) */}
          <div>
            <label className="block text-sm font-medium mb-2" style={{ color: '#e8f1f5' }}>
              Description <span style={{ color: '#6b7280' }}>(optional)</span>
            </label>
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Notes about scope, phase, or any relevant details..."
              rows={3}
              className="w-full px-4 py-3 rounded-lg text-base resize-none"
              style={{ 
                background: '#0f1c24',
                color: '#e8f1f5',
                border: '1px solid #2d4a5e'
              }}
            />
          </div>

          {/* Actions */}
          <div className="flex justify-end gap-3 pt-2">
            <button
              type="button"
              onClick={onCancel}
              className="px-5 py-2.5 rounded-lg text-sm font-medium transition-colors"
              style={{ 
                color: '#6b7280',
                background: 'transparent',
                border: '1px solid #2d4a5e'
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.borderColor = '#4a6a7a';
                e.currentTarget.style.color = '#e8f1f5';
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.borderColor = '#2d4a5e';
                e.currentTarget.style.color = '#6b7280';
              }}
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={!name.trim()}
              className="px-5 py-2.5 rounded-lg text-sm font-medium transition-all"
              style={{ 
                background: name.trim() ? '#c9a227' : '#3d3a20',
                color: name.trim() ? '#0f1c24' : '#6b7280',
                cursor: name.trim() ? 'pointer' : 'not-allowed'
              }}
            >
              Continue to Upload →
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

