/**
 * Save a project to the library
 * Stores the PDF as an ArrayBuffer for persistence
 */
export async function saveProjectToLibrary(project: Project, thumbnail?: string): Promise<void> {
  const db = await openDB();

  // Convert PDF File to ArrayBuffer for storage
  let pdfData: ArrayBuffer | undefined;
  let pdfName: string | undefined;

  if (project.pdfFile) {
    pdfData = await project.pdfFile.arrayBuffer();
    pdfName = project.pdfFile.name;
  }

  // Create a storable version
  const storable = {
    ...project,
    pdfFile: undefined,
    pdfUrl: undefined,
    pdfData,      // Store the actual PDF bytes
    pdfName,      // Store the filename
    thumbnail,
    createdAt: project.createdAt.toISOString(),
    updatedAt: new Date().toISOString()
  };

  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    const request = store.put(storable);

    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve();
  });
}

