/**
 * Load a full project by ID
 */
export async function loadProjectFromLibrary(id: string): Promise<Project | null> {
  const db = await openDB();

  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    const request = store.get(id);

    request.onerror = () => reject(request.error);
    request.onsuccess = () => {
      const data = request.result;
      if (!data) {
        resolve(null);
        return;
      }

      // Restore Date objects
      const project: Project = {
        ...data,
        createdAt: new Date(data.createdAt),
        updatedAt: new Date(data.updatedAt),
        pdfFile: undefined,
        pdfUrl: undefined
      };

      resolve(project);
    };
  });
}

arguments.new_string:
/**
 * Load a full project by ID
 * Restores the PDF from stored ArrayBuffer
 */
export async function loadProjectFromLibrary(id: string): Promise<Project | null> {
  const db = await openDB();

  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    const request = store.get(id);

    request.onerror = () => reject(request.error);
    request.onsuccess = () => {
      const data = request.result;
      if (!data) {
        resolve(null);
        return;
      }

      // Restore PDF from ArrayBuffer if available
      let pdfFile: File | undefined;
      let pdfUrl: string | undefined;

      if (data.pdfData) {
        const blob = new Blob([data.pdfData], { type: 'application/pdf' });
        pdfFile = new File([blob], data.pdfName || 'drawing.pdf', { type: 'application/pdf' });
        pdfUrl = URL.createObjectURL(blob);
      }

      // Restore Date objects and PDF
      const project: Project = {
        ...data,
        createdAt: new Date(data.createdAt),
        updatedAt: new Date(data.updatedAt),
        pdfFile,
        pdfUrl,
        // Remove storage-only fields
        pdfData: undefined,
        pdfName: undefined
      };

      resolve(project);
    };
  });
}

