// JOC Catalog management
import type { Project } from './types';

const DB_NAME = 'jocstudio';
const STORE_NAME = 'joc-catalog';

export interface JOCLineItem {
  code: string;
  description: string;
  uom: string;
  unitPrice: number;
}

export interface JOCAssembly {
  id: string;
  name: string;
  description?: string;
  lineItems: AssemblyLineItem[];
  tags?: string[];
}

export interface AssemblyLineItem {
  lineItem: JOCLineItem;
  multiplier: number; // e.g., 2.0 for two coats
  quantityFormula?: 'same' | 'perimeter' | 'area_per_floor' | string;
}

// Open IndexedDB
function openDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 2); // v2 for new store

    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve(request.result);

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        const store = db.createObjectStore(STORE_NAME, { keyPath: 'code' });
        store.createIndex('description', 'description', { unique: false });
        store.createIndex('tags', 'tags', { unique: false, multiEntry: true });
      }
    };
  });
}

/**
 * Import catalog from CSV string
 */
export async function importCatalogFromCSV(csvText: string): Promise<number> {
  const lines = csvText.trim().split('\n');
  const headers = lines[0].toLowerCase().split(',');

  const items: JOCLineItem[] = [];

  for (let i = 1; i < lines.length; i++) {
    const values = lines[i].split(',');
    if (values.length >= 4) {
      items.push({
        code: values[0].trim(),
        uom: values[1].trim(),
        description: values[2].trim().replace(/^"|"$/g, ''),
        unitPrice: parseFloat(values[3]) || 0
      });
    }
  }

  const db = await openDB();

  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);

    let count = 0;
    items.forEach(item => {
      const request = store.put(item);
      request.onsuccess = () => count++;
    });

    tx.oncomplete = () => resolve(count);
    tx.onerror = () => reject(tx.error);
  });
}

/**
 * Search catalog by description
 */
export async function searchCatalog(query: string): Promise<JOCLineItem[]> {
  const db = await openDB();

  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onerror = () => reject(request.error);
    request.onsuccess = () => {
      const all = request.result as JOCLineItem[];
      const q = query.toLowerCase();

      // Simple search: match in description or code
      const matches = all.filter(item => 
        item.description.toLowerCase().includes(q) ||
        item.code.toLowerCase().includes(q)
      );

      // Sort by relevance (exact matches first)
      matches.sort((a, b) => {
        const aExact = a.description.toLowerCase().startsWith(q) || a.code === q;
        const bExact = b.description.toLowerCase().startsWith(q) || b.code === q;
        if (aExact && !bExact) return -1;
        if (!aExact && bExact) return 1;
        return 0;
      });

      resolve(matches.slice(0, 50)); // Limit results
    };
  });
}

/**
 * Get a single line item by code
 */
export async function getLineItem(code: string): Promise<JOCLineItem | null> {
  const db = await openDB();

  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    const request = store.get(code);

    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve(request.result || null);
  });
}

/**
 * Save an assembly
 */
export async function saveAssembly(assembly: JOCAssembly): Promise<void> {
  const key = `assembly-${assembly.id}`;
  localStorage.setItem(key, JSON.stringify(assembly));
}

/**
 * Load all assemblies
 */
export function loadAssemblies(): JOCAssembly[] {
  const assemblies: JOCAssembly[] = [];
  for (let i = 0; i < localStorage.length; i++) {
    const key = localStorage.key(i);
    if (key?.startsWith('assembly-')) {
      try {
        const data = JSON.parse(localStorage.getItem(key)!);
        assemblies.push(data);
      } catch {
        // Skip invalid
      }
    }
  }
  return assemblies;
}

/**
 * Delete an assembly
 */
export function deleteAssembly(id: string): void {
  localStorage.removeItem(`assembly-${id}`);
}

/**
 * Calculate derived quantities for an assembly
 * e.g., Wall SF from Wall LF + height
 */
export function calculateAssemblyQuantities(
  assembly: JOCAssembly,
  baseMeasurement: { value: number; type: 'linear' | 'area' | 'count' | 'perimeter' },
  options?: { wallHeight?: number; floorArea?: number }
): { lineItem: JOCLineItem; quantity: number; unitPrice: number; total: number }[] {

  return assembly.lineItems.map(item => {
    let quantity = 0;

    switch (item.quantityFormula || 'same') {
      case 'same':
        quantity = baseMeasurement.value * item.multiplier;
        break;
      case 'perimeter':
        // Convert area to perimeter (rough estimate)
        if (baseMeasurement.type === 'area' && options?.wallHeight) {
          const perimeter = Math.sqrt(baseMeasurement.value) * 4; // Rough: square room
          quantity = perimeter * item.multiplier;
        } else {
          quantity = baseMeasurement.value * item.multiplier;
        }
        break;
      case 'area_from_perimeter':
        // Convert perimeter to area
        if (options?.wallHeight) {
          quantity = baseMeasurement.value * options.wallHeight * item.multiplier;
        } else {
          quantity = baseMeasurement.value * item.multiplier * 9; // Assume 9' height
        }
        break;
      default:
        quantity = baseMeasurement.value * item.multiplier;
    }

    return {
      lineItem: item.lineItem,
      quantity,
      unitPrice: item.lineItem.unitPrice,
      total: quantity * item.lineItem.unitPrice
    };
  });
}

/**
 * AI-like search: find best matches for a description
 * This will be enhanced with actual AI later
 */
export async function findMatchingLineItems(
  description: string,
  measurementType?: string
): Promise<JOCLineItem[]> {
  const keywords = description.toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(w => w.length > 3);

  const db = await openDB();

  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onerror = () => reject(request.error);
    request.onsuccess = () => {
      const all = request.result as JOCLineItem[];

      // Score each item by keyword matches
      const scored = all.map(item => {
        const itemText = (item.description + ' ' + item.code).toLowerCase();
        let score = 0;

        keywords.forEach(keyword => {
          if (itemText.includes(keyword)) score += 1;
        });

        // Boost for matching measurement type
        if (measurementType === 'area' && item.uom === 'SF') score += 0.5;
        if (measurementType === 'linear' && item.uom === 'LF') score += 0.5;
        if (measurementType === 'count' && item.uom === 'EA') score += 0.5;

        return { item, score };
      });

      // Sort by score
      scored.sort((a, b) => b.score - a.score);

      resolve(scored.slice(0, 20).filter(s => s.score > 0).map(s => s.item));
    };
  });
}

import { useState, useEffect } from 'react';
import toast from 'react-hot-toast';
import { 
  searchCatalog, 
  findMatchingLineItems, 
  getLineItem,
  type JOCLineItem 
} from '../utils/jocCatalog';

interface JOCAssignmentDialogProps {
  measurementValue: number;
  measurementType: 'linear' | 'area' | 'count' | 'perimeter';
  measurementName: string;
  onConfirm: (lineItems: AssignedLineItem[]) => void;
  onCancel: () => void;
  onSaveAssembly: (name: string, lineItems: AssignedLineItem[]) => void;
}

export interface AssignedLineItem {
  lineItem: JOCLineItem;
  quantity: number;
  multiplier: number;
}

export function JOCAssignmentDialog({
  measurementValue,
  measurementType,
  measurementName,
  onConfirm,
  onCancel,
  onSaveAssembly
}: JOCAssignmentDialogProps) {
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<JOCLineItem[]>([]);
  const [selectedItems, setSelectedItems] = useState<AssignedLineItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [showSaveAssembly, setShowSaveAssembly] = useState(false);
  const [assemblyName, setAssemblyName] = useState('');
  const [wallHeight, setWallHeight] = useState(9); // Default 9'

  // Auto-search on mount with measurement name
  useEffect(() => {
    handleAISearch(measurementName);
  }, [measurementName]);

  const handleSearch = async (query: string) => {
    setSearchQuery(query);
    if (!query.trim()) {
      setSearchResults([]);
      return;
    }

    setLoading(true);
    try {
      const results = await searchCatalog(query);
      setSearchResults(results);
    } catch (err) {
      toast.error('Search failed');
    } finally {
      setLoading(false);
    }
  };

  const handleAISearch = async (description: string) => {
    setLoading(true);
    try {
      const results = await findMatchingLineItems(description, measurementType);
      setSearchResults(results);
      // Pre-fill search with description
      setSearchQuery(description);
    } catch (err) {
      toast.error('AI search failed');
    } finally {
      setLoading(false);
    }
  };

  const addItem = (item: JOCLineItem) => {
    // Calculate initial quantity based on measurement
    let quantity = measurementValue;

    // Auto-convert units if needed
    if (measurementType === 'linear' && item.uom === 'SF') {
      quantity = measurementValue * wallHeight; // LF × height = SF
    }

    setSelectedItems(prev => [...prev, {
      lineItem: item,
      quantity,
      multiplier: 1
    }]);
    toast.success(`Added: ${item.code}`);
  };

  const removeItem = (index: number) => {
    setSelectedItems(prev => prev.filter((_, i) => i !== index));
  };

  const updateMultiplier = (index: number, multiplier: number) => {
    setSelectedItems(prev => prev.map((item, i) => 
      i === index ? { ...item, multiplier, quantity: measurementValue * multiplier } : item
    ));
  };

  const updateQuantity = (index: number, quantity: number) => {
    setSelectedItems(prev => prev.map((item, i) => 
      i === index ? { ...item, quantity } : item
    ));
  };

  const totalCost = selectedItems.reduce((sum, item) => 
    sum + (item.quantity * item.lineItem.unitPrice), 0
  );

  return (
    <div 
      className="fixed inset-0 z-50 flex items-center justify-center p-4"
      style={{ background: 'rgba(0,0,0,0.8)', backdropFilter: 'blur(4px)' }}
      onClick={onCancel}
    >
      <div 
        className="w-full max-w-4xl max-h-[90vh] rounded-xl overflow-hidden flex flex-col"
        style={{ 
          background: 'linear-gradient(180deg, #1e3a4c 0%, #152a36 100%)',
          border: '1px solid #3d5a6e'
        }}
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="px-6 py-4" style={{ borderBottom: '1px solid #2d4a5e' }}>
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-xl font-semibold" style={{ color: '#c9a227' }}>
                🤖 Assign JOC Line Items
              </h2>
              <p className="text-sm mt-1" style={{ color: '#6b7280' }}>
                {measurementName}: {measurementValue.toFixed(2)} {measurementType.toUpperCase()}
              </p>
            </div>

            {/* Wall height input (for conversions) */}
            <div className="flex items-center gap-2">
              <span className="text-sm" style={{ color: '#6b7280' }}>Wall height:</span>
              <input
                type="number"
                value={wallHeight}
                onChange={(e) => setWallHeight(parseFloat(e.target.value) || 9)}
                className="w-16 px-2 py-1 rounded text-sm text-center"
                style={{ background: '#0f1c24', color: '#e8f1f5', border: '1px solid #2d4a5e' }}
              />
              <span className="text-sm" style={{ color: '#6b7280' }}>ft</span>
            </div>
          </div>
        </div>

        {/* Main Content */}
        <div className="flex-1 flex overflow-hidden">
          {/* Left: Search */}
          <div className="w-1/2 p-4 overflow-y-auto" style={{ borderRight: '1px solid #2d4a5e' }}>
            {/* Search */}
            <div className="mb-4">
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => handleSearch(e.target.value)}
                placeholder="Search JOC catalog..."
                className="w-full px-4 py-3 rounded-lg text-base"
                style={{ background: '#0f1c24', color: '#e8f1f5', border: '1px solid #2d4a5e' }}
              />
            </div>

            {/* AI Suggestion */}
            <button
              onClick={() => handleAISearch(measurementName)}
              className="w-full mb-4 py-2 px-3 rounded-lg text-sm flex items-center justify-center gap-2"
              style={{ background: '#2d5a3d', color: '#7cb798' }}
            >
              🤖 Find matches for "{measurementName}"
            </button>

            {/* Results */}
            {loading ? (
              <div className="text-center py-8" style={{ color: '#6b7280' }}>
                Searching...
              </div>
            ) : searchResults.length === 0 ? (
              <div className="text-center py-8" style={{ color: '#6b7280' }}>
                {searchQuery ? 'No results' : 'Start typing to search'}
              </div>
            ) : (
              <div className="space-y-2">
                {searchResults.map(item => (
                  <button
                    key={item.code}
                    onClick={() => addItem(item)}
                    className="w-full p-3 rounded-lg text-left transition-colors hover:bg-white/5"
                    style={{ background: '#0f1c24', border: '1px solid #2d4a5e' }}
                  >
                    <div className="flex items-start justify-between gap-2">
                      <div className="flex-1 min-w-0">
                        <code className="text-xs px-1.5 py-0.5 rounded" style={{ background: '#c9a227', color: '#0f1c24' }}>
                          {item.code}
                        </code>
                        <p className="text-sm mt-1 truncate" style={{ color: '#e8f1f5' }}>
                          {item.description}
                        </p>
                      </div>
                      <div className="text-right">
                        <span className="text-sm font-medium" style={{ color: '#22c55e' }}>
                          ${item.unitPrice.toFixed(2)}
                        </span>
                        <span className="text-xs block" style={{ color: '#6b7280' }}>
                          {item.uom}
                        </span>
                      </div>
                    </div>
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* Right: Selected Items */}
          <div className="w-1/2 p-4 flex flex-col">
            <h3 className="text-sm font-medium mb-3" style={{ color: '#e8f1f5' }}>
              Selected Line Items
            </h3>

            {selectedItems.length === 0 ? (
              <div className="flex-1 flex items-center justify-center text-center" style={{ color: '#6b7280' }}>
                <div>
                  <div className="text-3xl mb-2">📋</div>
                  <p className="text-sm">Click items from the left to add them</p>
                </div>
              </div>
            ) : (
              <>
                <div className="flex-1 overflow-y-auto space-y-2">
                  {selectedItems.map((item, index) => (
                    <div 
                      key={`${item.lineItem.code}-${index}`}
                      className="p-3 rounded-lg"
                      style={{ background: '#0f1c24', border: '1px solid #2d4a5e' }}
                    >
                      <div className="flex items-start justify-between gap-2 mb-2">
                        <div className="flex-1 min-w-0">
                          <code className="text-xs px-1.5 py-0.5 rounded" style={{ background: '#c9a227', color: '#0f1c24' }}>
                            {item.lineItem.code}
                          </code>
                          <p className="text-xs mt-1" style={{ color: '#e8f1f5' }}>
                            {item.lineItem.description}
                          </p>
                        </div>
                        <button
                          onClick={() => removeItem(index)}
                          className="text-xs px-2 py-1 rounded"
                          style={{ color: '#ef4444' }}
                        >
                          ✕
                        </button>
                      </div>

                      <div className="flex items-center gap-3">
                        <div className="flex items-center gap-1">
                          <span className="text-xs" style={{ color: '#6b7280' }}>Qty:</span>
                          <input
                            type="number"
                            value={item.quantity.toFixed(2)}
                            onChange={(e) => updateQuantity(index, parseFloat(e.target.value) || 0)}
                            className="w-20 px-2 py-1 rounded text-sm text-right"
                            style={{ background: '#1a2f3d', color: '#e8f1f5', border: '1px solid #2d4a5e' }}
                          />
                          <span className="text-xs" style={{ color: '#6b7280' }}>{item.lineItem.uom}</span>
                        </div>

                        <div className="flex items-center gap-1">
                          <span className="text-xs" style={{ color: '#6b7280' }}>×</span>
                          <input
                            type="number"
                            value={item.multiplier}
                            onChange={(e) => updateMultiplier(index, parseFloat(e.target.value) || 1)}
                            className="w-12 px-2 py-1 rounded text-sm text-center"
                            style={{ background: '#1a2f3d', color: '#e8f1f5', border: '1px solid #2d4a5e' }}
                          />
                        </div>

                        <span className="ml-auto text-sm font-medium" style={{ color: '#22c55e' }}>
                          ${(item.quantity * item.lineItem.unitPrice).toFixed(2)}
                        </span>
                      </div>
                    </div>
                  ))}
                </div>

                {/* Total */}
                <div className="mt-4 pt-4" style={{ borderTop: '1px solid #2d4a5e' }}>
                  <div className="flex items-center justify-between mb-4">
                    <span className="text-lg font-medium" style={{ color: '#e8f1f5' }}>Total:</span>
                    <span className="text-2xl font-bold" style={{ color: '#22c55e' }}>
                      ${totalCost.toFixed(2)}
                    </span>
                  </div>

                  {/* Save Assembly toggle */}
                  {showSaveAssembly ? (
                    <div className="mb-4">
                      <input
                        type="text"
                        value={assemblyName}
                        onChange={(e) => setAssemblyName(e.target.value)}
                        placeholder="Assembly name (e.g., 'Interior Paint 2-Coat')"
                        className="w-full px-3 py-2 rounded text-sm mb-2"
                        style={{ background: '#0f1c24', color: '#e8f1f5', border: '1px solid #2d4a5e' }}
                      />
                      <div className="flex gap-2">
                        <button
                          onClick={() => setShowSaveAssembly(false)}
                          className="flex-1 py-2 rounded text-sm"
                          style={{ color: '#6b7280', border: '1px solid #2d4a5e' }}
                        >
                          Cancel
                        </button>
                        <button
                          onClick={() => {
                            if (assemblyName.trim()) {
                              onSaveAssembly(assemblyName.trim(), selectedItems);
                              setShowSaveAssembly(false);
                              setAssemblyName('');
                            }
                          }}
                          className="flex-1 py-2 rounded text-sm"
                          style={{ background: '#2d5a3d', color: '#7cb798' }}
                        >
