                    <button
                      onClick={() => setShowSaveAssembly(true)}
                      className="w-full mb-4 py-2 rounded text-sm"
                      style={{ color: '#8b7355', border: '1px dashed #3d5a6e' }}
                    >
                      💾 Save as Assembly for reuse
                    </button>
                  )}

                  {/* Actions */}
                  <div className="flex gap-3">
                    <button
                      onClick={onCancel}
                      className="flex-1 py-3 rounded-lg text-sm font-medium"
                      style={{ color: '#6b7280', border: '1px solid #2d4a5e' }}
                    >
                      Cancel
                    </button>
                    <button
                      onClick={() => onConfirm(selectedItems)}
                      className="flex-2 px-6 py-3 rounded-lg text-sm font-medium"
                      style={{ 
                        background: '#c9a227', 
                        color: '#0f1c24',
                        flex: 2
                      }}
                    >
                      Apply to Takeoff
                    </button>
                  </div>
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

