import type { Project, Measurement, MeasurementGroup, Tool, Point, Space } from '../types';
import { MEASUREMENT_COLORS, MAX_HISTORY, SEPARATOR_POINT } from '../constants';

interface ProjectState {
  // Current project
  project: Project | null;

  // UI State
  activeTool: Tool;
