/**
 * JOC Catalog Data Layer
 * Loads and indexes the HHC JOC catalog for fast searching
 */

export interface JOCItem {
  code: string;
  unit: string;
  description: string;
  unitPrice: number;
}

let catalog: JOCItem[] = [];
let loaded = false;

/**
 * Parse CSV line handling quoted fields
 */
function parseCSVLine(line: string): string[] {
  const result: string[] = [];
  let current = '';
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    if (char === '"') {
      inQuotes = !inQuotes;
    } else if (char === ',' && !inQuotes) {
      result.push(current.trim());
      current = '';
    } else {
      current += char;
    }
  }
  result.push(current.trim());
  return result;
}

/**
 * Load the JOC catalog from CSV
 */
export async function loadCatalog(): Promise<JOCItem[]> {
  if (loaded && catalog.length > 0) {
    return catalog;
  }

  try {
    // In dev, catalog is in public folder; in prod, same path
    const response = await fetch('/catalog/hhc-joc-catalog-sample.csv');
    if (!response.ok) {
      throw new Error(`Failed to load catalog: ${response.status}`);
    }

    const text = await response.text();
    const lines = text.split('\n').filter(line => line.trim());

    catalog = lines.map(line => {
      const [code, unit, description, price] = parseCSVLine(line);
      return {
        code: code || '',
        unit: unit || '',
        description: description || '',
        unitPrice: parseFloat(price) || 0
      };
    }).filter(item => item.code && item.description);

    loaded = true;
    console.log(`JOC Catalog loaded: ${catalog.length} items`);
    return catalog;
  } catch (error) {
    console.error('Failed to load JOC catalog:', error);
    return [];
  }
}

/**
 * Get the full catalog (must be loaded first)
 */
export function getCatalog(): JOCItem[] {
  return catalog;
}

/**
 * Simple fuzzy search - matches if all search terms appear in code or description
 */
export function searchCatalog(query: string, limit = 50): JOCItem[] {
  if (!query.trim()) return catalog.slice(0, limit);

  const terms = query.toLowerCase().split(/\s+/).filter(t => t.length > 0);

  // Score each item
  const scored = catalog.map(item => {
    const searchText = `${item.code} ${item.description}`.toLowerCase();
    let score = 0;
    let allMatch = true;

    for (const term of terms) {
      if (searchText.includes(term)) {
        // Exact word match scores higher
        if (searchText.includes(` ${term} `) || 
            searchText.startsWith(`${term} `) || 
            searchText.endsWith(` ${term}`)) {
          score += 10;
        } else {
          score += 5;
        }
        // Code match scores even higher
        if (item.code.toLowerCase().includes(term)) {
          score += 15;
        }
      } else {
        allMatch = false;
      }
    }

    return { item, score, allMatch };
  });

  // Filter to items that match all terms, sort by score
  return scored
    .filter(s => s.allMatch && s.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, limit)
    .map(s => s.item);
}

/**
 * Get items by CSI division (first 2 digits of code)
 */
export function getByDivision(division: string, limit = 100): JOCItem[] {
  return catalog
    .filter(item => item.code.startsWith(division))
    .slice(0, limit);
}

/**
 * Get unique divisions in the catalog
 */
export function getDivisions(): { code: string; name: string; count: number }[] {
  const divisionMap = new Map<string, number>();

  for (const item of catalog) {
    const div = item.code.substring(0, 2);
    divisionMap.set(div, (divisionMap.get(div) || 0) + 1);
  }

  const divisionNames: Record<string, string> = {
    '01': 'General Requirements',
    '02': 'Existing Conditions',
    '03': 'Concrete',
    '04': 'Masonry',
    '05': 'Metals',
    '06': 'Wood & Plastics',
    '07': 'Thermal & Moisture',
    '08': 'Openings',
    '09': 'Finishes',
    '10': 'Specialties',
    '11': 'Equipment',
    '12': 'Furnishings',
    '13': 'Special Construction',
    '14': 'Conveying Equipment',
    '21': 'Fire Suppression',
    '22': 'Plumbing',
    '23': 'HVAC',
    '26': 'Electrical',
    '27': 'Communications',
    '28': 'Electronic Safety',
    '31': 'Earthwork',
    '32': 'Exterior Improvements',
    '33': 'Utilities'
  };

  return Array.from(divisionMap.entries())
    .map(([code, count]) => ({
      code,
      name: divisionNames[code] || `Division ${code}`,
      count
    }))
    .sort((a, b) => a.code.localeCompare(b.code));
}

/**
 * JOC Line Item Picker Dialog
 * Search and select JOC catalog items to assign to measurements
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { loadCatalog, searchCatalog, getDivisions, type JOCItem } from '../data/jocCatalog';

interface JOCPickerDialogProps {
  isOpen: boolean;
  onClose: () => void;
  onSelect: (items: SelectedJOCItem[]) => void;
  measurementName: string;
  measurementValue: number;
  measurementUnit: string;
}

export interface SelectedJOCItem {
  code: string;
  description: string;
  uom: string;
  unitPrice: number;
  quantity: number;
  multiplier: number;
  total: number;
}

export function JOCPickerDialog({
  isOpen,
  onClose,
  onSelect,
  measurementName,
  measurementValue,
  measurementUnit
}: JOCPickerDialogProps) {
  const [searchQuery, setSearchQuery] = useState('');
  const [results, setResults] = useState<JOCItem[]>([]);
  const [selectedItems, setSelectedItems] = useState<SelectedJOCItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [divisions, setDivisions] = useState<{ code: string; name: string; count: number }[]>([]);
  const [activeDivision, setActiveDivision] = useState<string | null>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);

  // Load catalog on mount
  useEffect(() => {
    if (isOpen) {
      setIsLoading(true);
      loadCatalog().then(() => {
        setDivisions(getDivisions());
        setResults(searchCatalog('', 50));
        setIsLoading(false);
      });
      // Focus search input
      setTimeout(() => searchInputRef.current?.focus(), 100);
    }
  }, [isOpen]);

  // Search when query changes
  useEffect(() => {
    if (!isLoading) {
      const query = activeDivision ? `${activeDivision} ${searchQuery}` : searchQuery;
      setResults(searchCatalog(query, 100));
    }
  }, [searchQuery, activeDivision, isLoading]);

  // Reset state when dialog opens
  useEffect(() => {
    if (isOpen) {
      setSelectedItems([]);
      setSearchQuery('');
      setActiveDivision(null);
    }
  }, [isOpen]);

  const handleAddItem = useCallback((item: JOCItem) => {
    // Check if already selected
    if (selectedItems.some(s => s.code === item.code)) {
      return;
    }

    // Auto-set quantity based on unit match
    let quantity = measurementValue;
    if (item.unit !== measurementUnit) {
      // Unit mismatch - default to 1 and let user adjust
      quantity = 1;
    }

    const newItem: SelectedJOCItem = {
      code: item.code,
      description: item.description,
      uom: item.unit,
      unitPrice: item.unitPrice,
      quantity: Math.round(quantity * 100) / 100,
      multiplier: 1.0,
      total: Math.round(item.unitPrice * quantity * 100) / 100
    };

    setSelectedItems(prev => [...prev, newItem]);
  }, [selectedItems, measurementValue, measurementUnit]);

  const handleRemoveItem = useCallback((code: string) => {
    setSelectedItems(prev => prev.filter(item => item.code !== code));
  }, []);

  const handleQuantityChange = useCallback((code: string, quantity: number) => {
    setSelectedItems(prev => prev.map(item => {
      if (item.code === code) {
        const total = Math.round(item.unitPrice * quantity * item.multiplier * 100) / 100;
        return { ...item, quantity, total };
      }
      return item;
    }));
  }, []);

  const handleMultiplierChange = useCallback((code: string, multiplier: number) => {
    setSelectedItems(prev => prev.map(item => {
      if (item.code === code) {
        const total = Math.round(item.unitPrice * item.quantity * multiplier * 100) / 100;
        return { ...item, multiplier, total };
      }
      return item;
    }));
  }, []);

  const handleConfirm = useCallback(() => {
    onSelect(selectedItems);
    onClose();
  }, [selectedItems, onSelect, onClose]);

  const totalCost = selectedItems.reduce((sum, item) => sum + item.total, 0);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50">
      <div className="bg-slate-800 rounded-lg shadow-xl w-[900px] max-h-[80vh] flex flex-col">
        {/* Header */}
        <div className="px-6 py-4 border-b border-slate-700">
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-xl font-semibold text-white">Assign JOC Line Items</h2>
              <p className="text-sm text-slate-400 mt-1">
                {measurementName}: <span className="text-amber-400">{measurementValue.toLocaleString()} {measurementUnit}</span>
              </p>
            </div>
            <button
              onClick={onClose}
              className="text-slate-400 hover:text-white text-2xl leading-none"
            >
              ×
            </button>
          </div>
        </div>

        {/* Search and Filters */}
        <div className="px-6 py-3 border-b border-slate-700">
          <div className="flex gap-3">
            <div className="flex-1 relative">
              <input
                ref={searchInputRef}
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search by code or description..."
                className="w-full px-4 py-2 bg-slate-900 border border-slate-600 rounded text-white placeholder:text-slate-500 focus:outline-none focus:border-amber-500"
              />
              {searchQuery && (
                <button
                  onClick={() => setSearchQuery('')}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-white"
                >
                  ×
                </button>
              )}
            </div>
            <select
              value={activeDivision || ''}
              onChange={(e) => setActiveDivision(e.target.value || null)}
              className="px-3 py-2 bg-slate-900 border border-slate-600 rounded text-white focus:outline-none focus:border-amber-500"
            >
              <option value="">All Divisions</option>
              {divisions.map(div => (
                <option key={div.code} value={div.code}>
                  {div.code} - {div.name} ({div.count})
                </option>
              ))}
            </select>
          </div>
        </div>

        {/* Main Content - Split View */}
        <div className="flex-1 flex overflow-hidden">
          {/* Search Results */}
          <div className="w-1/2 border-r border-slate-700 overflow-y-auto">
            <div className="p-2">
              {isLoading ? (
                <div className="text-center py-8 text-slate-400">Loading catalog...</div>
              ) : results.length === 0 ? (
                <div className="text-center py-8 text-slate-400">No items found</div>
              ) : (
                <div className="space-y-1">
                  {results.map(item => (
                    <button
                      key={item.code}
                      onClick={() => handleAddItem(item)}
                      disabled={selectedItems.some(s => s.code === item.code)}
                      className={`w-full text-left p-3 rounded transition-colors ${
                        selectedItems.some(s => s.code === item.code)
                          ? 'bg-amber-900/30 border border-amber-600/50'
                          : 'bg-slate-700/50 hover:bg-slate-700 border border-transparent'
                      }`}
                    >
                      <div className="flex items-start justify-between gap-2">
                        <div className="min-w-0 flex-1">
                          <div className="text-xs text-amber-400 font-mono">{item.code}</div>
                          <div className="text-sm text-white truncate">{item.description}</div>
                        </div>
                        <div className="text-right shrink-0">
                          <div className="text-xs text-slate-400">{item.unit}</div>
                          <div className="text-sm text-green-400">${item.unitPrice.toFixed(2)}</div>
                        </div>
                      </div>
                    </button>
                  ))}
                </div>
              )}
            </div>
          </div>

          {/* Selected Items */}
          <div className="w-1/2 overflow-y-auto bg-slate-900/50">
            <div className="p-4">
              <h3 className="text-sm font-semibold text-slate-400 uppercase tracking-wide mb-3">
                Selected Items ({selectedItems.length})
              </h3>
              {selectedItems.length === 0 ? (
                <div className="text-center py-8 text-slate-500">
                  Click items on the left to add them
                </div>
              ) : (
                <div className="space-y-3">
                  {selectedItems.map(item => (
                    <div key={item.code} className="bg-slate-800 rounded p-3 border border-slate-700">
                      <div className="flex items-start justify-between mb-2">
                        <div className="min-w-0 flex-1">
                          <div className="text-xs text-amber-400 font-mono">{item.code}</div>
                          <div className="text-sm text-white">{item.description}</div>
                        </div>
                        <button
                          onClick={() => handleRemoveItem(item.code)}
                          className="text-slate-400 hover:text-red-400 ml-2"
                        >
                          ×
                        </button>
                      </div>
                      <div className="grid grid-cols-3 gap-2 text-xs">
                        <div>
                          <label className="text-slate-500">Qty ({item.uom})</label>
                          <input
                            type="number"
                            value={item.quantity}
                            onChange={(e) => handleQuantityChange(item.code, parseFloat(e.target.value) || 0)}
                            className="w-full mt-1 px-2 py-1 bg-slate-900 border border-slate-600 rounded text-white"
                            step="0.01"
                          />
                        </div>
                        <div>
                          <label className="text-slate-500">Multiplier</label>
                          <input
                            type="number"
                            value={item.multiplier}
                            onChange={(e) => handleMultiplierChange(item.code, parseFloat(e.target.value) || 1)}
                            className="w-full mt-1 px-2 py-1 bg-slate-900 border border-slate-600 rounded text-white"
                            step="0.01"
                          />
                        </div>
                        <div>
                          <label className="text-slate-500">Total</label>
                          <div className="mt-1 px-2 py-1 bg-slate-900/50 border border-slate-700 rounded text-green-400 font-semibold">
                            ${item.total.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                          </div>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="px-6 py-4 border-t border-slate-700 bg-slate-800/50">
          <div className="flex items-center justify-between">
            <div className="text-lg">
              <span className="text-slate-400">Total Cost:</span>
              <span className="ml-2 text-green-400 font-bold">
                ${totalCost.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
              </span>
            </div>
            <div className="flex gap-3">
              <button
                onClick={onClose}
                className="px-4 py-2 text-slate-400 hover:text-white transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={handleConfirm}
                disabled={selectedItems.length === 0}
                className="px-6 py-2 bg-amber-600 hover:bg-amber-500 disabled:bg-slate-600 disabled:text-slate-400 text-white font-semibold rounded transition-colors"
              >
                Assign {selectedItems.length} Item{selectedItems.length !== 1 ? 's' : ''}
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

