#!/usr/bin/env node
/**
 * Extract MEP (Fire Suppression + Electrical) from HHC JOC Catalog
 * Parses PDF text into structured JSON with base items + multipliers
 */

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const CATALOG_DIR = path.join(__dirname, '..', 'catalog');
const PDF1 = path.join(CATALOG_DIR, 'Pages from Construction Task Catalog® - Distribution (1)_unlocked_01.pdf');
const PDF2 = path.join(CATALOG_DIR, 'Pages from Construction Task Catalog® - Distribution (1)_unlocked_02.pdf');

// Extract text from PDF page range
function extractPages(pdf, startPage, endPage) {
  try {
    const cmd = `pdftotext -f ${startPage} -l ${endPage} "${pdf}" -`;
    return execSync(cmd, { encoding: 'utf8', maxBuffer: 50 * 1024 * 1024 });
  } catch (e) {
    console.error(`Error extracting pages ${startPage}-${endPage}:`, e.message);
    return '';
  }
}

// Parse a line item from catalog text
function parseLineItem(line) {
  // Pattern: CODE UOM DESCRIPTION ... PRICE
  // Example: 21 13 13 00-0277 EA 2' Long, 3/4" Stainless Steel ... 89.41
  const match = line.match(/^(\d{2}\s+\d{2}\s+\d{2}\s+\d{2}-\d{4})\s+(EA|LF|SF|HR|LS|CY|CF|TON|GAL|CLF|MSF|MBF|LB|MO|DA|WK|YR|CSF|CWT)\s+(.+?)\s+(\d+\.\d{2})$/);
  if (match) {
    return {
      code: match[1].replace(/\s+/g, ' '),
      unit: match[2],
      description: match[3].replace(/\.+$/, '').trim(),
      unitPrice: parseFloat(match[4])
    };
  }
  return null;
}

// Parse multiplier line
function parseMultiplier(line) {
  // Pattern: For CONDITION, Add/Deduct PRICE
  const match = line.match(/For\s+(.+?),\s+(Add|Deduct)\s+(-?\d+\.\d{2})/i);
  if (match) {
    return {
      condition: match[1].trim(),
      type: match[2].toLowerCase(),
      value: parseFloat(match[3])
    };
  }
  return null;
}

// Parse note line
function parseNote(line) {
  const match = line.match(/^Note:\s*(.+)/i);
  if (match) {
    return match[1].trim();
  }
  return null;
}

// Process extracted text into structured items
function processText(text, division) {
  const lines = text.split('\n').map(l => l.trim()).filter(l => l);
  const items = [];
  let currentItem = null;

  for (const line of lines) {
    // Skip headers and page numbers
    if (line.match(/^(MINOR|CSI|UOM|DESCRIPTION|TOTAL|DIRECT|DEMOLITION|UNIT COST|\d{1,4}|\.+|X+)$/)) continue;
    if (line.match(/^(\d{2})\s+(\d{2})\s+[A-Z]/)) continue; // Section headers like "21 13 Fire-Suppression"

    // Try parsing as line item
    const item = parseLineItem(line);
    if (item && item.code.startsWith(division)) {
      if (currentItem) {
        items.push(currentItem);
      }
      currentItem = {
        ...item,
        division,
        multipliers: [],
        notes: []
      };
      continue;
    }

    // Try parsing as multiplier (attached to current item)
    if (currentItem) {
      const mult = parseMultiplier(line);
      if (mult) {
        currentItem.multipliers.push(mult);
        continue;
      }

      const note = parseNote(line);
      if (note) {
        currentItem.notes.push(note);
        continue;
      }
    }
  }

  if (currentItem) {
    items.push(currentItem);
  }

  return items;
}

// Main extraction
async function main() {
  console.log('Extracting Fire Suppression (Div 21)...');
  const fp_text = extractPages(PDF1, 1400, 1500);
  const fpItems = processText(fp_text, '21');
  console.log(`  Found ${fpItems.length} fire protection items`);

  console.log('Extracting Electrical (Div 26)...');
  const elec_text = extractPages(PDF2, 700, 1200);
  const elecItems = processText(elec_text, '26');
  console.log(`  Found ${elecItems.length} electrical items`);

  const allItems = [...fpItems, ...elecItems];

  // Output structured JSON
  const output = {
    generated: new Date().toISOString(),
    source: 'HHC JOC Catalog',
    divisions: {
      '21': 'Fire Suppression',
      '26': 'Electrical'
    },
    itemCount: allItems.length,
    items: allItems
  };

  const outPath = path.join(CATALOG_DIR, 'mep-catalog.json');
  fs.writeFileSync(outPath, JSON.stringify(output, null, 2));
  console.log(`\nWrote ${allItems.length} items to ${outPath}`);

  // Also write a simple CSV for reference
  const csvPath = path.join(CATALOG_DIR, 'mep-catalog.csv');
  const csvLines = ['code,unit,description,unitPrice,multiplierCount'];
  for (const item of allItems) {
    const desc = item.description.replace(/"/g, '""');
    csvLines.push(`${item.code},${item.unit},"${desc}",${item.unitPrice},${item.multipliers.length}`);
  }
  fs.writeFileSync(csvPath, csvLines.join('\n'));
  console.log(`Wrote CSV to ${csvPath}`);

  // Show some examples
  console.log('\n--- Sample Fire Protection Items ---');
  fpItems.slice(0, 3).forEach(item => {
    console.log(`${item.code} | ${item.unit} | ${item.description.substring(0, 50)}... | $${item.unitPrice}`);
