}

// Process extracted text into structured items
function processText(text, division) {
  const lines = text.split('\n');
  const items = [];
  let currentCode = null;
  let currentItem = null;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line || line === '.') continue;

    // Match JOC code pattern: "21 13 13 00-0277" or "26 05 33 13-0537"
    const codeMatch = line.match(/^(\d{2}\s+\d{2}\s+\d{2}\s+\d{2}-\d{4})$/);
    if (codeMatch && line.startsWith(division)) {
      // Save previous item
      if (currentItem) {
        items.push(currentItem);
      }
      currentCode = codeMatch[1].replace(/\s+/g, ' ');
      currentItem = null;
      continue;
    }

    // Match description line: "EA Description... price"
    const descMatch = line.match(/^(EA|LF|SF|HR|LS|CY|CF|TON|GAL|CLF|MSF|MBF|LB|MO|DA|WK|YR|CSF|CWT)\s+(.+?)\s+(\d+\.\d{2})$/);
