        multipliers: [],
        notes: []
      };
      currentCode = null; // Reset for next item
      continue;
    }

    // Match multiplier: "For CONDITION, Add/Deduct PRICE"
    if (currentItem) {
      const multMatch = line.match(/^For\s+(.+?),\s+(Add|Deduct)\s+(-?\d+\.?\d*)$/i);
