 */

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const CATALOG_DIR = path.join(__dirname, '..', 'catalog');
const PDF1 = path.join(CATALOG_DIR, 'Pages from Construction Task Catalog® - Distribution (1)_unlocked_01.pdf');
const PDF2 = path.join(CATALOG_DIR, 'Pages from Construction Task Catalog® - Distribution (1)_unlocked_02.pdf');

function extractPages(pdf, startPage, endPage) {
  try {
    const cmd = `pdftotext -f ${startPage} -l ${endPage} "${pdf}" -`;
    return execSync(cmd, { encoding: 'utf8', maxBuffer: 50 * 1024 * 1024 });
  } catch (e) {
    console.error(`Error extracting pages ${startPage}-${endPage}:`, e.message);
    return '';
  }
}

function processText(text, division) {
  const lines = text.split('\n');
  const items = [];
  let currentCode = null;
  let currentItem = null;
  let pendingMultiplier = null;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line || line === '.' || line === 'XXXXXXX') continue;

    // Skip headers
    if (line.match(/^(MINOR|CSI|UOM|DESCRIPTION|TOTAL|DIRECT|DEMOLITION|UNIT COST|copyright|Page \d+)/) ||
        line.match(/^\d{4}$/) ||  // Year
        line.match(/^NYC Health/)) continue;

    // Match JOC code pattern
    const codeMatch = line.match(/^(\d{2}\s+\d{2}\s+\d{2}\s+\d{2}-\d{4})$/);
    if (codeMatch && line.startsWith(division)) {
      if (currentItem) items.push(currentItem);
      currentCode = codeMatch[1].replace(/\s+/g, ' ');
      currentItem = null;
      pendingMultiplier = null;
      continue;
    }

    // Match description line: "EA Description... price"
    const descMatch = line.match(/^(EA|LF|SF|HR|LS|CY|CF|TON|GAL|CLF|MSF|MBF|LB|MO|DA|WK|YR|CSF|CWT)\s+(.+?)\s+(\d{1,}[,\d]*\.\d{2})$/);
    if (descMatch && currentCode) {
      if (currentItem) items.push(currentItem);
      currentItem = {
        code: currentCode,
        unit: descMatch[1],
        description: descMatch[2].replace(/\.+$/, '').trim(),
        unitPrice: parseFloat(descMatch[3].replace(/,/g, '')),
        division,
        multipliers: [],
        notes: []
      };
      currentCode = null;
      pendingMultiplier = null;
      continue;
    }

    // Handle pending multiplier value (value comes on next line)
    if (pendingMultiplier && currentItem) {
      const valMatch = line.match(/^(-?\d{1,}[,\d]*\.?\d*)$/);
      if (valMatch) {
        pendingMultiplier.value = parseFloat(valMatch[1].replace(/,/g, ''));
        currentItem.multipliers.push(pendingMultiplier);
        pendingMultiplier = null;
        continue;
      }
    }

    // Match multiplier start: "For CONDITION, Add/Deduct"
    if (currentItem) {
      const multMatch = line.match(/^For\s+(.+?),\s+(Add|Deduct)$/i);
      if (multMatch) {
        pendingMultiplier = {
          condition: multMatch[1].trim(),
          type: multMatch[2].toLowerCase(),
          value: 0
        };
        continue;
      }

      // Match note
      const noteMatch = line.match(/^Note:\s*(.+)/i);
      if (noteMatch) {
        currentItem.notes.push(noteMatch[1].trim());
        continue;
      }
    }
  }

  if (currentItem) items.push(currentItem);
  return items;
}

