/**
 * JOC Catalog Data Layer
 * Loads MEP catalog with base items + multipliers
 */

export interface Multiplier {
  condition: string;
  type: 'add' | 'deduct';
  value: number;
}

export interface JOCItem {
  code: string;
  unit: string;
  description: string;
  unitPrice: number;
  division: string;
  multipliers: Multiplier[];
  notes: string[];
}

interface CatalogData {
  generated: string;
  source: string;
  divisions: Record<string, string>;
  itemCount: number;
  multiplierCount: number;
  items: JOCItem[];
}

let catalog: JOCItem[] = [];
let divisions: Record<string, string> = {};
let loaded = false;

/**
 * Load the MEP JOC catalog
 */
export async function loadCatalog(): Promise<JOCItem[]> {
  if (loaded && catalog.length > 0) {
    return catalog;
  }

  try {
    const response = await fetch('/catalog/mep-catalog.json');
    if (!response.ok) {
      throw new Error(`Failed to load catalog: ${response.status}`);
    }

    const data: CatalogData = await response.json();
    catalog = data.items;
    divisions = data.divisions;
    loaded = true;

    console.log(`MEP Catalog loaded: ${catalog.length} items, ${data.multiplierCount} multipliers`);
    return catalog;
  } catch (error) {
    console.error('Failed to load MEP catalog:', error);
    return [];
  }
}

/**
 * Get the full catalog
 */
export function getCatalog(): JOCItem[] {
  return catalog;
}

/**
 * Get available divisions
 */
export function getDivisions(): { code: string; name: string; count: number }[] {
  const divCounts = new Map<string, number>();
  for (const item of catalog) {
    divCounts.set(item.division, (divCounts.get(item.division) || 0) + 1);
  }

  return Object.entries(divisions).map(([code, name]) => ({
    code,
    name,
    count: divCounts.get(code) || 0
  }));
}

/**
 * Search catalog with fuzzy matching
 */
export function searchCatalog(query: string, divisionFilter?: string, limit = 50): JOCItem[] {
  let items = catalog;

  // Filter by division
  if (divisionFilter) {
    items = items.filter(i => i.division === divisionFilter);
  }

  if (!query.trim()) {
    return items.slice(0, limit);
  }

  const terms = query.toLowerCase().split(/\s+/).filter(t => t.length > 0);

  const scored = items.map(item => {
    const searchText = `${item.code} ${item.description}`.toLowerCase();
    let score = 0;
    let allMatch = true;

    for (const term of terms) {
      if (searchText.includes(term)) {
        score += 5;
        if (item.code.toLowerCase().includes(term)) {
          score += 15;
        }
        if (searchText.includes(` ${term} `)) {
          score += 10;
        }
      } else {
        allMatch = false;
      }
    }

    return { item, score, allMatch };
  });

  return scored
    .filter(s => s.allMatch && s.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, limit)
    .map(s => s.item);
}

/**
 * Get common multiplier categories for wizard
 */
export function getMultiplierCategories(item: JOCItem): { category: string; multipliers: Multiplier[] }[] {
  const categories = new Map<string, Multiplier[]>();

  for (const mult of item.multipliers) {
    let category = 'Other';
    const cond = mult.condition.toLowerCase();

    if (cond.includes('quantity') || cond.match(/^>\d|^up to \d|to \d/i)) {
      category = 'Quantity';
    } else if (cond.includes('elevated') || cond.includes('height')) {
      category = 'Elevation/Height';
    } else if (cond.includes('restricted') || cond.includes('working space')) {
      category = 'Working Conditions';
    } else if (cond.includes('pipe') || cond.includes('material')) {
      category = 'Material';
    } else if (cond.includes('hazard')) {
      category = 'Hazard Level';
    } else if (cond.includes('copper') || cond.includes('pvc') || cond.includes('steel')) {
      category = 'Material';
    }

    if (!categories.has(category)) {
      categories.set(category, []);
    }
    categories.get(category)!.push(mult);
  }

  return Array.from(categories.entries())
    .map(([category, multipliers]) => ({ category, multipliers }))
    .sort((a, b) => {
      // Prioritize common categories
      const order = ['Quantity', 'Working Conditions', 'Elevation/Height', 'Material', 'Hazard Level', 'Other'];
      return order.indexOf(a.category) - order.indexOf(b.category);
    });
}

/**
 * Calculate total with selected multipliers
 */
export function calculateTotal(
  basePrice: number, 
  quantity: number, 
  selectedMultipliers: Multiplier[]
): { subtotal: number; adjustments: number; total: number } {
  const subtotal = basePrice * quantity;

  let adjustments = 0;
  for (const mult of selectedMultipliers) {
    // Multiplier values are per-unit adjustments
    const adjustment = mult.value * quantity;
    adjustments += adjustment;
  }

  return {
    subtotal,
    adjustments,
    total: subtotal + adjustments
  };
}

/**
 * JOC Line Item Picker Dialog
 * Two-step wizard: 1) Select base item → 2) Apply multipliers
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { 
  loadCatalog, 
  searchCatalog, 
  getDivisions, 
  getMultiplierCategories,
  calculateTotal,
  type JOCItem,
  type Multiplier 
} from '../data/jocCatalog';

interface JOCPickerDialogProps {
  isOpen: boolean;
  onClose: () => void;
  onSelect: (items: SelectedJOCItem[]) => void;
  measurementName: string;
  measurementValue: number;
  measurementUnit: string;
}

export interface SelectedJOCItem {
  code: string;
  description: string;
  uom: string;
  unitPrice: number;
  quantity: number;
  multiplier: number;
  total: number;
  appliedMultipliers?: { condition: string; value: number }[];
}

type Step = 'search' | 'multipliers' | 'confirm';

export function JOCPickerDialog({
  isOpen,
  onClose,
  onSelect,
  measurementName,
  measurementValue,
  measurementUnit
}: JOCPickerDialogProps) {
  const [step, setStep] = useState<Step>('search');
  const [searchQuery, setSearchQuery] = useState('');
  const [results, setResults] = useState<JOCItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [divisions, setDivisions] = useState<{ code: string; name: string; count: number }[]>([]);
  const [activeDivision, setActiveDivision] = useState<string | null>('21'); // Default to Fire Protection

  // Selection state
  const [selectedItem, setSelectedItem] = useState<JOCItem | null>(null);
  const [quantity, setQuantity] = useState(measurementValue);
  const [selectedMultipliers, setSelectedMultipliers] = useState<Multiplier[]>([]);
  const [multiplierCategories, setMultiplierCategories] = useState<{ category: string; multipliers: Multiplier[] }[]>([]);

  const searchInputRef = useRef<HTMLInputElement>(null);

  // Load catalog
  useEffect(() => {
    if (isOpen) {
      setIsLoading(true);
      loadCatalog().then(() => {
        setDivisions(getDivisions());
        setResults(searchCatalog('', activeDivision || undefined, 50));
        setIsLoading(false);
      });
      setTimeout(() => searchInputRef.current?.focus(), 100);
    }
  }, [isOpen]);

  // Search when query or division changes
  useEffect(() => {
    if (!isLoading) {
      setResults(searchCatalog(searchQuery, activeDivision || undefined, 100));
    }
  }, [searchQuery, activeDivision, isLoading]);

  // Reset on open
  useEffect(() => {
    if (isOpen) {
      setStep('search');
      setSelectedItem(null);
      setSelectedMultipliers([]);
      setQuantity(measurementValue);
      setSearchQuery('');
    }
  }, [isOpen, measurementValue]);

  // Handle item selection → move to multipliers step
  const handleSelectItem = useCallback((item: JOCItem) => {
    setSelectedItem(item);
    setSelectedMultipliers([]);

    // Auto-set quantity if units match
    if (item.unit === measurementUnit) {
      setQuantity(measurementValue);
    } else {
      setQuantity(1);
    }

    // Categorize multipliers
    const categories = getMultiplierCategories(item);
    setMultiplierCategories(categories);

    if (item.multipliers.length > 0) {
      setStep('multipliers');
    } else {
      setStep('confirm');
    }
  }, [measurementValue, measurementUnit]);

  // Toggle a multiplier
  const toggleMultiplier = useCallback((mult: Multiplier) => {
    setSelectedMultipliers(prev => {
      const exists = prev.some(m => m.condition === mult.condition);
      if (exists) {
        return prev.filter(m => m.condition !== mult.condition);
      } else {
        return [...prev, mult];
      }
    });
  }, []);

  // Go back
  const handleBack = useCallback(() => {
    if (step === 'multipliers') {
      setStep('search');
      setSelectedItem(null);
    } else if (step === 'confirm') {
      setStep('multipliers');
    }
  }, [step]);

  // Skip multipliers
  const handleSkipMultipliers = useCallback(() => {
    setStep('confirm');
  }, []);

  // Confirm selection
  const handleConfirm = useCallback(() => {
    if (!selectedItem) return;

    const calc = calculateTotal(selectedItem.unitPrice, quantity, selectedMultipliers);

    const result: SelectedJOCItem = {
      code: selectedItem.code,
      description: selectedItem.description,
      uom: selectedItem.unit,
      unitPrice: selectedItem.unitPrice,
      quantity,
      multiplier: 1, // We use appliedMultipliers instead
      total: calc.total,
      appliedMultipliers: selectedMultipliers.map(m => ({ condition: m.condition, value: m.value }))
    };

    onSelect([result]);
    onClose();
  }, [selectedItem, quantity, selectedMultipliers, onSelect, onClose]);

  if (!isOpen) return null;

  const calc = selectedItem 
    ? calculateTotal(selectedItem.unitPrice, quantity, selectedMultipliers)
    : { subtotal: 0, adjustments: 0, total: 0 };

  return (
    <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50">
      <div className="bg-slate-800 rounded-lg shadow-xl w-[800px] max-h-[85vh] flex flex-col">
        {/* Header */}
        <div className="px-6 py-4 border-b border-slate-700">
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-xl font-semibold text-white">
                {step === 'search' && 'Select JOC Line Item'}
                {step === 'multipliers' && 'Apply Multipliers'}
                {step === 'confirm' && 'Confirm Assignment'}
              </h2>
              <p className="text-sm text-slate-400 mt-1">
                {measurementName}: <span className="text-amber-400">{measurementValue.toLocaleString()} {measurementUnit}</span>
              </p>
            </div>
            <button onClick={onClose} className="text-slate-400 hover:text-white text-2xl">×</button>
          </div>

          {/* Step indicator */}
          <div className="flex items-center gap-2 mt-4">
            {['search', 'multipliers', 'confirm'].map((s, i) => (
              <div key={s} className="flex items-center">
                <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium ${
                  step === s ? 'bg-amber-500 text-black' : 
                  ['search', 'multipliers', 'confirm'].indexOf(step) > i ? 'bg-green-600 text-white' : 
                  'bg-slate-700 text-slate-400'
                }`}>
                  {i + 1}
                </div>
                {i < 2 && <div className="w-12 h-0.5 bg-slate-700 mx-1" />}
              </div>
            ))}
          </div>
        </div>

        {/* Step 1: Search & Select */}
        {step === 'search' && (
          <>
            <div className="px-6 py-3 border-b border-slate-700">
              <div className="flex gap-3">
                <div className="flex-1 relative">
                  <input
                    ref={searchInputRef}
                    type="text"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    placeholder="Search sprinkler heads, conduit, panels..."
                    className="w-full px-4 py-2 bg-slate-900 border border-slate-600 rounded text-white placeholder:text-slate-500 focus:outline-none focus:border-amber-500"
                  />
                </div>
                <div className="flex gap-1">
                  {divisions.map(div => (
                    <button
                      key={div.code}
                      onClick={() => setActiveDivision(activeDivision === div.code ? null : div.code)}
                      className={`px-3 py-2 rounded text-sm font-medium transition-colors ${
                        activeDivision === div.code
                          ? 'bg-amber-600 text-white'
                          : 'bg-slate-700 text-slate-300 hover:bg-slate-600'
                      }`}
                    >
                      {div.code === '21' ? '🚿 Fire' : '⚡ Elec'}
                    </button>
                  ))}
                </div>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-4">
              {isLoading ? (
                <div className="text-center py-8 text-slate-400">Loading MEP catalog...</div>
              ) : results.length === 0 ? (
                <div className="text-center py-8 text-slate-400">No items found</div>
              ) : (
                <div className="space-y-2">
                  {results.map(item => (
                    <button
                      key={item.code}
                      onClick={() => handleSelectItem(item)}
                      className="w-full text-left p-4 rounded-lg bg-slate-700/50 hover:bg-slate-700 border border-transparent hover:border-amber-500/50 transition-all"
                    >
                      <div className="flex items-start justify-between gap-3">
                        <div className="min-w-0 flex-1">
                          <div className="flex items-center gap-2">
                            <span className="text-xs text-amber-400 font-mono">{item.code}</span>
                            {item.multipliers.length > 0 && (
                              <span className="text-xs px-1.5 py-0.5 rounded bg-slate-600 text-slate-300">
                                {item.multipliers.length} options
                              </span>
                            )}
                          </div>
                          <div className="text-sm text-white mt-1">{item.description}</div>
                        </div>
                        <div className="text-right shrink-0">
                          <div className="text-xs text-slate-400">{item.unit}</div>
                          <div className="text-sm text-green-400 font-semibold">${item.unitPrice.toLocaleString()}</div>
                        </div>
                      </div>
                    </button>
                  ))}
                </div>
              )}
            </div>
          </>
        )}

        {/* Step 2: Multipliers Wizard */}
        {step === 'multipliers' && selectedItem && (
          <>
            <div className="px-6 py-4 bg-slate-900/50 border-b border-slate-700">
              <div className="flex items-center gap-3">
                <div className="text-amber-400 font-mono text-sm">{selectedItem.code}</div>
                <div className="text-white text-sm flex-1">{selectedItem.description}</div>
                <div className="text-green-400 font-semibold">${selectedItem.unitPrice.toLocaleString()}/{selectedItem.unit}</div>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-4">
              <p className="text-slate-400 text-sm mb-4">
                Select applicable conditions to adjust pricing:
              </p>

              {multiplierCategories.map(({ category, multipliers }) => (
                <div key={category} className="mb-4">
                  <h4 className="text-sm font-semibold text-slate-300 mb-2">{category}</h4>
                  <div className="grid grid-cols-2 gap-2">
                    {multipliers.map((mult, idx) => {
                      const isSelected = selectedMultipliers.some(m => m.condition === mult.condition);
                      return (
                        <button
                          key={idx}
                          onClick={() => toggleMultiplier(mult)}
                          className={`p-3 rounded text-left text-sm transition-all ${
                            isSelected
                              ? 'bg-amber-600/20 border-2 border-amber-500'
                              : 'bg-slate-700/50 border border-slate-600 hover:border-slate-500'
                          }`}
                        >
                          <div className="flex items-center justify-between">
                            <span className="text-white">{mult.condition}</span>
                            <span className={mult.type === 'add' ? 'text-red-400' : 'text-green-400'}>
                              {mult.type === 'add' ? '+' : '−'}${Math.abs(mult.value).toFixed(2)}
                            </span>
                          </div>
                        </button>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>

            <div className="px-6 py-4 border-t border-slate-700 flex justify-between">
              <button onClick={handleBack} className="px-4 py-2 text-slate-400 hover:text-white">
                ← Back
              </button>
              <div className="flex gap-3">
                <button
                  onClick={handleSkipMultipliers}
                  className="px-4 py-2 text-slate-400 hover:text-white"
                >
                  Skip
                </button>
                <button
                  onClick={() => setStep('confirm')}
                  className="px-6 py-2 bg-amber-600 hover:bg-amber-500 text-white font-semibold rounded"
                >
                  Continue →
                </button>
              </div>
            </div>
          </>
        )}

        {/* Step 3: Confirm */}
        {step === 'confirm' && selectedItem && (
          <>
            <div className="flex-1 overflow-y-auto p-6">
              <div className="bg-slate-900 rounded-lg p-4 mb-4">
                <div className="text-amber-400 font-mono text-sm mb-1">{selectedItem.code}</div>
                <div className="text-white">{selectedItem.description}</div>
              </div>

              <div className="grid grid-cols-2 gap-4 mb-4">
                <div>
                  <label className="text-sm text-slate-400">Quantity ({selectedItem.unit})</label>
                  <input
                    type="number"
                    value={quantity}
                    onChange={(e) => setQuantity(parseFloat(e.target.value) || 0)}
                    className="w-full mt-1 px-3 py-2 bg-slate-900 border border-slate-600 rounded text-white text-lg"
                    step="0.01"
                  />
                </div>
                <div>
                  <label className="text-sm text-slate-400">Unit Price</label>
                  <div className="mt-1 px-3 py-2 bg-slate-900/50 border border-slate-700 rounded text-green-400 text-lg">
                    ${selectedItem.unitPrice.toLocaleString()}
                  </div>
                </div>
              </div>

              {selectedMultipliers.length > 0 && (
                <div className="mb-4">
                  <label className="text-sm text-slate-400 mb-2 block">Applied Adjustments</label>
                  <div className="space-y-1">
                    {selectedMultipliers.map((mult, idx) => (
                      <div key={idx} className="flex justify-between text-sm px-3 py-2 bg-slate-900/50 rounded">
                        <span className="text-slate-300">{mult.condition}</span>
                        <span className={mult.type === 'add' ? 'text-red-400' : 'text-green-400'}>
                          {mult.type === 'add' ? '+' : '−'}${Math.abs(mult.value * quantity).toFixed(2)}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              <div className="bg-slate-700/50 rounded-lg p-4">
                <div className="flex justify-between text-sm mb-2">
                  <span className="text-slate-400">Subtotal ({quantity} × ${selectedItem.unitPrice})</span>
                  <span className="text-white">${calc.subtotal.toLocaleString(undefined, { minimumFractionDigits: 2 })}</span>
                </div>
                {calc.adjustments !== 0 && (
                  <div className="flex justify-between text-sm mb-2">
                    <span className="text-slate-400">Adjustments</span>
                    <span className={calc.adjustments > 0 ? 'text-red-400' : 'text-green-400'}>
                      {calc.adjustments > 0 ? '+' : ''}${calc.adjustments.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                    </span>
                  </div>
                )}
                <div className="flex justify-between text-lg font-semibold pt-2 border-t border-slate-600">
                  <span className="text-white">Total</span>
                  <span className="text-green-400">${calc.total.toLocaleString(undefined, { minimumFractionDigits: 2 })}</span>
                </div>
              </div>
            </div>

            <div className="px-6 py-4 border-t border-slate-700 flex justify-between">
              <button onClick={handleBack} className="px-4 py-2 text-slate-400 hover:text-white">
                ← Back
              </button>
              <button
                onClick={handleConfirm}
                className="px-8 py-2 bg-green-600 hover:bg-green-500 text-white font-semibold rounded"
              >
                ✓ Assign to {measurementName}
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

