import { useCallback, useState } from 'react';

interface DropZoneProps {
  onFileLoad: (file: File) => void;
  onBack?: () => void;
  showBackButton?: boolean;
}

export function DropZone({ onFileLoad, onBack, showBackButton }: DropZoneProps) {
  const [isDragging, setIsDragging] = useState(false);

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);

    const file = e.dataTransfer.files[0];
    if (file && file.type === 'application/pdf') {
      onFileLoad(file);
    }
  }, [onFileLoad]);

  const handleFileSelect = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && file.type === 'application/pdf') {
      onFileLoad(file);
    }
  }, [onFileLoad]);

  return (
    <div className="min-h-screen w-full flex flex-col items-center justify-center p-8 relative"
         style={{ background: 'linear-gradient(180deg, #1a2f3d 0%, #0f1c24 100%)' }}>

      {/* Back Button */}
      {showBackButton && onBack && (
        <button
          onClick={onBack}
          className="absolute top-6 left-6 flex items-center gap-2 px-4 py-2 rounded-lg transition-all"
          style={{ 
            color: '#6b7280',
            background: 'transparent'
          }}
          onMouseEnter={(e) => {
            e.currentTarget.style.background = '#1e3a4c';
            e.currentTarget.style.color = '#e8f1f5';
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.background = 'transparent';
            e.currentTarget.style.color = '#6b7280';
          }}
        >
          ← Back to Library
        </button>
      )}

      {/* Header */}
      <div className="text-center mb-12">
        <div className="text-6xl mb-4">📐</div>
        <h1 className="text-5xl font-bold mb-2" 
            style={{ fontFamily: 'Playfair Display, serif', color: '#c9a227' }}>
          JOCstudio
        </h1>
        <p className="text-lg opacity-70" style={{ color: '#e8f1f5' }}>
          Takeoff & JOC Line Item Assignment
        </p>
      </div>

      {/* Drop Zone */}
      <div
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        onClick={() => document.getElementById('file-input')?.click()}
        className={`
          w-full max-w-2xl aspect-[16/10] rounded-lg
          flex flex-col items-center justify-center gap-6 p-12
          transition-all duration-300 cursor-pointer
          ${isDragging 
            ? 'scale-102 shadow-2xl' 
            : 'hover:scale-101'
          }
        `}
        style={{
          background: isDragging 
            ? 'linear-gradient(135deg, #2d4a5e 0%, #1e3a4c 100%)'
            : 'linear-gradient(135deg, #1e3a4c 0%, #152a36 100%)',
          border: `2px dashed ${isDragging ? '#c9a227' : '#4a6a7a'}`,
          boxShadow: isDragging 
            ? '0 20px 60px rgba(0,0,0,0.4), inset 0 0 60px rgba(201, 162, 39, 0.1)'
            : '0 10px 40px rgba(0,0,0,0.3)'
        }}
      >
        <div className="text-5xl opacity-80">📋</div>
        <div className="text-center">
          <p className="text-xl mb-2" style={{ color: '#e8f1f5' }}>
            Drop your drawings here
          </p>
          <p className="text-sm opacity-60">
            PDF files • Click or drag
          </p>
        </div>
      </div>

      {/* Footer */}
      <div className="mt-12 text-center opacity-40">
        <p className="text-xs" style={{ color: '#8b7355' }}>
          Built for JOC Estimators • Precision Takeoff
        </p>
      </div>

      <input
        id="file-input"
        type="file"
        accept=".pdf"
        className="hidden"
        onChange={handleFileSelect}
      />
    </div>
  );
}

