import { useCallback, useState } from 'react';
import { PDFDocument } from 'pdf-lib';

interface DropZoneProps {
  onFileLoad: (file: File) => void;
  onBack?: () => void;
  showBackButton?: boolean;
}

interface PendingFile {
  file: File;
  name: string;
  pages: number | null;
}

export function DropZone({ onFileLoad, onBack, showBackButton }: DropZoneProps) {
  const [isDragging, setIsDragging] = useState(false);
  const [pendingFiles, setPendingFiles] = useState<PendingFile[]>([]);
  const [isMerging, setIsMerging] = useState(false);
  const [mergeProgress, setMergeProgress] = useState(0);

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  }, []);

  const addFiles = useCallback(async (files: FileList) => {
    const pdfFiles = Array.from(files).filter(f => f.type === 'application/pdf');

    // Get page counts for each file
    const newFiles: PendingFile[] = await Promise.all(
      pdfFiles.map(async (file) => {
        try {
          const arrayBuffer = await file.arrayBuffer();
          const pdf = await PDFDocument.load(arrayBuffer);
          return { file, name: file.name, pages: pdf.getPageCount() };
        } catch {
          return { file, name: file.name, pages: null };
        }
      })
    );

    setPendingFiles(prev => [...prev, ...newFiles]);
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    addFiles(e.dataTransfer.files);
  }, [addFiles]);

  const handleFileSelect = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      addFiles(e.target.files);
    }
  }, [addFiles]);

  const removeFile = useCallback((index: number) => {
    setPendingFiles(prev => prev.filter((_, i) => i !== index));
  }, []);

  const moveFile = useCallback((index: number, direction: 'up' | 'down') => {
    setPendingFiles(prev => {
      const newFiles = [...prev];
      const newIndex = direction === 'up' ? index - 1 : index + 1;
      if (newIndex < 0 || newIndex >= newFiles.length) return prev;
      [newFiles[index], newFiles[newIndex]] = [newFiles[newIndex], newFiles[index]];
      return newFiles;
    });
  }, []);

  const mergePdfs = useCallback(async () => {
    if (pendingFiles.length === 0) return;

    setIsMerging(true);
    setMergeProgress(0);

    try {
      if (pendingFiles.length === 1) {
        // Single file, no merge needed
        onFileLoad(pendingFiles[0].file);
        setPendingFiles([]);
        setIsMerging(false);
        return;
      }

      // Merge multiple PDFs
      const mergedPdf = await PDFDocument.create();

      for (let i = 0; i < pendingFiles.length; i++) {
        const { file } = pendingFiles[i];
        const arrayBuffer = await file.arrayBuffer();
        const pdf = await PDFDocument.load(arrayBuffer);
        const pages = await mergedPdf.copyPages(pdf, pdf.getPageIndices());
        pages.forEach(page => mergedPdf.addPage(page));
        setMergeProgress(Math.round(((i + 1) / pendingFiles.length) * 100));
      }

      const mergedBytes = await mergedPdf.save();
      const mergedBlob = new Blob([mergedBytes], { type: 'application/pdf' });
      const mergedFile = new File([mergedBlob], 'Combined_Drawings.pdf', { type: 'application/pdf' });

      onFileLoad(mergedFile);
      setPendingFiles([]);
    } catch (error) {
      console.error('Failed to merge PDFs:', error);
      alert('Failed to merge PDFs. Try uploading them one at a time.');
    } finally {
      setIsMerging(false);
      setMergeProgress(0);
    }
  }, [pendingFiles, onFileLoad]);

  const totalPages = pendingFiles.reduce((sum, f) => sum + (f.pages || 0), 0);

  return (
    <div className="min-h-screen w-full flex flex-col items-center justify-center p-8 relative"
         style={{ background: 'linear-gradient(180deg, #1a2f3d 0%, #0f1c24 100%)' }}>

      {/* Back Button */}
      {showBackButton && onBack && (
        <button
          onClick={onBack}
          className="absolute top-6 left-6 flex items-center gap-2 px-4 py-2 rounded-lg transition-all"
          style={{ 
            color: '#6b7280',
            background: 'transparent'
          }}
          onMouseEnter={(e) => {
            e.currentTarget.style.background = '#1e3a4c';
            e.currentTarget.style.color = '#e8f1f5';
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.background = 'transparent';
            e.currentTarget.style.color = '#6b7280';
          }}
        >
          ← Back to Library
        </button>
      )}

      {/* Header */}
      <div className="text-center mb-8">
        <div className="text-6xl mb-4">📐</div>
        <h1 className="text-5xl font-bold mb-2" 
            style={{ fontFamily: 'Playfair Display, serif', color: '#c9a227' }}>
          JOCstudio
        </h1>
        <p className="text-lg opacity-70" style={{ color: '#e8f1f5' }}>
          Takeoff & JOC Line Item Assignment
        </p>
      </div>

      {/* Drop Zone */}
      <div
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        onClick={() => document.getElementById('file-input')?.click()}
        className={`
          w-full max-w-2xl rounded-lg
          flex flex-col items-center justify-center gap-4 p-8
          transition-all duration-300 cursor-pointer
          ${isDragging ? 'scale-102 shadow-2xl' : 'hover:scale-101'}
        `}
        style={{
          background: isDragging 
            ? 'linear-gradient(135deg, #2d4a5e 0%, #1e3a4c 100%)'
            : 'linear-gradient(135deg, #1e3a4c 0%, #152a36 100%)',
          border: `2px dashed ${isDragging ? '#c9a227' : '#4a6a7a'}`,
          boxShadow: isDragging 
            ? '0 20px 60px rgba(0,0,0,0.4), inset 0 0 60px rgba(201, 162, 39, 0.1)'
            : '0 10px 40px rgba(0,0,0,0.3)',
          minHeight: pendingFiles.length > 0 ? 'auto' : '280px'
        }}
      >
        {pendingFiles.length === 0 ? (
          <>
            <div className="text-5xl opacity-80">📋</div>
            <div className="text-center">
              <p className="text-xl mb-2" style={{ color: '#e8f1f5' }}>
                Drop your drawings here
              </p>
              <p className="text-sm opacity-60">
                PDF files • Multiple files supported • Click or drag
              </p>
            </div>
          </>
        ) : (
          <div className="w-full" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-4">
              <span className="text-sm font-medium" style={{ color: '#e8f1f5' }}>
                {pendingFiles.length} file{pendingFiles.length !== 1 ? 's' : ''} • {totalPages} pages total
              </span>
              <button
                onClick={() => document.getElementById('file-input')?.click()}
                className="text-sm px-3 py-1 rounded"
                style={{ background: '#2d4a5e', color: '#c9a227' }}
              >
                + Add More
              </button>
            </div>

            <div className="space-y-2 max-h-48 overflow-y-auto mb-4">
              {pendingFiles.map((pf, index) => (
                <div 
                  key={index}
                  className="flex items-center gap-3 px-3 py-2 rounded"
                  style={{ background: '#0f1c24' }}
                >
                  <span className="text-lg">📄</span>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm truncate" style={{ color: '#e8f1f5' }}>{pf.name}</p>
                    <p className="text-xs" style={{ color: '#6b7280' }}>
                      {pf.pages ? `${pf.pages} pages` : 'Loading...'}
                    </p>
                  </div>
                  <div className="flex items-center gap-1">
                    <button
                      onClick={() => moveFile(index, 'up')}
                      disabled={index === 0}
                      className="p-1 rounded text-xs disabled:opacity-30"
                      style={{ color: '#6b7280' }}
                    >
                      ▲
                    </button>
                    <button
                      onClick={() => moveFile(index, 'down')}
                      disabled={index === pendingFiles.length - 1}
                      className="p-1 rounded text-xs disabled:opacity-30"
                      style={{ color: '#6b7280' }}
                    >
                      ▼
                    </button>
                    <button
                      onClick={() => removeFile(index)}
                      className="p-1 rounded text-xs"
                      style={{ color: '#ef4444' }}
                    >
                      ✕
                    </button>
                  </div>
                </div>
              ))}
            </div>

            <button
              onClick={mergePdfs}
              disabled={isMerging}
              className="w-full py-3 rounded-lg font-semibold text-lg transition-all"
              style={{ 
                background: isMerging ? '#4a6a7a' : '#c9a227', 
                color: '#0f1c24' 
              }}
            >
              {isMerging 
                ? `Merging... ${mergeProgress}%` 
                : pendingFiles.length === 1 
                  ? 'Open Project' 
                  : `Merge & Open (${totalPages} pages)`
              }
            </button>
          </div>
        )}
      </div>

      {/* Footer */}
      <div className="mt-8 text-center opacity-40">
        <p className="text-xs" style={{ color: '#8b7355' }}>
          Built for JOC Estimators • Precision Takeoff
        </p>
      </div>

      <input
        id="file-input"
        type="file"
        accept=".pdf"
        multiple
        className="hidden"
        onChange={handleFileSelect}
      />
    </div>
  );
}

